INSERT INTO public.chapter_exercices
  (id, chapter_id, style, contenu, difficulte, origine, created_by)
SELECT
  md5('exercice-catalogue:' || v.chapter_id::text || ':' || v.difficulte::text)::uuid,
  v.chapter_id,
  v.style,
  v.contenu,
  v.difficulte,
  'catalogue',
  NULL
FROM (VALUES
  ('7cbd8a7e-3772-51db-a89c-0390e1c6eb36'::uuid, 1, 'redaction', $exo${"titre":"Se connaître : d'où vient la question, et ce que Freud y change","consigne":"Réponds à chaque question en quelques phrases précises, en t'appuyant sur le cours.","enonce":"**Questions de cours**\n\n1. D'où vient la maxime « Connais-toi toi-même » et qui l'a reprise ? Que veut-elle dire ?\n2. Que signifie l'affirmation de Freud selon laquelle le moi n'est « pas maître dans sa propre maison » ?\n3. L'objection freudienne rend-elle impossible toute connaissance de soi ? Explique comment elle en **déplace la méthode**, avec au moins un exemple.","bareme":[{"critere":"Origine de la maxime (temple de Delphes, reprise par Socrate) et sens : le savoir commence par soi","points":6},{"critere":"Sens de la formule de Freud : l'inconscient agit sans nous, le moi ne se voit pas directement","points":6},{"critere":"Déplacement de la méthode : passer par ce que le moi produit (actes manqués, rêves, récits), exemple juste","points":8}],"dureeMin":7,"corrige":"1. La maxime était **inscrite au temple de Delphes** ; **Socrate** l'a reprise. Elle signifie que le savoir commence par soi : avant de prétendre connaître le monde, il faut s'examiner soi-même.\n2. Pour **Freud**, une part de ce qui nous fait agir est **inconsciente** : elle agit sans nous et sans que nous le sachions. Le moi n'est donc pas « maître dans sa propre maison » : l'introspection classique, qui croit que la conscience s'atteint directement, est prise en défaut.\n3. Non. L'objection ne **détruit pas** la connaissance de soi, elle en **déplace la méthode** : si le moi ne se voit pas en se regardant, il faut passer par **ce qu'il produit** — les **actes manqués**, les **rêves**, les **récits**. Exemple attendu : un lapsus, un oubli répété, un rêve qui revient, qu'on interprète pour comprendre ce qu'on ne s'avouait pas."}$exo$::jsonb),
  ('7cbd8a7e-3772-51db-a89c-0390e1c6eb36'::uuid, 2, 'redaction', $exo${"titre":"Le journal de Nathan","consigne":"Lis le texte (écrit pour l'exercice), puis réponds aux questions en citant le texte et en utilisant les notions du cours.","enonce":"**Texte** (inventé pour l'exercice)\n\n> Ce soir, j'ai relu mon journal de l'an dernier. Je n'y reconnais presque pas celui qui écrit : il s'indigne de tout, il se trouve toujours dans son bon droit. Et surtout, je vois ce qu'il n'a pas écrit. La dispute avec Samir, par exemple : pas une ligne. À la place, trois pages sur un concert. J'écrivais au jour le jour, sans savoir ce qui compterait. Aujourd'hui, si je devais raconter cette année, je commencerais par Samir.\n> — Nathan, 17 ans\n\n1. À quelle forme d'écriture de soi appartient ce texte ? Quelle caractéristique du cours s'y vérifie ? Cite le texte.\n2. Montre, en citant, que le récit de soi **sélectionne** et **ordonne**.\n3. D'après ce texte, l'écriture de soi dit-elle le moi ou le fabrique-t-elle ? Réponds en quelques lignes argumentées.","bareme":[{"critere":"Forme identifiée (journal) et caractéristique : le moi écrit au présent, sans recul, appuyée sur une citation","points":5},{"critere":"Sélection et ordre du récit montrés par deux éléments précis du texte (la dispute tue, le concert, « je commencerais par Samir »)","points":7},{"critere":"Réponse argumentée : le récit construit le moi, avec nuance","points":6},{"critere":"Expression claire, citations exactes","points":2}],"dureeMin":11,"corrige":"1. C'est un **journal** (« j'ai relu mon journal »). Le cours dit que le journal écrit **le moi au présent, sans recul** : Nathan le confirme, « J'écrivais au jour le jour, sans savoir ce qui compterait ».\n2. Le récit **sélectionne** : la dispute avec Samir n'a « pas une ligne », alors que le concert occupe « trois pages ». Il **ordonne** : relisant son année avec du recul, Nathan « commencerait par Samir », c'est-à-dire qu'il réorganiserait les faits selon ce qui lui paraît important aujourd'hui. Il **justifie** aussi : l'ancien Nathan « se trouve toujours dans son bon droit ».\n3. Le texte montre que se raconter, c'est **aussi se construire** : chaque version (le journal d'hier, le récit d'aujourd'hui) donne une image différente du même garçon, selon ce qu'elle retient et met en avant. L'écriture ne restitue donc pas un moi déjà là : elle le **fabrique** en partie. Nuance attendue : elle n'est pas pure invention — la relecture fait apparaître un oubli (la dispute), et le recul permet à Nathan de mieux se comprendre. Le récit dit quelque chose de vrai, mais toujours à travers un choix."}$exo$::jsonb),
  ('7cbd8a7e-3772-51db-a89c-0390e1c6eb36'::uuid, 3, 'redaction', $exo${"titre":"Peut-on se connaître sans les autres ?","consigne":"Rédige un essai court (introduction avec problématique, deux parties argumentées, conclusion) en mobilisant plusieurs notions du chapitre.","enonce":"**Sujet d'essai**\n\n> Peut-on se connaître soi-même sans les autres ?\n\nTon essai doit :\n- montrer dans l'introduction pourquoi la question n'a pas de réponse évidente ;\n- mobiliser au moins **trois** références du cours (par exemple : la maxime delphique et l'introspection, Freud, Hegel, Sartre, l'écriture de soi) ;\n- s'appuyer sur au moins un exemple précis (littéraire ou personnel) ;\n- répondre clairement à la question dans la conclusion.","bareme":[{"critere":"Problématique : tension entre la connaissance de soi par soi (introspection) et le moi comme rapport à autrui","points":4},{"critere":"Première partie : limites de l'introspection (Freud) ou appui de la tradition delphique, correctement exposés","points":5},{"critere":"Deuxième partie : Hegel (reconnaissance) et Sartre (regard qui fige), le moi comme rapport et non substance","points":6},{"critere":"Exemple précis qui sert l'argument","points":2},{"critere":"Conclusion qui répond effectivement à la question","points":3}],"dureeMin":20,"corrige":"**Problématique attendue.** La maxime « Connais-toi toi-même » semble faire de la connaissance de soi une affaire solitaire : l'introspection classique pense que la conscience s'atteint directement. Mais si le moi ne se voit pas en se regardant, et s'il se forme dans ses relations, l'autre est peut-être indispensable. Le moi est-il une réalité intérieure qu'on découvre seul, ou un rapport qui n'existe que dans la relation ?\n\n**Partie 1 — Seul, on se connaît mal.** L'introspection suppose que la conscience se voit elle-même. **Freud** l'objecte : le moi n'est « pas maître dans sa propre maison », l'inconscient agit sans nous. Il faut passer par ce que le moi produit (actes manqués, rêves, récits) — et ces productions, souvent, c'est un autre (l'analyste, un ami) qui les interprète. Même l'**écriture de soi** (Augustin, Rousseau) s'adresse à quelqu'un : Dieu chez Augustin, le lecteur chez Rousseau.\n\n**Partie 2 — Le moi se constitue par l'autre.** Pour **Hegel**, la conscience de soi passe par la **reconnaissance** d'autrui. Pour **Sartre**, le regard de l'autre me **fige en objet** (« l'enfer, c'est les autres ») : il me révèle ce que je suis pour lui, que je ne peux pas voir seul, mais il m'enferme aussi. Dans les deux cas, le moi est un **rapport**, jamais une substance : il n'existe pas avant la relation qui le constitue.\n\n**Exemple possible.** Le roman d'apprentissage : le héros ne se découvre pas, il se construit en se heurtant au monde et aux autres. Ou un exemple personnel précis (une remarque d'un ami qui révèle un trait qu'on ignorait).\n\n**Conclusion attendue.** On ne peut pas se connaître **sans** les autres, car le moi n'est pas une chose intérieure qu'il suffirait de regarder : il se forme dans la relation. Mais l'autre ne suffit pas non plus : son regard peut me figer. La connaissance de soi passe par autrui, sans s'y réduire."}$exo$::jsonb),
  ('c72a0423-5189-5138-8487-3350088f8afe'::uuid, 1, 'redaction', $exo${"titre":"Deux racines, une tête bien faite","consigne":"Réponds à chaque question en quelques phrases, avec les mots précis du cours.","enonce":"**Questions de cours**\n\n1. Le mot « éducation » se rattache à deux racines latines, *educere* et *educare*. Donne le sens de chacune et ce qu'elle suppose sur l'enfant.\n2. Explique la formule de Montaigne : « une tête bien faite plutôt que bien pleine ». Dans quelle œuvre la trouve-t-on ?\n3. Que veut dire Montaigne quand il demande que l'élève rende compte non « seulement [d]es mots de sa leçon, mais [d]u sens et [de] la substance » ?","bareme":[{"critere":"Educere (conduire hors de : arracher l'enfant à son état premier) et educare (nourrir, élever : l'aider à s'accomplir)","points":8},{"critere":"Sens de la tête bien faite (le jugement plutôt que le savoir accumulé) et référence (Essais, « De l'institution des enfants »)","points":7},{"critere":"Explication : comprendre et juger le savoir, pas le réciter","points":5}],"dureeMin":7,"corrige":"1. *Educere* signifie **conduire hors de** : il suppose que l'enfant doit être **arraché à son état premier**. *Educare* signifie **nourrir, élever** : il suppose que l'enfant doit être **aidé à s'accomplir**. Toute l'histoire de l'éducation tient dans cet écart.\n2. La formule est tirée de « **De l'institution des enfants** » (*Essais*, I, 26). Montaigne y congédie le **savoir accumulé** : mieux vaut un esprit capable de **juger** qu'une mémoire remplie. L'élève doit passer le savoir **au crible de son propre jugement**.\n3. Montaigne refuse la récitation : réciter les mots de la leçon ne prouve pas qu'on a compris. Il faut que l'élève en saisisse le **sens** et se l'approprie, au point de pouvoir l'expliquer et le discuter lui-même."}$exo$::jsonb),
  ('c72a0423-5189-5138-8487-3350088f8afe'::uuid, 2, 'redaction', $exo${"titre":"Deux professeurs de sciences","consigne":"Lis la situation (inventée pour l'exercice), puis réponds en rapprochant chaque cas des auteurs du cours.","enonce":"**Situation**\n\n> Dans le même lycée, deux professeurs enseignent le même chapitre sur les plantes.\n> **Mme Arnal** dicte la leçon ; au cours suivant, elle interroge les élèves, qui doivent la réciter mot pour mot.\n> **M. Okafor** emmène sa classe au jardin du lycée. Les élèves observent, mesurent, se trompent, discutent entre eux ; il ne donne la définition qu'à la fin, quand ils l'ont presque trouvée. Un parent se plaint : « On perd un temps fou ! »\n\n1. À quels précepteurs de *Gargantua* de Rabelais peut-on comparer chacun des deux professeurs ? Justifie.\n2. Que répondrait Rousseau au parent qui se plaint ? Appuie-toi sur la citation d'*Émile* vue en cours et sur la notion d'**éducation négative**.\n3. Montre qu'une difficulté subsiste dans la méthode de M. Okafor, en t'appuyant sur la formule de Kant citée en cours.","bareme":[{"critere":"Mme Arnal rapprochée de Thubal Holopherne (récitation, par cœur), M. Okafor de Ponocrates (observation, conversation), justifié","points":6},{"critere":"Réponse de Rousseau : « perdre du temps », éducation négative (expérience, nécessité des choses, pas l'autorité)","points":7},{"critere":"Tension kantienne expliquée : cultiver la liberté par la contrainte, appliquée à la situation","points":5},{"critere":"Rédaction claire et justifiée","points":2}],"dureeMin":12,"corrige":"1. **Mme Arnal** ressemble à **Thubal Holopherne**, le précepteur de la **récitation** et du **par cœur** : chez Rabelais, cette méthode **abrutit**. **M. Okafor** ressemble à **Ponocrates**, qui forme par le **corps**, l'**observation** et la **conversation** : cette méthode **forme**. On peut ajouter Montaigne : M. Okafor vise « une tête bien faite plutôt que bien pleine ».\n2. Rousseau répondrait que ce temps « perdu » est justement l'essentiel : « Le plus grand, le plus important, le plus utile de toute l'éducation, c'est de ne pas gagner du temps, c'est d'en perdre. » Pour lui l'enfant n'est pas un adulte incomplet qu'il faudrait remplir vite. L'**éducation négative** protège l'enfant des préjugés au lieu de les lui inculquer : il apprend **par l'expérience et par la nécessité des choses**, non par l'autorité du maître — exactement ce qui se passe au jardin.\n3. M. Okafor ne laisse pas les élèves totalement libres : c'est lui qui choisit le jardin, le moment et la définition finale. Toute éducation, même libérale, suppose un cadre. **Kant** formule cette tension : « comment cultiver la liberté par la contrainte ? » On veut rendre l'élève autonome, mais on ne peut le faire qu'en l'encadrant."}$exo$::jsonb),
  ('c72a0423-5189-5138-8487-3350088f8afe'::uuid, 3, 'redaction', $exo${"titre":"Éduquer : transmettre un héritage ou rendre capable de le contester ?","consigne":"Rédige un essai court et construit (introduction problématisée, deux ou trois parties, conclusion) en mobilisant au moins quatre auteurs du chapitre.","enonce":"**Sujet d'essai**\n\n> Éduquer, est-ce transmettre un héritage ou rendre capable de le contester ?\n\nConseils :\n- appuie-toi sur l'école républicaine (Condorcet, lois Ferry) ;\n- confronte-la à au moins une critique contemporaine (Bourdieu et Passeron, Illich, Freire) ;\n- termine en examinant la réponse d'Hannah Arendt ;\n- réponds clairement à la question en conclusion.","bareme":[{"critere":"Problématique posant l'alternative transmettre / contester et sa difficulté","points":3},{"critere":"L'école républicaine : Condorcet (égalité des lumières) et lois Ferry, l'instruction comme condition de la citoyenneté","points":5},{"critere":"Critiques contemporaines exactement exposées (au moins deux parmi Bourdieu-Passeron, Illich, Freire)","points":6},{"critere":"Position d'Arendt comprise : refuser de choisir, transmettre pour permettre le renouvellement","points":4},{"critere":"Conclusion qui répond à la question","points":2}],"dureeMin":20,"corrige":"**Problématique.** Éduquer, c'est transmettre ce qui existe déjà : des savoirs, une langue, une culture. Mais une éducation qui ne ferait que transmettre formerait des héritiers dociles. Faut-il donc choisir entre conserver et émanciper ?\n\n**Partie 1 — Transmettre pour rendre libre.** Pour **Condorcet** (1792), l'égalité politique reste **fictive sans égalité des lumières**. Les **lois Ferry** (1881-1882) rendent l'école **gratuite, laïque et obligatoire** : l'instruction devient une **condition de la citoyenneté**, non un ornement. Transmettre un héritage commun est ici la condition même de la liberté.\n\n**Partie 2 — La transmission peut enfermer.** **Bourdieu et Passeron** (*Les Héritiers*, 1964 ; *La Reproduction*, 1970) montrent que, sous couvert de méritocratie, l'école transmet un **capital culturel** qui avantage ceux qui l'ont déjà. **Paulo Freire** (*Pédagogie des opprimés*) dénonce l'éducation « **bancaire** » : le maître dépose, l'élève reçoit passivement ; il lui oppose la **conscientisation**. **Ivan Illich** (*Une société sans école*, 1971) va plus loin : l'institution crée le besoin qu'elle prétend satisfaire. Transmettre sans rendre capable de contester, c'est reproduire.\n\n**Partie 3 — Arendt : refuser l'alternative.** Dans *La Crise de la culture*, **Hannah Arendt** refuse de choisir : c'est **parce que le monde est ancien** qu'on doit l'enseigner, et **parce qu'il est confié à des nouveaux venus** qu'il peut être renouvelé. On ne conteste bien que ce qu'on connaît.\n\n**Conclusion.** Éduquer n'est ni seulement transmettre ni seulement émanciper : on transmet l'héritage **pour** rendre capable de le contester. Une critique sans héritage est vide, un héritage sans critique est une reproduction."}$exo$::jsonb),
  ('70da3aef-6b9c-5d46-a2e1-f4414de341b7'::uuid, 1, 'redaction', $exo${"titre":"Le mythe de Theuth","consigne":"Réponds à chaque question en quelques phrases, avec les mots du cours.","enonce":"**Questions de cours**\n\n1. Dans quelle œuvre Platon fait-il raconter le mythe de Theuth, et par qui ?\n2. Que voient respectivement **Theuth** et le roi **Thamous** dans l'écriture ?\n3. Que signifie dire que l'écriture est un *pharmakon* ? Montre que cette inquiétude s'est répétée pour d'autres supports.","bareme":[{"critere":"Le Phèdre, récit fait par Socrate","points":4},{"critere":"Theuth : un remède à la mémoire ; Thamous : un poison, on croira savoir sans savoir","points":8},{"critere":"Pharmakon = remède et poison à la fois ; inquiétude reprise pour l'imprimerie puis Internet","points":8}],"dureeMin":7,"corrige":"1. Dans le ***Phèdre*** de Platon ; c'est **Socrate** qui raconte le mythe.\n2. **Theuth**, l'inventeur, voit dans l'écriture un **remède** à la mémoire. **Thamous**, le roi, y voit un **poison** : on cessera de se souvenir, on se reposera sur les signes écrits, et l'on **croira savoir sans savoir**.\n3. Le *pharmakon* est à la fois **remède et poison**. L'écriture aide à conserver le savoir, mais elle risque d'affaiblir la mémoire et de donner l'illusion du savoir. Cette inquiétude a accompagné l'**imprimerie**, puis **Internet** : chaque support nouveau est accusé de ruiner la faculté qu'il prétend servir."}$exo$::jsonb),
  ('70da3aef-6b9c-5d46-a2e1-f4414de341b7'::uuid, 2, 'redaction', $exo${"titre":"Ce que Lucie a reçu de sa grand-mère","consigne":"Lis la situation (inventée pour l'exercice), puis classe et analyse ce qui se transmet à l'aide du tableau du cours.","enonce":"**Situation**\n\n> Lucie passe tous ses étés chez sa grand-mère, boulangère à la retraite. Elle y a appris :\n> a) la recette écrite du pain de campagne, recopiée dans un cahier ;\n> b) le geste pour façonner une boule de pâte, qu'elle a acquis en regardant puis en recommençant cent fois ;\n> c) une manière de parler et de se tenir à table que personne ne lui a jamais enseignée, mais que ses amis remarquent ;\n> d) le souvenir de la libération du village, raconté chaque année devant le monument aux morts.\n\n1. Pour chacun des éléments a, b, c, d, dis **ce qui** est transmis et **par quel canal**, et nomme l'auteur du cours qui le décrit quand il y en a un.\n2. Lucie dit : « Mon pain n'est jamais tout à fait celui de ma grand-mère. » Explique ce constat à l'aide de l'idée du cours selon laquelle le savoir ne se transmet pas comme un objet.","bareme":[{"critere":"a) contenu par l'écrit ; b) geste par imitation et apprentissage","points":5},{"critere":"c) habitus transmis par la famille sans être enseigné (Bourdieu)","points":4},{"critere":"d) mémoire collective par commémoration, cadres sociaux (Halbwachs)","points":4},{"critere":"Question 2 : le savoir se reconstruit, l'élève doit le refaire ; la transmission transforme","points":5},{"critere":"Rédaction précise","points":2}],"dureeMin":12,"corrige":"1.\n- a) Un **contenu**, transmis par l'**écrit** (le cahier, comme le livre ou l'école).\n- b) Un **geste**, transmis par l'**imitation** et l'**apprentissage**, comme à l'atelier ou dans le compagnonnage.\n- c) Un ***habitus*** : façons de parler, de se tenir, goûts, transmis par la **famille**, **sans être enseigné**. C'est **Bourdieu** qui le décrit.\n- d) Une **mémoire collective**, transmise par les **monuments** et les **commémorations**. **Halbwachs** montre que le souvenir s'appuie sur des **cadres sociaux** : on ne se souvient jamais seul.\n2. Le savoir ne se transmet pas comme un objet qui passerait de main en main : il se **reconstruit** chez celui qui l'acquiert. Ce que le maître donne, l'élève doit le **refaire** — avec ses mains, son four, sa farine. Le pain de Lucie diffère donc nécessairement : la transmission comporte une part de perte et de déformation, mais aussi de création (*traduttore, traditore*). C'est ce qui garde la tradition vivante."}$exo$::jsonb),
  ('70da3aef-6b9c-5d46-a2e1-f4414de341b7'::uuid, 3, 'redaction', $exo${"titre":"Transmettre, est-ce toujours trahir ?","consigne":"Rédige un essai construit (introduction problématisée, deux ou trois parties, conclusion) en mobilisant au moins quatre références du chapitre.","enonce":"**Sujet d'essai**\n\n> Transmettre, est-ce toujours trahir ?\n\nPistes possibles (à choisir et à relier) : le mythe de Theuth, l'imprimerie de Gutenberg, l'habitus selon Bourdieu, la mémoire collective selon Halbwachs, *Petite Poucette* de Michel Serres, la formule *traduttore, traditore*.\n\nTa conclusion doit répondre clairement à la question.","bareme":[{"critere":"Problématique : la transmission fidèle est-elle possible, et la trahison est-elle une perte ou une chance ?","points":3},{"critere":"Partie montrant ce qui se perd ou se déforme (Theuth / Thamous, commémoration et oubli, trahison partielle)","points":5},{"critere":"Partie montrant que la reconstruction fait vivre le savoir (élève qui refait, Gutenberg, tradition réinterprétée)","points":5},{"critere":"Usage pertinent et exact d'au moins quatre références","points":4},{"critere":"Conclusion qui répond à la question","points":3}],"dureeMin":20,"corrige":"**Problématique.** On attend d'une transmission qu'elle soit fidèle. Or entre celui qui donne et celui qui reçoit, quelque chose se perd. Faut-il y voir un échec inévitable, ou la condition même de toute transmission vivante ?\n\n**Partie 1 — Toute transmission déforme.** Dans le *Phèdre*, **Thamous** voit dans l'écriture un **poison** : on croira savoir sans savoir. Le support même altère ce qu'il transmet. Une société transmet aussi ce qu'elle choisit de **commémorer** — donc, en creux, ce qu'elle choisit d'**oublier** (**Halbwachs** : la mémoire s'appuie sur des cadres sociaux). Et ce qui passe sans être enseigné, l'***habitus*** (**Bourdieu**), échappe au contrôle de celui qui transmet. *Traduttore, traditore* : toute transmission est une traduction, donc une **trahison partielle**.\n\n**Partie 2 — Mais cette trahison est féconde.** Le savoir ne passe pas comme un objet : il se **reconstruit**, l'élève doit le **refaire**. Avec **Gutenberg** (vers 1450), le livre devient reproductible, **vérifiable, discutable** : la Réforme, la révolution scientifique et les Lumières en sont indissociables — la diffusion a permis la contestation. **Michel Serres** (*Petite Poucette*, 2012) en tire que, le savoir étant accessible d'un clic, il faut surtout apprendre à **s'orienter** : on transmet une capacité, non un stock.\n\n**Partie 3 — Trahir pour garder vivant.** Une tradition qui ne se réinterprète plus est une **tradition morte** : la trahison partielle est ce qui permet au savoir de rester vivant.\n\n**Conclusion.** Oui, transmettre, c'est toujours trahir un peu — mais ce n'est pas une perte à regretter : c'est parce que celui qui reçoit refait le savoir que celui-ci survit. La vraie trahison serait la répétition morte."}$exo$::jsonb),
  ('cee613e0-8d08-598a-86a2-22bdefbc269d'::uuid, 1, 'redaction', $exo${"titre":"Le critère de Lévi-Strauss","consigne":"Réponds à chaque question en justifiant avec le critère du cours.","enonce":"**Questions de cours**\n\n1. Quel critère Lévi-Strauss propose-t-il pour distinguer le naturel du culturel ?\n2. Classe, avec ce critère, les conduites suivantes : a) dormir ; b) manger avec des baguettes ; c) les règles qui disent qui l'on peut épouser ; d) marcher.\n3. Pourquoi la **prohibition de l'inceste** est-elle un cas qui « oblige à penser » ?","bareme":[{"critere":"Critère exact : l'universel relève de la nature, ce qui varie selon les sociétés de la culture","points":6},{"critere":"Classement juste des quatre conduites, justifié","points":6},{"critere":"Prohibition de l'inceste : universelle comme la nature et réglée comme la culture, brouille la frontière","points":8}],"dureeMin":7,"corrige":"1. Est **naturel** ce qui est **universel** ; est **culturel** ce qui **varie** selon les sociétés.\n2. a) **Dormir** : naturel (universel). b) **Manger avec des baguettes** : culturel (la manière de table varie). c) **Les règles de mariage** : culturel (la parenté varie selon les sociétés). d) **Marcher** : naturel (universel).\n3. La prohibition de l'inceste est **universelle**, comme ce qui est naturel, mais elle est **réglée** différemment selon les sociétés, comme ce qui est culturel. Elle **brouille la frontière** entre les deux : elle n'entre pas proprement dans une case. C'est pourquoi elle oblige à penser le passage de la nature à la culture au lieu de simplement confirmer le critère."}$exo$::jsonb),
  ('cee613e0-8d08-598a-86a2-22bdefbc269d'::uuid, 2, 'redaction', $exo${"titre":"L'implant Mnémos","consigne":"Lis le document (inventé pour l'exercice), puis réponds en t'appuyant sur les notions du cours.","enonce":"**Document** (publicité imaginaire)\n\n> **Mnémos, l'implant qui ne vous laisse jamais oublier.** Retenez tout ce que vous lisez, parlez vingt langues, ne perdez plus jamais un souvenir. Aujourd'hui votre mémoire, demain votre vieillissement : l'humain n'est pas fini, il est à améliorer. Effets à long terme en cours d'étude.\n\n1. À quel courant de pensée cette publicité se rattache-t-elle ? Justifie par deux expressions du document.\n2. Quelle conception de l'humain cette publicité défend-elle : sa **perfectibilité** ou sa **finitude** ? Explique ce que défendrait la conception opposée.\n3. Que dirait Hans Jonas de la dernière phrase du document ? Formule son principe.","bareme":[{"critere":"Transhumanisme identifié, justifié par deux expressions du document","points":5},{"critere":"Perfectibilité reconnue ; conception opposée (finitude : l'être qui sait qu'il meurt) expliquée","points":6},{"critere":"Principe responsabilité de Jonas exactement formulé et appliqué aux effets inconnus","points":7},{"critere":"Expression claire","points":2}],"dureeMin":12,"corrige":"1. Le document relève du **transhumanisme** : augmenter techniquement l'humain. Expressions : « l'humain n'est pas fini, il est à améliorer », « demain votre vieillissement », « parlez vingt langues ».\n2. Il défend la **perfectibilité** : l'humain serait l'être qui se transforme, et la technique accomplirait ce mouvement. La conception opposée définit l'humain par sa **finitude** : il est l'être qui sait qu'il meurt ; supprimer l'oubli ou le vieillissement ne l'accomplirait pas, cela risquerait de le supprimer. Tout le débat tient dans cet écart : augmenter l'humain, est-ce l'accomplir ou le supprimer ?\n3. La technique augmente ici le pouvoir de l'homme **sur lui-même**, alors que les « effets à long terme » sont inconnus. **Hans Jonas** formule un **principe responsabilité** : agir de telle sorte que les effets de l'action soient **compatibles avec la permanence d'une vie humaine authentique sur terre**. Il exigerait donc de ne pas lancer une telle transformation tant qu'on ignore ses effets sur l'humain lui-même."}$exo$::jsonb),
  ('cee613e0-8d08-598a-86a2-22bdefbc269d'::uuid, 3, 'redaction', $exo${"titre":"La culture protège-t-elle de la barbarie ?","consigne":"Rédige un essai construit (introduction problématisée, deux parties au moins, conclusion) en mobilisant plusieurs notions du chapitre.","enonce":"**Sujet d'essai**\n\n> La culture protège-t-elle de la barbarie ?\n\nTon essai doit mobiliser :\n- la promesse de l'humanisme ;\n- le procès que lui fait le XXe siècle (Primo Levi, Hannah Arendt) ;\n- la question de la technique (Hans Jonas).\n\nAppuie-toi sur au moins un exemple précis et réponds clairement dans ta conclusion.","bareme":[{"critere":"Problématique : la culture comme promesse d'humanité face à l'expérience du XXe siècle","points":3},{"critere":"L'humanisme exposé : l'homme au centre, la culture comme promesse","points":4},{"critere":"Le procès : la Shoah, Primo Levi (témoignage), Arendt (banalité du mal, hommes ordinaires, système obéissant)","points":6},{"critere":"La technique et Jonas : le pouvoir sans responsabilité, principe responsabilité","points":4},{"critere":"Conclusion nuancée qui répond à la question","points":3}],"dureeMin":20,"corrige":"**Problématique.** L'humanisme a fait de la culture une promesse : plus l'homme se cultive, plus il devient humain. Mais le XXe siècle a vu la barbarie surgir au cœur de nations cultivées. La culture est-elle un rempart, ou peut-elle coexister avec le pire ?\n\n**Partie 1 — La promesse humaniste.** L'**humanisme** place l'homme au centre et fait de la culture une **promesse** : elle arracherait l'homme à la violence et le rendrait pleinement humain.\n\n**Partie 2 — Le procès du XXe siècle.** La **Shoah** montre que **ni la culture ni la technique n'empêchent la barbarie**. **Primo Levi** témoigne de ce que le camp fait à l'humain. **Hannah Arendt** analyse la « **banalité du mal** » : le crime est commis par des **hommes ordinaires**, dans un **système obéissant** — non par des monstres incultes. La culture n'a pas protégé ; la technique a même servi l'extermination.\n\n**Partie 3 — Ce que la culture doit devenir.** La technique augmente le pouvoir de l'homme sur lui-même (de Prométhée aux biotechnologies). **Hans Jonas** en tire un **principe responsabilité** : agir de telle sorte que les effets de l'action soient compatibles avec la permanence d'une vie humaine authentique sur terre. La culture ne protège pas par elle-même ; elle ne protège que si elle se double d'une responsabilité.\n\n**Conclusion.** La culture ne garantit pas contre la barbarie : l'expérience du XXe siècle l'a prouvé. Elle en donne pourtant les moyens de la penser (le témoignage de Levi, l'analyse d'Arendt) et de la prévenir (la responsabilité selon Jonas). Elle est une condition nécessaire, jamais suffisante."}$exo$::jsonb),
  ('7aeefedb-4028-5b71-b194-3542de89aaef'::uuid, 1, 'redaction', $exo${"titre":"Sortir de la minorité","consigne":"Réponds à chaque question en quelques phrases, avec les mots du cours.","enonce":"**Questions de cours**\n\n1. D'où vient le mot « émanciper » ? Quel passage désigne-t-il ?\n2. Comment Kant définit-il les Lumières dans *Qu'est-ce que les Lumières ?* (1784) ?\n3. Explique ce que Kant entend par **minorité**, pourquoi l'homme en est **responsable**, et le mot d'ordre qui en découle.","bareme":[{"critere":"Étymologie : sortir de la manus, la main du père ; passage de la tutelle à l'autonomie","points":5},{"critere":"Définition des Lumières : sortie de l'homme hors de l'état de minorité dont il est lui-même responsable","points":5},{"critere":"Minorité, responsabilité (paresse et lâcheté, non la nature) et Sapere aude expliqués","points":10}],"dureeMin":8,"corrige":"1. En droit romain, s'émanciper, c'est **sortir de la *manus***, la main du père. Le mot désigne le passage d'un état de **tutelle** à un état d'**autonomie**.\n2. Les Lumières sont « la sortie de l'homme hors de l'état de **minorité** dont il est lui-même **responsable** ».\n3. La **minorité** est l'**incapacité de se servir de son entendement sans la direction d'autrui**. L'homme en est **responsable** parce que ce n'est pas la nature qui l'y maintient, mais sa **paresse** et sa **lâcheté** : il est plus confortable de laisser d'autres penser pour soi. D'où le mot d'ordre : ***Sapere aude*** — **ose savoir**, aie le courage de te servir de ton propre entendement."}$exo$::jsonb),
  ('7aeefedb-4028-5b71-b194-3542de89aaef'::uuid, 2, 'redaction', $exo${"titre":"Des émancipations fragiles","consigne":"Étudie le document, puis réponds en t'appuyant uniquement sur ses données et sur le cours.","enonce":"**Document — Quelques émancipations en France**\n\n| Date | Ce qui est proclamé | Ce qui suit |\n|---|---|---|\n| 1794 | Abolition de l'esclavage | Rétablissement en 1802, abolition définitive en 1848 |\n| 1944 | Droit de vote des femmes | Capacité juridique pleine en 1965 seulement |\n\n1. Que montre la colonne « Ce qui suit » sur la nature d'une émancipation politique ? Appuie-toi sur les deux lignes.\n2. Le cours pose la question : « à quelles conditions **matérielles** une liberté proclamée devient-elle une liberté réelle ? » Explique cette distinction à l'aide de la deuxième ligne.\n3. Le cours affirme aussi qu'« il n'y a pas d'émancipation qui ne s'exerce **depuis quelque part** ». Explique cette phrase avec un des exemples du cours (école obligatoire ou laïcité).","bareme":[{"critere":"Fragilité montrée : une émancipation peut être annulée (1802) ou rester incomplète (1965), avec les dates","points":6},{"critere":"Distinction liberté proclamée / liberté réelle expliquée sur l'exemple du vote des femmes","points":6},{"critere":"Explication de « depuis quelque part » : ce qu'une émancipation libère et ce qu'elle impose, exemple exact","points":6},{"critere":"Rédaction claire","points":2}],"dureeMin":12,"corrige":"1. Une émancipation n'est **jamais acquise une fois pour toutes**. L'abolition de 1794 est **annulée** en 1802 : il faut attendre 1848 pour une abolition définitive. Le droit de vote de 1944 est une conquête réelle, mais **incomplète** : la capacité juridique pleine ne vient qu'en 1965. Proclamer ne suffit pas.\n2. Une liberté **proclamée** existe dans le droit ; une liberté **réelle** peut s'exercer dans la vie. En 1944, les femmes votent : elles sont citoyennes. Mais sans pleine capacité juridique, leur autonomie reste limitée dans la vie quotidienne jusqu'en 1965. La proclamation est une étape, les conditions de son exercice en sont une autre.\n3. Toute émancipation libère **de** quelque chose, mais au nom d'une norme. **L'école obligatoire** libère de l'ignorance et du travail des enfants, mais elle **arrache aussi l'enfant à sa famille**. La **laïcité** libère du dogme, mais impose **sa propre norme**. S'émanciper, ce n'est donc pas sortir de toute contrainte : c'est passer d'une contrainte à une autre, jugée plus juste."}$exo$::jsonb),
  ('7aeefedb-4028-5b71-b194-3542de89aaef'::uuid, 3, 'redaction', $exo${"titre":"L'éducation émancipe-t-elle ?","consigne":"Rédige un essai construit (introduction problématisée, deux ou trois parties, conclusion) en mobilisant au moins quatre références du chapitre.","enonce":"**Sujet d'essai**\n\n> L'éducation émancipe-t-elle, ou fabrique-t-elle la minorité qu'elle prétend abolir ?\n\nMobilise notamment : Kant et la minorité ; Jacotot et Rancière (*Le Maître ignorant*) ; les tensions de l'école obligatoire ; Simone de Beauvoir.\n\nRéponds clairement à la question dans ta conclusion.","bareme":[{"critere":"Problématique : l'éducation comme sortie de tutelle, mais aussi comme tutelle","points":3},{"critere":"Kant : minorité, responsabilité, Sapere aude, correctement mobilisés","points":4},{"critere":"Rancière et Jacotot : égalité des intelligences posée au départ, le maître qui explique installe la dépendance","points":6},{"critere":"Tensions (école obligatoire) et Beauvoir (ce qui est construit peut être défait, conditions matérielles)","points":4},{"critere":"Conclusion qui répond à la question","points":3}],"dureeMin":20,"corrige":"**Problématique.** On attend de l'éducation qu'elle fasse sortir de la tutelle. Mais elle repose sur un maître qui sait et un élève qui ne sait pas : ne risque-t-elle pas d'entretenir la dépendance qu'elle veut abolir ?\n\n**Partie 1 — L'éducation comme sortie de la minorité.** **Kant** définit les Lumières comme la sortie de la **minorité**, incapacité de se servir de son entendement sans la direction d'autrui. Cette minorité n'est pas naturelle : elle vient de la paresse et de la lâcheté. L'éducation doit donc donner le courage de penser par soi-même : ***Sapere aude***. L'**école obligatoire** libère de l'ignorance et du travail des enfants.\n\n**Partie 2 — L'éducation peut fabriquer la minorité.** **Jacotot**, redécouvert par **Rancière** (*Le Maître ignorant*, 1987), fait l'hypothèse de l'**égalité des intelligences** : ce n'est pas l'inégalité qu'il faut réduire, c'est l'égalité qu'il faut **poser au départ** et vérifier. Un maître qui explique **installe la dépendance** qu'il prétend guérir : l'élève apprend qu'il a besoin qu'on lui explique. De plus, l'école obligatoire **arrache aussi l'enfant à sa famille** : toute émancipation s'exerce **depuis quelque part**.\n\n**Partie 3 — Une émancipation à conditions.** **Simone de Beauvoir** (« On ne naît pas femme : on le devient ») montre que ce qui est **construit** peut être défait : l'éducation peut aussi défaire les assignations. Mais une liberté proclamée ne devient réelle qu'à certaines **conditions matérielles**.\n\n**Conclusion.** L'éducation émancipe à condition de ne pas faire de l'explication une tutelle permanente : elle doit supposer l'élève capable dès le départ et viser son autonomie. Sinon, elle fabrique la minorité qu'elle prétend abolir."}$exo$::jsonb),
  ('a1467307-77b6-5c43-b345-e82504ab15b0'::uuid, 1, 'redaction', $exo${"titre":"Ce que le romantisme renverse","consigne":"Réponds à chaque question en quelques phrases précises.","enonce":"**Questions de cours**\n\n1. De quel poème et de quel recueil est tiré le vers « Un seul être vous manque et tout est dépeuplé » ? Quel basculement condense-t-il ?\n2. Compare la place de la **passion** et du **sujet** à l'âge classique et dans le romantisme.\n3. Qu'est-ce que le « mal du siècle » ? Cite les deux œuvres du cours qui le fixent et ce que chacune établit.","bareme":[{"critere":"« L'Isolement », Méditations poétiques (Lamartine, 1820) ; le sentiment individuel devient le centre d'où l'on regarde le monde","points":5},{"critere":"Comparaison juste : désordre à corriger / source de vérité ; sujet qui se retient / émotion matière de l'œuvre","points":6},{"critere":"René (mélancolie sans objet, vague des passions) et La Confession d'un enfant du siècle (explication historique, génération entre deux mondes)","points":9}],"dureeMin":8,"corrige":"1. Le vers est de **Lamartine**, dans « **L'Isolement** » (*Méditations poétiques*, 1820). Il condense un basculement : le **sentiment individuel** devient le centre d'où l'on regarde le monde entier — l'absence d'un seul être vide l'univers.\n2. À l'**âge classique**, la passion est un **désordre à corriger par la raison**, et le sujet **se retient, se dissimule**. Dans le **romantisme**, la passion devient une **source de vérité**, et le sujet fait de son **émotion la matière de l'œuvre**.\n3. Le « mal du siècle » est une mélancolie propre à la génération romantique. ***René*** (Chateaubriand, 1802) en fait une mélancolie **sans objet** : le « **vague des passions** », où le désir devance l'expérience. ***La Confession d'un enfant du siècle*** (Musset, 1836) en donne une explication **historique** : une génération née « **entre deux mondes** », l'Empire écroulé et une monarchie sans grandeur."}$exo$::jsonb),
  ('a1467307-77b6-5c43-b345-e82504ab15b0'::uuid, 2, 'redaction', $exo${"titre":"Élise au bord de l'étang","consigne":"Lis le texte (écrit pour l'exercice, à la manière des romantiques), puis analyse-le avec les notions du cours en citant le texte.","enonce":"**Texte** (inventé pour l'exercice)\n\n> Je suis revenue au bord de l'étang où nous marchions l'automne dernier. Les mêmes saules, la même eau grise. Toi, tu n'es plus là, et c'est comme si tout le paysage s'était vidé. Je demande à ces arbres de se souvenir pour moi, puisque les jours effacent tout. Mais l'eau ne me rend que mon visage. Je voudrais quelque chose d'immense, et je ne sais même pas quoi.\n\n1. Relève dans le texte les **trois éléments** que le romantisme lie, selon le cours (le moi, le temps, le monde), en citant à chaque fois.\n2. Quel rôle la **nature** joue-t-elle ici ? Rapproche ce texte d'un poème romantique cité dans le cours.\n3. La dernière phrase relève-t-elle du « vague des passions » ? Justifie avec la définition du cours.","bareme":[{"critere":"Les trois éléments repérés et cités : exaltation du moi, temps qui passe, monde qui ne répond pas","points":8},{"critere":"Nature miroir et refuge, à qui l'on demande de garder la mémoire ; rapprochement avec « Le Lac » ou « Tristesse d'Olympio »","points":6},{"critere":"Dernière phrase : désir sans objet qui devance l'expérience, lien avec René","points":4},{"critere":"Citations exactes et analyse, pas de paraphrase","points":2}],"dureeMin":12,"corrige":"1. **Le moi** : tout est vu depuis l'émotion de la narratrice (« c'est comme si tout le paysage s'était vidé » — écho du vers de Lamartine). **Le temps qui passe** : « l'automne dernier », « les jours effacent tout ». **Le monde qui ne répond pas** : « l'eau ne me rend que mon visage ».\n2. La nature n'est pas un décor : elle **répond** au sentiment, elle est **miroir et refuge**. Élise lui demande de **garder la mémoire** d'un amour que le temps efface (« Je demande à ces arbres de se souvenir pour moi ») — exactement ce que font **Lamartine** dans « **Le Lac** » et **Hugo** dans « **Tristesse d'Olympio** ». Mais ici le miroir déçoit : il ne renvoie qu'à soi.\n3. Oui. Le « vague des passions » (*René*, Chateaubriand) est une mélancolie **sans objet**, où **le désir devance l'expérience**. « Je voudrais quelque chose d'immense, et je ne sais même pas quoi » : le désir est immense et ne sait pas ce qu'il vise."}$exo$::jsonb),
  ('a1467307-77b6-5c43-b345-e82504ab15b0'::uuid, 3, 'redaction', $exo${"titre":"La sincérité d'une émotion suffit-elle à lui donner de la valeur ?","consigne":"Rédige un essai construit (introduction problématisée, deux parties au moins, conclusion) en mobilisant au moins quatre références du chapitre.","enonce":"**Sujet d'essai**\n\n> La sincérité d'une émotion suffit-elle à lui donner de la valeur ?\n\nAppuie-toi sur le renversement romantique et le « mal du siècle », puis sur les objections de Hegel, de Nietzsche et de la psychanalyse. Tu peux terminer par l'héritage romantique aujourd'hui (chanson, cinéma, réseaux sociaux).\n\nRéponds clairement dans ta conclusion.","bareme":[{"critere":"Problématique : l'émotion sincère comme caution, héritage romantique","points":3},{"critere":"Le romantisme exposé : la passion source de vérité, l'émotion matière de l'œuvre, exemples précis","points":5},{"critere":"Objections exactes : Hegel (âme belle), Nietzsche (détresse / surabondance), psychanalyse (deuil impossible)","points":7},{"critere":"Prolongement actuel pertinent (sincérité comme caution)","points":2},{"critere":"Conclusion qui répond à la question","points":3}],"dureeMin":20,"corrige":"**Problématique.** Depuis le romantisme, on tend à croire qu'une émotion vraie vaut par elle-même. Mais une émotion peut être sincère et stérile, sincère et complaisante. La sincérité est-elle une valeur, ou seulement une condition ?\n\n**Partie 1 — Le romantisme fait de l'émotion une vérité.** À l'âge classique, la passion était un désordre à corriger ; le romantisme en fait une **source de vérité**, et le sujet fait de son émotion **la matière de l'œuvre**. Lamartine (« L'Isolement ») fait du sentiment le centre du monde ; *René* explore une mélancolie sans objet ; Musset en donne la raison historique (une génération « entre deux mondes »).\n\n**Partie 2 — Les objections.** **Hegel** reproche à l'« **âme belle** » de préférer sa **pureté à l'action** et de se complaire dans son insatisfaction : une émotion sincère peut dispenser d'agir. **Nietzsche** distingue un romantisme de la **détresse**, qui souffre du manque, d'un art de la **surabondance**, qu'il préfère : toutes les émotions sincères ne se valent pas. La **psychanalyse** relit la mélancolie comme un **deuil impossible** : le mélancolique ne sait pas ce qu'il a perdu — la sincérité n'est pas la lucidité.\n\n**Partie 3 — L'héritage.** Le romantisme a installé l'idée que la **sincérité** de l'émotion **vaut caution** ; la chanson, le cinéma et les réseaux sociaux la reprennent. Or une émotion affichée peut être sincère et pourtant ne rien prouver.\n\n**Conclusion.** La sincérité est nécessaire à la valeur d'une émotion, mais elle ne suffit pas : il faut encore se demander ce que l'émotion fait faire (Hegel), d'où elle vient (Nietzsche) et ce qu'elle cache (la psychanalyse)."}$exo$::jsonb),
  ('37aff0ea-aa91-5a64-b706-3590a8a24ccc'::uuid, 1, 'redaction', $exo${"titre":"La méfiance antique envers les passions","consigne":"Réponds à chaque question en quelques phrases précises.","enonce":"**Questions de cours**\n\n1. Pour les stoïciens, qu'est-ce qu'une passion ? Explique la formule « ce n'est pas la chose qui trouble, c'est l'opinion qu'on en a ».\n2. Que signifie l'*apatheia* ? Pourquoi n'est-ce pas l'insensibilité ?\n3. Décris l'image de l'âme chez Platon et ce qu'elle signifie.","bareme":[{"critere":"Passion = jugement faux ; la formule expliquée avec un exemple","points":7},{"critere":"Apatheia : affranchissement des jugements précipités, non insensibilité","points":6},{"critere":"L'attelage : le cocher (raison) maîtrise deux chevaux, dont l'un tire vers le bas","points":7}],"dureeMin":7,"corrige":"1. Pour les **stoïciens**, la passion est un **jugement faux**. Ce qui nous trouble n'est pas l'événement lui-même, mais l'**opinion** que nous nous en faisons. Exemple : une mauvaise note n'est pas un malheur en soi ; c'est le jugement « c'est une catastrophe » qui produit l'angoisse.\n2. L'***apatheia*** est l'**affranchissement des jugements précipités**. Ce n'est pas ne plus rien sentir : c'est ne plus se laisser emporter par des jugements hâtifs sur ce qui arrive.\n3. Chez **Platon**, l'âme est un **attelage** : un **cocher**, la **raison**, conduit **deux chevaux**, dont **l'un tire vers le bas**. La raison doit maîtriser les forces de l'âme qui l'entraîneraient ; les passions ne sont pas supprimées, elles sont dirigées."}$exo$::jsonb),
  ('37aff0ea-aa91-5a64-b706-3590a8a24ccc'::uuid, 2, 'redaction', $exo${"titre":"Inès et le choix de la prépa","consigne":"Lis la situation (inventée pour l'exercice), puis réponds en t'appuyant sur les auteurs du cours.","enonce":"**Situation**\n\n> Inès est admise dans une classe préparatoire loin de chez elle et dans une licence dans sa ville. Elle a dressé un tableau des avantages et inconvénients : il est parfaitement équilibré. Pourtant, en pensant à la prépa, elle ressent une peur qui lui serre le ventre. Son frère lui dit : « Oublie tes émotions, raisonne ! »\n\n1. Selon Hume, la raison peut-elle trancher seule pour Inès ? Explique sa formule « la raison est, et ne doit être, que l'esclave des passions ».\n2. Que montrent les observations d'Antonio Damasio sur la capacité de décider ? Applique-les à la situation.\n3. Selon Martha Nussbaum, que « dit » la peur d'Inès ? Réponds au conseil du frère.","bareme":[{"critere":"Hume : la raison calcule les moyens, ne fixe aucune fin ; appliqué au tableau équilibré","points":6},{"critere":"Damasio : patients aux circuits émotionnels lésés incapables de décider, l'émotion condition du raisonnement","points":6},{"critere":"Nussbaum : l'émotion comme jugement de valeur (juger qu'une chose importante est menacée), réponse au frère","points":6},{"critere":"Rédaction claire et reliée à la situation","points":2}],"dureeMin":12,"corrige":"1. Non. Pour **Hume**, la raison **calcule les moyens** mais **ne fixe aucune fin** : elle peut comparer les avantages, pas dire ce qu'Inès veut vraiment. Le tableau équilibré le montre : la raison a fait son travail et ne tranche pas. Ce qui décidera, c'est ce à quoi Inès tient.\n2. **Damasio** (*L'Erreur de Descartes*, 1994) observe des patients dont les **circuits émotionnels sont lésés** et l'intelligence intacte : ils deviennent **incapables de décider**. L'émotion n'est donc pas le contraire du raisonnement, elle en est une **condition**. Sans ses émotions, Inès resterait paralysée devant son tableau.\n3. Pour **Nussbaum**, les émotions sont des **jugements de valeur** : avoir peur, c'est **juger qu'une chose importante est menacée**. La peur d'Inès lui apprend quelque chose : ce qui compte pour elle (sa famille, ses repères, ou sa réussite). Le frère a tort d'opposer émotion et raison : Inès doit plutôt se demander **ce que sa peur connaît** que son tableau ignore, puis juger si ce qui est menacé est réellement important."}$exo$::jsonb),
  ('37aff0ea-aa91-5a64-b706-3590a8a24ccc'::uuid, 3, 'redaction', $exo${"titre":"Faut-il se méfier de ce que l'on ressent ?","consigne":"Rédige un essai construit (introduction problématisée, deux ou trois parties, conclusion) en mobilisant au moins cinq références du chapitre.","enonce":"**Sujet d'essai**\n\n> Faut-il se méfier de ce que l'on ressent ?\n\nTon essai doit confronter la méfiance antique (stoïciens, Platon), le partage cartésien, la réhabilitation (Pascal, Hume, Rousseau) et le tournant contemporain (Damasio, Nussbaum). Il doit aussi tenir compte du fait que les émotions **se manipulent**.\n\nRéponds clairement dans ta conclusion.","bareme":[{"critere":"Problématique : les émotions égarent-elles ou renseignent-elles ?","points":3},{"critere":"Méfiance antique et Descartes exactement exposés (jugement faux, attelage, passions bonnes mais à ne pas subir, générosité)","points":5},{"critere":"Réhabilitation et tournant contemporain (Pascal non irrationnel, Hume, pitié rousseauiste, Damasio, Nussbaum)","points":6},{"critere":"Prise en compte de la manipulation (pathos, publicité, algorithmes et indignation)","points":3},{"critere":"Conclusion qui répond à la question","points":3}],"dureeMin":20,"corrige":"**Problématique.** Nos émotions nous égarent-elles, ou nous renseignent-elles sur ce qui compte ? Le débat s'est déplacé : non plus « faut-il obéir à ses sentiments ? » mais « que connaissent-ils que la raison seule ne connaît pas ? »\n\n**Partie 1 — Les raisons de se méfier.** Pour les **stoïciens**, la passion est un **jugement faux** : c'est l'opinion qui trouble, non la chose ; l'*apatheia* affranchit des jugements précipités. Pour **Platon**, l'âme est un **attelage** dont un cheval tire vers le bas. **Descartes** (*Les Passions de l'âme*, 1649) nuance : les passions sont « toutes bonnes de leur nature », mais il ne faut pas s'y **soumettre** ; la **générosité**, sentiment de sa propre liberté, est le remède.\n\n**Partie 2 — Les émotions renseignent.** **Pascal** : « Le cœur a ses raisons que la raison ne connaît point » — non un éloge de l'irrationnel, mais un **autre ordre de connaissance**. **Hume** : la raison est « l'esclave des passions », elle calcule les **moyens**, pas les **fins**. **Rousseau** fait de la **pitié** un fondement moral **antérieur** à la réflexion. **Damasio** montre que des patients privés d'émotions deviennent **incapables de décider**. **Nussbaum** : les émotions sont des **jugements de valeur**.\n\n**Partie 3 — Se méfier non des émotions, mais de leur exploitation.** Les émotions **renseignent**, mais elles **se manipulent** : rhétorique du *pathos*, publicité, algorithmes de recommandation qui exploitent l'**indignation** parce qu'elle retient l'attention.\n\n**Conclusion.** Il ne faut pas se méfier de ce qu'on ressent au point de le taire : l'émotion est une connaissance et une condition du choix. Il faut en revanche examiner ses émotions — se demander ce qu'elles jugent et qui a intérêt à les provoquer."}$exo$::jsonb),
  ('7a11e7fe-a29d-50be-aa9e-ac7d75246068'::uuid, 1, 'redaction', $exo${"titre":"Le beau, le sublime et le goût","consigne":"Réponds à chaque question en quelques phrases précises.","enonce":"**Questions de cours**\n\n1. Distingue, selon Kant, le **beau** et le **sublime** : ce que c'est, ce qu'on éprouve, pourquoi.\n2. Classe chacun des exemples suivants du côté du beau ou du sublime : a) un océan démonté ; b) un petit bouquet aux couleurs harmonieuses.\n3. Explique le paradoxe kantien du jugement de goût, en t'appuyant sur la différence entre « c'est beau » et « ça me plaît ».","bareme":[{"critere":"Beau (forme accordée à nos facultés, apaisement) / sublime (ce qui les excède, déplaisir puis grandeur, l'imagination échoue là où la raison conçoit)","points":8},{"critere":"Classement juste des deux exemples","points":4},{"critere":"Paradoxe : jugement subjectif (repose sur un sentiment) qui prétend à l'universalité, expliqué avec la différence entre les deux phrases","points":8}],"dureeMin":8,"corrige":"1. Le **beau** est une **forme qui s'accorde à nos facultés** : on éprouve un **apaisement**, parce que la forme est à notre mesure. Le **sublime** est ce qui **excède** nos facultés (l'océan démonté, la montagne, l'infini) : on éprouve **un déplaisir d'abord, une grandeur ensuite**, parce que **l'imagination échoue là où la raison conçoit**.\n2. a) L'océan démonté : **sublime**. b) Le bouquet harmonieux : **beau**.\n3. Le jugement esthétique est **subjectif** : il repose sur un **sentiment**, non sur un concept ou une démonstration. Mais il prétend à l'**universalité** : quand je dis « **c'est beau** », j'attends que tout le monde soit d'accord, alors que « **ça me plaît** » n'engage que moi. C'est le paradoxe : un jugement personnel qui parle au nom de tous."}$exo$::jsonb),
  ('7a11e7fe-a29d-50be-aa9e-ac7d75246068'::uuid, 2, 'redaction', $exo${"titre":"Pourquoi Hugo pleure au cinéma","consigne":"Lis la situation (inventée pour l'exercice), puis réponds en t'appuyant sur les auteurs du cours.","enonce":"**Situation**\n\n> Hugo, 17 ans, sort d'un film en larmes : l'héroïne y perd son frère. Sa sœur se moque : « Tu sais bien que c'est inventé ! » Le lendemain, Hugo remarque que la musique du film l'a bouleversé plus encore que les dialogues, alors qu'elle ne racontait rien.\n\n1. Comment s'appelle le problème que soulève la remarque de la sœur ? Formule-le.\n2. Quelle réponse Aristote apporte-t-il à ce problème ? Explique-la.\n3. Comment expliquer, avec le cours, que la musique ait bouleversé Hugo davantage que les dialogues ? Appuie-toi sur Schopenhauer.","bareme":[{"critere":"Paradoxe de la fiction nommé et formulé : pleurer sans croire à la réalité","points":5},{"critere":"Catharsis : la tragédie purge les passions en les faisant éprouver à distance protégée","points":6},{"critere":"Musique qui émeut sans représenter ; Schopenhauer : expression directe de la volonté, fond du monde","points":7},{"critere":"Rédaction claire et reliée à la situation","points":2}],"dureeMin":12,"corrige":"1. C'est le **paradoxe de la fiction** : comment peut-on éprouver une émotion véritable, et même pleurer, devant une histoire **à la réalité de laquelle on ne croit pas** ? L'émotion esthétique est-elle une vraie émotion ?\n2. **Aristote** répond par la **catharsis** : la tragédie **purge les passions** en les faisant éprouver **à distance protégée**. Hugo ressent vraiment la douleur de la perte, mais sans subir la perte : c'est ce qui rend l'émotion à la fois réelle et bienfaisante.\n3. La musique pose un problème unique : elle **émeut sans représenter**, elle ne raconte rien, et pourtant elle agit plus directement que les autres arts. Pour **Schopenhauer**, les autres arts figurent des apparences, alors que la musique est l'expression **directe de la volonté**, du fond même du monde. Les dialogues passent par la représentation d'une histoire ; la musique touche Hugo sans ce détour."}$exo$::jsonb),
  ('7a11e7fe-a29d-50be-aa9e-ac7d75246068'::uuid, 3, 'redaction', $exo${"titre":"Le goût musical est-il personnel ?","consigne":"Rédige un essai construit (introduction problématisée, deux ou trois parties, conclusion) en mobilisant au moins quatre auteurs du chapitre.","enonce":"**Sujet d'essai**\n\n> Nos goûts musicaux nous appartiennent-ils ?\n\nMobilise au moins quatre références parmi : Kant (le jugement de goût), Bourdieu (*La Distinction*), Adorno (l'industrie culturelle), Platon (la musique et l'âme). Termine en discutant l'idée du cours selon laquelle « la sensibilité s'éduque ».\n\nRéponds clairement dans ta conclusion.","bareme":[{"critere":"Problématique : le goût vécu comme intime face à ce qui le détermine","points":3},{"critere":"Kant : jugement subjectif qui prétend à l'universalité","points":4},{"critere":"Bourdieu (goûts marqueurs sociaux) et Adorno (écoute standardisée, formatée) exactement exposés","points":6},{"critere":"Platon et la sensibilité qui s'éduque, reliés à la question","points":4},{"critere":"Conclusion qui répond à la question","points":3}],"dureeMin":20,"corrige":"**Problématique.** Rien ne semble plus personnel qu'un goût musical : on aime une chanson sans savoir pourquoi. Mais si ce goût dépend de notre milieu et de ce qu'on nous fait écouter, est-il encore le nôtre ?\n\n**Partie 1 — Un goût personnel qui parle au nom de tous.** Pour **Kant**, le jugement de goût est **subjectif** (il repose sur un sentiment) mais prétend à l'**universalité** : on dit « c'est beau », pas « ça me plaît ». Le goût est donc intime, et pourtant il ne se vit pas comme un simple caprice.\n\n**Partie 2 — Un goût socialement fabriqué.** **Bourdieu** (*La Distinction*, 1979) montre que les goûts musicaux sont des **marqueurs sociaux** : ce qu'on trouve beau dit **d'où l'on vient**. **Adorno** dénonce l'« **industrie culturelle** » qui **standardise** l'écoute : la musique de masse ne libère pas la sensibilité, elle la **formate**. Déjà **Platon** voyait dans la musique une **éducation de l'âme**, donc une affaire politique : ce qu'on écoute nous façonne.\n\n**Partie 3 — Un goût qui peut devenir le nôtre.** Si la **sensibilité s'éduque**, alors entendre une œuvre difficile n'est pas un don mais le résultat d'un **apprentissage**. Reconnaître ce qui détermine nos goûts est le premier pas pour les choisir.\n\n**Conclusion.** Nos goûts musicaux ne nous appartiennent pas d'emblée : ils portent la marque de notre milieu et de l'industrie. Mais ils peuvent devenir les nôtres par l'éducation de la sensibilité — un goût est moins une propriété qu'une conquête."}$exo$::jsonb),
  ('9667b134-4db8-5573-88b0-16ab3f9ea2a6'::uuid, 1, 'redaction', $exo${"titre":"Les cinq étapes du « je »","consigne":"Réponds à chaque question avec précision.","enonce":"**Questions de cours**\n\nVoici cinq figures du moi, dans le désordre :\n- a) un **fondement** ;\n- b) un **soupçon** ;\n- c) un **dedans** ;\n- d) rien d'intime ;\n- e) un **objet d'étude**.\n\n1. Remets-les dans l'ordre chronologique et associe à chacune l'auteur (ou les auteurs) et l'époque du cours.\n2. Explique en deux ou trois phrases ce que devient le moi chez Montaigne, en citant sa formule sur le « passage ».","bareme":[{"critere":"Ordre chronologique juste : d, c, e, a, b","points":5},{"critere":"Auteurs et époques justes (Socrate / Augustin IVe s. / Montaigne 1580 / Descartes 1637 / Marx, Nietzsche, Freud XIXe-XXe)","points":8},{"critere":"Montaigne : moi mouvant, contradictoire, « je ne peins pas l'être, je peins le passage », une qualité et non un défaut","points":7}],"dureeMin":8,"corrige":"1. Ordre : **d → c → e → a → b**.\n- d) **Rien d'intime** : **Socrate**, Antiquité — « connais-toi » invite à mesurer ce qu'on sait et ce qu'on ignore.\n- c) **Un dedans** : **Augustin**, *Confessions*, IVe siècle.\n- e) **Un objet d'étude** : **Montaigne**, *Essais*, 1580 — « je suis moi-même la matière de mon livre ».\n- a) **Un fondement** : **Descartes**, *cogito*, 1637 — une substance pensante transparente à elle-même.\n- b) **Un soupçon** : **Marx, Nietzsche, Freud**, XIXe-XXe siècles — le moi n'est plus transparent.\n2. Chez Montaigne, le moi **n'est pas stable** : « Je ne peins pas l'être, je peins le **passage**. » Il est **mouvant, contradictoire, saisi dans le temps**. C'est la première fois qu'un auteur en fait une **qualité** et non un défaut."}$exo$::jsonb),
  ('9667b134-4db8-5573-88b0-16ab3f9ea2a6'::uuid, 2, 'redaction', $exo${"titre":"Les trois blessures narcissiques","consigne":"Réponds à chaque question en rédigeant, avec les notions du cours.","enonce":"**Situation**\n\n> Dans un débat en classe, Yanis affirme : « L'homme a toujours eu raison de se croire au centre de tout : il est le seul à penser, et il sait ce qu'il pense. »\n\n1. Présente les **trois blessures narcissiques** décrites par Freud : pour chacune, dis ce qu'elle retire à l'homme.\n2. Laquelle de ces blessures contredit la dernière partie de la phrase de Yanis (« il sait ce qu'il pense ») ? Explique pourquoi elle atteint directement le moi cartésien.\n3. Montre que Marx et Nietzsche prolongent ce soupçon, chacun à sa manière.","bareme":[{"critere":"Copernic (la Terre pas au centre), Darwin (l'homme pas d'une autre nature que l'animal), psychanalyse (le moi pas maître dans sa maison)","points":7},{"critere":"La psychanalyse contre la transparence du cogito cartésien, expliqué","points":6},{"critere":"Marx (conscience déterminée par les conditions matérielles) et Nietzsche (le « je » fiction grammaticale)","points":5},{"critere":"Rédaction reliée à la phrase de Yanis","points":2}],"dureeMin":12,"corrige":"1. **Copernic** : la Terre **n'est pas au centre** du monde. **Darwin** : l'homme **n'est pas d'une autre nature que l'animal**. **La psychanalyse** : le moi « **n'est pas maître dans sa propre maison** ».\n2. C'est la **troisième blessure**, la psychanalyse. Chez **Descartes**, le moi est une **substance pensante, transparente à elle-même** : je peux douter de tout, sauf que je pense, et je sais ce que je pense. Freud montre qu'une part de nos pensées et de nos actes est **inconsciente** : le moi ne sait pas tout ce qu'il pense. Yanis reprend donc exactement la **transparence** que les siècles suivants ont démolie.\n3. **Marx** : la conscience est **déterminée par les conditions matérielles d'existence** — ce que je pense dépend de ma place dans la société. **Nietzsche** : le « je » est une **fiction grammaticale**, une cause inventée derrière l'action. Chacun retire au moi son statut de fondement."}$exo$::jsonb),
  ('9667b134-4db8-5573-88b0-16ab3f9ea2a6'::uuid, 3, 'redaction', $exo${"titre":"Le moi est-il une invention de l'histoire ?","consigne":"Rédige un essai construit (introduction problématisée, deux ou trois parties, conclusion) en mobilisant au moins cinq références du chapitre.","enonce":"**Sujet d'essai**\n\n> Le moi a-t-il toujours existé ?\n\nTon essai doit s'appuyer sur l'histoire du « je » vue en cours (de Socrate à Descartes), sur les soupçons du XIXe et du XXe siècle (Marx, Nietzsche, Freud, Sartre) et sur ce que devient le moi aujourd'hui (mise en scène, exposition).\n\nRéponds clairement dans ta conclusion.","bareme":[{"critere":"Problématique : évidence intime du moi / résultat d'une histoire","points":3},{"critere":"Histoire du « je » exacte : Socrate, Augustin, Montaigne, Descartes, et ce que chacun fait du moi","points":6},{"critere":"Soupçons et renversement : Marx, Nietzsche, Freud, Sartre (l'existence précède l'essence)","points":5},{"critere":"Le moi contemporain : exposition, image à administrer, relié à la question","points":3},{"critere":"Conclusion qui répond à la question","points":3}],"dureeMin":20,"corrige":"**Problématique.** Le moi nous semble une **évidence intime** : chacun a un « je ». Mais la forme que nous lui connaissons est peut-être le résultat d'une histoire. Le moi est-il une réalité permanente, ou une construction historique ?\n\n**Partie 1 — Une histoire du « je ».** Chez **Socrate**, « connais-toi » n'a **rien d'intime** : il s'agit de mesurer ce qu'on sait et ce qu'on ignore. **Augustin** (*Confessions*, IVe s.) invente un **dedans** où chercher la vérité. **Montaigne** (1580) fait du moi un **objet d'étude** (« je suis moi-même la matière de mon livre »), mouvant : « je peins le passage ». **Descartes** (1637) en fait un **fondement** : une substance pensante transparente à elle-même.\n\n**Partie 2 — Le soupçon.** **Marx** : la conscience est déterminée par les conditions matérielles. **Nietzsche** : le « je » est une **fiction grammaticale**. **Freud** : le moi n'est pas maître dans sa propre maison. **Sartre** renverse : l'homme **n'a pas de nature**, « l'existence précède l'essence » — le moi n'est pas donné, il se fait.\n\n**Partie 3 — Aujourd'hui.** Le moi se **met en scène** : profils, avatars, récits de soi. Ce qui était examen intérieur devient **exposition** : le moi est peut-être moins un secret à découvrir qu'une **image à administrer**.\n\n**Conclusion.** Le moi, tel que nous le vivons, n'a pas toujours existé : chaque époque en a produit une figure. Cela ne le rend pas irréel — mais cela interdit de le tenir pour une évidence naturelle."}$exo$::jsonb),
  ('a75fbd39-ecee-50e0-8bb6-4171a4931cc6'::uuid, 1, 'redaction', $exo${"titre":"Sexe, genre et la formule de Beauvoir","consigne":"Réponds à chaque question en quelques phrases précises.","enonce":"**Questions de cours**\n\n1. Quelle double exigence le mot « identité » contient-il ?\n2. Distingue le **sexe** et le **genre**.\n3. Explique la formule de Simone de Beauvoir (1949) : « On ne naît pas femme : on le devient ».","bareme":[{"critere":"Identité : ce qui reste identique dans le temps et ce qui distingue de tous les autres","points":5},{"critere":"Sexe (caractères biologiques) / genre (rôles, conduites, attentes qu'une société y associe)","points":7},{"critere":"Beauvoir : la féminité produit de l'histoire, non une essence ; ce qui est construit peut être défait","points":8}],"dureeMin":7,"corrige":"1. L'identité désigne à la fois ce qui reste **identique dans le temps** et ce qui **distingue de tous les autres**.\n2. Le **sexe** désigne les **caractères biologiques**. Le **genre** désigne les **rôles, conduites et attentes** qu'une société associe à ces caractères.\n3. Pour **Beauvoir** (*Le Deuxième Sexe*, 1949), la **féminité** n'est pas une essence donnée à la naissance : elle est un **produit de l'histoire** et de la société, qui apprend aux filles à devenir « femmes ». Conséquence : ce qui est **construit** peut être **défait**."}$exo$::jsonb),
  ('a75fbd39-ecee-50e0-8bb6-4171a4931cc6'::uuid, 2, 'redaction', $exo${"titre":"Le même homme ?","consigne":"Lis la situation (inventée pour l'exercice), puis réponds en t'appuyant sur les trois penseurs de l'identité personnelle vus en cours.","enonce":"**Situation**\n\n> Marc, 50 ans, a été gravement blessé dans un accident. Il a perdu presque tous ses souvenirs des vingt dernières années. Ses goûts ont changé, son caractère aussi. Pourtant, dès qu'il a pu, il a repris la tâche qu'il avait promis à sa fille d'accomplir avant l'accident : l'accompagner dans son projet de restaurant.\n\n1. Selon **Locke**, Marc est-il encore la même personne ? Explique sur quoi Locke fonde l'identité et la difficulté que révèle ce cas.\n2. Que dirait **Hume** de la recherche d'un « vrai » Marc derrière ses perceptions ?\n3. Avec la distinction de **Ricœur** entre *idem* et *ipse*, montre en quel sens Marc est resté lui-même.","bareme":[{"critere":"Locke : identité fondée sur la conscience et la mémoire ; la perte de mémoire pose la difficulté","points":6},{"critere":"Hume : seulement un faisceau de perceptions, l'unité du moi fiction utile","points":5},{"critere":"Ricœur : idem (mêmeté) perdu, ipse (tenir sa promesse) conservé, identité narrative","points":7},{"critere":"Rédaction reliée au cas de Marc","points":2}],"dureeMin":12,"corrige":"1. Pour **Locke**, l'identité personnelle tient à la **conscience**, qui relie les moments de la vie par la **mémoire**. Marc ayant perdu vingt ans de souvenirs, la conscience ne relie plus ces années à son présent : selon Locke, il n'est plus tout à fait la même personne pour cette période. C'est la difficulté du cours : **que devient l'identité quand la mémoire manque ?**\n2. Pour **Hume**, chercher un « vrai » Marc est vain : quand on cherche son moi, on ne trouve qu'**un faisceau de perceptions**, jamais un moi. L'unité de Marc — avant comme après l'accident — serait une **fiction utile**.\n3. **Ricœur** distingue l'***idem***, la **mêmeté** (rester le même : goûts, caractère, souvenirs) et l'***ipse***, l'**ipséité** (se tenir à ses promesses). Marc a perdu une grande part de sa mêmeté, mais il **tient sa promesse** : il reste lui-même au sens de l'ipséité. On peut changer entièrement et rester fidèle : c'est l'**identité narrative**, le récit qui noue les deux."}$exo$::jsonb),
  ('a75fbd39-ecee-50e0-8bb6-4171a4931cc6'::uuid, 3, 'redaction', $exo${"titre":"Ce qui est construit est-il facile à défaire ?","consigne":"Rédige un essai construit (introduction problématisée, deux ou trois parties, conclusion) en mobilisant au moins quatre références du chapitre.","enonce":"**Sujet d'essai**\n\n> Dire que notre identité est construite, est-ce dire que nous pouvons la choisir ?\n\nMobilise au moins : Beauvoir, Butler (la performativité), le point de méthode du cours sur la construction sociale, Sartre (*Réflexions sur la question juive*) et Amin Maalouf. Tu peux t'appuyer sur un exemple littéraire du cours.\n\nRéponds clairement dans ta conclusion.","bareme":[{"critere":"Problématique : construit ne veut pas dire choisi, faux ou facile à défaire","points":3},{"critere":"Beauvoir et Butler exactement exposés (devenir femme ; le genre comme série d'actes répétés)","points":5},{"critere":"Point de méthode : une construction sociale est réelle et contraignante","points":4},{"critere":"Sartre (identité subie par le regard d'autrui) et Maalouf (identité réduite à une appartenance, meurtrière)","points":5},{"critere":"Conclusion qui répond à la question","points":3}],"dureeMin":20,"corrige":"**Problématique.** Si l'identité n'est pas une nature, il semble qu'on puisse la choisir. Mais ce qui est construit par la société peut peser plus lourd qu'une nature. Construit veut-il dire libre ?\n\n**Partie 1 — Une identité qui se fait.** **Beauvoir** : « On ne naît pas femme : on le devient » — la féminité est un produit de l'histoire, non une essence. **Butler** (*Trouble dans le genre*, 1990) radicalise : le genre n'est pas ce que l'on **est**, c'est ce que l'on **fait**, une **série d'actes répétés** qui finissent par produire l'illusion d'une nature. Ce qui est fait peut donc être refait autrement.\n\n**Partie 2 — Mais construit ne veut pas dire choisi.** Point de méthode décisif : dire qu'une chose est **construite** ne signifie pas qu'elle est **fausse** ou **facile à défaire**. Une construction sociale est **réelle et contraignante** — c'est même à cela qu'on la reconnaît. **Sartre** montre qu'une identité peut être **subie** avant d'être choisie : c'est le **regard de l'antisémite qui fait le Juif**. **Amin Maalouf** (*Les Identités meurtrières*, 1998) met en garde : réduite à une **seule appartenance**, l'identité devient meurtrière.\n\n**Exemple.** *Orlando* de Virginia Woolf, dont le personnage traverse les siècles et change de sexe : la fiction imagine une identité mobile, justement parce que la réalité la fixe.\n\n**Conclusion.** Que l'identité soit construite ouvre une liberté — ce qui a été fait peut être défait —, mais cette liberté est lente et limitée : elle s'exerce contre des constructions réelles et contre le regard des autres. Construit ne veut pas dire choisi ; cela veut dire **transformable**."}$exo$::jsonb),
  ('0534bd63-d404-5338-870b-1d39fdb6ca01'::uuid, 1, 'redaction', $exo${"titre":"Les gueules cassées et le visage","consigne":"Réponds à chaque question en quelques phrases précises.","enonce":"**Questions de cours**\n\n1. Qui appelle-t-on les « gueules cassées » ? Pourquoi la mutilation du visage attaque-t-elle l'identité elle-même ?\n2. Que représente le **visage** d'autrui pour Emmanuel Levinas ?\n3. Dans *Au revoir là-haut* de Pierre Lemaitre, que fait le héros défiguré, et que signifie ce geste selon le cours ?","bareme":[{"critere":"Survivants de la Première Guerre mondiale au visage détruit ; le visage est ce par quoi on est reconnu","points":7},{"critere":"Levinas : le visage n'est pas un objet, il m'oblige, il dit « tu ne tueras point »","points":7},{"critere":"Les masques : devenir une image faute de redevenir un visage","points":6}],"dureeMin":7,"corrige":"1. Ce sont des **survivants de la Première Guerre mondiale** dont le **visage a été détruit**. Le visage étant ce par quoi on est **reconnu**, sa mutilation n'atteint pas seulement le corps : elle attaque l'**identité** elle-même.\n2. Pour **Levinas**, le visage d'autrui **n'est pas un objet** : c'est ce qui m'**oblige**, ce qui me dit « **tu ne tueras point** ». Détruire un visage, c'est donc plus que blesser un corps.\n3. Dans *Au revoir là-haut* (2013), le héros défiguré se fabrique des **masques**. Selon le cours, il tente de **devenir une image faute de redevenir un visage** : il ne peut plus être reconnu, il se donne une apparence."}$exo$::jsonb),
  ('0534bd63-d404-5338-870b-1d39fdb6ca01'::uuid, 2, 'redaction', $exo${"titre":"La caméra de l'internat","consigne":"Lis la situation (inventée pour l'exercice), puis réponds avec les analyses de Foucault vues en cours.","enonce":"**Situation**\n\n> Dans un internat, la direction installe dans le couloir une caméra reliée à un écran du bureau du surveillant. Personne ne sait si le surveillant regarde l'écran, ni à quel moment. Au bout de quelques semaines, les internes ne sortent plus de leur chambre après l'extinction des feux — même les soirs où le surveillant est absent.\n\n1. À quel dispositif décrit par Foucault cette situation fait-elle penser ? Qui l'a imaginé ?\n2. Explique, à partir de la dernière phrase de la situation, pourquoi le pouvoir devient « intérieur ».\n3. Compare la peine ancienne et la prison moderne selon *Surveiller et punir* : ce que chacune vise et ses moyens.","bareme":[{"critere":"Panoptique de Bentham identifié","points":4},{"critere":"Savoir qu'on peut être vu sans savoir quand : on finit par se surveiller soi-même, appliqué aux internes","points":7},{"critere":"Peine ancienne (le corps, spectacle du supplice, échafaud) / prison moderne (l'âme, discipline, emploi du temps, surveillance continue)","points":7},{"critere":"Rédaction reliée à la situation","points":2}],"dureeMin":11,"corrige":"1. C'est le **panoptique**, imaginé par **Bentham**, que **Foucault** analyse dans *Surveiller et punir* (1975).\n2. Dans le panoptique, le détenu sait qu'il **peut** être vu à tout moment sans savoir **quand** : il finit par **se surveiller lui-même**. Les internes obéissent même quand personne ne regarde : la surveillance n'a plus besoin d'être réelle, elle est devenue une disposition intérieure. Le pouvoir devient **intérieur** — c'est son **économie** : il coûte moins qu'un surveillant permanent.\n3. La **peine ancienne** vise le **corps** du supplicié ; ses moyens sont le **spectacle du supplice** ; son modèle est l'**échafaud**. La **prison moderne** vise l'**âme** ; ses moyens sont la **discipline**, l'**emploi du temps**, la **surveillance continue** ; son modèle est le **panoptique**."}$exo$::jsonb),
  ('0534bd63-d404-5338-870b-1d39fdb6ca01'::uuid, 3, 'redaction', $exo${"titre":"Que reste-t-il du moi ?","consigne":"Rédige un essai construit (introduction problématisée, deux ou trois parties, conclusion) en mobilisant au moins quatre références du chapitre.","enonce":"**Sujet d'essai**\n\n> Que reste-t-il du moi lorsqu'on lui retire son corps intact, sa liberté ou son nom ?\n\nMobilise au moins : Merleau-Ponty (le corps), une œuvre sur la guerre, Foucault (la détention), Primo Levi et Robert Antelme.\n\nRéponds clairement dans ta conclusion.","bareme":[{"critere":"Problématique : le moi forteresse intérieure ou moi tenant à ses conditions","points":3},{"critere":"Corps et mutilation : Merleau-Ponty (on est son corps, membre fantôme), gueules cassées, une œuvre du cours","points":5},{"critere":"Détention : Foucault, la peine qui vise l'âme, le pouvoir intériorisé","points":4},{"critere":"Levi (démolition d'un homme, numéro) et Antelme (une seule espèce humaine), et la résistance par le témoignage","points":5},{"critere":"Conclusion qui répond à la question","points":3}],"dureeMin":20,"corrige":"**Problématique.** On aime penser le moi comme une forteresse intérieure que rien d'extérieur n'atteint. Mais la guerre, la prison et le camp montrent qu'on peut défaire un homme en lui retirant son corps, sa liberté, son nom. Le moi survit-il à ces épreuves ?\n\n**Partie 1 — Le moi tient à un corps.** **Merleau-Ponty** : on n'**a** pas un corps comme un objet, on **est** son corps, par lequel on habite le monde. La mutilation reconfigure donc le **rapport au monde** ; le **membre fantôme** montre que le corps vécu ne coïncide pas avec le corps objectif. Les **gueules cassées** perdent le visage par lequel on est reconnu ; *Au revoir là-haut* (Lemaitre, 2013) montre un héros qui se réfugie derrière des **masques**. *Le Feu* (Barbusse, 1916) et *À l'Ouest, rien de nouveau* (Remarque, 1929) montrent la guerre depuis la tranchée et une génération sacrifiée.\n\n**Partie 2 — Le moi tient à une liberté et à un nom.** **Foucault** : la prison moderne vise l'**âme** par la discipline et la surveillance ; le pouvoir devient intérieur. **Primo Levi** (*Si c'est un homme*, 1947) décrit la « **démolition d'un homme** » : le nom remplacé par un **numéro**, les cheveux, les vêtements, le langage retirés.\n\n**Partie 3 — Et pourtant il résiste.** **Robert Antelme** (*L'Espèce humaine*, 1947) établit qu'il n'existe **pas plusieurs espèces humaines** — ce que le bourreau tentait précisément de nier. Les témoignages existent : **écrire est déjà une reconquête**.\n\n**Conclusion.** Le moi n'est pas une forteresse indépendante des conditions : il tient à un corps, à un nom, à un regard, et peut être détruit. Mais il reste la capacité de témoigner et de maintenir l'unité de l'espèce humaine : c'est ce qui en reste, et ce n'est pas rien."}$exo$::jsonb),
  ('245d7288-4db0-5e78-847e-1826becffcfe'::uuid, 1, 'redaction', $exo${"titre":"Induction et réfutabilité","consigne":"Réponds à chaque question en quelques phrases précises.","enonce":"**Questions de cours**\n\n1. Qu'est-ce que le **problème de l'induction** posé par Hume ? Illustre-le par l'exemple du soleil.\n2. Quel critère Popper propose-t-il pour distinguer une théorie scientifique ? Comment la science progresse-t-elle selon lui ?\n3. Pourquoi une théorie « réfutable » n'est-elle pas une théorie « fausse » ? Et pourquoi une théorie qui explique tout n'est-elle pas plus forte ?","bareme":[{"critere":"Problème de l'induction : aucune série d'observations ne prouve une loi générale ; exemple du soleil ; la science repose sur un pari","points":7},{"critere":"Popper : réfutabilité et non vérifiabilité ; conjectures et réfutations","points":6},{"critere":"Réfutable = qui pourrait être démenti, pas démenti ; une théorie qui explique tout est hors du champ scientifique","points":7}],"dureeMin":8,"corrige":"1. **Hume** montre qu'**aucun nombre d'observations ne prouve une loi générale**. Que le soleil se soit levé chaque jour n'implique pas qu'il se lèvera demain. Toute science empirique repose donc sur un **pari**.\n2. Pour **Popper**, une théorie est scientifique parce qu'elle est **réfutable** — elle pourrait être démentie par un fait —, et non parce qu'elle serait vérifiable. La science progresse par « **conjectures et réfutations** ».\n3. **Réfutable** ne veut pas dire **faux** : cela veut dire qu'on peut imaginer une observation qui la démentirait, et qu'on la met à l'épreuve ; tant qu'elle résiste, on la garde. Une théorie qui **explique tout**, quel que soit le fait observé, ne peut jamais être démentie : elle n'est pas plus forte, elle est **hors du champ scientifique**."}$exo$::jsonb),
  ('245d7288-4db0-5e78-847e-1826becffcfe'::uuid, 2, 'redaction', $exo${"titre":"Trois affirmations au crible","consigne":"Lis les affirmations (inventées pour l'exercice), puis réponds avec les critères du cours.","enonce":"**Trois affirmations**\n\n> A. « Tous les corbeaux de cette forêt sont noirs : nous en avons observé deux mille. »\n> B. « Cette semaine, il vous arrivera quelque chose d'important. » (horoscope)\n> C. « Les mesures montrent que la température moyenne de la région a augmenté de 1,5 °C en cinquante ans. Il faut donc interdire les voitures en ville. »\n\n1. L'affirmation A est-elle prouvée ? Réponds avec le problème de l'induction, puis dis ce qui pourrait la démentir.\n2. L'affirmation B est-elle réfutable au sens de Popper ? Justifie.\n3. Dans l'affirmation C, distingue ce que la science établit et ce qu'elle n'établit pas. Appuie-toi sur Hume et Weber.","bareme":[{"critere":"A non prouvée (induction), mais réfutable : un seul corbeau d'une autre couleur la démentirait","points":6},{"critere":"B non réfutable : aucun fait ne peut la démentir, hors du champ scientifique","points":5},{"critere":"C : le fait (ce qui est) distingué de la décision (ce qui doit être) ; Hume, neutralité axiologique de Weber","points":7},{"critere":"Rédaction claire et justifiée","points":2}],"dureeMin":12,"corrige":"1. Non. Selon **Hume**, **aucun nombre d'observations** ne prouve une loi générale : deux mille corbeaux noirs n'impliquent pas que le deux-mille-unième le sera. Mais l'affirmation est **réfutable** : l'observation d'**un seul** corbeau d'une autre couleur dans cette forêt suffirait à la démentir. C'est ce qui en fait une hypothèse scientifique.\n2. Non. « Quelque chose d'important » peut désigner n'importe quel événement : **aucun fait** ne peut démentir cette phrase. Elle « explique tout », donc **rien** : elle est hors du champ scientifique au sens de **Popper**.\n3. La science établit **ce qui est** : une hausse mesurée de 1,5 °C. Elle n'établit pas **ce qui doit être** : interdire les voitures est une **politique**, un choix de valeurs. **Hume** : on ne déduit pas un **devoir** d'un **fait**. **Weber** en tire la **neutralité axiologique** du savant : ne pas confondre sa chaire et sa tribune. La donnée climatique peut éclairer la décision, elle ne la dicte pas."}$exo$::jsonb),
  ('245d7288-4db0-5e78-847e-1826becffcfe'::uuid, 3, 'redaction', $exo${"titre":"Sur quoi repose l'autorité de la science ?","consigne":"Rédige un essai construit (introduction problématisée, deux ou trois parties, conclusion) en mobilisant au moins quatre références du chapitre.","enonce":"**Sujet d'essai**\n\n> Faut-il croire la science sur parole ?\n\nMobilise : le problème de l'induction (Hume), Popper, Kuhn, Bachelard, et la distinction entre ce qui est et ce qui doit être. Tiens compte des défis contemporains (crise de la reproductibilité, expertise contestée, désinformation).\n\nAttention aux trois confusions signalées par le cours (réfutable, paradigme, construit). Réponds clairement dans ta conclusion.","bareme":[{"critere":"Problématique : autorité de la science et limites de ce qu'elle garantit","points":3},{"critere":"Hume, Popper, Kuhn et Bachelard exposés sans les trois confusions (réfutable ≠ faux, paradigme ≠ opinion, construit ≠ arbitraire)","points":7},{"critere":"Ce que la science ne dit pas : fait / devoir, Weber","points":4},{"critere":"Réponse aux défis contemporains : exposer la méthode plutôt que renforcer l'autorité","points":3},{"critere":"Conclusion qui répond à la question","points":3}],"dureeMin":20,"corrige":"**Problématique.** On croit la science sur parole là où l'on discute tout le reste. Mais si aucune loi n'est jamais définitivement prouvée, sur quoi repose cette confiance ? Et que ne garantit-elle pas ?\n\n**Partie 1 — La science ne prouve pas définitivement.** **Hume** : aucun nombre d'observations ne prouve une loi générale ; la science repose sur un **pari**. **Popper** : une théorie est scientifique parce qu'elle est **réfutable** — ce qui ne veut pas dire fausse ; elle progresse par conjectures et réfutations. **Kuhn** : la science ordinaire travaille dans un **paradigme** — un cadre partagé de problèmes et de méthodes, pas une opinion — qui bascule quand les anomalies s'accumulent. **Bachelard** : le savoir se construit **contre** l'expérience première ; « le fait scientifique est conquis, construit, constaté » — construit, non arbitraire.\n\n**Partie 2 — La science ne dit pas ce qu'il faut faire.** Elle établit **ce qui est**, pas **ce qui doit être** : une donnée climatique n'énonce aucune politique, une possibilité technique n'est pas une permission. **Hume** : on ne déduit pas un devoir d'un fait. **Weber** : **neutralité axiologique** du savant.\n\n**Partie 3 — Une confiance fondée sur la méthode.** Face à la crise de la reproductibilité, à l'expertise contestée et à la désinformation, la réponse n'est pas de **renforcer l'autorité** mais d'**exposer la méthode** : ce qui distingue une science, c'est qu'elle expose ce qui pourrait la démentir.\n\n**Conclusion.** Non, il ne faut pas croire la science sur parole : il faut lui faire confiance **pour de bonnes raisons** — parce qu'elle s'expose à la réfutation — et dans ses limites — elle dit ce qui est, jamais à elle seule ce qu'il faut faire."}$exo$::jsonb),
  ('1b407335-9135-5de3-9afd-9e5cd66da90d'::uuid, 1, 'redaction', $exo${"titre":"La fin de l'imitation","consigne":"Réponds à chaque question en quelques phrases précises.","enonce":"**Questions de cours**\n\n1. Comment l'art était-il défini depuis Aristote ? Quelle invention rend cette fonction techniquement caduque, et en quelle année ?\n2. Qu'abandonnent respectivement l'impressionnisme, le cubisme et l'abstraction ?\n3. Qu'est-ce que *Fountain* de Duchamp (1917) et quelle question le ready-made déplace-t-il ?","bareme":[{"critere":"Mimesis, imitation de la nature ; la photographie (1839)","points":6},{"critere":"Impressionnisme (la ligne, le fini), cubisme (le point de vue unique), abstraction (le sujet)","points":6},{"critere":"Urinoir renversé et signé ; ce n'est plus le faire mais le choix et le contexte qui font l'œuvre, le musée devient l'opérateur","points":8}],"dureeMin":7,"corrige":"1. Depuis Aristote, l'art était ***mimesis***, **imitation de la nature**. La **photographie** (**1839**) rend cette fonction techniquement caduque : si la machine copie mieux, l'art doit chercher ailleurs.\n2. L'**impressionnisme** abandonne **la ligne, le fini** ; le **cubisme**, **le point de vue unique** ; l'**abstraction**, **le sujet lui-même**. Le tableau cesse d'être une **fenêtre** pour devenir une **surface**.\n3. *Fountain* est un **urinoir renversé et signé**. Le ready-made déplace la question : ce n'est plus le **faire** (le savoir-faire) qui fait l'œuvre, c'est le **choix** et le **contexte de présentation**. Le **musée** devient l'opérateur."}$exo$::jsonb),
  ('1b407335-9135-5de3-9afd-9e5cd66da90d'::uuid, 2, 'redaction', $exo${"titre":"Le caddie de Maëlle","consigne":"Lis la situation (inventée pour l'exercice), puis réponds en t'appuyant sur les penseurs du cours.","enonce":"**Situation**\n\n> L'artiste Maëlle expose dans un musée d'art contemporain un caddie de supermarché, identique à ceux du parking. Un visiteur s'agace : « Je pourrais faire pareil ! Et d'ailleurs, quelle différence avec celui de dehors ? »\n\n1. De quel geste artistique du XXe siècle Maëlle s'inscrit-elle dans la lignée ? Explique ce qu'il a changé.\n2. Réponds à la question « quelle différence avec celui de dehors ? » avec Arthur Danto.\n3. Quelle réponse George Dickie donnerait-il ? Montre la limite de cette réponse à partir de la question centrale du chapitre.","bareme":[{"critere":"Ready-made de Duchamp (Fountain, 1917) : le choix et le contexte font l'œuvre","points":5},{"critere":"Danto (Boîtes Brillo) : rien de visible ne distingue l'œuvre du produit, la différence est théorique","points":6},{"critere":"Dickie : définition institutionnelle ; limite expliquée (par quoi l'art est-il défini ?)","points":7},{"critere":"Rédaction reliée à la situation","points":2}],"dureeMin":12,"corrige":"1. Maëlle s'inscrit dans la lignée du **ready-made** de **Duchamp** (*Fountain*, 1917, un urinoir renversé et signé). Ce geste a déplacé la question : ce n'est plus le **faire** qui fait l'œuvre, c'est le **choix** et le **contexte de présentation**. Le visiteur a raison de dire qu'il « pourrait faire pareil » : le savoir-faire n'est plus le critère.\n2. **Danto**, devant les *Boîtes Brillo* de Warhol (1964), constate que **rien de visible** ne distingue l'œuvre du produit : la différence est **théorique**. Le caddie du musée et celui du parking sont identiques à l'œil ; ce qui les sépare, c'est la théorie et l'histoire de l'art qui permettent de voir l'un comme une œuvre.\n3. **Dickie** propose une définition **institutionnelle** : est art ce qu'un **monde de l'art** traite comme tel. Le caddie est une œuvre parce que le musée l'expose. Limite : cette réponse dit **qui** décide, pas **pourquoi**. Si l'art n'est plus défini par le savoir-faire ni par la beauté, **par quoi l'est-il ?** — la définition institutionnelle constate le fait sans le justifier."}$exo$::jsonb),
  ('1b407335-9135-5de3-9afd-9e5cd66da90d'::uuid, 3, 'redaction', $exo${"titre":"Une transgression qui devient canonique reste-t-elle une transgression ?","consigne":"Rédige un essai construit (introduction problématisée, deux ou trois parties, conclusion) en mobilisant au moins quatre références du chapitre.","enonce":"**Sujet d'essai**\n\n> L'art contemporain peut-il encore rompre avec la tradition ?\n\nMobilise : la fin de l'imitation, Duchamp, au moins deux penseurs parmi Danto, Dickie, Benjamin et Adorno, et le constat que les avant-gardes ont fini au musée.\n\nRéponds clairement dans ta conclusion.","bareme":[{"critere":"Problématique : la rupture devenue norme","points":3},{"critere":"Les ruptures exposées : fin de la mimesis (photographie), mouvements, ready-made","points":5},{"critere":"Deux penseurs au moins exactement exposés (Danto, Dickie, Benjamin et l'aura, Adorno et la standardisation)","points":5},{"critere":"La rupture comme institution : avant-gardes enseignées, cotées, patrimonialisées ; continuité de la question","points":4},{"critere":"Conclusion qui répond à la question","points":3}],"dureeMin":20,"corrige":"**Problématique.** L'art du XXe siècle s'est défini **contre** : contre l'imitation, contre le métier, contre le musée. Mais si rompre est devenu la règle, la rupture est-elle encore possible, ou est-elle devenue une tradition ?\n\n**Partie 1 — Un art qui rompt.** Depuis Aristote, l'art était *mimesis* ; la **photographie** (1839) rend l'imitation caduque. L'impressionnisme abandonne la ligne, le cubisme le point de vue unique, l'abstraction le sujet. **Duchamp** (*Fountain*, 1917) rompt avec le savoir-faire : le **choix** et le contexte font l'œuvre. **Danto** : devant les *Boîtes Brillo*, rien de visible ne distingue l'œuvre du produit. **Dickie** : est art ce qu'un monde de l'art traite comme tel.\n\n**Partie 2 — La rupture récupérée.** Les avant-gardes ont fini au **musée** : ce qui devait scandaliser est enseigné, coté, patrimonialisé. **Benjamin** : la reproduction fait perdre l'**aura**, mais c'est une chance politique — l'art sort du culte pour entrer dans l'usage. **Adorno** : la culture de masse **standardise** ; l'art ne résiste qu'en n'étant pas immédiatement consommable — or une transgression devenue canonique est consommée.\n\n**Partie 3 — Une continuité de la question.** Une transgression qui devient canonique cesse d'être une transgression. Mais peut-être que la vraie continuité de l'art contemporain est celle de la **question** qu'il pose — qu'est-ce que l'art ? — non de la réponse qu'il donne.\n\n**Conclusion.** L'art contemporain ne peut plus rompre comme au début du siècle : la rupture est devenue une norme. Il continue pourtant à interroger ses propres limites, et c'est dans cette question maintenue, plus que dans le scandale, qu'il reste vivant."}$exo$::jsonb),
  ('3dfe8b2c-e4d9-5f74-8d21-6dd731772024'::uuid, 1, 'redaction', $exo${"titre":"Le procès de l'industrie culturelle","consigne":"Réponds à chaque question en quelques phrases précises.","enonce":"**Questions de cours**\n\n1. Dans quelle œuvre Adorno et Horkheimer forgent-ils la notion d'**industrie culturelle** ? Pourquoi choisissent-ils ce mot plutôt que « culture de masse » ?\n2. Explique les trois reproches qu'ils adressent à l'industrie culturelle.\n3. Que montre Bourdieu dans *La Distinction* (1979) sur la légitimité culturelle ?","bareme":[{"critere":"La Dialectique de la raison (1944) ; les masses ne produisent pas cette culture, elles la reçoivent","points":6},{"critere":"Standardisation, pseudo-individualisation, distraction, chacune expliquée","points":8},{"critere":"Bourdieu : la légitimité n'est pas une propriété des œuvres mais un rapport de force symbolique ; hiérarchies culturelles et sociales","points":6}],"dureeMin":8,"corrige":"1. Dans ***La Dialectique de la raison*** (1944). Le mot est choisi **contre** « culture de masse » : les masses **ne produisent pas** cette culture, elles la **reçoivent**, fabriquée comme un produit industriel.\n2. **La standardisation** : les mêmes formes répétées sous couvert de nouveauté. **La pseudo-individualisation** : des variantes de surface qui **simulent le choix**. **La distraction** : elle **neutralise la critique** ; le divertissement prolonge le travail.\n3. **Bourdieu** déplace la question du **contenu** vers l'**usage social** : ce qui sépare culture légitime et culture populaire n'est **pas une propriété des œuvres** mais un **rapport de force symbolique**. Les hiérarchies culturelles **reconduisent les hiérarchies sociales**."}$exo$::jsonb),
  ('3dfe8b2c-e4d9-5f74-8d21-6dd731772024'::uuid, 2, 'redaction', $exo${"titre":"Les fans de « Brume »","consigne":"Lis la situation (inventée pour l'exercice ; la série est imaginaire), puis réponds en t'appuyant sur les penseurs du cours.","enonce":"**Situation**\n\n> *Brume* est une série policière regardée par des millions de personnes. Son héros, un policier, y viole souvent la loi « pour la bonne cause ».\n> - Karim adore la série et pense que le héros a raison.\n> - Jade l'aime aussi, mais trouve que le héros va parfois trop loin.\n> - Tom la regarde pour s'en moquer : il y voit une propagande qui excuse les abus de la police.\n> - Léna écrit sur Internet des suites de la série où c'est une avocate qui devient l'héroïne.\n\n1. Classe les réceptions de Karim, Jade et Tom selon les trois lectures de Stuart Hall.\n2. Quel concept de Michel de Certeau décrit ce que fait Léna ? Explique-le.\n3. En quoi ces exemples s'opposent-ils à l'analyse d'Adorno et Horkheimer ? Montre enfin, avec Barthes, pourquoi une telle série mérite un examen sérieux.","bareme":[{"critere":"Karim lecture dominante, Jade négociée, Tom oppositionnelle","points":6},{"critere":"Braconnage : l'usager détourne, bricole, réemploie","points":4},{"critere":"Opposition à Adorno : la réception n'est pas passive","points":4},{"critere":"Barthes : mythologies communes ; la série façonne des représentations de la justice","points":4},{"critere":"Rédaction reliée à la situation","points":2}],"dureeMin":12,"corrige":"1. Selon **Stuart Hall**, un même message peut être lu de trois façons. **Karim** : lecture **dominante** (il adopte le sens proposé). **Jade** : lecture **négociée** (elle l'accepte en partie, avec des réserves). **Tom** : lecture **oppositionnelle** (il lit le message contre son sens).\n2. Léna pratique le **braconnage** au sens de **Michel de Certeau** (1980) : l'usager **détourne, bricole, réemploie** ce qui lui est donné pour en faire autre chose.\n3. **Adorno et Horkheimer** décrivent un public qui **reçoit** passivement une culture standardisée qui neutralise la critique. Ces quatre spectateurs montrent au contraire que **la réception n'est pas passive** : on peut adhérer, négocier, s'opposer, recréer. Enfin, au sens de **Barthes** (qui analysait en 1957 le catch ou le bifteck-frites), la pop culture produit des **mythologies** communes : une série vue par des millions de personnes **façonne des représentations** — ici, de la justice et de la police. C'est pourquoi elle relève d'un examen **sérieux** : ni complaisance, ni mépris."}$exo$::jsonb),
  ('3dfe8b2c-e4d9-5f74-8d21-6dd731772024'::uuid, 3, 'redaction', $exo${"titre":"La pop culture mérite-t-elle d'être étudiée ?","consigne":"Rédige un essai construit (introduction problématisée, deux ou trois parties, conclusion) en mobilisant au moins cinq références du chapitre.","enonce":"**Sujet d'essai**\n\n> Séries, jeux vidéo, bandes dessinées : la culture populaire mérite-t-elle d'être étudiée comme la culture savante ?\n\nConfronte le procès d'Adorno et Horkheimer aux réponses d'Eco, de Hall et de Certeau ; mobilise Bourdieu et le fait que « les frontières bougent » ; tu peux terminer avec Barthes.\n\nRéponds clairement dans ta conclusion.","bareme":[{"critere":"Problématique : divertissement mineur ou essentiel de l'expérience culturelle","points":3},{"critere":"Procès d'Adorno et Horkheimer exactement exposé","points":4},{"critere":"Réponses d'Eco, Hall et Certeau exactement exposées","points":5},{"critere":"Bourdieu (légitimité = rapport de force) et frontières qui bougent (roman, cinéma, jazz, BD), Barthes","points":5},{"critere":"Conclusion qui répond à la question","points":3}],"dureeMin":20,"corrige":"**Problématique.** Ce que le XXe siècle tenait pour un divertissement mineur constitue aujourd'hui l'essentiel de l'expérience culturelle. Faut-il y voir une culture digne d'étude, ou un produit qui ne mérite que la critique ?\n\n**Partie 1 — Le procès.** Pour **Adorno et Horkheimer** (*La Dialectique de la raison*, 1944), l'**industrie culturelle** n'est pas une culture des masses mais une culture qu'elles reçoivent : **standardisation**, **pseudo-individualisation**, **distraction** qui neutralise la critique. L'étudier, ce serait seulement la dénoncer.\n\n**Partie 2 — Les réponses.** **Umberto Eco** (1964) refuse le partage entre lucides et naïfs : il faut analyser James Bond **avec les mêmes outils** que le reste. **Stuart Hall** montre que la réception n'est pas passive : lectures **dominantes, négociées ou oppositionnelles**. **Michel de Certeau** (1980) décrit le **braconnage** de l'usager qui détourne et réemploie.\n\n**Partie 3 — Une hiérarchie qui n'est pas dans les œuvres.** **Bourdieu** (*La Distinction*, 1979) : la légitimité culturelle n'est pas une propriété des œuvres mais un **rapport de force symbolique**. Et **les frontières bougent** : le roman, le cinéma, le jazz et la bande dessinée ont tous été des divertissements suspects avant de devenir des objets d'étude. **Barthes** analysait déjà le catch ou le bifteck-frites comme des **mythologies** ; une série vue par des millions de personnes façonne des représentations de la justice, du travail, de la famille.\n\n**Conclusion.** Oui : la culture populaire mérite d'être étudiée, non parce qu'elle vaudrait tout, mais parce qu'elle façonne les représentations communes. Il faut l'examiner sérieusement — ni complaisance, ni mépris."}$exo$::jsonb),
  ('4fce27b4-0ef0-58ec-b4f2-92b9f0286eea'::uuid, 1, 'redaction', $exo${"titre":"Utopie et dystopie : le même geste retourné","consigne":"Réponds à chaque question en quelques phrases précises.","enonce":"**Questions de cours**\n\n1. Qui invente le mot « utopie », en quelle année, et à partir de quel jeu sur le grec ?\n2. Quel est l'objet **réel** de l'utopie ?\n3. Qu'ont en commun l'utopie et la dystopie ? En quoi s'opposent-elles ?","bareme":[{"critere":"Thomas More, 1516 ; ou-topos (lieu de nulle part) et jeu possible sur eu-topos (lieu du bonheur)","points":7},{"critere":"Objet réel : la société de l'auteur, critiquée par contraste","points":5},{"critere":"Point commun : l'organisation totale ; l'utopie espère, la dystopie avertit","points":8}],"dureeMin":7,"corrige":"1. **Thomas More** invente le mot en **1516**, à partir du grec ***ou-topos***, le **lieu de nulle part**, avec un jeu possible sur ***eu-topos***, le **lieu du bonheur**.\n2. L'utopie décrit une société idéale, close et réglée, sur une île ; mais son objet **réel** est la **société de l'auteur**, **critiquée par contraste**.\n3. Toutes deux décrivent une société **entièrement organisée** : l'**organisation totale** est leur point commun. Elles sont **le même geste retourné** : l'utopie **espère**, la dystopie **avertit** — elle retourne contre l'utopie cette organisation totale."}$exo$::jsonb),
  ('4fce27b4-0ef0-58ec-b4f2-92b9f0286eea'::uuid, 2, 'redaction', $exo${"titre":"La ville de Clarté","consigne":"Lis l'extrait (écrit pour l'exercice, il n'appartient à aucun roman réel), puis analyse-le avec les notions du cours.","enonce":"**Extrait** (inventé pour l'exercice)\n\n> À Clarté, chaque habitant reçoit chaque matin sa ration de bonne humeur : une pastille rose, gratuite, qui efface l'ennui. Personne n'est forcé de la prendre ; presque tout le monde la prend. Cette année, le Dictionnaire officiel a encore perdu quatre cents mots, dont « révolte » et « pourquoi ». Les enfants apprennent que l'ancien monde était triste, et les archives qui disaient autre chose ont été corrigées.\n\n1. Quel mécanisme de servitude cet extrait emprunte-t-il au *Meilleur des mondes* de Huxley ? Cite l'extrait.\n2. Quels mécanismes emprunte-t-il à *1984* d'Orwell ? Explique en particulier le rôle de la disparition des mots.\n3. Cet extrait parle-t-il seulement de l'avenir ? Réponds avec ce que le cours dit du rapport entre dystopie et histoire.","bareme":[{"critere":"Huxley : servitude par le plaisir, pastille comparable au soma, on ne force personne","points":5},{"critere":"Orwell : novlangue (appauvrir le vocabulaire pour rendre la dissidence impensable), réécriture du passé","points":7},{"critere":"La dystopie décrit des mécanismes réels (contrôle de l'information, réécriture du passé, fabrique du consentement), détour pour parler du présent","points":6},{"critere":"Citations exactes de l'extrait","points":2}],"dureeMin":12,"corrige":"1. Comme chez **Huxley**, la servitude passe par le **plaisir** : « sa ration de bonne humeur », une pastille qui efface l'ennui, rappelle le ***soma***. « Personne n'est forcé de la prendre ; presque tout le monde la prend » : on prive de liberté **en donnant ce que les gens désirent**, sans terreur.\n2. Comme dans *1984*, la **langue** est une arme : le Dictionnaire « a encore perdu quatre cents mots, dont ‹ révolte › et ‹ pourquoi › ». C'est la **novlangue** : **appauvrir le vocabulaire** pour rendre la dissidence littéralement **impensable** — sans le mot « révolte », on ne peut plus la penser. Autre mécanisme orwellien : la **réécriture du passé** (« les archives qui disaient autre chose ont été corrigées »).\n3. Non. Les dystopies sont écrites **après ou pendant** les totalitarismes : elles ne prédisent pas l'avenir, elles décrivent des **mécanismes réels** — **contrôle de l'information**, **réécriture du passé**, **fabrique du consentement**. Comme l'utopie chez More, la dystopie reste un **détour pour parler du présent**."}$exo$::jsonb),
  ('4fce27b4-0ef0-58ec-b4f2-92b9f0286eea'::uuid, 3, 'redaction', $exo${"titre":"La dystopie parle-t-elle de l'avenir ?","consigne":"Rédige un essai construit (introduction problématisée, deux ou trois parties, conclusion) en mobilisant au moins cinq références du chapitre.","enonce":"**Sujet d'essai**\n\n> La dystopie est-elle une prédiction de l'avenir ?\n\nMobilise : l'utopie de More, les trois romans qui fixent le genre (Zamiatine, Huxley, Orwell), la différence entre les avertissements de Huxley et d'Orwell (et le résumé de Postman), Arendt, et au moins un exemple contemporain du cours.\n\nRéponds clairement dans ta conclusion.","bareme":[{"critere":"Problématique : anticipation apparente / critique du présent","points":3},{"critere":"Les trois romans et leurs moyens de servitude exactement présentés","points":5},{"critere":"Huxley / Orwell et le résumé de Postman expliqués","points":4},{"critere":"Arendt (idéologie, terreur, destruction de l'espace public), More, exemple contemporain","points":5},{"critere":"Conclusion qui répond à la question","points":3}],"dureeMin":20,"corrige":"**Problématique.** La dystopie se déroule souvent dans un futur imaginaire, et l'on dit volontiers qu'Orwell « avait prévu » notre monde. Mais une œuvre qui décrit l'avenir parle-t-elle vraiment de lui ?\n\n**Partie 1 — Un genre qui semble anticiper.** *Nous autres* (**Zamiatine**, 1920) : numéros, maisons de verre, ablation chirurgicale de l'imagination. *Le Meilleur des mondes* (**Huxley**, 1932) : servitude par le **plaisir** — conditionnement, castes fabriquées, *soma*. *1984* (**Orwell**, 1949) : **terreur** et **langue** — Big Brother, novlangue, double-pensée. Leurs avertissements diffèrent : Huxley craint qu'on nous prive de liberté **en nous donnant ce que nous désirons**, Orwell qu'on nous l'**arrache par la peur** ; Postman résume : chez Huxley, que personne n'ait plus envie de lire ; chez Orwell, que les livres soient interdits.\n\n**Partie 2 — Une description du présent.** Ces romans sont écrits **après ou pendant** les totalitarismes : ils décrivent des **mécanismes réels** — contrôle de l'information, réécriture du passé, fabrique du consentement. **Arendt** (*Les Origines du totalitarisme*, 1951) en donne l'analyse théorique : idéologie totale, terreur, destruction de l'espace public. Déjà chez **More** (1516), l'utopie visait la société de l'auteur, critiquée par contraste.\n\n**Partie 3 — Aujourd'hui.** Surveillance de masse, données personnelles, effondrement écologique, biotechnologies : *La Servante écarlate* d'**Atwood**, *Black Mirror*. Le genre reste un **détour pour parler du présent**.\n\n**Conclusion.** La dystopie n'est pas une prédiction : elle grossit des tendances présentes pour les rendre visibles. Si elle semble parfois « se réaliser », c'est qu'elle avait bien lu son époque."}$exo$::jsonb),
  ('b7369998-f445-522b-a4aa-73ca33b02ec4'::uuid, 1, 'redaction', $exo${"titre":"L'état de nature et l'État","consigne":"Réponds à chaque question en quelques phrases précises.","enonce":"**Questions de cours**\n\n1. Compare le diagnostic de Hobbes et celui de Rousseau sur l'état de nature : qu'est-ce qui produit la violence pour chacun ?\n2. Que l'homme échange-t-il, chez Hobbes, dans le contrat social ?\n3. Comment Max Weber définit-il l'État moderne ? Que devient alors la violence ?","bareme":[{"critere":"Hobbes (guerre de tous contre tous, l'absence d'État) / Rousseau (homme naturel pacifique, la société, la propriété, la comparaison)","points":8},{"critere":"Contrat hobbesien : liberté illimitée contre sécurité","points":4},{"critere":"Weber : monopole de la violence physique légitime sur un territoire ; violence confisquée et encadrée","points":8}],"dureeMin":7,"corrige":"1. Pour **Hobbes** (*Léviathan*, 1651), l'état de nature est une « **guerre de tous contre tous** » : la vie y est « solitaire, misérable, dangereuse, animale et brève ». Ce qui produit la violence, c'est l'**absence d'État**. Pour **Rousseau**, l'homme naturel est **pacifique** et capable de pitié : ce qui produit la violence, c'est la **société**, la **propriété**, la **comparaison**.\n2. Chez Hobbes, le contrat social échange la **liberté illimitée** contre la **sécurité**.\n3. **Weber** définit l'État moderne comme ce qui revendique avec succès le **monopole de la violence physique légitime** sur un territoire. La violence n'a pas disparu : elle a été **confisquée et encadrée** (police, justice, armée)."}$exo$::jsonb),
  ('b7369998-f445-522b-a4aa-73ca33b02ec4'::uuid, 2, 'redaction', $exo${"titre":"Le mécanisme du bouc émissaire","consigne":"Lis la situation (inventée pour l'exercice), puis analyse-la avec la théorie de René Girard.","enonce":"**Situation**\n\n> Dans une équipe de handball, Maxime et Ilyes veulent tous deux devenir capitaine, surtout depuis que Maxime a dit en vouloir. Leur rivalité divise l'équipe ; les disputes gagnent tous les joueurs, les entraînements tournent aux insultes. Un jour, après une défaite, tout le monde accuse Sacha, un remplaçant discret, d'avoir « porté la poisse ». Sacha quitte le club. Le lendemain, l'équipe se retrouve soudée comme jamais.\n\n1. Retrouve dans la situation les **cinq étapes** du mécanisme décrit par Girard, en citant à chaque fois le passage correspondant.\n2. Pourquoi Sacha est-il désigné ? Que signifie dire que la victime est désignée « arbitrairement » ?\n3. Girard dit que les mythes racontent ces meurtres « du point de vue des meurtriers ». Comment l'équipe raconterait-elle l'histoire ? Explique.","bareme":[{"critere":"Cinq étapes correctement repérées : désir mimétique, rivalité, crise, bouc émissaire, unité restaurée","points":10},{"critere":"Désignation arbitraire : Sacha n'est pas responsable, toute la violence est reportée sur lui","points":4},{"critere":"Point de vue des meurtriers : l'équipe croirait Sacha coupable et son départ justifié","points":4},{"critere":"Rédaction reliée à la situation","points":2}],"dureeMin":12,"corrige":"1. **Désir mimétique** : Ilyes veut être capitaine « surtout depuis que Maxime a dit en vouloir » — on désire ce que l'autre désire. **Rivalité** : « leur rivalité divise l'équipe » — le désir partagé devient conflit. **Crise** : « les disputes gagnent tous les joueurs » — la violence se généralise. **Bouc émissaire** : « tout le monde accuse Sacha » — toute la violence est reportée sur une victime. **Unité restaurée** : « l'équipe se retrouve soudée comme jamais » — l'exclusion refait le groupe.\n2. Sacha est désigné non parce qu'il est coupable, mais parce qu'il est **discret**, isolé, sans défense : la victime est désignée **arbitrairement**. Il n'a rien à voir avec la rivalité ; il sert à décharger la violence de tous sur un seul.\n3. L'équipe raconterait que Sacha « portait la poisse » et que son départ a tout arrangé : elle présenterait l'exclusion comme **justifiée** et la victime comme **coupable**. C'est ce que Girard prétend décrypter dans les mythes : ils racontent la violence collective **du point de vue de ceux qui l'ont commise**, qui croient à la culpabilité de leur victime."}$exo$::jsonb),
  ('b7369998-f445-522b-a4aa-73ca33b02ec4'::uuid, 3, 'redaction', $exo${"titre":"Y a-t-il des violences légitimes ?","consigne":"Rédige un essai construit (introduction problématisée, deux ou trois parties, conclusion) en mobilisant au moins cinq références du chapitre.","enonce":"**Sujet d'essai**\n\n> Y a-t-il des violences légitimes ?\n\nMobilise : Hobbes et Weber, les violences invisibles (Bourdieu, Galtung) avec la précaution du cours, Elias et Freud, Benjamin, Gandhi et King.\n\nRéponds clairement dans ta conclusion.","bareme":[{"critere":"Problématique : toute société interdit la violence et en exerce","points":3},{"critere":"Légitimité par l'État : Hobbes, Weber, et la question critique (qui nomme la violence légitime ?)","points":5},{"critere":"Violences invisibles (symbolique, structurelle) et précaution : si tout est violence, le mot ne distingue plus rien","points":4},{"critere":"Elias / Freud et Benjamin (violence qui fonde / qui conserve le droit), non-violence comme stratégie","points":5},{"critere":"Conclusion qui répond à la question","points":3}],"dureeMin":20,"corrige":"**Problématique.** Toute société **interdit** la violence, et toute société en **exerce**. Si certaines violences sont dites légitimes, qu'est-ce qui les rend telles — leur fin, ou celui qui les nomme ainsi ?\n\n**Partie 1 — La violence légitime de l'État.** Pour **Hobbes**, sans État règne la guerre de tous contre tous ; le contrat échange la liberté illimitée contre la sécurité. **Weber** définit l'État par le **monopole de la violence physique légitime** : la violence est **confisquée et encadrée** (police, justice, armée). Mais la question critique demeure : qu'est-ce qui rend une violence légitime, **sinon celui qui la nomme ainsi** ?\n\n**Partie 2 — Les violences qu'on ne voit pas.** **Bourdieu** : la violence **symbolique** s'exerce avec la complicité tacite de ceux qui la subissent. **Galtung** : la violence **structurelle** — des inégalités qui tuent sans qu'aucun coup soit porté. Précaution : ces notions **élargissent** le mot ; si tout est violence, il ne distingue plus rien. **Elias** décrit la montée de l'autocontrôle et la baisse de la violence interpersonnelle ; **Freud** (*Malaise dans la civilisation*, 1930) montre qu'elle est **refoulée** et ressurgit dans la guerre.\n\n**Partie 3 — Des violences justes ?** **Benjamin** distingue la violence qui **fonde** le droit de celle qui le **conserve**. **Gandhi** et **King** ont opposé une troisième voie : la **non-violence organisée**, qui n'est pas passivité mais **stratégie**.\n\n**Conclusion.** Il existe des violences **légitimées** — celle de l'État encadrée par le droit —, mais leur légitimité reste toujours à interroger. L'exemple de la non-violence montre qu'on peut combattre l'injustice sans reprendre les armes : la violence n'est pas le seul moyen de fonder un droit."}$exo$::jsonb),
  ('a80fab3b-809c-5553-99d8-aa651fc764ae'::uuid, 1, 'redaction', $exo${"titre":"Les trois âges de la folie","consigne":"Réponds à chaque question en quelques phrases précises.","enonce":"**Questions de cours**\n\n1. Quel est l'objet réel de l'*Histoire de la folie à l'âge classique* (1961) de Foucault ?\n2. Présente les **trois âges** de la folie selon Foucault : époque, statut du fou, dispositif.\n3. Qu'est-ce que le « grand renfermement » de 1656 ? Quel en est le critère ?","bareme":[{"critere":"Objet : le partage entre raison et déraison, non la maladie mentale","points":5},{"critere":"Trois âges exacts : Moyen Âge-Renaissance (circule et parle), 1656 (enfermé et tu, Hôpital général), fin XVIIIe (observé, psychiatrie)","points":9},{"critere":"Grand renfermement : pauvres, oisifs, vénériens, libertins et insensés ensemble ; critère social et moral, l'incapacité de travailler","points":6}],"dureeMin":8,"corrige":"1. Son objet n'est **pas** la maladie mentale, mais le **partage entre raison et déraison** : comment une société décide de ce qui relève de l'entendement.\n2. **Moyen Âge et Renaissance** : le fou **circule** et **parle** (la nef des fous, le bouffon, Érasme, Shakespeare). **À partir de 1656** : il est **enfermé** et **tu**, à l'**Hôpital général** de Paris. **Fin du XVIIIe siècle** : il est **observé**, par la **psychiatrie naissante**.\n3. En 1656, on enferme **ensemble** pauvres, oisifs, vénériens, libertins et insensés. Le critère n'est **pas médical** mais **social et moral** : l'**incapacité de travailler**."}$exo$::jsonb),
  ('a80fab3b-809c-5553-99d8-aa651fc764ae'::uuid, 2, 'redaction', $exo${"titre":"Pinel libère les aliénés","consigne":"Lis le document (inventé pour l'exercice), puis analyse-le avec la lecture de Foucault.","enonce":"**Document** (texte imaginaire, à la manière d'un manuel du XIXe siècle)\n\n> Le docteur Pinel fit ôter leurs chaînes aux malheureux aliénés. Désormais, ils se promenaient librement dans la cour de l'asile. Le médecin les visitait chaque jour, notait leurs paroles et leurs gestes, les félicitait quand ils se conduisaient bien et les réprimandait quand ils s'écartaient de la raison. Ainsi la médecine remplaça la barbarie.\n\n1. Quelle image du geste de Pinel ce texte donne-t-il ? Cite-le.\n2. Relis ce geste comme Foucault : ce qu'on retire, ce qu'on installe. Appuie-toi sur des passages du texte.\n3. Montre que cette relecture annonce la thèse de *Surveiller et punir* et du biopouvoir : comment s'exerce le pouvoir moderne ?","bareme":[{"critere":"Image d'Épinal : une libération, la médecine contre la barbarie, citée","points":4},{"critere":"Chaînes / regard médical, contrainte visible / observation et jugement moral permanents, violence physique / contrainte intériorisée, avec citations","points":8},{"critere":"Pouvoir moderne par la norme plutôt que l'interdiction : il classe, mesure, corrige ; discipline et biopouvoir","points":6},{"critere":"Rédaction reliée au document","points":2}],"dureeMin":12,"corrige":"1. Le texte présente le geste de Pinel comme une **libération** pure : « fit ôter leurs chaînes », « ils se promenaient librement », « la médecine remplaça la barbarie ». C'est le **geste fondateur devenu image d'Épinal**.\n2. **Foucault** relit ce geste : on retire **les chaînes**, mais on installe le **regard médical** (« le médecin les visitait chaque jour, notait leurs paroles et leurs gestes ») ; on retire **la contrainte visible**, mais on installe **l'observation et le jugement moral permanents** (« les félicitait… les réprimandait quand ils s'écartaient de la raison ») ; on retire **une violence physique**, mais on installe une **contrainte intériorisée** : le fou doit apprendre à se conduire selon ce qu'on attend de lui.\n3. Cette relecture annonce *Surveiller et punir* (1975 : discipline, panoptique) et *La Volonté de savoir* (1976 : le **biopouvoir**, pouvoir qui prend en charge la vie, la santé, la population). Le pouvoir moderne ne s'exerce plus principalement par l'**interdiction** mais par la **norme** : il produit des savoirs, **classe, mesure, corrige** — exactement ce que fait le médecin du document."}$exo$::jsonb),
  ('a80fab3b-809c-5553-99d8-aa651fc764ae'::uuid, 3, 'redaction', $exo${"titre":"Nos catégories sont-elles naturelles ?","consigne":"Rédige un essai construit (introduction problématisée, deux ou trois parties, conclusion) en mobilisant plusieurs notions du chapitre.","enonce":"**Sujet d'essai**\n\n> La frontière entre le normal et l'anormal est-elle naturelle ?\n\nMobilise : la thèse de l'*Histoire de la folie* (le partage, l'exclusion), le grand renfermement, la relecture de Pinel, le passage de l'interdiction à la norme (biopouvoir), et les critiques adressées à Foucault (Derrida, les historiens).\n\nRéponds clairement dans ta conclusion.","bareme":[{"critere":"Problématique : catégorie naturelle ou découpage historique","points":3},{"critere":"Thèse de Foucault : partage raison / déraison, la raison exclut sans réfuter ; grand renfermement et son critère","points":6},{"critere":"Pinel et la norme : regard médical, contrainte intériorisée, biopouvoir","points":4},{"critere":"Critiques (chronologie contestée, Derrida) et leur portée : une archéologie n'est pas une chronique","points":4},{"critere":"Conclusion qui répond à la question","points":3}],"dureeMin":20,"corrige":"**Problématique.** La folie semble un fait de nature, que la médecine constate. Mais si la manière de la définir et de la traiter change selon les époques, la frontière entre normal et anormal n'est-elle pas tracée par la société ?\n\n**Partie 1 — Un partage historique.** Foucault étudie non la maladie mentale mais le **partage entre raison et déraison**. Au Moyen Âge et à la Renaissance, le fou **circule et parle** ; en **1656**, l'**Hôpital général** enferme ensemble pauvres, oisifs, libertins et insensés — critère **social et moral** : l'incapacité de travailler, non la médecine. Thèse : la raison classique ne **réfute** pas la folie, elle l'**exclut** ; le silence de l'interné est la condition du monologue de la raison.\n\n**Partie 2 — La norme remplace l'interdit.** Pinel ôte les chaînes, mais installe le **regard médical** et une **contrainte intériorisée**. Avec *Surveiller et punir* et le **biopouvoir**, Foucault montre que le pouvoir moderne s'exerce moins par l'**interdiction** que par la **norme** : il classe, mesure, corrige. La frontière du normal est produite par des institutions et des savoirs.\n\n**Partie 3 — Les limites.** La chronologie du grand renfermement est **contestée** (Gauchet et Swain, Scull). **Derrida** objecte qu'on ne peut faire l'histoire de la folie **elle-même** dans le langage de la raison. Ces objections n'annulent pas la méthode : une **archéologie** n'est pas une chronique.\n\n**Conclusion.** La frontière entre normal et anormal n'est pas simplement naturelle : c'est un **découpage historique**, donc contestable. L'outil que fournit Foucault est de **ne jamais tenir une catégorie pour naturelle** — sans nier pour autant la souffrance réelle qu'elle désigne."}$exo$::jsonb),
  ('640789de-a2ba-55f1-9cbc-47c8ff599ab1'::uuid, 1, 'redaction', $exo${"titre":"Mythes de la démesure","consigne":"Réponds à chaque question en quelques phrases précises.","enonce":"**Questions de cours**\n\n1. Pour chacun des mythes suivants, indique le geste et le châtiment : Prométhée, Icare, Babel, Faust.\n2. Quelle formule du *Discours de la méthode* (1637) exprime le programme moderne ? Pourquoi le mot « comme » compte-t-il ?\n3. Quelle formule de Bacon nuance l'idée de maîtrise ?","bareme":[{"critere":"Geste et châtiment justes pour les quatre mythes","points":8},{"critere":"« comme maîtres et possesseurs de la nature » ; le « comme » : Descartes ne divinise pas l'homme, il l'assigne à une tâche","points":8},{"critere":"Bacon : « on ne commande à la nature qu'en lui obéissant »","points":4}],"dureeMin":8,"corrige":"1. **Prométhée** vole le feu aux dieux pour les hommes → le **supplice éternel**. **Icare** vole trop haut → la **chute**. **Babel** : une tour, une langue unique → la **dispersion**. **Faust** vend son âme contre la connaissance sans limite → la **damnation**.\n2. La science pratique doit nous rendre « **comme maîtres et possesseurs de la nature** ». Le « **comme** » compte : Descartes ne **divinise** pas l'homme, il l'**assigne à une tâche** ; c'est souvent ce qu'on oublie de citer.\n3. **Bacon** : « **on ne commande à la nature qu'en lui obéissant** » — la maîtrise suppose de connaître et respecter les lois de la nature."}$exo$::jsonb),
  ('640789de-a2ba-55f1-9cbc-47c8ff599ab1'::uuid, 2, 'redaction', $exo${"titre":"L'entreprise Hélios et sa créature","consigne":"Lis la situation (inventée pour l'exercice), puis réponds avec les références du cours.","enonce":"**Situation**\n\n> L'entreprise Hélios met en ligne un programme capable de modifier le climat local en dispersant des produits dans les nuages. Des pluies violentes frappent ensuite une région voisine. Le directeur déclare : « Nous avons créé l'outil ; ce que les autres en font, et ce qui se passe ensuite, ne nous regarde plus. »\n\n1. En quoi la position du directeur ressemble-t-elle à la faute de Victor Frankenstein, selon le roman de Mary Shelley ? Corrige l'idée reçue sur ce roman.\n2. Quelle question le cours propose-t-il de substituer à « peut-on ? » ? Applique-la à la situation.\n3. Que dirait Hans Jonas ? Explique son **impératif** et l'**heuristique de la peur**, et pourquoi l'échelle de la technique moderne les rend nécessaires.","bareme":[{"critere":"Frankenstein puni d'avoir abandonné sa créature, non de l'avoir créée ; le refus d'en répondre, rapproché du directeur","points":6},{"critere":"« Qui répondra de ce qui arrivera ? » appliqué à la situation","points":4},{"critere":"Jonas : impératif exact, heuristique de la peur (pronostic pessimiste, enjeu irréversible), changement d'échelle","points":8},{"critere":"Rédaction reliée à la situation","points":2}],"dureeMin":12,"corrige":"1. L'idée reçue veut que Victor Frankenstein soit puni d'avoir **créé** un être vivant. Le roman de **Mary Shelley** (1818, *Le Prométhée moderne*) dit autre chose : il est puni d'avoir **abandonné** sa créature. Ce n'est pas la technique qui est monstrueuse, c'est le **refus d'en répondre**. Le directeur d'Hélios fait exactement cela : il crée, puis se désintéresse des conséquences.\n2. La question n'est pas « **peut-on ?** » mais « **qui répondra de ce qui arrivera ?** » Hélios a pu techniquement créer l'outil ; la vraie question est de savoir qui répondra des pluies de la région voisine.\n3. **Hans Jonas** (1979) constate que la technique moderne a changé d'**échelle** : ses effets portent sur des populations et des générations qui ne peuvent ni consentir ni protester. Son impératif : « **Agis de telle sorte que les effets de ton action soient compatibles avec la permanence d'une vie authentiquement humaine sur terre** ». L'**heuristique de la peur** consiste à **donner plus de poids au pronostic pessimiste**, parce que l'enjeu est **irréversible**. Hélios aurait dû envisager le pire avant de mettre l'outil en ligne."}$exo$::jsonb),
  ('640789de-a2ba-55f1-9cbc-47c8ff599ab1'::uuid, 3, 'redaction', $exo${"titre":"L'homme est-il un apprenti sorcier ?","consigne":"Rédige un essai construit (introduction problématisée, deux ou trois parties, conclusion) en mobilisant au moins cinq références du chapitre.","enonce":"**Sujet d'essai**\n\n> Faut-il fixer des limites au pouvoir technique de l'homme ?\n\nMobilise : les mythes fondateurs, Descartes et Bacon, *Frankenstein*, Hans Jonas et Heidegger. Tu peux terminer par le déplacement contemporain du fantasme de toute-puissance.\n\nRéponds clairement dans ta conclusion.","bareme":[{"critere":"Problématique : désir de tout pouvoir et question du prix","points":3},{"critere":"Mythes et programme moderne (Descartes, le « comme », Bacon) exactement exposés","points":5},{"critere":"Frankenstein et Jonas : responsabilité, impératif, heuristique de la peur","points":5},{"critere":"Heidegger : Gestell, le monde réduit à un fonds disponible ; le regard plutôt que l'usage","points":4},{"critere":"Conclusion qui répond à la question","points":3}],"dureeMin":20,"corrige":"**Problématique.** Le désir de tout pouvoir est aussi ancien que les récits qui en avertissent. Ces récits ne condamnent pas la technique : ils posent la question du **prix**. Faut-il limiter ce que l'homme peut faire, et au nom de quoi ?\n\n**Partie 1 — Le désir de maîtrise et ses avertissements.** **Prométhée**, **Icare**, **Babel**, **Faust** : chaque geste de démesure appelle un châtiment. Le programme moderne l'assume pourtant : **Descartes** veut nous rendre « **comme** maîtres et possesseurs de la nature » — le « comme » ne divinise pas l'homme, il l'assigne à une tâche ; **Bacon** rappelle qu'« on ne commande à la nature qu'en lui obéissant ».\n\n**Partie 2 — La limite est la responsabilité.** *Frankenstein* (**Mary Shelley**, 1818) : Victor est puni d'avoir **abandonné** sa créature, non de l'avoir créée ; la question devient « **qui répondra de ce qui arrivera ?** ». **Hans Jonas** (1979) : la technique a changé d'**échelle** ; il faut agir de sorte que les effets soient compatibles avec la permanence d'une vie authentiquement humaine sur terre, et suivre l'**heuristique de la peur** face à l'irréversible.\n\n**Partie 3 — Plus profond que l'usage : le regard.** Pour **Heidegger**, la technique moderne n'est pas un outil neutre : elle transforme le monde en **fonds disponible** (*Gestell*) — le fleuve devient une réserve d'énergie. Ce qui est en jeu n'est pas l'**usage** mais le **regard** qu'elle impose. Aujourd'hui, le fantasme s'est **déplacé de la nature vers l'humain lui-même** (édition du génome, IA) : transhumanisme et bioéthique.\n\n**Conclusion.** Oui, il faut des limites, mais pas des interdits de principe : la limite est la **responsabilité** — répondre des effets, peser le pire quand il est irréversible, et garder conscience du regard que la technique nous impose."}$exo$::jsonb),
  ('0f1bd440-e489-50c6-9d89-b6f338df63e9'::uuid, 1, 'redaction', $exo${"titre":"L'Anthropocène","consigne":"Réponds à chaque question en quelques phrases précises.","enonce":"**Questions de cours**\n\n1. Que désigne le concept d'**Anthropocène** ? Qui l'a popularisé et quand ?\n2. Quelle conséquence philosophique ce concept entraîne-t-il ? Quelle idée Bruno Latour en tire-t-il ?\n3. Que montre Philippe Descola dans *Par-delà nature et culture* (2005) ?","bareme":[{"critere":"L'activité humaine devenue une force géologique ; Crutzen, 2000","points":6},{"critere":"Fin de la distinction histoire humaine / histoire naturelle ; Latour : jamais aussi peu séparés de la nature qu'en croyant la dominer","points":8},{"critere":"Descola : le partage nature / culture est une singularité occidentale","points":6}],"dureeMin":7,"corrige":"1. L'**Anthropocène**, popularisé par **Crutzen** en **2000**, énonce que l'**activité humaine est devenue une force géologique**.\n2. Conséquence : la distinction entre **histoire humaine** et **histoire naturelle**, qui structurait la pensée moderne, **ne tient plus**. **Bruno Latour** en tire l'idée que nous n'avons **jamais été aussi peu séparés de la nature** qu'au moment où nous croyions l'avoir dominée.\n3. **Descola** montre que le partage **nature / culture** est une **singularité occidentale** : d'autres sociétés découpent le monde autrement."}$exo$::jsonb),
  ('0f1bd440-e489-50c6-9d89-b6f338df63e9'::uuid, 2, 'redaction', $exo${"titre":"Le barrage de la vallée","consigne":"Lis la situation (inventée pour l'exercice), puis réponds avec les penseurs du cours.","enonce":"**Situation**\n\n> Un projet de barrage doit noyer une vallée. Lors de la réunion publique, quatre personnes prennent la parole :\n> - **Amina** : « Dans cinquante ans, nos petits-enfants n'auront plus cette rivière, et personne ne leur aura demandé leur avis. »\n> - **Bastien** : « Les loutres et les poissons de la vallée vont souffrir et mourir : leur souffrance compte. »\n> - **Chloé** : « Ce qui compte, c'est l'équilibre de tout le milieu : la rivière, les berges, les espèces qui dépendent les unes des autres. »\n> - **David** : « Cette vallée a une valeur en elle-même, indépendamment de toute utilité pour nous. »\n\n1. Rattache chaque intervention à un penseur du cours (Jonas, Singer, Leopold, Næss) et précise **qui** il inclut dans le cercle moral et sur **quel critère**.\n2. Quelle question unique, selon le cours, traverse toute cette discussion ? Classe les quatre interventions selon la réponse qu'elles y donnent.\n3. Formule l'objection que Luc Ferry pourrait adresser à David.","bareme":[{"critere":"Amina-Jonas (générations futures), Bastien-Singer (êtres sensibles), Chloé-Leopold (communauté biotique), David-Næss (valeur intrinsèque), critères justes","points":10},{"critere":"La nature vaut-elle pour nous ou en elle-même ; classement justifié","points":4},{"critere":"Objection de Ferry : une écologie qui subordonne l'humain à un tout est dangereuse","points":4},{"critere":"Rédaction reliée à la situation","points":2}],"dureeMin":12,"corrige":"1. **Amina → Hans Jonas** : il inclut les **générations futures**, parce qu'elles ne peuvent **ni consentir ni réclamer**. **Bastien → Peter Singer** : il inclut les **êtres sensibles**, selon la **capacité de souffrir** (d'où l'antispécisme). **Chloé → Aldo Leopold** (1949) : il inclut la **communauté biotique** ; est juste ce qui préserve son **intégrité et sa beauté**. **David → Arne Næss** : il inclut la **nature entière**, qui a une **valeur intrinsèque** (écologie profonde).\n2. La question : **la nature vaut-elle pour nous, ou en elle-même ?** Amina pense encore **pour nous** (les humains futurs). Bastien étend la valeur aux animaux sensibles, sans aller jusqu'à la nature entière. Chloé et surtout David vont vers une valeur **en elle-même** : l'équilibre du milieu, puis la vallée comme telle.\n3. **Luc Ferry** (*Le Nouvel Ordre écologique*, 1992) objecterait qu'une écologie qui **subordonne l'humain à un tout** est **dangereuse** : si la vallée vaut en elle-même, au-dessus des intérêts humains, on risque de sacrifier les hommes à la nature. On peut ajouter l'objection juridique : on ne peut accorder des **droits** à des entités incapables de **devoirs**."}$exo$::jsonb),
  ('0f1bd440-e489-50c6-9d89-b6f338df63e9'::uuid, 3, 'redaction', $exo${"titre":"Que devons-nous aux vivants qui ne sont pas nous ?","consigne":"Rédige un essai construit (introduction problématisée, deux ou trois parties, conclusion) en mobilisant au moins cinq références du chapitre.","enonce":"**Sujet d'essai**\n\n> La crise écologique oblige-t-elle à repenser ce que l'humanité est ?\n\nMobilise : l'Anthropocène et Latour, la généalogie du problème (Lynn White, la modernité cartésienne, Descola), l'élargissement du cercle moral, les objections, et ce que la littérature apporte.\n\nRéponds clairement dans ta conclusion.","bareme":[{"critere":"Problématique : problème technique ou question sur ce qu'est l'humanité","points":3},{"critere":"Anthropocène, Latour et généalogie exactement exposés","points":5},{"critere":"Élargissement du cercle moral (au moins trois penseurs) et objections (Ferry, juridique, justice)","points":6},{"critere":"Apport de la littérature (Thoreau, Giono, Calvino, nature writing) : rendre sensible","points":3},{"critere":"Conclusion qui répond à la question","points":3}],"dureeMin":20,"corrige":"**Problématique.** On présente souvent la crise écologique comme un problème technique : moins émettre, mieux produire. Mais si l'humanité est devenue une force géologique, c'est la définition même de l'humain, séparé de la nature, qui vacille.\n\n**Partie 1 — La fin d'une séparation.** L'**Anthropocène** (Crutzen, 2000) : l'activité humaine est une **force géologique** ; la distinction entre histoire humaine et histoire naturelle ne tient plus. **Latour** : nous n'avons jamais été aussi peu séparés de la nature qu'en croyant la dominer. Généalogie : **Lynn White** accuse le récit biblique de la domination ; la **modernité cartésienne** réduit la nature à un objet mesurable ; l'**économie extractive** à une ressource ; **Descola** montre que le partage nature / culture est une **singularité occidentale**.\n\n**Partie 2 — Élargir le cercle moral.** **Jonas** : les générations futures. **Leopold** : la communauté biotique. **Singer** : les êtres sensibles. **Næss** : la nature entière, valeur intrinsèque. Toute la discussion : la nature vaut-elle **pour nous** ou **en elle-même** ?\n\n**Partie 3 — Les objections et la juste mesure.** **Luc Ferry** : une écologie qui subordonne l'humain à un tout est dangereuse. L'objection juridique : pas de **droits** sans **devoirs**. L'écologie politique : la crise est d'abord une question de **justice** — les moins responsables subissent les effets les plus lourds. La littérature (*Walden* de Thoreau, *L'Homme qui plantait des arbres* de Giono, *Le Baron perché* de Calvino) ne démontre pas : elle rend **sensible** un rapport au monde, là où les chiffres ne suffisent pas à faire agir.\n\n**Conclusion.** Oui : la crise écologique oblige à penser l'humanité non plus comme maîtresse d'une nature extérieure, mais comme partie prenante d'un monde qu'elle transforme. Cela n'impose pas de sacrifier l'humain au tout, mais d'élargir ce dont il se sait responsable."}$exo$::jsonb),
  ('215ac38c-8bc0-521d-90f8-78b2edabf966'::uuid, 1, 'redaction', $exo${"titre":"Nuremberg et les quatre principes","consigne":"Réponds à chaque question en quelques phrases précises.","enonce":"**Questions de cours**\n\n1. Quel principe le **code de Nuremberg** (1947) pose-t-il ? Dans quel contexte a-t-il été rédigé ?\n2. Présente les **quatre principes** de Beauchamp et Childress (1979) et ce que chacun exige.\n3. Pourquoi ces principes sont-ils à la fois utiles et difficiles à appliquer ?","bareme":[{"critere":"Consentement volontaire absolument essentiel ; après le procès des médecins nazis ; le corps n'est pas un matériau disponible","points":6},{"critere":"Autonomie, bienfaisance, non-malfaisance (primum non nocere), justice, chacun défini","points":8},{"critere":"Ils entrent en conflit ; arbitrage fréquent entre autonomie du patient et bienfaisance du soignant","points":6}],"dureeMin":8,"corrige":"1. Le **code de Nuremberg** (1947) pose que le **consentement volontaire** du sujet humain est « absolument essentiel ». Il est rédigé **après le procès des médecins nazis** et fonde la bioéthique moderne sur un principe : **le corps n'est pas un matériau disponible**. La déclaration d'Helsinki (1964) l'étend à toute la recherche médicale.\n2. **Autonomie** : respecter la décision informée de la personne. **Bienfaisance** : agir pour son bien. **Non-malfaisance** : *primum non nocere*, d'abord ne pas nuire. **Justice** : l'équité dans l'accès aux soins et la répartition des ressources.\n3. Leur intérêt est aussi leur difficulté : ils **entrent en conflit**. Le débat bioéthique consiste le plus souvent à **arbitrer** entre l'**autonomie** du patient et la **bienfaisance** du soignant."}$exo$::jsonb),
  ('215ac38c-8bc0-521d-90f8-78b2edabf966'::uuid, 2, 'redaction', $exo${"titre":"Le refus de M. Garnier","consigne":"Lis la situation (inventée pour l'exercice), puis réponds avec les notions et le droit présentés en cours.","enonce":"**Situation**\n\n> M. Garnier, 82 ans, est atteint d'une maladie grave et incurable. Pleinement lucide et bien informé, il refuse une nouvelle opération lourde qui pourrait prolonger sa vie de quelques mois. Son médecin, le docteur Lemoine, voudrait le convaincre d'accepter. La fille de M. Garnier demande : « Et si la douleur devient insupportable, pourra-t-on l'aider à mourir ? »\n\n1. Quels principes de Beauchamp et Childress entrent ici en conflit ? Explique la position de chacun des deux hommes.\n2. Quel principe issu du code de Nuremberg soutient la décision de M. Garnier ? Justifie.\n3. Que prévoit le droit français, selon le cours, en réponse à la question de la fille ? Nomme les lois concernées.","bareme":[{"critere":"Conflit autonomie (M. Garnier, décision informée) / bienfaisance (le médecin veut son bien), expliqué","points":7},{"critere":"Consentement volontaire : on ne peut imposer un acte médical, le corps n'est pas un matériau disponible","points":5},{"critere":"Lois Leonetti (2005) et Claeys-Leonetti (2016) : sédation profonde et continue, pas d'euthanasie active","points":6},{"critere":"Rédaction reliée à la situation","points":2}],"dureeMin":12,"corrige":"1. Le conflit oppose l'**autonomie** et la **bienfaisance**. M. Garnier, lucide et informé, exerce son **autonomie** : respecter la décision informée de la personne. Le docteur Lemoine agit selon la **bienfaisance** : il veut agir pour le bien de son patient en prolongeant sa vie. C'est le cas typique du débat bioéthique : arbitrer entre l'autonomie du patient et la bienfaisance du soignant. On peut ajouter la **non-malfaisance** : une opération lourde pour quelques mois peut aussi nuire.\n2. Le **consentement volontaire**, posé par le **code de Nuremberg** (1947) comme « absolument essentiel ». Aucun acte médical ne peut être imposé : **le corps n'est pas un matériau disponible**, même pour son bien.\n3. En France, les lois **Leonetti** (2005) et **Claeys-Leonetti** (2016) permettent une **sédation profonde et continue**, mais **pas d'euthanasie active**. On pourra donc soulager M. Garnier jusqu'à l'endormir profondément, mais pas provoquer délibérément sa mort."}$exo$::jsonb),
  ('215ac38c-8bc0-521d-90f8-78b2edabf966'::uuid, 3, 'redaction', $exo${"titre":"Peut-on modifier le génome de ses enfants ?","consigne":"Rédige un essai construit (introduction problématisée, deux ou trois parties, conclusion) en mobilisant au moins cinq références du chapitre.","enonce":"**Sujet d'essai**\n\n> Tout ce que la technique permet sur le vivant doit-il être autorisé ?\n\nAppuie-toi en particulier sur la question de l'édition du génome : CRISPR-Cas9, les cellules germinales et l'affaire de 2018. Mobilise aussi Nuremberg, les quatre principes, Kant, Habermas, et la méthode française.\n\nRéponds clairement dans ta conclusion.","bareme":[{"critere":"Problématique : écart entre ce que la technique permet et ce que la loi autorise ; au nom de quoi autoriser","points":3},{"critere":"Dossier du génome exact : CRISPR-Cas9 (2012), cellules germinales transmissibles, moratoire franchi en 2018 par He Jiankui, condamné","points":5},{"critere":"Kant (dignité, non un prix ; jamais simplement comme un moyen) et Habermas (égalité entre générations, auteur de sa vie)","points":6},{"critere":"Nuremberg, principes, méthode française délibérative et révisable (CCNE)","points":3},{"critere":"Conclusion qui répond à la question","points":3}],"dureeMin":20,"corrige":"**Problématique.** La bioéthique naît d'un **écart** : la médecine peut faire des choses sur lesquelles aucune tradition morale ne s'était prononcée. Elle ne consiste pas à interdire, mais à décider **au nom de quoi** on autorise. Le possible technique vaut-il permission ?\n\n**Partie 1 — Ce que la technique permet.** **CRISPR-Cas9** (2012) a rendu l'édition génétique **simple et peu coûteuse** : la question est passée du laboratoire au débat public. Modifier les cellules **germinales**, c'est modifier ce qui se **transmet aux descendants**. Un **moratoire international** existe ; il a été **franchi en 2018 par He Jiankui**, condamné en Chine.\n\n**Partie 2 — Au nom de quoi limiter.** Le **code de Nuremberg** : le **consentement volontaire** est essentiel — or l'enfant à naître ne peut pas consentir. **Kant** : la personne a une **dignité**, non un **prix** ; elle ne doit jamais être traitée « simplement comme un moyen ». **Habermas** (*L'Avenir de la nature humaine*, 2001) : programmer génétiquement un enfant **rompt l'égalité entre générations** — celui qui a été conçu selon un projet ne peut plus se considérer comme **l'auteur unique de sa vie**. Les quatre principes (autonomie, bienfaisance, non-malfaisance, justice) obligent à arbitrer : soigner une maladie grave n'est pas « améliorer » un enfant.\n\n**Partie 3 — Une méthode plutôt qu'un dogme.** La France a choisi, avec le **CCNE** (1983), des lois de bioéthique **révisées périodiquement** et des états généraux, une éthique **délibérative et révisable**.\n\n**Conclusion.** Non : ce que la technique permet ne doit pas être autorisé par principe. Chaque pouvoir nouveau doit être justifié — ici, la dignité de l'enfant et l'égalité entre générations imposent la plus grande prudence envers l'édition germinale —, par une délibération publique qui reste révisable."}$exo$::jsonb),
  ('4b21fe51-1861-54d5-a941-0bd78aa07130'::uuid, 1, 'redaction', $exo${"titre":"Connaître l'épreuve","consigne":"Réponds à chaque question avec précision.","enonce":"**Questions de cours**\n\n1. Combien de temps dure l'épreuve de HLP ? Combien comporte-t-elle d'exercices, notés sur combien, et à partir de quoi ?\n2. Compare l'**interprétation littéraire** et l'**essai philosophique** : ce qui est donné, ce qu'on attend, le matériau, le risque.\n3. Propose une répartition du temps pour les deux exercices et la relecture, et dis pourquoi la relecture compte.","bareme":[{"critere":"4 heures ; deux exercices notés sur 10 chacun, à partir d'un même texte","points":5},{"critere":"Comparaison juste sur les quatre lignes du tableau","points":9},{"critere":"Répartition (2 h, 1 h 50, 10 min, dont préparation au brouillon) et rôle de la relecture (syntaxe, exactitude des citations)","points":6}],"dureeMin":8,"corrige":"1. L'épreuve dure **4 heures** et comporte **deux exercices notés sur 10 chacun**, à partir d'un **même texte**.\n2. **Interprétation littéraire** : on reçoit une **question sur le texte** ; on attend une **analyse du texte lui-même** ; le matériau est fait de **citations courtes et exactes** ; le risque est de **paraphraser**. **Essai philosophique** : on reçoit une **question liée au thème, plus large** ; on attend une **argumentation qui dépasse le texte** ; le matériau, ce sont des **exemples littéraires, historiques, scientifiques** ; le risque est de **réciter un cours**.\n3. **Exercice 1** : 2 h, dont 20 min de préparation au brouillon. **Exercice 2** : 1 h 50, dont 20 min de préparation. **Relecture** : 10 min, pour la **syntaxe** et l'**exactitude des citations**. Elle compte parce que les fautes de syntaxe et les citations approximatives pèsent lourd sur une copie qui, sur le fond, se tenait : les dix dernières minutes rapportent plus que les dix premières."}$exo$::jsonb),
  ('4b21fe51-1861-54d5-a941-0bd78aa07130'::uuid, 2, 'redaction', $exo${"titre":"Corriger un paragraphe d'interprétation","consigne":"Lis le texte et le paragraphe d'élève (tous deux inventés pour l'exercice), puis réponds.","enonce":"**Texte** (inventé pour l'exercice)\n\n> Je rouvre la boîte de mes lettres d'enfance. L'encre a pâli, les mots aussi. Qui était cet enfant si sûr de lui ? Je ne le reconnais qu'à son écriture, penchée comme la mienne.\n\n**Question posée** : comment le narrateur exprime-t-il l'écart entre lui et l'enfant qu'il a été ?\n\n**Paragraphe de Tom** :\n> Dans ce texte, le narrateur ouvre une boîte avec des lettres de quand il était petit. Il dit que l'encre a pâli. Ensuite il se demande qui était cet enfant. Il y a une question rhétorique. À la fin il reconnaît son écriture. Comme le disait Montaigne, Descartes, Freud et Rousseau, le moi change.\n\n1. Identifie les **trois erreurs** de méthode que commet Tom, en les nommant avec les termes du cours et en citant son paragraphe.\n2. Explique pourquoi « Il y a une question rhétorique » ne rapporte rien, selon le cours.\n3. Réécris un paragraphe d'interprétation (6 à 8 lignes) qui répond à la question en articulant **procédé relevé** et **effet produit**, avec des citations courtes et exactes.","bareme":[{"critere":"Trois erreurs identifiées et citées : paraphrase, procédé nommé sans effet, accumulation de références qui décorent","points":6},{"critere":"Un procédé nommé sans effet analysé ne rapporte rien : explication","points":3},{"critere":"Paragraphe réécrit : thèse claire, au moins deux procédés reliés à leur effet, sans suivre le texte ligne à ligne","points":8},{"critere":"Citations courtes et exactes, syntaxe correcte","points":3}],"dureeMin":12,"corrige":"1. **Paraphrase** : « le narrateur ouvre une boîte… Il dit que l'encre a pâli. Ensuite… À la fin… » — Tom raconte le texte ligne à ligne au lieu de l'expliquer. **Procédé nommé sans effet** : « Il y a une question rhétorique » — rien sur ce qu'elle produit. **Accumulation de références** : « Comme le disait Montaigne, Descartes, Freud et Rousseau » — des noms qui **décorent** et ne **travaillent** pas, cités sans rien dire de précis (et l'interprétation porte sur le texte, non sur un cours).\n2. Le cours dit qu'**un procédé nommé sans effet analysé ne rapporte rien** : l'interprétation repose sur l'articulation entre le procédé relevé et l'effet produit. Repérer une figure n'est qu'un début.\n3. **Exemple de paragraphe attendu** : « Le narrateur traduit d'abord l'écart par l'usure du temps : le parallèle entre ‹ L'encre a pâli › et ‹ les mots aussi › fait passer la perte du support matériel au sens, comme si les lettres ne disaient plus rien à celui qui les relit. La question ‹ Qui était cet enfant si sûr de lui ? › le confirme : en parlant de lui-même à la troisième personne (‹ cet enfant ›), il s'en sépare et le regarde comme un étranger. Pourtant, un fil demeure : ‹ penchée comme la mienne ›. La comparaison ne sauve qu'une trace corporelle, l'écriture, et non l'identité intérieure : le narrateur ne se reconnaît plus que du dehors. » On valorise toute analyse juste qui relie au moins deux procédés à leur effet et répond à la question."}$exo$::jsonb),
  ('4b21fe51-1861-54d5-a941-0bd78aa07130'::uuid, 3, 'redaction', $exo${"titre":"Construire un essai de A à Z","consigne":"Prépare au brouillon, puis rédige l'introduction et le plan détaillé d'un essai, en appliquant la méthode du cours.","enonce":"**Sujet d'essai**\n\n> Se raconter, est-ce se connaître ?\n\n1. **Problématise** : rédige une introduction (8 à 10 lignes) qui montre que la question n'a pas de réponse évidente et se termine par une problématique.\n2. Rédige un **plan détaillé** en deux ou trois parties : pour chacune, une **thèse** formulée en une phrase et au moins un **exemple** précis (littéraire, historique ou personnel) qui sert l'argument.\n3. Rédige la **conclusion** (4 à 6 lignes) : elle doit répondre effectivement à la question.\n4. Dis, en deux ou trois phrases, quelles erreurs du cours ton travail évite, et comment.","bareme":[{"critere":"Introduction qui problématise : tension explicite, problématique formulée","points":5},{"critere":"Plan : parties argumentées, chacune avec une thèse claire, progression logique","points":6},{"critere":"Exemples précis et exploités, qui servent l'argument (pas de liste de références)","points":3},{"critere":"Conclusion qui répond effectivement à la question posée","points":3},{"critere":"Retour réflexif pertinent sur les erreurs évitées (réciter, accumuler, plan non suivi)","points":3}],"dureeMin":20,"corrige":"Plusieurs réponses sont possibles ; le correcteur vérifie la **méthode** plus que le contenu. Exemple de copie attendue :\n\n1. **Introduction.** Se raconter semble le moyen le plus direct de se connaître : qui mieux que moi sait ce que j'ai vécu ? Pourtant, raconter, c'est choisir, ordonner, justifier : le récit pourrait aussi bien masquer que révéler. **Problématique** : le récit de soi est-il un chemin vers la vérité sur soi, ou une construction qui fabrique le moi qu'elle prétend décrire ?\n\n2. **Plan détaillé.**\n- **I. Se raconter permet de se connaître.** Thèse : mettre sa vie en récit oblige à prendre du recul et à se voir. Exemple : Montaigne, « je suis moi-même la matière de mon livre » — l'écriture devient un examen de soi.\n- **II. Mais le récit sélectionne et fabrique.** Thèse : on raconte ce qui nous arrange, et l'inconscient échappe au récit. Exemple : un journal relu des années plus tard, où l'on découvre ce qu'on avait tu ; Freud, le moi « pas maître dans sa propre maison ».\n- **III. Se raconter, c'est se construire, et cette construction est une connaissance.** Thèse : le récit ne restitue pas un moi déjà là, mais il permet de tenir une identité dans le temps. Exemple : l'identité narrative de Ricœur (tenir ses promesses malgré le changement).\n\n3. **Conclusion.** Se raconter n'est pas se connaître au sens de découvrir une vérité cachée : le récit trie et fabrique. Mais c'est une manière de se connaître **en se construisant** — à condition de lire son propre récit avec soupçon.\n\n4. **Retour réflexif.** Le travail évite de **réciter un cours** (chaque référence répond à la question), d'**accumuler des références** (un exemple par partie, exploité), et d'**annoncer un plan qu'on ne suit pas** (la problématique annonce exactement les trois parties). Il **conclut** en répondant à la question."}$exo$::jsonb),
  ('6cb7aadf-41e1-552f-82c2-e653fd402ea7'::uuid, 1, 'application', $exo${"titre":"Le lampadaire solaire du chemin piéton","consigne":"Lis l'extrait du cahier des charges, puis réponds à chaque question en t'appuyant sur le vocabulaire du cours.","enonce":"**Situation.** Une commune veut équiper un chemin piéton de lampadaires solaires autonomes. Voici un extrait du diagramme d'exigences (req) et de ses relations.\n\n> **Exigence 1** « Éclairer le chemin piéton »\n> - contient **1.1** « Éclairer toute la nuit » — critère : 12 h d'éclairage\n> - contient **1.2** « Résister aux intempéries » — critère : fonctionner de −10 °C à 40 °C\n>\n> **Exigence 1.1.1** « Stocker 240 Wh » — relation **deriveReqt** vers 1.1\n> Bloc **Batterie 12 V** — relation **satisfy** vers 1.1.1\n> Essai **Test en chambre climatique** — relation **verify** vers 1.2\n\n1. Explique le sens de chacune des quatre relations présentes dans l'extrait (contient, deriveReqt, satisfy, verify), en t'appuyant sur les éléments du lampadaire.\n2. Deux essais sont prévus : (a) on mesure au banc que la batterie stocke bien 240 Wh ; (b) on fait marcher des promeneurs de nuit sur le chemin pour savoir s'ils se sentent suffisamment éclairés. Pour chacun, dis s'il s'agit d'une **vérification** ou d'une **validation**, et justifie.\n3. Cite deux parties prenantes autres que l'usager dont il faut tenir compte, et donne pour chacune une exigence qu'elle pourrait imposer.","bareme":[{"critere":"Sens correct des quatre relations, illustré par les éléments du lampadaire","points":8},{"critere":"Essai (a) classé en vérification et essai (b) en validation, avec justification spécification / besoin","points":6},{"critere":"Deux parties prenantes pertinentes avec une exigence plausible pour chacune","points":6}],"dureeMin":8,"corrige":"1. Les relations :\n- **contient** : l'exigence 1 se décompose en sous-exigences 1.1 et 1.2 ;\n- **deriveReqt** : l'exigence technique 1.1.1 (stocker 240 Wh) découle de l'exigence de plus haut niveau 1.1 (éclairer toute la nuit) ;\n- **satisfy** : le bloc Batterie 12 V répond à l'exigence 1.1.1 ;\n- **verify** : l'essai en chambre climatique contrôle l'exigence 1.2.\n2. (a) C'est une **vérification** : on contrôle qu'un constituant (la batterie) respecte sa **spécification** (240 Wh). (b) C'est une **validation** : on regarde si le système répond au **besoin** de l'usager (se sentir éclairé sur le chemin). On vérifie par rapport aux spécifications, on valide par rapport au besoin.\n3. Exemples attendus (deux suffisent) :\n- le **mainteneur** : changer la batterie sans outil spécial, en moins de 15 min ;\n- le **gestionnaire** (la commune) : coût d'entretien limité, suivi du fonctionnement ;\n- la **réglementation** : aucune partie sous tension accessible, normes électriques ;\n- l'**environnement** : résister au vandalisme et aux intempéries.\nOublier une partie prenante, c'est oublier une exigence."}$exo$::jsonb),
  ('6cb7aadf-41e1-552f-82c2-e653fd402ea7'::uuid, 2, 'application', $exo${"titre":"Quel chargeur pour la station de trottinettes ?","consigne":"Pour chaque calcul, écris la formule, l'application numérique avec les unités, puis compare le résultat au critère en citant l'identifiant de l'exigence.","enonce":"**Situation.** Une station de recharge de trottinettes en libre-service doit respecter l'exigence suivante :\n\n> **Id 2.1** — « Recharger une batterie de 360 Wh » — critère : **en moins de 3 h**.\n\nDeux chargeurs sont proposés :\n\n| Chargeur | Puissance absorbée | Rendement |\n| A | 150 W | 0,85 |\n| B | 120 W | 0,9 |\n\nOn considère que la puissance fournie à la batterie est constante pendant toute la charge.\n\n1. Calcule la puissance réellement fournie à la batterie par chacun des deux chargeurs.\n2. Calcule la durée de charge avec chaque chargeur.\n3. Justifie, pour chaque chargeur, si l'exigence 2.1 est satisfaite.\n4. Quelle puissance absorbée minimale faudrait-il à un chargeur de rendement 0,9 pour satisfaire tout juste l'exigence ?","bareme":[{"critere":"Puissances fournies à la batterie justes : 127,5 W pour A et 108 W pour B","points":5},{"critere":"Durées de charge justes : environ 2,8 h pour A et 3,3 h pour B","points":5},{"critere":"Conclusion citant l'identifiant 2.1 et comparant chaque durée au critère de 3 h","points":5},{"critere":"Puissance minimale calculée : 120 W en sortie, soit environ 133 W absorbés","points":5}],"dureeMin":10,"corrige":"1. Puissance fournie = rendement × puissance absorbée.\n- A : 0,85 × 150 = **127,5 W**.\n- B : 0,9 × 120 = **108 W**.\n2. Durée = énergie / puissance.\n- A : 360 / 127,5 ≈ **2,8 h** (environ 2 h 50 min).\n- B : 360 / 108 ≈ **3,3 h** (environ 3 h 20 min).\n3. Exigence **2.1** (moins de 3 h) :\n- chargeur A : 2,8 h < 3 h → l'exigence est **satisfaite**, avec une faible marge ;\n- chargeur B : 3,3 h > 3 h → l'exigence **n'est pas satisfaite** : chargeur non conforme.\n4. Pour charger 360 Wh en 3 h, il faut fournir à la batterie au moins 360 / 3 = **120 W**. Avec un rendement de 0,9, la puissance absorbée doit valoir au moins 120 / 0,9 ≈ **133 W**. Un chargeur de 120 W absorbés ne suffit donc pas, comme le montre la question 3."}$exo$::jsonb),
  ('6cb7aadf-41e1-552f-82c2-e653fd402ea7'::uuid, 3, 'application', $exo${"titre":"Une borne de recharge hors réseau pour un parc naturel","consigne":"Analyse le cahier des charges et réponds en justifiant chaque réponse : identifiant de l'exigence, valeur calculée, comparaison au critère, conclusion.","enonce":"**Situation.** Un parc naturel installe à l'entrée d'un sentier une borne solaire de recharge de vélos, sans raccordement au réseau.\n\n**Extrait du diagramme d'exigences**\n\n| Id | Texte | Critère |\n| 1 | Recharger les vélos des visiteurs | — |\n| 1.1 | Recharger une batterie de vélo | En moins de 4 h |\n| 1.2 | Fonctionner hors réseau | Autonomie de 3 jours sans soleil |\n| 1.3 | Protéger l'usager | Aucune partie sous tension accessible |\n\n**Données.** Consommation moyenne de la borne : **1,2 kWh par jour**. Le bloc Batterie de stockage annonce **4,2 kWh utilisables**. Un essai de trois jours sans recharge solaire a été mené sur site.\n\n1. Justifie que la solution satisfait (ou non) l'exigence 1.2. Donne la marge obtenue en pourcentage.\n2. Quelle relation relie le bloc Batterie de stockage à l'exigence 1.2 ? Et l'essai de trois jours sur site ?\n3. Après un été d'utilisation, toutes les exigences sont respectées, mais les visiteurs se plaignent de devoir attendre longtemps car la borne ne recharge que deux vélos à la fois. Le système est-il **vérifié** ? Est-il **validé** ? Explique. Que désignerait la **qualification** de cette borne ?\n4. Des câbles ont été arrachés par des personnes malveillantes. Quelle partie prenante a été oubliée ? Rédige une exigence nouvelle, avec un identifiant et un critère vérifiable, pour corriger cet oubli.","bareme":[{"critere":"Exigence 1.2 vérifiée : 3 × 1,2 = 3,6 kWh comparé à 4,2 kWh, conclusion et marge d'environ 17 %","points":5},{"critere":"Relations satisfy (batterie → 1.2) et verify (essai → 1.2) correctement attribuées","points":4},{"critere":"Distinction vérifié / non validé argumentée par spécification et besoin ; qualification définie","points":5},{"critere":"Partie prenante « environnement » identifiée et exigence nouvelle avec identifiant et critère chiffré ou vérifiable","points":4},{"critere":"Rédaction structurée : identifiant cité, calcul posé, conclusion explicite","points":2}],"dureeMin":18,"corrige":"1. Énergie nécessaire pour 3 jours sans soleil : 3 × 1,2 = **3,6 kWh**. Énergie utilisable : 4,2 kWh. 4,2 kWh > 3,6 kWh : l'exigence **1.2 est satisfaite**. Marge : (4,2 − 3,6) / 3,6 ≈ 0,17, soit environ **17 %**.\n2. Le bloc Batterie de stockage **satisfait** (satisfy) l'exigence 1.2. L'essai de trois jours **vérifie** (verify) l'exigence 1.2.\n3. Le système est **vérifié** : chaque exigence du cahier des charges, donc chaque spécification, est respectée. Il n'est pas **validé** : il ne répond pas pleinement au **besoin** des visiteurs, qui veulent recharger sans attendre. On vérifie par rapport aux spécifications, on valide par rapport au besoin : ici le cahier des charges a oublié une exigence sur le nombre de vélos rechargés en même temps. La **qualification** consisterait à mesurer les performances réelles de la borne produite et installée (durée réelle de charge, autonomie réelle).\n4. La partie prenante oubliée est l'**environnement** (vandalisme, intempéries). Exemple d'exigence : **1.4** « Résister au vandalisme » — critère : aucun câble ni connecteur accessible sans outil spécial, ou câbles sous gaine métallique résistant à un arrachement donné. Toute exigence est acceptée si elle a un identifiant et un critère que l'on peut contrôler par un essai. Oublier une partie prenante, c'est oublier une exigence."}$exo$::jsonb),
  ('f947ad8e-255e-5af6-a101-00ba1a63ed2a'::uuid, 1, 'application', $exo${"titre":"Gourde ou bouteilles jetables : poser l'ACV","consigne":"Réponds à chaque question en utilisant le vocabulaire de l'analyse de cycle de vie.","enonce":"**Situation.** Maëlle veut comparer, pour sa classe, l'impact environnemental d'une gourde en inox et celui de bouteilles d'eau en plastique jetables. Son premier brouillon compare « 1 gourde » à « 1 bouteille ».\n\n1. Cite, dans l'ordre, les quatre étapes d'une analyse de cycle de vie normalisée.\n2. Explique pourquoi comparer « 1 gourde » à « 1 bouteille » n'a pas de sens, puis propose une **unité fonctionnelle** adaptée à cette comparaison.\n3. Associe chacun des indicateurs suivants à son unité : réchauffement climatique, épuisement des ressources, consommation d'eau, énergie primaire consommée.","bareme":[{"critere":"Les quatre étapes citées dans l'ordre : objectif et champ, inventaire, évaluation des impacts, interprétation","points":6},{"critere":"Critique de la comparaison objet contre objet et unité fonctionnelle quantifiée proposée","points":7},{"critere":"Quatre indicateurs associés à la bonne unité","points":7}],"dureeMin":7,"corrige":"1. Les quatre étapes : **objectif et champ** (dont l'unité fonctionnelle) → **inventaire** (matières, énergie, transports, rejets à chaque phase) → **évaluation des impacts** → **interprétation** (quelle phase et quel choix pèsent le plus).\n2. Une gourde sert des centaines de fois, une bouteille une seule fois : elles ne rendent pas le même service. On compare des **services rendus**, pas des objets. Unité fonctionnelle possible : « fournir 1 L d'eau à boire par jour pendant 1 an » (soit 365 L). On compte alors une gourde contre environ 365 bouteilles de 1 L.\n3. Associations :\n- réchauffement climatique → **kg éq. CO2** ;\n- épuisement des ressources → **kg éq. antimoine** ;\n- consommation d'eau → **m³** ;\n- énergie primaire consommée → **MJ ou kWh**."}$exo$::jsonb),
  ('f947ad8e-255e-5af6-a101-00ba1a63ed2a'::uuid, 2, 'application', $exo${"titre":"Relamper l'atelier du lycée","consigne":"Pose chaque calcul (formule, application numérique, unité) puis conclus en citant la phase du cycle de vie concernée.","enonce":"**Situation.** L'atelier du lycée est éclairé par des tubes fluorescents. On étudie leur remplacement par des tubes LED.\n\n**Unité fonctionnelle** : éclairer un poste de travail pendant **30 000 h**.\n\n| | Tube fluorescent | Tube LED |\n| Puissance | 36 W | 18 W |\n| Durée de vie | 10 000 h | 30 000 h |\n| Fabrication d'un tube | 0,4 kg éq. CO2 | 1,5 kg éq. CO2 |\n\nFacteur d'émission de l'électricité : **60 g de CO2 par kWh**.\n\n1. Combien de tubes de chaque type faut-il pour assurer l'unité fonctionnelle ?\n2. Calcule l'énergie consommée pendant l'usage par chaque solution, en kWh.\n3. Calcule les émissions de l'usage, puis le total (usage + fabrication) pour chaque solution.\n4. Par combien la solution LED divise-t-elle l'impact sur le climat ? Quelle phase domine ? Conclus.","bareme":[{"critere":"Nombre de tubes juste (3 fluorescents, 1 LED) et énergies de 1 080 kWh et 540 kWh","points":6},{"critere":"Émissions de l'usage justes : 64,8 kg et 32,4 kg éq. CO2","points":5},{"critere":"Totaux justes : environ 66 kg et 34 kg éq. CO2","points":5},{"critere":"Rapport d'environ 2, phase d'usage dominante et conclusion argumentée","points":4}],"dureeMin":12,"corrige":"1. Fluorescent : 30 000 / 10 000 = **3 tubes**. LED : 30 000 / 30 000 = **1 tube**.\n2. E = P × t.\n- Fluorescent : 36 W × 30 000 h = 1 080 000 Wh = **1 080 kWh**.\n- LED : 18 W × 30 000 h = 540 000 Wh = **540 kWh**.\n3. Émissions de l'usage (0,06 kg/kWh) :\n- fluorescent : 1 080 × 0,06 = **64,8 kg éq. CO2** ; fabrication : 3 × 0,4 = 1,2 kg ; total ≈ **66,0 kg éq. CO2** ;\n- LED : 540 × 0,06 = **32,4 kg éq. CO2** ; fabrication : 1 × 1,5 = 1,5 kg ; total ≈ **33,9 kg éq. CO2**.\n4. 66,0 / 33,9 ≈ **1,9** : la LED divise l'impact climatique par environ **2**. Dans les deux cas, la phase d'**usage** domine très largement (plus de 95 % du total) : la fabrication plus lourde du tube LED est largement compensée par sa plus faible consommation et sa plus longue durée de vie. Le remplacement est justifié par le calcul."}$exo$::jsonb),
  ('f947ad8e-255e-5af6-a101-00ba1a63ed2a'::uuid, 3, 'application', $exo${"titre":"Alléger le cadre d'une trottinette : fausse bonne idée ?","consigne":"Analyse les données, pose chaque calcul et justifie ton choix par des nombres et par la phase du cycle de vie qu'il améliore.","enonce":"**Situation.** Un fabricant de trottinettes électriques veut alléger le cadre, aujourd'hui en acier. Un ingénieur propose l'aluminium.\n\n| Solution | Masse du cadre | Fabrication de la matière |\n| Acier | 6 kg | 2 kg éq. CO2 par kg |\n| Aluminium primaire | 3,5 kg | 9 kg éq. CO2 par kg |\n| Aluminium recyclé | 3,5 kg | 1 kg éq. CO2 par kg |\n\n**Usage.** Sur toute la durée de vie de la trottinette (10 000 km), chaque kilogramme transporté ajoute **1 kWh** de consommation électrique.\n\n1. Calcule, pour chaque solution, les émissions dues à la fabrication de la matière du cadre.\n2. Calcule, pour chaque solution, les émissions de l'usage attribuables à la masse du cadre, avec un mix à **60 g de CO2 par kWh**. Fais le total.\n3. Quelle solution retenir ? Justifie en citant la phase qui pèse le plus.\n4. Refais le calcul de l'usage pour l'acier et l'aluminium primaire avec un mix très carboné à **500 g/kWh**. Ton classement change-t-il ?\n5. Propose un autre levier d'éco-conception pour ce cadre et précise son point de vigilance.","bareme":[{"critere":"Émissions de fabrication justes : 12 kg, 31,5 kg et 3,5 kg éq. CO2","points":5},{"critere":"Émissions d'usage (0,36 kg ; 0,21 kg) et totaux justes pour les trois solutions","points":4},{"critere":"Choix de l'aluminium recyclé justifié par le calcul et la phase de fabrication dominante","points":5},{"critere":"Calcul avec le mix à 500 g/kWh (15 kg contre 33,25 kg) et conclusion sur le classement","points":3},{"critere":"Levier supplémentaire pertinent avec son point de vigilance","points":3}],"dureeMin":18,"corrige":"1. Fabrication :\n- acier : 6 × 2 = **12 kg éq. CO2** ;\n- aluminium primaire : 3,5 × 9 = **31,5 kg éq. CO2** ;\n- aluminium recyclé : 3,5 × 1 = **3,5 kg éq. CO2**.\n2. Usage : masse × 1 kWh/kg × 0,06 kg/kWh.\n- acier : 6 × 0,06 = 0,36 kg → total ≈ **12,4 kg éq. CO2** ;\n- aluminium primaire : 3,5 × 0,06 = 0,21 kg → total ≈ **31,7 kg éq. CO2** ;\n- aluminium recyclé : 0,21 kg → total ≈ **3,7 kg éq. CO2**.\n3. Avec l'électricité française peu carbonée, l'allègement ne fait gagner que 0,15 kg à l'usage : c'est la **fabrication de la matière** qui pèse le plus. L'aluminium primaire est **plus de 2,5 fois pire** que l'acier (l'aluminium primaire demande beaucoup d'énergie à produire). On retient l'**aluminium recyclé** (≈ 3,7 kg contre 12,4 kg pour l'acier), à condition de garantir l'approvisionnement en matière recyclée ; à défaut, on garde l'acier.\n4. Mix à 500 g/kWh : acier 12 + 6 × 0,5 = **15 kg** ; aluminium primaire 31,5 + 3,5 × 0,5 = **33,25 kg**. L'écart d'usage grandit, mais le classement **ne change pas** : l'aluminium primaire reste le plus mauvais choix.\n5. Exemples : **allonger la durée de vie** (cadre et pièces vissés, pièces détachées) — vigilance : coût de fabrication un peu plus élevé ; **prévoir la fin de vie** (cadre monomatériau, marquage) — vigilance : contraintes de conception."}$exo$::jsonb),
  ('1e93d6ee-75bb-5f4f-bf3b-11f57521c6a1'::uuid, 1, 'application', $exo${"titre":"Quatre convertisseurs, un hacheur","consigne":"Réponds à chaque question ; pour les calculs, écris la formule puis l'application numérique.","enonce":"**Situation.** Dans la maison de Samir, on trouve plusieurs convertisseurs statiques.\n\n1. Nomme le convertisseur utilisé dans chaque cas et la conversion qu'il réalise (AC ou DC en entrée, AC ou DC en sortie) :\n   a. le chargeur de téléphone branché sur une prise du secteur ;\n   b. le variateur qui règle la luminosité d'une lampe halogène alimentée par le secteur ;\n   c. l'appareil qui injecte sur le réseau l'électricité des panneaux solaires du toit ;\n   d. le variateur de vitesse de la trottinette électrique de Samir, alimentée par une batterie.\n2. Le hacheur de la trottinette est alimenté par une batterie de **36 V**. Calcule la tension moyenne de sortie pour un rapport cyclique α = 0,4.\n3. Quel rapport cyclique faut-il pour obtenir **27 V** moyens ?","bareme":[{"critere":"Quatre convertisseurs identifiés avec la bonne conversion : redresseur, gradateur, onduleur, hacheur","points":8},{"critere":"Tension moyenne juste : 0,4 × 36 = 14,4 V","points":6},{"critere":"Rapport cyclique juste : 27 / 36 = 0,75","points":6}],"dureeMin":8,"corrige":"1. Les convertisseurs :\n- a. **redresseur** : AC → DC ;\n- b. **gradateur** : AC → AC, valeur efficace réglable ;\n- c. **onduleur** : DC → AC ;\n- d. **hacheur** : DC → DC réglable.\n2. U moy = α × U alim = 0,4 × 36 = **14,4 V**.\n3. α = U moy / U alim = 27 / 36 = **0,75** (le transistor est passant pendant les trois quarts de la période)."}$exo$::jsonb),
  ('1e93d6ee-75bb-5f4f-bf3b-11f57521c6a1'::uuid, 2, 'application', $exo${"titre":"Le variateur du chariot de manutention","consigne":"Pose chaque calcul avec les unités et justifie les réponses qualitatives avec le cours.","enonce":"**Situation.** Un petit chariot de manutention électrique est entraîné par un moteur à courant continu, alimenté par une batterie de **48 V** à travers un hacheur piloté en MLI. Pour la vitesse de croisière, le moteur doit recevoir **30 V** moyens. La fréquence de découpage est de **25 kHz**.\n\n1. Calcule le rapport cyclique α nécessaire.\n2. Calcule la période T du découpage, puis la durée t_on pendant laquelle le transistor est passant.\n3. Justifie le choix d'une fréquence de 25 kHz.\n4. Le constructeur annonce un rendement du hacheur supérieur à 95 %. Explique pourquoi ce convertisseur dissipe si peu d'énergie.\n5. Le chariot doit pouvoir reculer et freiner en renvoyant de l'énergie vers la batterie. Quelle structure faut-il ? Explique comment elle inverse le sens de rotation.","bareme":[{"critere":"Rapport cyclique juste : α = 30 / 48 = 0,625","points":5},{"critere":"Période de 40 µs et t_on de 25 µs justes","points":5},{"critere":"Choix de la fréquence et fort rendement expliqués (hors audible, lissage, transistor bloqué ou saturé)","points":5},{"critere":"Pont en H : diagonales, inversion du courant et freinage récupératif expliqués","points":5}],"dureeMin":11,"corrige":"1. α = U moy / U alim = 30 / 48 = **0,625**.\n2. T = 1 / f = 1 / 25 000 = 0,000 04 s = **40 µs**. t_on = α × T = 0,625 × 40 = **25 µs**.\n3. 25 kHz est au-dessus des fréquences audibles : le moteur ne siffle pas. C'est aussi assez élevé pour que l'inductance du moteur lisse le courant.\n4. Le transistor est soit **bloqué** (aucun courant ne le traverse), soit **saturé** (presque aucune tension à ses bornes) : dans les deux cas la puissance qu'il dissipe est très faible. D'où un rendement qui dépasse souvent 95 %.\n5. Il faut un **pont en H** (hacheur réversible) : quatre interrupteurs autour du moteur. En fermant la diagonale T1-T4 ou la diagonale T2-T3, on inverse le sens du courant dans le moteur, donc son **sens de rotation**. Le pont permet aussi le **freinage** ; comme la batterie accepte d'être rechargée, l'énergie de freinage peut lui être renvoyée : c'est la réversibilité du convertisseur."}$exo$::jsonb),
  ('1e93d6ee-75bb-5f4f-bf3b-11f57521c6a1'::uuid, 3, 'application', $exo${"titre":"La chaîne de traction d'une citadine électrique","consigne":"Analyse la chaîne de puissance, pose chaque calcul et argumente tes choix avec le cours.","enonce":"**Situation.** Une citadine électrique possède une batterie de **400 V** (continu) et un moteur synchrone à **4 paires de pôles**. Le moteur est piloté par un convertisseur placé entre la batterie et le moteur.\n\n1. Quel convertisseur faut-il entre la batterie et le moteur ? Précise la conversion réalisée et ce qu'il permet de régler.\n2. Un stagiaire propose un gradateur. Explique pourquoi c'est impossible.\n3. Calcule la fréquence d'alimentation nécessaire pour que le moteur tourne à **3 000 tr/min**, puis à **1 200 tr/min**.\n4. Que se passerait-il si l'on alimentait ce moteur directement en 50 Hz ? Calcule sa vitesse.\n5. Sans récupération d'énergie, l'autonomie en ville est de **240 km**. Le freinage récupératif fait gagner 10 à 25 % d'autonomie en ville. Donne la fourchette d'autonomie obtenue et explique quelle propriété du convertisseur rend ce gain possible.","bareme":[{"critere":"Onduleur identifié (DC → AC) réglant fréquence et amplitude ; gradateur écarté car il demande une source alternative","points":4},{"critere":"Fréquences justes : 200 Hz pour 3 000 tr/min et 80 Hz pour 1 200 tr/min, formule écrite","points":6},{"critere":"Vitesse en 50 Hz juste (750 tr/min) et conséquence expliquée","points":4},{"critere":"Fourchette de 264 à 300 km et réversibilité de l'onduleur expliquée","points":6}],"dureeMin":16,"corrige":"1. Il faut un **onduleur** : il transforme le continu de la batterie en alternatif (DC → AC) et permet de régler **la fréquence et l'amplitude** de la tension, donc la vitesse du moteur.\n2. Un gradateur réalise une conversion **AC → AC** : il a besoin d'une source alternative en entrée. Or la batterie fournit du continu : le gradateur ne peut pas fonctionner ici.\n3. N = 60 × f / p, donc f = N × p / 60.\n- 3 000 tr/min : f = 3 000 × 4 / 60 = **200 Hz** ;\n- 1 200 tr/min : f = 1 200 × 4 / 60 = **80 Hz**.\n4. En 50 Hz : N = 60 × 50 / 4 = **750 tr/min**, une seule vitesse, impossible à faire varier. Il faudrait de toute façon une source alternative. C'est parce que la vitesse dépend de la fréquence qu'on utilise un onduleur à fréquence réglable.\n5. 10 % de 240 = 24 km ; 25 % de 240 = 60 km. Autonomie : **de 264 à 300 km**. Ce gain repose sur la **réversibilité** de l'onduleur : au freinage, le moteur fonctionne en générateur et l'onduleur renvoie l'énergie vers la batterie (un redresseur à diodes, non réversible, ne le permettrait pas)."}$exo$::jsonb),
  ('21fc23b8-7d0a-5cee-8284-3fad6af886e5'::uuid, 1, 'application', $exo${"titre":"Batteries et cellules du camping-car","consigne":"Réponds à chaque question ; pour les calculs, écris la formule, l'application numérique et l'unité.","enonce":"**Situation.** Léo prépare l'équipement électrique du camping-car familial.\n\n1. La batterie auxiliaire porte l'inscription **12 V – 80 Ah**. Calcule l'énergie qu'elle stocke, en Wh.\n2. Classe chacun des stockages suivants dans sa forme (chimique, électrostatique, mécanique, thermique) : le ballon d'eau chaude du camping-car ; la batterie lithium-ion du vélo ; un supercondensateur ; une STEP (barrage de pompage).\n3. Léo dispose de quatre cellules identiques de **3,7 V – 2,5 Ah**. Donne la tension et la capacité du pack obtenu s'il les associe toutes les quatre en **série**, puis toutes les quatre en **parallèle**. Que remarques-tu sur l'énergie stockée dans les deux cas ?","bareme":[{"critere":"Énergie juste : E = U × Q = 12 × 80 = 960 Wh","points":6},{"critere":"Quatre stockages classés dans la bonne forme","points":6},{"critere":"Série (14,8 V ; 2,5 Ah) et parallèle (3,7 V ; 10 Ah) justes, énergie identique de 37 Wh","points":8}],"dureeMin":8,"corrige":"1. E = U × Q = 12 × 80 = **960 Wh**.\n2. Classement :\n- ballon d'eau chaude → **thermique** (chaleur sensible) ;\n- batterie lithium-ion → **chimique** ;\n- supercondensateur → **électrostatique** ;\n- STEP → **mécanique** (énergie potentielle de l'eau).\n3. En **série** : les tensions s'additionnent, la capacité reste celle d'une cellule : 4 × 3,7 = **14,8 V** et **2,5 Ah**.\nEn **parallèle** : les capacités s'additionnent, la tension reste celle d'une cellule : **3,7 V** et 4 × 2,5 = **10 Ah**.\nÉnergie : 14,8 × 2,5 = 37 Wh et 3,7 × 10 = 37 Wh. L'énergie est **la même** (quatre fois celle d'une cellule, 9,25 Wh) : seul le couple tension-capacité change."}$exo$::jsonb),
  ('21fc23b8-7d0a-5cee-8284-3fad6af886e5'::uuid, 2, 'application', $exo${"titre":"Dimensionner la batterie d'une tondeuse robot","consigne":"Pose chaque calcul (formule, application numérique, unité) et justifie le choix du pack.","enonce":"**Situation.** Une tondeuse robot consomme en moyenne **45 W** et doit tondre pendant **3 h** sans recharge. Pour préserver la batterie, on ne la décharge qu'à **80 %**. On fabrique le pack avec des cellules lithium-ion de **3,6 V – 2,5 Ah**. Le moteur demande une tension d'environ **25 V**.\n\n1. Calcule l'énergie nécessaire pour une tonte, puis l'énergie à installer.\n2. Combien de cellules faut-il en série pour atteindre environ 25 V ? Quelle est alors la tension du pack ?\n3. Calcule la capacité minimale du pack, puis le nombre de branches en parallèle nécessaire. Donne la désignation du pack (du type « xSyP »), son nombre de cellules et l'énergie qu'il stocke.\n4. Estime la masse du pack avec une énergie massique de **180 Wh/kg**.","bareme":[{"critere":"Énergie nécessaire de 135 Wh et énergie à installer d'environ 169 Wh","points":5},{"critere":"Sept cellules en série, tension de 25,2 V","points":4},{"critere":"Capacité minimale d'environ 6,7 Ah, pack 7S3P de 21 cellules stockant 189 Wh, choix justifié","points":6},{"critere":"Masse estimée juste : environ 1,05 kg","points":5}],"dureeMin":12,"corrige":"1. Énergie nécessaire : E = P × t = 45 × 3 = **135 Wh**. Décharge limitée à 80 % : énergie à installer = 135 / 0,8 ≈ **169 Wh** (168,75 Wh).\n2. 25 / 3,6 ≈ 6,9 → **7 cellules en série** : 7 × 3,6 = **25,2 V**.\n3. Capacité minimale : Q = E / U = 168,75 / 25,2 ≈ **6,7 Ah**. Une branche fournit 2,5 Ah : 2 branches donnent 5 Ah (insuffisant), **3 branches** donnent 7,5 Ah ≥ 6,7 Ah. Pack **7S3P** : 7 × 3 = **21 cellules**, 25,2 V et 7,5 Ah, soit 25,2 × 7,5 = **189 Wh** ≥ 169 Wh : le pack convient.\n4. Masse ≈ 189 / 180 ≈ **1,05 kg**."}$exo$::jsonb),
  ('21fc23b8-7d0a-5cee-8284-3fad6af886e5'::uuid, 3, 'application', $exo${"titre":"Stocker le surplus solaire d'une maison","consigne":"Analyse les deux solutions, pose chaque calcul et argumente ta conclusion avec les notions du cours.","enonce":"**Situation.** La toiture solaire d'une famille produit à midi plus qu'elle ne consomme. Deux solutions sont envisagées pour mettre ce surplus de côté :\n\n- **Solution A** : une batterie domestique lithium-ion de **5 kWh** ;\n- **Solution B** : piloter le ballon d'eau chaude de **300 L** pour le chauffer de **20 à 55 °C** aux heures de production (c eau = 4 185 J/(kg·°C), 1 L d'eau = 1 kg).\n\n1. Indique la forme de stockage de chaque solution.\n2. Calcule l'énergie stockée par le ballon, en joules puis en kWh.\n3. Estime la masse de la batterie A en lithium-ion (200 Wh/kg), puis celle qu'aurait une batterie au plomb de même énergie (35 Wh/kg).\n4. Compare les deux solutions : quantité stockée, forme de l'énergie restituée, usages possibles. Laquelle conseilles-tu en premier, et pourquoi ?\n5. La batterie A est livrée avec un BMS. Explique son rôle.\n6. Le fabricant propose d'ajouter un supercondensateur à la batterie pour démarrer un gros moteur (pompe de piscine). Justifie cette association.","bareme":[{"critere":"Formes identifiées et énergie du ballon juste : environ 43,9 MJ, soit 12,2 kWh","points":6},{"critere":"Masses justes : 25 kg en lithium-ion et environ 143 kg en plomb","points":4},{"critere":"Comparaison argumentée : chaleur seulement pour le ballon, électricité pour la batterie, conseil justifié","points":4},{"critere":"Rôle du BMS : surveiller tensions, courants, températures, équilibrer, couper en cas de danger","points":3},{"critere":"Association batterie et supercondensateur justifiée par énergie contre puissance","points":3}],"dureeMin":18,"corrige":"1. A : stockage **chimique** (réaction d'oxydoréduction réversible). B : stockage **thermique** (chaleur sensible).\n2. Q = m × c × ΔT = 300 × 4 185 × (55 − 20) = 300 × 4 185 × 35 ≈ **43 900 000 J** (43,9 MJ). En kWh : 43 942 500 / 3 600 000 ≈ **12,2 kWh**.\n3. Lithium-ion : 5 000 / 200 = **25 kg**. Plomb : 5 000 / 35 ≈ **143 kg**.\n4. Le ballon stocke plus (12,2 kWh contre 5 kWh), pour un appareil déjà présent : il suffit de piloter son chauffage aux heures solaires. Mais il ne restitue que de la **chaleur** (eau chaude sanitaire), alors que la batterie restitue de l'**électricité** utilisable par tous les appareils, le soir. Conseil attendu : commencer par piloter le ballon (peu coûteux, grande quantité), puis envisager la batterie si le surplus reste important. Toute conclusion argumentée par les chiffres est acceptée.\n5. Le **BMS** (battery management system) surveille la tension, le courant et la température de chaque cellule, équilibre leurs charges et coupe en cas de danger. C'est la chaîne d'information au service de la chaîne de puissance.\n6. La batterie stocke beaucoup d'**énergie** mais fournit une puissance limitée ; le supercondensateur stocke peu d'énergie (5 à 10 Wh/kg) mais a une **puissance massique très élevée** : il fournit le pic de puissance du démarrage, la batterie assure la durée. On associe ainsi énergie et puissance."}$exo$::jsonb),
  ('fd328438-8bb9-54d5-95ca-16027500a4eb'::uuid, 1, 'application', $exo${"titre":"Vitesses d'une petite transmission","consigne":"Pour chaque calcul, écris la formule, l'application numérique avec les unités, puis le résultat.","enonce":"**Situation.** Inès étudie la transmission d'un robot éducatif.\n\n1. Le moteur tourne à **3 000 tr/min**. Convertis cette vitesse en rad/s.\n2. Le moteur entraîne un engrenage : un pignon de **15 dents** mène une roue de **45 dents**. Calcule le rapport de transmission k, puis la vitesse angulaire de la roue en rad/s. S'agit-il d'un réducteur ? Justifie.\n3. Une roue du robot, de rayon **0,25 m**, tourne à **20 rad/s**. Calcule la vitesse d'avance du robot.","bareme":[{"critere":"Conversion juste : ω = 2π × 3 000 / 60 ≈ 314 rad/s","points":6},{"critere":"Rapport k = 15/45 = 1/3, vitesse de sortie d'environ 105 rad/s, réducteur justifié par k < 1","points":7},{"critere":"Vitesse d'avance juste : v = R × ω = 0,25 × 20 = 5 m/s","points":7}],"dureeMin":8,"corrige":"1. ω = 2π × N / 60 = 2π × 3 000 / 60 ≈ **314 rad/s**.\n2. k = Z entrée / Z sortie = 15 / 45 = **1/3** (≈ 0,33). ω sortie = k × ω entrée = 314 / 3 ≈ **105 rad/s**. Comme k < 1, c'est un **réducteur** : il réduit la vitesse (et augmente le couple).\n3. v = R × ω = 0,25 × 20 = **5 m/s**."}$exo$::jsonb),
  ('fd328438-8bb9-54d5-95ca-16027500a4eb'::uuid, 2, 'application', $exo${"titre":"Le convoyeur de colis","consigne":"Pose chaque étape : formule, application numérique avec unités, résultat arrondi raisonnablement.","enonce":"**Situation.** Un convoyeur de colis est entraîné par un moteur de **0,75 kW** tournant à **1 450 tr/min**. La transmission comporte deux étages :\n\n- une transmission poulies-courroie : poulie motrice de **80 mm** de diamètre, poulie réceptrice de **240 mm** ;\n- un engrenage : pignon de **20 dents**, roue de **60 dents**.\n\nLe tambour qui entraîne la bande a un rayon de **0,1 m**. Le rendement global de la transmission est de **0,85**. On suppose que le moteur fonctionne à sa puissance nominale.\n\n1. Calcule la vitesse angulaire du moteur en rad/s.\n2. Calcule le rapport de transmission de chaque étage, puis le rapport global.\n3. Calcule la vitesse angulaire du tambour et la vitesse de la bande.\n4. Calcule la puissance disponible au tambour et le couple sur le tambour.\n5. Déduis-en l'effort que la bande peut exercer pour tirer les colis.","bareme":[{"critere":"Vitesse du moteur juste : environ 151,8 rad/s","points":4},{"critere":"Rapports justes : 1/3 pour chaque étage, 1/9 au total","points":4},{"critere":"Vitesse du tambour (≈ 16,9 rad/s) et de la bande (≈ 1,69 m/s) justes","points":4},{"critere":"Puissance de 637,5 W et couple d'environ 37,8 N·m justes","points":5},{"critere":"Effort de la bande juste : environ 378 N","points":3}],"dureeMin":12,"corrige":"1. ω moteur = 2π × 1 450 / 60 ≈ **151,8 rad/s**.\n2. Poulies-courroie : k1 = D entrée / D sortie = 80 / 240 = **1/3**. Engrenage : k2 = Z entrée / Z sortie = 20 / 60 = **1/3**. Rapport global : k = k1 × k2 = **1/9**.\n3. ω tambour = 151,8 / 9 ≈ **16,9 rad/s**. Vitesse de la bande : v = R × ω = 0,1 × 16,9 ≈ **1,69 m/s**.\n4. P tambour = η × P moteur = 0,85 × 750 = **637,5 W**. C = P / ω = 637,5 / 16,87 ≈ **37,8 N·m**.\n5. F = C / R = 37,8 / 0,1 ≈ **378 N**."}$exo$::jsonb),
  ('fd328438-8bb9-54d5-95ca-16027500a4eb'::uuid, 3, 'application', $exo${"titre":"Le moteur du portail coulissant convient-il ?","consigne":"Pose chaque calcul avec formule, application numérique et unités, puis compare les résultats aux critères du cahier des charges.","enonce":"**Situation.** Un portail coulissant de **300 kg** est entraîné par un système pignon-crémaillère.\n\n**Chaîne de transmission.** Moteur : **1 400 tr/min**, couple disponible **0,5 N·m** → réducteur de rapport **k = 1/25**, rendement **0,7** → pignon de rayon **0,03 m** → crémaillère fixée au portail.\n\n**Cahier des charges.** Vitesse d'ouverture d'au moins **0,15 m/s** ; le portail doit atteindre sa vitesse en **0,5 s**. La résistance au roulement du portail vaut **150 N**.\n\n1. Calcule la vitesse de translation du portail en régime établi. L'exigence de vitesse est-elle respectée ?\n2. Calcule l'accélération au démarrage, la force d'accélération, puis l'effort total que la crémaillère doit transmettre au démarrage.\n3. Calcule le couple nécessaire sur le pignon au démarrage.\n4. Calcule le couple que doit fournir le moteur au démarrage (utilise C sortie = η × C entrée / k). Le moteur convient-il ?\n5. Pourquoi est-ce le démarrage, et non le régime établi, qui dimensionne le moteur ? Appuie-toi sur tes résultats.","bareme":[{"critere":"Vitesse du portail juste (≈ 0,176 m/s) comparée à 0,15 m/s","points":5},{"critere":"Accélération (≈ 0,35 m/s²), force d'accélération (≈ 106 N) et effort au démarrage (≈ 256 N) justes","points":5},{"critere":"Couple sur le pignon juste : environ 7,7 N·m","points":3},{"critere":"Couple moteur d'environ 0,44 N·m calculé et comparé aux 0,5 N·m disponibles","points":4},{"critere":"Rôle du démarrage expliqué en comparant effort au démarrage et en régime établi","points":3}],"dureeMin":20,"corrige":"1. ω moteur = 2π × 1 400 / 60 ≈ 146,6 rad/s. ω pignon = k × ω moteur = 146,6 / 25 ≈ 5,86 rad/s. v = R × ω = 0,03 × 5,86 ≈ **0,176 m/s**. 0,176 m/s > 0,15 m/s : exigence de vitesse **respectée**.\n2. a = Δv / Δt = 0,176 / 0,5 ≈ **0,35 m/s²**. Force d'accélération : F = m × a = 300 × 0,352 ≈ **106 N**. Effort total au démarrage : 150 + 106 ≈ **256 N**.\n3. C pignon = F × R = 256 × 0,03 ≈ **7,7 N·m**.\n4. C entrée = C sortie × k / η = 7,7 × (1/25) / 0,7 = 7,7 / 17,5 ≈ **0,44 N·m**. 0,44 N·m < 0,5 N·m : le moteur **convient**, avec une marge d'environ 12 %.\n5. En régime établi, il suffit de vaincre les 150 N de résistance : C pignon = 150 × 0,03 = 4,5 N·m, soit un couple moteur de 4,5 / 17,5 ≈ 0,26 N·m. Au démarrage, il faut en plus fournir l'effort d'accélération : 256 N contre 150 N, et 0,44 N·m contre 0,26 N·m. C'est donc le démarrage qui impose le couple le plus élevé et qui dimensionne le moteur."}$exo$::jsonb),
  ('29435005-8b98-5af4-a25a-226f6b969d8b'::uuid, 1, 'application', $exo${"titre":"Le hauban d'un auvent","consigne":"Écris chaque formule, l'application numérique avec les unités, puis le résultat.","enonce":"**Situation.** Un auvent est retenu par un hauban (tirant) en acier de **1 500 mm** de long et de section **50 mm²**, qui supporte un effort de traction de **8 kN**. Module d'Young de l'acier : E = 210 000 MPa.\n\n1. Calcule la contrainte normale dans le hauban.\n2. Calcule la déformation, puis l'allongement du hauban.\n3. Associe chaque pièce à sa sollicitation principale (traction, compression, flexion, torsion, cisaillement) : l'étagère chargée de livres ; l'axe d'une chape qui relie deux pièces ; l'arbre de transmission d'une voiture ; le poteau d'un préau.","bareme":[{"critere":"Contrainte juste : σ = 8 000 / 50 = 160 MPa","points":5},{"critere":"Déformation (≈ 7,6 × 10⁻⁴) et allongement (≈ 1,1 mm) justes","points":7},{"critere":"Quatre pièces associées à la bonne sollicitation","points":8}],"dureeMin":8,"corrige":"1. σ = N / S = 8 000 / 50 = **160 MPa**.\n2. ε = σ / E = 160 / 210 000 ≈ **7,6 × 10⁻⁴**. ΔL = ε × L0 = 7,6 × 10⁻⁴ × 1 500 ≈ **1,1 mm**.\n3. Associations :\n- étagère chargée → **flexion** ;\n- axe de chape → **cisaillement** ;\n- arbre de transmission → **torsion** ;\n- poteau de préau → **compression**."}$exo$::jsonb),
  ('29435005-8b98-5af4-a25a-226f6b969d8b'::uuid, 2, 'application', $exo${"titre":"Choisir le diamètre d'une suspente","consigne":"Pose chaque calcul et justifie ton choix en comparant au critère du cahier des charges.","enonce":"**Situation.** Une passerelle est suspendue par des suspentes en acier S235 (Re = 235 MPa, E = 210 000 MPa), de section circulaire pleine et de longueur **3 m**. Chaque suspente supporte **24 kN**. Le cahier des charges impose un coefficient de sécurité **s ≥ 2**.\n\nDiamètres disponibles : 12, 14, 16, 18 et 20 mm. Aire d'un disque de diamètre d : S = π × d² / 4.\n\n1. Calcule la contrainte maximale admissible dans une suspente.\n2. Calcule la section minimale nécessaire.\n3. Choisis le plus petit diamètre disponible qui convient. Justifie.\n4. Calcule la contrainte réelle et le coefficient de sécurité obtenu avec ce diamètre.\n5. Calcule l'allongement de la suspente.","bareme":[{"critere":"Contrainte admissible juste : 235 / 2 = 117,5 MPa","points":4},{"critere":"Section minimale juste : environ 204 mm²","points":5},{"critere":"Diamètre de 18 mm choisi, en montrant que 16 mm (≈ 201 mm²) ne suffit pas","points":5},{"critere":"Contrainte réelle (≈ 94 MPa) et coefficient de sécurité (≈ 2,5) justes","points":3},{"critere":"Allongement juste : environ 1,35 mm","points":3}],"dureeMin":12,"corrige":"1. σ adm = Re / s = 235 / 2 = **117,5 MPa**.\n2. S ≥ N / σ adm = 24 000 / 117,5 ≈ **204 mm²**.\n3. d = 16 mm : S = π × 16² / 4 ≈ 201 mm² < 204 mm² → **insuffisant**. d = 18 mm : S = π × 18² / 4 ≈ **254,5 mm²** ≥ 204 mm² → on choisit **18 mm**.\n4. σ = 24 000 / 254,5 ≈ **94 MPa**. s = Re / σ = 235 / 94,3 ≈ **2,5** ≥ 2 : exigence respectée.\n5. ε = σ / E = 94,3 / 210 000 ≈ 4,5 × 10⁻⁴. ΔL = ε × L0 = 4,5 × 10⁻⁴ × 3 000 ≈ **1,35 mm**."}$exo$::jsonb),
  ('29435005-8b98-5af4-a25a-226f6b969d8b'::uuid, 3, 'application', $exo${"titre":"Simulation d'une poutre de rayonnage","consigne":"Interprète les résultats de simulation, pose chaque calcul et justifie chaque conclusion par une comparaison chiffrée au cahier des charges.","enonce":"**Situation.** Une poutre de rayonnage en acier S235 (Re = 235 MPa, E = 210 000 MPa) repose sur deux appuis distants de **1,2 m** et porte des cartons. Le cahier des charges impose un coefficient de sécurité **s ≥ 2** et une flèche inférieure à **portée / 300**.\n\n**Résultats de simulation par éléments finis**\n\n| Version | Détail de forme | Contrainte de Von Mises maximale | Flèche maximale |\n| V1 | Angle vif au raccord avec le support | 180 MPa (dans l'angle vif) | 3,2 mm |\n| V2 | Congé de raccordement à la place de l'angle vif | 110 MPa | 3,2 mm |\n\n1. Avant de lancer le calcul, quelles données a-t-il fallu fournir au logiciel en plus du maillage ?\n2. Calcule le coefficient de sécurité de chaque version et conclus. Explique pourquoi la contrainte est plus forte en V1.\n3. Vérifie l'exigence de flèche.\n4. Un collègue propose de refaire la poutre V2 en aluminium (E = 70 000 MPa), même forme, mêmes charges. En t'appuyant sur la loi de Hooke, estime la nouvelle flèche et conclus.\n5. Dans cette poutre chargée, quelle fibre est comprimée, laquelle est tendue ? Propose une forme de section qui la rendrait plus rigide à quantité de matière égale, et explique pourquoi.","bareme":[{"critere":"Matériau, liaisons et chargements cités","points":2},{"critere":"Coefficients justes (≈ 1,3 pour V1, ≈ 2,1 pour V2), conclusion et rôle de la concentration de contraintes","points":6},{"critere":"Flèche limite de 4 mm calculée et comparée à 3,2 mm","points":4},{"critere":"Flèche en aluminium estimée à environ 9,6 mm et jugée non conforme, raisonnement par E trois fois plus faible","points":4},{"critere":"Fibre supérieure comprimée, inférieure tendue ; section en I ou tube justifiée par la matière loin de la fibre neutre","points":4}],"dureeMin":20,"corrige":"1. En plus du maillage, il faut définir le **matériau** (acier S235 : E, Re), les **liaisons** (les deux appuis) et les **chargements** (poids des cartons).\n2. V1 : s = 235 / 180 ≈ **1,3** < 2 → **non conforme**. V2 : s = 235 / 110 ≈ **2,1** ≥ 2 → **conforme**. En V1, l'angle vif crée une **concentration de contraintes** : la contrainte y est bien plus forte qu'ailleurs. Le congé de raccordement la réduit fortement.\n3. Flèche limite : 1 200 / 300 = **4 mm**. 3,2 mm < 4 mm : exigence **respectée**.\n4. Avec la même forme et les mêmes charges, les contraintes sont les mêmes. D'après σ = E × ε, la déformation est inversement proportionnelle à E : l'aluminium (70 000 MPa) se déforme 210 000 / 70 000 = **3 fois plus**. Flèche estimée : 3 × 3,2 ≈ **9,6 mm** > 4 mm → **non conforme**, la rigidité est insuffisante.\n5. Poutre sur deux appuis chargée : la fibre **supérieure est comprimée**, la fibre **inférieure est tendue**, la fibre neutre ne change pas de longueur. Une section **en I** (ou un tube) place la matière **loin de la fibre neutre**, là où les contraintes sont les plus fortes : à quantité de matière égale, elle résiste et se déforme bien mieux en flexion qu'une section pleine et plate."}$exo$::jsonb),
  ('5f404260-52cc-59e5-9e87-b461a7634711'::uuid, 1, 'application', $exo${"titre":"Le rendement de la pompe d'arrosage","consigne":"Écris chaque formule, l'application numérique avec les unités, puis le résultat.","enonce":"**Situation.** Une pompe d'arrosage est alimentée par la chaîne suivante : variateur (rendement **0,97**) → moteur (rendement **0,9**) → pompe (rendement **0,7**). L'ensemble absorbe **2 kW** au réseau.\n\n1. Calcule le rendement global de la chaîne.\n2. Calcule la puissance utile fournie à l'eau, puis les pertes totales.\n3. La pompe fonctionne **3 h** par jour. Calcule l'énergie absorbée au réseau chaque jour, en kWh.","bareme":[{"critere":"Rendement global juste : 0,97 × 0,9 × 0,7 ≈ 0,61","points":7},{"critere":"Puissance utile (≈ 1,22 kW) et pertes (≈ 0,78 kW) justes","points":7},{"critere":"Énergie journalière juste : 2 × 3 = 6 kWh","points":6}],"dureeMin":7,"corrige":"1. η global = η1 × η2 × η3 = 0,97 × 0,9 × 0,7 ≈ **0,61**.\n2. P utile = η global × P absorbée = 0,611 × 2 ≈ **1,22 kW**. Pertes = P absorbée − P utile = 2 − 1,22 ≈ **0,78 kW**.\n3. E = P × t = 2 kW × 3 h = **6 kWh** par jour."}$exo$::jsonb),
  ('5f404260-52cc-59e5-9e87-b461a7634711'::uuid, 2, 'application', $exo${"titre":"Le monte-charge de la boulangerie","consigne":"Suis l'énergie de la source à l'effecteur : pose chaque calcul avec les unités, puis identifie l'étage à améliorer en chiffrant le gain.","enonce":"**Situation.** Le monte-charge d'une boulangerie hisse une charge de **300 kg** (sans contrepoids) sur **6 m** en **12 s**, à vitesse constante. On prend g = 9,81 N/kg.\n\n**Chaîne de puissance.** Variateur (**0,95**) → moteur (**0,85**) → réducteur à roue et vis sans fin (**0,65**) → tambour (**0,95**).\n\n1. Calcule l'énergie utile pour une montée, puis la puissance utile.\n2. Calcule le rendement global de la chaîne.\n3. Calcule la puissance absorbée au réseau et les pertes totales.\n4. Quel étage faut-il améliorer en priorité ? Calcule la nouvelle puissance absorbée si on le remplace par un réducteur à engrenages hélicoïdaux de rendement **0,95**.","bareme":[{"critere":"Énergie utile (≈ 17,7 kJ) et puissance utile (≈ 1,47 kW) justes","points":5},{"critere":"Rendement global juste : environ 0,50","points":4},{"critere":"Puissance absorbée (≈ 2,95 kW) et pertes (≈ 1,48 kW) justes","points":5},{"critere":"Réducteur désigné comme étage prioritaire et nouvelle puissance absorbée d'environ 2,02 kW","points":6}],"dureeMin":12,"corrige":"1. E = m × g × h = 300 × 9,81 × 6 ≈ **17 660 J** (17,7 kJ). P utile = E / t = 17 658 / 12 ≈ **1 470 W** (1,47 kW).\n2. η global = 0,95 × 0,85 × 0,65 × 0,95 ≈ **0,50**.\n3. P absorbée = P utile / η = 1 471,5 / 0,4986 ≈ **2 950 W** (2,95 kW). Pertes = 2 950 − 1 470 ≈ **1 480 W**, soit la moitié de la puissance absorbée.\n4. L'étage de plus faible rendement est le **réducteur à roue et vis sans fin** (0,65) : à lui seul, il perd environ 830 W. Avec un réducteur hélicoïdal : η global = 0,95 × 0,85 × 0,95 × 0,95 ≈ **0,73**. P absorbée = 1 471,5 / 0,729 ≈ **2 020 W**, soit environ 930 W de moins (−32 %)."}$exo$::jsonb),
  ('5f404260-52cc-59e5-9e87-b461a7634711'::uuid, 3, 'application', $exo${"titre":"Le cycle d'une presse d'atelier","consigne":"Analyse la courbe et les mesures, pose chaque calcul, puis interprète les écarts et propose des pistes d'optimisation.","enonce":"**Situation.** Un moteur entraîne une presse d'atelier. Un wattmètre relève la puissance électrique absorbée pendant un cycle :\n\n| Phase | Durée | Puissance absorbée |\n| Démarrage | 5 s | monte linéairement de 0 à 3 kW |\n| Travail | 40 s | constante, 3 kW |\n| Arrêt | 5 s | descend linéairement de 3 kW à 0 |\n\nLa presse réalise **200 cycles par jour**. Pendant la phase de travail, un couplemètre et un tachymètre mesurent en sortie du moteur **25 N·m** à **1 000 tr/min**. Le constructeur annonce un rendement du moteur de **0,92**.\n\n1. Classe chaque phase en régime transitoire ou établi.\n2. Calcule l'énergie absorbée pendant un cycle (aire sous la courbe P(t)), en joules puis en Wh.\n3. Calcule l'énergie absorbée par jour, en kWh.\n4. Calcule la puissance mécanique mesurée en sortie du moteur pendant le travail, puis le rendement mesuré. Compare-le au rendement annoncé et propose une interprétation de l'écart.\n5. Propose deux pistes pour réduire la consommation de cette presse, en précisant le levier (réduire les pertes, récupérer, piloter, stocker).","bareme":[{"critere":"Démarrage et arrêt classés en transitoire, travail en régime établi","points":3},{"critere":"Énergie par cycle juste : 7,5 kJ + 120 kJ + 7,5 kJ = 135 kJ, soit 37,5 Wh","points":5},{"critere":"Énergie journalière juste : 7,5 kWh","points":3},{"critere":"Puissance mécanique (≈ 2,62 kW) et rendement mesuré (≈ 0,87) justes, écart interprété","points":5},{"critere":"Deux pistes d'optimisation pertinentes rattachées à un levier","points":4}],"dureeMin":18,"corrige":"1. Démarrage et arrêt : **régime transitoire** (les grandeurs varient). Travail : **régime établi** (puissance stable).\n2. Aire sous la courbe :\n- démarrage : ½ × 3 000 × 5 = 7 500 J ;\n- travail : 3 000 × 40 = 120 000 J ;\n- arrêt : ½ × 3 000 × 5 = 7 500 J.\nTotal : **135 000 J**, soit 135 000 / 3 600 = **37,5 Wh**.\n3. 200 × 37,5 = 7 500 Wh = **7,5 kWh** par jour.\n4. ω = 2π × 1 000 / 60 ≈ 104,7 rad/s. P méca = C × ω = 25 × 104,7 ≈ **2 620 W**. η mesuré = 2 620 / 3 000 ≈ **0,87**, contre 0,92 annoncé. L'écart peut venir de l'**état du moteur** (usure, échauffement, mauvaise lubrification) ou d'un **point de fonctionnement** éloigné de celui du rendement maximal, ou encore de l'imprécision des mesures : il faut refaire la mesure et vérifier le moteur.\n5. Exemples : **réduire les pertes** (moteur à haut rendement, lubrification) ; **piloter** (couper le moteur entre deux cycles au lieu de le laisser tourner, faire travailler le moteur près de son rendement maximal) ; **récupérer** l'énergie de freinage à l'arrêt si le variateur est réversible."}$exo$::jsonb),
  ('fb970bea-7672-5c00-a72a-415c3426f942'::uuid, 1, 'application', $exo${"titre":"La chaîne d'acquisition d'une station météo","consigne":"Réponds à chaque question ; pour les calculs, écris la formule et l'application numérique.","enonce":"**Situation.** Une station météo mesure la température extérieure et l'affiche sur un écran.\n\n1. Remets dans l'ordre les étages de la chaîne d'acquisition et donne le rôle de chacun : CAN, traitement numérique, capteur, conditionnement.\n2. Le CAN de la station a une résolution de **10 bits** et une pleine échelle de **5 V**. Calcule son quantum.\n3. Le capteur conditionné délivre **2 V**. Quel nombre N le CAN transmet-il au programme ?","bareme":[{"critere":"Ordre capteur → conditionnement → CAN → traitement, avec le rôle de chaque étage","points":6},{"critere":"Quantum juste : q = 5 / 1 024 ≈ 4,88 mV","points":7},{"critere":"Nombre juste : N = partie entière de 2 / 0,004 88, soit 409","points":7}],"dureeMin":8,"corrige":"1. **Capteur** (traduit la température en signal électrique) → **conditionnement** (amplifie, filtre, décale pour utiliser toute la plage du CAN) → **CAN** (transforme la tension en nombre entier) → **traitement numérique** (convertit en °C, compare, décide, affiche).\n2. q = pleine échelle / 2ⁿ = 5 / 2¹⁰ = 5 / 1 024 ≈ **4,88 mV**.\n3. N = partie entière de (U / q) = partie entière de (2 / 0,004 883) = partie entière de 409,6 = **409**."}$exo$::jsonb),
  ('fb970bea-7672-5c00-a72a-415c3426f942'::uuid, 2, 'application', $exo${"titre":"Surveiller l'eau d'un chauffe-eau d'atelier","consigne":"Pose chaque calcul avec les unités et compare tes résultats à l'exigence.","enonce":"**Situation.** Pour surveiller l'eau d'un chauffe-eau d'atelier, on utilise un capteur de température à caractéristique linéaire : il délivre **0,4 V à 0 °C** et **2,4 V à 100 °C**. Il est relié à un CAN **12 bits** de pleine échelle **3,3 V**. Exigence : la résolution de la mesure doit être meilleure que **0,5 °C**.\n\n1. Calcule la sensibilité du capteur, en V/°C.\n2. Calcule le quantum du CAN, puis la résolution de la mesure en °C. L'exigence est-elle satisfaite ?\n3. Le programme lit **N = 1 500**. Calcule la tension correspondante, puis la température mesurée.\n4. Pour réduire le coût, on propose un CAN **8 bits** de même pleine échelle. Recalcule la résolution et conclus.","bareme":[{"critere":"Sensibilité juste : 2 V / 100 °C = 0,02 V/°C (20 mV/°C)","points":4},{"critere":"Quantum (≈ 0,81 mV) et résolution (≈ 0,04 °C) justes, comparaison à 0,5 °C","points":5},{"critere":"Conversion juste : U ≈ 1,21 V puis T ≈ 40 °C","points":6},{"critere":"Résolution en 8 bits (≈ 0,64 °C) jugée non conforme","points":5}],"dureeMin":12,"corrige":"1. Sensibilité = (2,4 − 0,4) / (100 − 0) = 2 / 100 = **0,02 V/°C** (20 mV/°C).\n2. q = 3,3 / 4 096 ≈ **0,81 mV**. Résolution en température : 0,81 mV ÷ 20 mV/°C ≈ **0,04 °C**. 0,04 °C < 0,5 °C : exigence **satisfaite**, largement.\n3. U ≈ N × q = 1 500 × 3,3 / 4 096 ≈ **1,21 V**. T = (1,21 − 0,4) / 0,02 ≈ **40 °C** (40,4 °C).\n4. En 8 bits : q = 3,3 / 256 ≈ 12,9 mV. Résolution : 12,9 / 20 ≈ **0,64 °C** > 0,5 °C : exigence **non satisfaite**. Le CAN 8 bits ne convient pas."}$exo$::jsonb),
  ('fb970bea-7672-5c00-a72a-415c3426f942'::uuid, 3, 'application', $exo${"titre":"Le pèse-personne connecté qui affiche n'importe quoi","consigne":"Analyse chaque étage de la chaîne d'acquisition, pose les calculs et justifie chaque proposition avec le cours.","enonce":"**Situation.** Un pèse-personne connecté mesure une force. Le signal utile varie lentement (fréquences inférieures à **2 Hz**), mais il est pollué par un bruit à **50 Hz** venant du secteur. Plusieurs utilisateurs signalent des défauts.\n\n1. On place un filtre passe-bas RC avec **R = 4,7 kΩ** et **C = 10 µF**. Calcule sa fréquence de coupure. Ce filtre convient-il ? Justifie.\n2. Quelle fréquence d'échantillonnage minimale faut-il choisir pour le signal utile ? Le programme échantillonne à 1 Hz : est-ce correct ?\n3. Le programme stocke la masse **en grammes** dans un entier **16 bits signé** (valeurs de −32 768 à 32 767). Que se passe-t-il quand un adulte de 80 kg monte sur la balance ? Propose une correction.\n4. Pour stabiliser l'affichage, le programme calcule la moyenne des quatre dernières mesures en kilogrammes, stockées en entiers : 80, 79, 80, 79. Il obtient 79 au lieu de 79,5. Explique l'erreur, et nomme ce type de filtrage.\n5. La balance affiche 1 kg de plus quand elle reste en plein soleil. Comment appelle-t-on la température dans ce cas ?","bareme":[{"critere":"Fréquence de coupure juste (≈ 3,4 Hz) et filtre jugé adapté : laisse passer 2 Hz, atténue 50 Hz","points":5},{"critere":"Shannon appliqué : au moins 4 Hz, échantillonnage à 1 Hz jugé trop lent","points":4},{"critere":"Débordement de l'entier identifié (80 000 > 32 767) et correction proposée","points":4},{"critere":"Division entière identifiée (318 / 4 = 79) et moyenne glissante nommée","points":4},{"critere":"Grandeur d'influence nommée","points":3}],"dureeMin":18,"corrige":"1. fc = 1 / (2π × R × C) = 1 / (2π × 4 700 × 0,000 01) ≈ 1 / 0,295 ≈ **3,4 Hz**. Le signal utile (< 2 Hz) passe, le bruit à 50 Hz, bien au-dessus de fc, est atténué : le filtre **convient**.\n2. D'après le théorème de Shannon, il faut échantillonner à au moins deux fois la plus haute fréquence utile : 2 × 2 = **4 Hz** au minimum. 1 Hz est **trop lent** : le signal reconstruit serait faux. On peut choisir par exemple 10 Hz.\n3. 80 kg = 80 000 g > 32 767 : l'entier **déborde** et la valeur stockée devient fausse. Corrections possibles : un entier plus grand (32 bits), un flottant, ou stocker la masse dans une unité plus grande (en hectogrammes : 800).\n4. Somme : 80 + 79 + 80 + 79 = 318. En **division entière**, 318 / 4 donne **79** : la partie décimale (0,5) est perdue. Il faut faire le calcul en flottant (ou en grammes). Ce calcul est un **filtrage numérique** par **moyenne glissante**.\n5. La température est ici une **grandeur d'influence** : elle perturbe la mesure du capteur de force (dérive)."}$exo$::jsonb),
  ('2b0aee15-572b-5419-a50f-08da8108987e'::uuid, 1, 'application', $exo${"titre":"Le réseau de la salle de technologie","consigne":"Réponds à chaque question en justifiant avec le cours.","enonce":"**Situation.** Dans la salle de technologie, un serveur a l'adresse **10.0.5.77** avec le masque **255.255.255.0** (/24).\n\n1. Donne l'adresse du réseau et l'adresse de diffusion. Combien de machines peut-on adresser dans ce réseau ?\n2. Deux équipements veulent dialoguer avec le serveur sans passer par un routeur : une imprimante en **10.0.5.200/24** et une caméra en **10.0.6.3/24**. Lesquels le peuvent ? Justifie.\n3. Sur la carte d'un robot, on veut relier trois capteurs à un microcontrôleur avec seulement deux fils de signal, chaque capteur ayant sa propre adresse. Quelle liaison choisir ? Comment s'appellent ses deux fils ?","bareme":[{"critere":"Adresse réseau 10.0.5.0, diffusion 10.0.5.255 et 254 machines","points":8},{"critere":"Imprimante dans le même réseau, caméra dans le réseau 10.0.6.0, passerelle nécessaire","points":7},{"critere":"Bus I2C choisi, fils SDA et SCL nommés","points":5}],"dureeMin":8,"corrige":"1. Adresse réseau = adresse IP ET masque : **10.0.5.0**. Adresse de diffusion : **10.0.5.255**. Machines de 10.0.5.1 à 10.0.5.254 : **254 adresses** utilisables.\n2. L'**imprimante** (10.0.5.200/24) a la même adresse réseau 10.0.5.0 : elle communique **directement** avec le serveur. La **caméra** (10.0.6.3/24) est dans le réseau **10.0.6.0**, différent : elle ne peut pas communiquer directement, il faut passer par une **passerelle** (routeur) ou changer son adresse en 10.0.5.x.\n3. Le bus **I2C** : deux fils, **SDA** (données) et **SCL** (horloge), plusieurs esclaves adressés sur le même bus."}$exo$::jsonb),
  ('2b0aee15-572b-5419-a50f-08da8108987e'::uuid, 2, 'application', $exo${"titre":"Connecter une exploitation agricole","consigne":"Justifie chaque choix par les critères du cours : portée, débit, consommation.","enonce":"**Situation.** Une agricultrice, Mme Duval, veut connecter trois équipements :\n\n- **A** : un capteur d'humidité du sol, alimenté par pile, au fond d'un champ situé à **3 km** de la ferme, qui envoie une mesure toutes les 30 minutes ;\n- **B** : une caméra de surveillance dans le hangar, qui transmet une vidéo en continu vers la box de la ferme, à 30 m ;\n- **C** : un bracelet porté par l'agricultrice, qui transmet son rythme de pas à son smartphone, dans sa poche.\n\n1. Choisis une technologie sans fil pour chaque équipement et justifie.\n2. Le capteur A publie ses mesures en **MQTT** sur le sujet « ferme/champ3/humidite ». Explique le fonctionnement de ce protocole : qui publie, par où passe le message, qui le reçoit ?\n3. Pour mettre à jour le logiciel de la caméra, faut-il utiliser TCP ou UDP ? Justifie.","bareme":[{"critere":"LoRa ou Sigfox pour A, Wi-Fi pour B, Bluetooth Low Energy pour C","points":4},{"critere":"Chaque choix justifié par la portée, le débit et la consommation","points":5},{"critere":"MQTT expliqué : publication sur un sujet, serveur broker, réception par les abonnés","points":6},{"critere":"TCP choisi et justifié par la garantie de réception (accusés de réception)","points":5}],"dureeMin":11,"corrige":"1. Choix attendus :\n- **A** : **LoRa ou Sigfox** (LPWAN) : portée de plusieurs km, très faible consommation (pile), le très faible débit suffit pour une mesure toutes les 30 min ;\n- **B** : **Wi-Fi** : débit élevé nécessaire pour la vidéo, portée d'environ 50 m suffisante ; la consommation élevée n'est pas gênante (caméra branchée sur le secteur) ;\n- **C** : **Bluetooth Low Energy** : portée d'environ 10 m suffisante (bracelet près du smartphone), très faible consommation pour une petite batterie.\n2. MQTT fonctionne par **publication / abonnement** : le capteur **publie** sa valeur (par exemple « ferme/champ3/humidite = 32 ») sur un serveur appelé **broker** ; toutes les applications **abonnées** à ce sujet (tableau de bord, smartphone) reçoivent la valeur. Le capteur n'a pas à connaître les destinataires.\n3. **TCP** : c'est un protocole **fiable**, avec accusés de réception ; une mise à jour logicielle ne doit perdre aucune donnée. UDP est rapide mais sans garantie."}$exo$::jsonb),
  ('2b0aee15-572b-5419-a50f-08da8108987e'::uuid, 3, 'application', $exo${"titre":"La supervision de l'atelier ne voit plus l'automate","consigne":"Analyse le dysfonctionnement, pose les calculs et justifie chaque proposition avec le cours.","enonce":"**Situation.** Dans un atelier, on installe une nouvelle supervision. Voici la configuration relevée :\n\n| Équipement | Adresse IP |\n| Automate de la ligne | 172.16.4.10/24 |\n| Poste de supervision | 172.16.5.20/24 |\n| Capteur connecté (Wi-Fi) | 172.16.4.35/24, mot de passe « admin », pages web en HTTP |\n\nIl n'y a pas de routeur entre les équipements. Le capteur est branché sur le même réseau que les ordinateurs du bureau.\n\n1. Calcule l'adresse réseau de chaque équipement. Explique pourquoi la supervision ne voit pas l'automate.\n2. Propose deux corrections possibles, dont une avec une adresse précise.\n3. L'automate dialogue aussi avec un module par une liaison série UART à **9 600 bit/s**. Chaque trame comporte 1 bit de start, 8 bits de données, 1 bit de parité et 1 bit de stop. Calcule la durée d'une trame et le nombre maximal d'octets de données transmis par seconde.\n4. Relève trois faiblesses de sécurité du capteur connecté et propose une mesure pour chacune.\n5. Quel protocole de transport faut-il pour les commandes envoyées à l'automate ? Justifie.","bareme":[{"critere":"Adresses réseau 172.16.4.0 et 172.16.5.0 calculées, réseaux différents sans routeur","points":5},{"critere":"Deux corrections : adresse 172.16.4.x libre (différente de 10 et 35) ou passerelle","points":3},{"critere":"Trame de 11 bits, durée d'environ 1,15 ms et environ 872 octets par seconde","points":5},{"critere":"Trois faiblesses de sécurité et une mesure pour chacune","points":4},{"critere":"TCP choisi et justifié","points":3}],"dureeMin":18,"corrige":"1. Adresse réseau = IP ET masque /24 : automate **172.16.4.0**, supervision **172.16.5.0**, capteur 172.16.4.0. L'automate et la supervision sont dans deux **réseaux différents** et aucun routeur ne les relie : ils ne peuvent pas communiquer directement.\n2. Corrections : donner à la supervision une adresse **172.16.4.x** libre, par exemple **172.16.4.50/24** (x différent de 10 et de 35) ; ou installer et configurer une **passerelle** (routeur) entre les deux réseaux.\n3. Trame : 1 + 8 + 1 + 1 = **11 bits**. Durée : 11 / 9 600 ≈ **1,15 ms**. Nombre de trames par seconde : 9 600 / 11 ≈ **872**, chacune portant un octet de données : environ **872 octets par seconde**.\n4. Faiblesses et mesures :\n- mot de passe par défaut « admin » → le remplacer par un **mot de passe robuste** ;\n- pages en HTTP, non chiffrées → passer en **HTTPS / TLS** (chiffrement) ;\n- capteur sur le réseau du bureau → **séparer** le réseau des objets du réseau principal.\nOn peut aussi citer les **mises à jour** du logiciel.\n5. **TCP** : il garantit la bonne réception des données grâce aux accusés de réception. Une commande perdue ou incomplète vers un automate pourrait provoquer un fonctionnement dangereux."}$exo$::jsonb),
  ('0ba3cb40-87a4-5764-8631-67cef5de82e4'::uuid, 1, 'application', $exo${"titre":"La régulation du four à pain","consigne":"Réponds à chaque question avec le vocabulaire de la boucle fermée.","enonce":"**Situation.** Un four de boulangerie doit rester à **180 °C** pendant la cuisson. Une sonde mesure la température, un programme calcule l'écart, et un contacteur alimente les résistances chauffantes. Quand le boulanger ouvre la porte, la température chute.\n\n1. Identifie dans ce four : la consigne, le capteur, le comparateur, le correcteur, l'actionneur, une perturbation.\n2. S'agit-il d'une régulation ou d'un asservissement ? Justifie.\n3. Le four fonctionne en tout ou rien avec une hystérésis de **± 5 °C**. À quelles températures les résistances s'allument-elles et s'éteignent-elles ? À quoi sert cette hystérésis ?","bareme":[{"critere":"Six éléments de la boucle correctement identifiés","points":8},{"critere":"Régulation justifiée par une consigne fixe et la lutte contre les perturbations","points":6},{"critere":"Seuils de 175 °C et 185 °C justes et rôle de l'hystérésis expliqué","points":6}],"dureeMin":8,"corrige":"1. Éléments :\n- **consigne** : 180 °C ;\n- **capteur** : la sonde de température ;\n- **comparateur** : la partie du programme qui calcule ε = consigne − mesure ;\n- **correcteur** : le programme qui élabore la commande à partir de l'écart ;\n- **actionneur** : les résistances chauffantes (commandées par le contacteur) ;\n- **perturbation** : l'ouverture de la porte.\n2. C'est une **régulation** : la consigne est **fixe** (180 °C) et le système lutte contre les perturbations. Un asservissement ferait suivre à la sortie une consigne qui change.\n3. Les résistances s'allument quand T < **175 °C** et s'éteignent quand T > **185 °C** ; la température oscille entre environ 175 et 185 °C. Sans hystérésis, le contacteur commuterait sans cesse autour de 180 °C et s'userait."}$exo$::jsonb),
  ('0ba3cb40-87a4-5764-8631-67cef5de82e4'::uuid, 2, 'application', $exo${"titre":"Le tapis roulant de la salle de sport","consigne":"Lis la réponse indicielle, calcule chaque critère de performance et compare-le au cahier des charges.","enonce":"**Situation.** La vitesse du tapis d'un tapis roulant est asservie. On applique un échelon de consigne de **0 à 2,0 m/s** et on relève la réponse :\n\n- la vitesse monte jusqu'à **2,25 m/s**, puis oscille et se stabilise à **1,9 m/s** ;\n- à partir de **t = 1,6 s**, la vitesse reste à ± 5 % de sa valeur finale.\n\n**Cahier des charges** : erreur statique ≤ **2 %** ; dépassement ≤ **15 %** ; temps de réponse à 5 % ≤ **2 s**.\n\nLe correcteur actuel est un correcteur proportionnel.\n\n1. Calcule le dépassement en %.\n2. Calcule l'erreur statique, en m/s et en %.\n3. Donne l'intervalle de ± 5 % autour de la valeur finale, puis le temps de réponse à 5 %.\n4. Pour chaque critère, dis si le cahier des charges est respecté.\n5. Quelle modification du correcteur proposes-tu pour corriger les défauts ? Explique l'effet attendu et le compromis à respecter.","bareme":[{"critere":"Dépassement juste : (2,25 − 1,9) / 1,9 ≈ 18 %","points":4},{"critere":"Erreur statique juste : 0,1 m/s, soit 5 %","points":4},{"critere":"Intervalle de 1,805 à 1,995 m/s et temps de réponse de 1,6 s","points":3},{"critere":"Conformité jugée pour les trois critères","points":4},{"critere":"Action intégrale proposée pour l'erreur statique et gain réduit ou action dérivée pour le dépassement, compromis expliqué","points":5}],"dureeMin":12,"corrige":"1. Dépassement = (2,25 − 1,9) / 1,9 ≈ **18 %**.\n2. Erreur statique = 2,0 − 1,9 = **0,1 m/s**, soit 0,1 / 2,0 = **5 %** de la consigne.\n3. ± 5 % de 1,9 m/s : de 1,9 × 0,95 = **1,805 m/s** à 1,9 × 1,05 = **1,995 m/s**. Temps de réponse à 5 % : **1,6 s**.\n4. Conformité :\n- erreur statique 5 % > 2 % → **non conforme** ;\n- dépassement 18 % > 15 % → **non conforme** ;\n- temps de réponse 1,6 s ≤ 2 s → **conforme**.\n5. Ajouter une **action intégrale** (correcteur PI ou PID) : elle ajoute la somme des écarts passés et **annule l'erreur statique**, mais elle ralentit. Pour réduire le dépassement, on peut **diminuer le gain Kp** ou ajouter une **action dérivée**, qui amortit. Il faut respecter le **compromis rapidité / stabilité** : en ralentissant le système, on doit garder un temps de réponse inférieur à 2 s. Le réglage se fait par simulation puis par essais."}$exo$::jsonb),
  ('0ba3cb40-87a4-5764-8631-67cef5de82e4'::uuid, 3, 'application', $exo${"titre":"Choisir le correcteur d'une couveuse","consigne":"Analyse les trois essais, calcule les critères de performance, puis choisis et justifie un correcteur en comparant chaque résultat au cahier des charges.","enonce":"**Situation.** Une couveuse d'œufs doit maintenir **37,5 °C**. Le correcteur est un programme dans un microcontrôleur qui commande une résistance chauffante. Quand on soulève le couvercle pour retourner les œufs, la température baisse.\n\n**Cahier des charges** : erreur statique ≤ **0,2 °C** ; la température ne doit **jamais dépasser 38,5 °C** ; temps de réponse à 5 % ≤ **20 min**.\n\n**Essais** (échelon de consigne jusqu'à 37,5 °C)\n\n| Essai | Correcteur | Température maximale | Valeur finale | Temps de réponse à 5 % |\n| A | P, gain faible | 36,9 °C (aucun dépassement) | 36,9 °C | 25 min |\n| B | P, gain fort | 39,0 °C | 37,2 °C | 12 min |\n| C | PI | 38,1 °C | 37,5 °C | 15 min |\n\n1. Ce système est-il une régulation ou un asservissement ? Nomme la perturbation principale.\n2. Pour chaque essai, calcule l'erreur statique et, s'il y en a un, le dépassement en %. Vérifie chaque critère du cahier des charges.\n3. Quel correcteur retiens-tu ? Justifie.\n4. Compare les essais A et B : que montrent-ils sur l'effet du gain proportionnel ?\n5. Décris ce que fait le programme du microcontrôleur à chaque période d'échantillonnage.","bareme":[{"critere":"Régulation identifiée et perturbation (couvercle soulevé) nommée","points":3},{"critere":"Erreurs statiques (0,6 ; 0,3 ; 0 °C) et dépassements (≈ 4,8 % ; 1,6 %) justes, chaque critère vérifié","points":7},{"critere":"Correcteur PI retenu et justifié par les trois critères","points":4},{"critere":"Compromis rapidité / stabilité expliqué à partir des essais A et B","points":3},{"critere":"Boucle du programme décrite : lecture du capteur, calcul de l'écart, calcul et envoi de la commande","points":3}],"dureeMin":20,"corrige":"1. C'est une **régulation** : la consigne est fixe (37,5 °C) et le système lutte contre les perturbations. Perturbation principale : l'**ouverture du couvercle**.\n2. Analyse :\n- **A** : erreur statique = 37,5 − 36,9 = **0,6 °C** > 0,2 → non conforme ; pas de dépassement, maximum 36,9 °C ≤ 38,5 → conforme ; 25 min > 20 min → non conforme.\n- **B** : erreur statique = 37,5 − 37,2 = **0,3 °C** > 0,2 → non conforme ; dépassement = (39,0 − 37,2) / 37,2 ≈ **4,8 %**, mais surtout 39,0 °C > 38,5 °C → **non conforme** (danger pour les œufs) ; 12 min ≤ 20 → conforme.\n- **C** : erreur statique **0 °C** → conforme ; dépassement = (38,1 − 37,5) / 37,5 ≈ **1,6 %**, maximum 38,1 °C ≤ 38,5 → conforme ; 15 min ≤ 20 → conforme.\n3. On retient le **correcteur PI (essai C)** : c'est le seul qui respecte les trois critères. L'action intégrale **annule l'erreur statique**.\n4. Augmenter le gain (A → B) rend la réponse **plus rapide** (25 → 12 min) et réduit l'erreur statique, mais la rend **plus oscillante** (dépassement jusqu'à 39 °C). C'est le **compromis rapidité / stabilité** ; un correcteur P seul laisse une erreur statique.\n5. À chaque période d'échantillonnage, le programme **lit le capteur** de température, **calcule l'écart** ε = consigne − mesure, **calcule la commande** (terme proportionnel + somme des écarts passés), puis l'envoie à la résistance (par exemple sous forme de rapport cyclique MLI)."}$exo$::jsonb),
  ('33441d30-66aa-5411-92fd-8ea37d0f66de'::uuid, 1, 'application', $exo${"titre":"Comment tient et isole une maison","consigne":"Réponds à chaque question ; pour le calcul, écris la formule, l'application numérique et l'unité.","enonce":"**Situation.** Nora suit la construction de la maison de ses parents.\n\n1. Remets dans l'ordre le chemin des charges, du haut vers le bas : fondation, poteau, sol, plancher, poutre. Dans quel cas utilise-t-on des fondations profondes ?\n2. Les combles sont isolés avec **12 cm** de laine de verre de conductivité **λ = 0,035 W/(m·K)**. Calcule la résistance thermique de cette couche.\n3. Cite trois principes de la conception bioclimatique que les architectes auraient pu appliquer à cette maison.","bareme":[{"critere":"Ordre plancher → poutre → poteau → fondation → sol et cas des fondations profondes","points":6},{"critere":"Résistance thermique juste : R = 0,12 / 0,035 ≈ 3,4 m²·K/W","points":7},{"critere":"Trois principes bioclimatiques corrects et expliqués","points":7}],"dureeMin":8,"corrige":"1. **Plancher → poutre → poteau → fondation → sol**. On utilise des **fondations profondes** (pieux, micropieux) quand le sol porteur est **profond** ; sinon, des fondations superficielles suffisent.\n2. R = e / λ = 0,12 / 0,035 ≈ **3,4 m²·K/W** (attention : e en mètres).\n3. Trois principes parmi :\n- **orienter** : grandes baies au sud, peu au nord ;\n- **capter** le soleil l'hiver et s'en **protéger** l'été (casquettes, brise-soleil, végétation caduque) ;\n- **stocker** la chaleur dans une masse (inertie thermique) ;\n- **ventiler** naturellement l'été ;\n- **isoler** et supprimer les ponts thermiques."}$exo$::jsonb),
  ('33441d30-66aa-5411-92fd-8ea37d0f66de'::uuid, 2, 'application', $exo${"titre":"La semelle et le mur de l'extension","consigne":"Pose chaque calcul (formule, application numérique, unité) et conclus.","enonce":"**Situation.** On construit l'extension d'une médiathèque.\n\n**Fondation.** Un poteau transmet **450 kN** au sol, qui admet une pression de **0,25 MPa**.\n\n**Mur.** Un mur de **25 m²** est composé de :\n\n| Couche | Épaisseur | λ en W/(m·K) |\n| Brique | 20 cm | 0,5 |\n| Isolant | 14 cm | 0,035 |\n\nTempérature intérieure : 20 °C ; température extérieure : 1 °C.\n\n1. Calcule la surface de semelle nécessaire, en m², puis le côté d'une semelle carrée.\n2. Calcule la résistance thermique de chaque couche, puis la résistance totale du mur.\n3. Calcule le flux de chaleur qui traverse le mur.\n4. Calcule ce flux sans l'isolant et commente.","bareme":[{"critere":"Surface de semelle (1,8 m²) et côté (≈ 1,35 m) justes","points":6},{"critere":"Résistances justes : 0,4 ; 4 ; total 4,4 m²·K/W","points":5},{"critere":"Flux juste : Φ = 25 × 19 / 4,4 ≈ 108 W","points":5},{"critere":"Flux sans isolant (≈ 1 190 W) et commentaire sur le rôle de l'isolant","points":4}],"dureeMin":12,"corrige":"1. S = N / p = 450 000 / 0,25 = 1 800 000 mm² = **1,8 m²**. Semelle carrée : côté = √1,8 ≈ **1,35 m**.\n2. Brique : R = 0,20 / 0,5 = **0,4 m²·K/W**. Isolant : R = 0,14 / 0,035 = **4 m²·K/W**. R total = 0,4 + 4 = **4,4 m²·K/W**.\n3. ΔT = 20 − 1 = 19 °C. Φ = S × ΔT / R total = 25 × 19 / 4,4 ≈ **108 W**.\n4. Sans isolant : Φ = 25 × 19 / 0,4 ≈ **1 190 W**, soit environ **11 fois plus**. Presque toute la résistance thermique du mur vient de l'isolant : la brique seule isole très mal."}$exo$::jsonb),
  ('33441d30-66aa-5411-92fd-8ea37d0f66de'::uuid, 3, 'application', $exo${"titre":"Béton ou bois pour les murs de l'école ?","consigne":"Compare les deux solutions par le calcul, analyse le plan, puis rédige une conclusion argumentée pour le maître d'ouvrage.","enonce":"**Situation.** Une commune fait construire une école. Deux solutions de mur extérieur sont étudiées pour une façade de **80 m²**, avec un écart de température intérieur-extérieur de **18 °C**.\n\n| | Solution A | Solution B |\n| Composition | Béton 18 cm (λ = 2) + polystyrène 12 cm (λ = 0,032) | Ossature bois : fibre de bois 20 cm (λ = 0,04) + panneau OSB 1,2 cm (λ = 0,13) |\n| Empreinte carbone du mur | 55 kg éq. CO2 par m² | 20 kg éq. CO2 par m² |\n\n**Extrait de l'esquisse.** Les salles de classe ont de grandes baies vitrées **au nord**, pour « une lumière douce » ; la façade sud est presque aveugle. Au droit de chaque plancher, le béton de la dalle traverse le mur jusqu'à la façade.\n\n1. Calcule la résistance thermique totale de chaque solution (λ en W/(m·K)).\n2. Calcule le flux de chaleur à travers la façade pour chaque solution.\n3. Calcule l'empreinte carbone de chaque façade. Pourquoi la solution B est-elle avantagée par la RE2020 ?\n4. Critique l'esquisse du point de vue bioclimatique et propose deux améliorations.\n5. Qu'est-ce qui se produit au droit des planchers ? Propose une solution.\n6. Rédige une conclusion de quelques lignes pour le maître d'ouvrage.","bareme":[{"critere":"Résistances justes : environ 3,84 m²·K/W pour A et 5,09 m²·K/W pour B","points":5},{"critere":"Flux justes : environ 375 W pour A et 283 W pour B","points":4},{"critere":"Empreintes de 4 400 kg et 1 600 kg, avantage biosourcé et stockage du carbone expliqués","points":4},{"critere":"Critique bioclimatique (baies au nord) et pont thermique identifiés, solutions proposées","points":4},{"critere":"Conclusion argumentée reprenant les résultats chiffrés","points":3}],"dureeMin":20,"corrige":"1. A : R = 0,18 / 2 + 0,12 / 0,032 = 0,09 + 3,75 = **3,84 m²·K/W**. B : R = 0,20 / 0,04 + 0,012 / 0,13 = 5 + 0,09 ≈ **5,09 m²·K/W**.\n2. Φ = S × ΔT / R. A : 80 × 18 / 3,84 = 1 440 / 3,84 = **375 W**. B : 1 440 / 5,09 ≈ **283 W** (environ 25 % de moins).\n3. A : 80 × 55 = **4 400 kg éq. CO2**. B : 80 × 20 = **1 600 kg éq. CO2**, près de trois fois moins. La RE2020 fixe des seuils d'empreinte carbone sur le cycle de vie : le bois est un matériau **biosourcé** qui **stocke du carbone**, alors que le ciment du béton a une forte empreinte.\n4. Les grandes baies au **nord** ne captent pas le soleil l'hiver et font perdre de la chaleur ; la façade sud aveugle se prive des apports solaires. Améliorations : placer les **grandes baies au sud**, avec des **casquettes ou brise-soleil** pour se protéger l'été ; réduire les ouvertures au nord ; prévoir une ventilation traversante nocturne l'été.\n5. La dalle qui traverse le mur interrompt l'isolation : c'est un **pont thermique**, par lequel la chaleur fuit. Il faut assurer la **continuité de l'isolant** autour du plancher, sans interruption.\n6. Conclusion attendue : la solution **B** isole mieux (283 W contre 375 W) et divise presque par trois l'empreinte carbone (1 600 kg contre 4 400 kg) : elle est préférable pour la RE2020, à condition de protéger le bois de l'humidité et du feu. L'orientation des baies doit être revue et les ponts thermiques traités."}$exo$::jsonb),
  ('2774fa37-70aa-5c10-a20f-72e35dc083a9'::uuid, 1, 'application', $exo${"titre":"Panneaux et pompe à chaleur","consigne":"Réponds à chaque question ; pour les calculs, écris la formule et l'application numérique.","enonce":"**Situation.** La famille de Hugo équipe sa maison.\n\n1. Elle installe **12 panneaux de 375 Wc** dans une région où l'on produit **1 100 kWh par kWc et par an**. Calcule la puissance crête installée, puis la production annuelle.\n2. Elle installe aussi une pompe à chaleur de COP **3**. Pour **1 kWh** électrique consommé, combien de kWh de chaleur sont fournis au logement, et combien sont pris à l'environnement ?\n3. L'électricité des centrales arrive par des lignes à **400 kV**. Explique pourquoi on transporte l'électricité en très haute tension.","bareme":[{"critere":"Puissance crête (4,5 kWc) et production annuelle (4 950 kWh) justes","points":7},{"critere":"3 kWh de chaleur fournis, dont 2 kWh pris à l'environnement","points":6},{"critere":"Haute tension expliquée : courant plus faible à puissance égale, pertes par effet Joule réduites","points":7}],"dureeMin":8,"corrige":"1. Puissance crête : 12 × 375 = 4 500 Wc = **4,5 kWc**. Production : 4,5 × 1 100 = **4 950 kWh/an**.\n2. COP = chaleur fournie / énergie électrique consommée, donc chaleur fournie = 3 × 1 = **3 kWh**, dont 3 − 1 = **2 kWh** prélevés gratuitement à l'environnement (air, sol ou eau).\n3. À puissance égale, plus la tension est élevée, plus le **courant est faible**. Or les pertes par **effet Joule** valent R × I² : elles chutent fortement quand le courant diminue. Les transformateurs permettent de changer de niveau de tension."}$exo$::jsonb),
  ('2774fa37-70aa-5c10-a20f-72e35dc083a9'::uuid, 2, 'application', $exo${"titre":"Autoconsommer le soleil de la ferme","consigne":"Pose chaque calcul avec les unités, puis conclus.","enonce":"**Situation.** Une ferme installe **20 panneaux de 400 Wc** dans une région à **1 300 kWh/kWc/an**. Elle consomme **7 000 kWh/an**, dont **35 %** pendant les heures de production solaire.\n\n1. Calcule la puissance crête installée et la production annuelle.\n2. Calcule l'énergie autoconsommée et l'énergie injectée sur le réseau.\n3. En pilotant le ballon d'eau chaude et le lave-linge aux heures solaires, la ferme déplace **1 000 kWh** de consommation par an vers ces heures. Calcule la nouvelle autoconsommation et la part de la production consommée sur place avant et après.\n4. La ferme veut aussi chauffer son logement, qui a besoin de **9 000 kWh** de chaleur par an, avec une pompe à chaleur de COP **3,2**. Calcule l'électricité consommée par la pompe à chaleur. Pourquoi le COP sera-t-il plus faible en plein hiver ?","bareme":[{"critere":"Puissance crête (8 kWc) et production (10 400 kWh/an) justes","points":4},{"critere":"Autoconsommation de 2 450 kWh et injection de 7 950 kWh justes","points":5},{"critere":"Nouvelle autoconsommation de 3 450 kWh et parts d'environ 24 % puis 33 %","points":5},{"critere":"Électricité de la pompe à chaleur (≈ 2 810 kWh) et baisse du COP par grand froid expliquée","points":6}],"dureeMin":12,"corrige":"1. Puissance crête : 20 × 400 = 8 000 Wc = **8 kWc**. Production : 8 × 1 300 = **10 400 kWh/an**.\n2. Autoconsommation : 0,35 × 7 000 = **2 450 kWh**. Injection : 10 400 − 2 450 = **7 950 kWh**.\n3. Nouvelle autoconsommation : 2 450 + 1 000 = **3 450 kWh** (injection : 6 950 kWh). Part de la production consommée sur place : avant 2 450 / 10 400 ≈ **24 %**, après 3 450 / 10 400 ≈ **33 %**.\n4. Électricité = chaleur / COP = 9 000 / 3,2 ≈ **2 810 kWh**. Le COP baisse quand l'écart de température entre la source (l'air extérieur) et le logement augmente : par grand froid, la pompe consomme plus d'électricité pour la même chaleur."}$exo$::jsonb),
  ('2774fa37-70aa-5c10-a20f-72e35dc083a9'::uuid, 3, 'application', $exo${"titre":"Le mix d'un territoire de montagne","consigne":"Pose chaque calcul, puis analyse le rôle du réseau et de l'information dans la gestion de l'énergie du territoire.","enonce":"**Situation.** Une vallée de montagne veut produire une partie de son électricité.\n\n**Données**\n- Une éolienne fournit **2 MW** avec un vent de **12 m/s** (en dessous de sa puissance maximale, sa puissance est proportionnelle au cube de la vitesse du vent).\n- Une microcentrale sur le torrent : débit **Qv = 2 m³/s**, hauteur de chute **h = 15 m**, rendement **η = 0,85**, ρ = 1 000 kg/m³, g = 9,81 N/kg.\n- L'électricité produite est élevée de **20 kV à 400 kV** pour rejoindre le réseau de transport.\n\n1. Calcule la puissance de l'éolienne quand le vent tombe à **6 m/s**. Commente.\n2. Calcule la puissance de la microcentrale (P = ρ × g × Qv × h × η).\n3. À puissance transportée égale, par combien le courant est-il divisé en passant de 20 kV à 400 kV ? Et les pertes par effet Joule (R × I²), à résistance de ligne égale ?\n4. Un soir sans vent, la consommation de la vallée dépasse la production disponible. Que risque-t-il de se passer sur le réseau si rien n'est fait ?\n5. Explique comment un réseau intelligent (smart grid) peut aider la vallée : donne deux actions concrètes.","bareme":[{"critere":"Puissance à 6 m/s juste : 2 MW / 8 = 250 kW, forte sensibilité au vent commentée","points":5},{"critere":"Puissance de la microcentrale juste : environ 250 kW","points":4},{"critere":"Courant divisé par 20 et pertes divisées par 400, raisonnement justifié","points":4},{"critere":"Équilibre production-consommation et dérive de la fréquence de 50 Hz expliqués","points":3},{"critere":"Deux actions de réseau intelligent pertinentes","points":4}],"dureeMin":18,"corrige":"1. La vitesse est divisée par 2 : la puissance est divisée par 2³ = **8**. P = 2 000 / 8 = **250 kW**. Un vent deux fois plus faible fait perdre 87,5 % de la puissance : l'éolien est très sensible au vent, donc **intermittent**.\n2. P = 1 000 × 9,81 × 2 × 15 × 0,85 ≈ **250 000 W**, soit environ **250 kW**, de façon plus régulière que l'éolien.\n3. À puissance égale, le courant est inversement proportionnel à la tension : 400 / 20 = 20, le courant est **divisé par 20**. Les pertes R × I² sont divisées par 20² = **400**.\n4. Le réseau doit à chaque instant **équilibrer production et consommation**. Sinon, la **fréquence** (50 Hz) dérive, ce qui peut entraîner des coupures. Il faut importer de l'électricité par le réseau de transport, produire davantage ou réduire la consommation.\n5. Exemples : **piloter les usages** (recharger les véhicules électriques et chauffer les ballons aux heures de production, effacer certaines consommations aux heures de pointe) ; **prévoir** la production éolienne et hydraulique ; **compteurs communicants** pour connaître la consommation en temps réel ; **stocker** (ballons pilotés, batteries) ; autoconsommation collective. L'information s'ajoute à l'énergie : elle évite de gaspiller."}$exo$::jsonb),
  ('51252a34-afd8-53d2-9c80-a37caf268eb9'::uuid, 1, 'application', $exo${"titre":"Quel procédé pour quelle pièce ?","consigne":"Réponds à chaque question en justifiant avec le cours.","enonce":"**Situation.** Un bureau d'études doit fabriquer plusieurs pièces.\n\n1. Associe à chaque pièce la famille de procédés la plus adaptée (moulage par injection, usinage, déformation, fabrication additive, découpe) et justifie en une phrase :\n   a. une coque de télécommande en plastique, 200 000 exemplaires ;\n   b. un prototype unique de support à la forme très complexe ;\n   c. une platine plane en tôle d'acier, avec un contour découpé ;\n   d. une pièce en aluminium à 20 exemplaires, avec des alésages précis.\n2. Pour la coque injectée, cite quatre règles de forme à respecter et explique l'utilité de deux d'entre elles.\n3. Pourquoi dit-on que forme, matériau et procédé sont des choix interdépendants ? Donne un exemple.","bareme":[{"critere":"Quatre procédés adaptés et justifiés : injection, fabrication additive, découpe, usinage","points":7},{"critere":"Quatre règles de forme citées (épaisseur constante, dépouilles, congés, nervures) et deux expliquées","points":7},{"critere":"Interdépendance expliquée avec un exemple","points":6}],"dureeMin":7,"corrige":"1. Associations :\n- a. **moulage par injection** : grande série, le coût du moule est amorti ;\n- b. **fabrication additive** : unité et forme complexe, aucun outillage ;\n- c. **découpe** (laser, jet d'eau, poinçonnage) : pièce plane dans une tôle ;\n- d. **usinage** (tournage, fraisage) : unité à moyenne série, bonne précision.\n2. Règles : **épaisseur constante** (sinon retassures), **dépouilles** de 1 à 2° (pour démouler la pièce), **congés** partout, **nervures** (pour rigidifier sans épaissir).\n3. Le matériau conditionne les procédés possibles ; le procédé conditionne les formes réalisables et le coût selon la quantité ; la forme conditionne la résistance et la fonction. Exemple : une pièce injectée en plastique n'a pas la même forme qu'une pièce usinée en aluminium qui remplit la même fonction (épaisseurs constantes, nervures, dépouilles d'un côté ; formes accessibles à l'outil de l'autre)."}$exo$::jsonb),
  ('51252a34-afd8-53d2-9c80-a37caf268eb9'::uuid, 2, 'application', $exo${"titre":"Le boîtier du capteur de parking","consigne":"Pose chaque calcul avec les unités, puis conclus sur le choix du procédé selon la quantité.","enonce":"**Situation.** Une start-up conçoit le boîtier d'un capteur de place de parking. Trois procédés sont possibles :\n\n| Procédé | Coût fixe | Coût par pièce |\n| Impression 3D | 0 € | 4,50 € |\n| Usinage | 1 500 € | 7 € |\n| Injection plastique | 18 000 € (moule) | 0,60 € |\n\n1. Calcule le coût total de chaque procédé pour une première série de **2 000 boîtiers**. Lequel choisir ?\n2. Calcule le coût total de chaque procédé pour **20 000 boîtiers**. Lequel choisir ?\n3. Calcule le seuil de rentabilité entre l'impression 3D et l'injection.\n4. La start-up prévoit 2 000 boîtiers la première année, puis 20 000 par an. Quelle stratégie lui conseilles-tu ?","bareme":[{"critere":"Coûts pour 2 000 pièces justes (9 000 € ; 15 500 € ; 19 200 €) et impression 3D choisie","points":6},{"critere":"Coûts pour 20 000 pièces justes (90 000 € ; 141 500 € ; 30 000 €) et injection choisie","points":5},{"critere":"Seuil de rentabilité juste : environ 4 616 pièces","points":5},{"critere":"Stratégie argumentée par les résultats","points":4}],"dureeMin":12,"corrige":"1. Pour 2 000 pièces :\n- impression 3D : 4,50 × 2 000 = **9 000 €** ;\n- usinage : 1 500 + 7 × 2 000 = **15 500 €** ;\n- injection : 18 000 + 0,60 × 2 000 = **19 200 €**.\nL'**impression 3D** est la moins chère.\n2. Pour 20 000 pièces :\n- impression 3D : 4,50 × 20 000 = **90 000 €** ;\n- usinage : 1 500 + 7 × 20 000 = **141 500 €** ;\n- injection : 18 000 + 0,60 × 20 000 = **30 000 €**.\nL'**injection** s'impose.\n3. 18 000 + 0,6 × n = 4,5 × n → 3,9 × n = 18 000 → n ≈ 4 615,4, soit **4 616 pièces** environ. Au-delà, l'injection est moins chère.\n4. Stratégie : imprimer en 3D la première série (2 000 < 4 616), ce qui permet aussi de corriger la conception sans avoir payé de moule ; puis investir dans le moule d'injection pour les séries de 20 000, une fois la forme stabilisée (en respectant les règles de l'injection : épaisseur constante, dépouilles, congés)."}$exo$::jsonb),
  ('51252a34-afd8-53d2-9c80-a37caf268eb9'::uuid, 3, 'application', $exo${"titre":"Reconcevoir une lampe torche","consigne":"Analyse la solution actuelle, propose une reconception et justifie chaque choix par un gain chiffré ou une règle du cours.","enonce":"**Situation.** Une lampe torche est aujourd'hui fabriquée ainsi : corps en aluminium **usiné**, **7 pièces** au total, dont 2 collées entre elles, masse **180 g**. Une molette permet de régler la luminosité ; elle tourne lentement, quelques fois par jour, et supporte un effort très faible. L'entreprise veut produire **100 000 lampes par an**.\n\n**Données de coût**\n\n| Procédé | Coût fixe | Coût par corps |\n| Usinage de l'aluminium | 0 € | 12 € |\n| Injection d'un plastique recyclé | 40 000 € (moule) | 1,20 € |\n\n**Proposition de reconception** : corps injecté en plastique recyclé, avec **charnière et clips intégrés** ; **3 pièces** au total, toutes du même plastique ; masse **95 g**.\n\n1. Calcule le coût annuel des corps pour chaque procédé et conclus.\n2. Quelles règles de forme faudra-t-il respecter pour le nouveau corps injecté ? Cite-en trois.\n3. En quoi la reconception améliore-t-elle la fin de vie et la réparation ? Critique l'assemblage collé actuel.\n4. Pour guider la molette en rotation, faut-il un coussinet ou un roulement à billes ? Justifie.\n5. Chiffre les gains de la reconception (nombre de pièces, masse en %). Nomme la démarche d'innovation utilisée.","bareme":[{"critere":"Coûts annuels justes (1 200 000 € contre 160 000 €) et injection retenue","points":5},{"critere":"Trois règles de forme de l'injection citées","points":4},{"critere":"Monomatériau et assemblage démontable reliés à la fin de vie ; collage critiqué","points":4},{"critere":"Coussinet choisi et justifié par la faible vitesse et le faible effort","points":3},{"critere":"Gains chiffrés (4 pièces de moins, ≈ 47 % de masse) et intégration de fonctions nommée","points":4}],"dureeMin":20,"corrige":"1. Usinage : 12 × 100 000 = **1 200 000 €**. Injection : 40 000 + 1,20 × 100 000 = **160 000 €**. À 100 000 pièces par an, l'**injection** est de loin la moins chère : le moule est amorti par la grande série.\n2. **Épaisseur constante** (sinon retassures), **dépouilles** de 1 à 2° pour démouler, **congés** partout, **nervures** pour rigidifier sans épaissir.\n3. Toutes les pièces sont du **même plastique** (monomatériau) : la lampe se recycle sans tri. Les **clips** forment un assemblage **démontable** : on peut ouvrir la lampe pour la réparer. Le collage actuel est un assemblage **permanent** : il empêche le démontage et, s'il unit des matériaux différents, gêne le recyclage.\n4. Un **coussinet** (bague de frottement) suffit : la molette tourne lentement, rarement, sous un effort très faible ; il est plus simple et moins cher. Le roulement à billes, qui réduit le frottement, se justifie pour des vitesses ou des charges plus élevées.\n5. Pièces : 7 → 3, soit **4 pièces de moins**. Masse : (180 − 95) / 180 ≈ **47 %** de moins. La démarche est l'**intégration de fonctions** (charnière et clips dans la même pièce plastique), avec un matériau **recyclé**."}$exo$::jsonb),
  ('7cb44eba-8094-52a0-80ca-2c337dfe27f0'::uuid, 1, 'application', $exo${"titre":"Quelle carte, quelles entrées-sorties ?","consigne":"Réponds à chaque question en justifiant avec le cours.","enonce":"**Situation.** Le club de robotique du lycée prépare deux projets.\n\n1. Choisis entre un **microcontrôleur** et un **nano-ordinateur** pour chaque projet, et justifie :\n   a. un détecteur d'ouverture de porte sur pile, qui allume une LED et envoie une alerte ;\n   b. une borne qui héberge un site web local et analyse les images d'une caméra.\n2. Pour chaque composant, indique le type d'entrée ou de sortie utilisé : un bouton-poussoir ; un capteur de luminosité qui délivre une tension variable ; un moteur à courant continu dont on veut régler la vitesse ; un capteur de température relié par deux fils SDA et SCL.\n3. Décris la structure générale du programme principal d'une carte programmable.","bareme":[{"critere":"Microcontrôleur pour a et nano-ordinateur pour b, justifiés","points":6},{"critere":"Types justes : TOR, analogique (CAN), MLI, bus I2C","points":8},{"critere":"Structure décrite : initialisation puis boucle infinie","points":6}],"dureeMin":7,"corrige":"1. a. **Microcontrôleur** : il pilote des entrées-sorties en temps réel avec une **faible consommation**, idéal sur pile. b. **Nano-ordinateur** : il dispose d'un système d'exploitation, peut héberger un **serveur web**, gérer une **caméra** et faire des calculs lourds.\n2. Types :\n- bouton-poussoir → entrée **numérique TOR** ;\n- capteur de luminosité → entrée **analogique** (CAN) ;\n- moteur à courant continu → sortie **MLI** ;\n- capteur sur SDA et SCL → **bus I2C**.\n3. Le programme principal commence par une **initialisation** (capteurs, sorties, communication), puis exécute une **boucle infinie** qui lit les entrées, traite et commande les sorties, en appelant des fonctions."}$exo$::jsonb),
  ('7cb44eba-8094-52a0-80ca-2c337dfe27f0'::uuid, 2, 'application', $exo${"titre":"La ventilation de la salle de classe","consigne":"Analyse le pseudo-code, repère le défaut et propose une version corrigée, puis prépare les tests.","enonce":"**Situation.** Un capteur de CO2 pilote le ventilateur d'une salle de classe. Cahier des charges : ventiler au-dessus de **1 000 ppm**, arrêter sous **800 ppm**, publier la mesure toutes les **5 minutes**.\n\n| Ligne | Pseudo-code |\n| 1 | initialiser capteur, ventilateur, wifi |\n| 2 | tant que vrai : |\n| 3 | co2 ← lire_co2() |\n| 4 | si co2 > 1000 alors ventilateur ← MARCHE |\n| 5 | si co2 < 800 alors ventilateur ← ARRET |\n| 6 | publier(\"salle12/co2\", co2) |\n| 7 | attendre 300 s |\n\n1. Que fait le programme pour une mesure de **900 ppm** ? Comment s'appelle ce type de régulation, et quel est son intérêt ?\n2. Quel est le défaut de la ligne 7 ? Décris ce qui peut se passer dans la salle.\n3. Réécris les lignes 6 et 7 (tu peux ajouter une variable initialisée avant la boucle) pour publier toutes les 5 minutes sans bloquer la régulation.\n4. Propose des valeurs de test pour vérifier les lignes 4 et 5, et justifie leur choix.","bareme":[{"critere":"900 ppm : l'état du ventilateur ne change pas ; tout ou rien avec hystérésis et intérêt expliqués","points":5},{"critere":"Défaut identifié : l'attente bloque la régulation pendant cinq minutes","points":5},{"critere":"Réécriture correcte avec une variable de dernier envoi et une comparaison de temps","points":5},{"critere":"Valeurs de test autour des deux seuils, justifiées","points":5}],"dureeMin":12,"corrige":"1. À 900 ppm, aucune des deux conditions n'est vraie : le ventilateur **garde son état** (marche s'il était en marche, arrêt sinon). C'est une régulation **tout ou rien avec hystérésis** : entre 800 et 1 000 ppm, on ne change rien, ce qui évite que le ventilateur démarre et s'arrête sans cesse.\n2. « attendre 300 s » **bloque** tout le programme pendant cinq minutes : le CO2 n'est pas relu, le ventilateur n'est ni démarré ni arrêté pendant ce temps. Le taux peut dépasser largement 1 000 ppm sans réaction.\n3. Version corrigée :\n- avant la boucle : dernier_envoi ← 0 ;\n- ligne 6 : si temps() − dernier_envoi ≥ 300 alors publier(\"salle12/co2\", co2) ; dernier_envoi ← temps() ;\n- ligne 7 supprimée.\nLa boucle tourne en permanence et ne publie que toutes les 5 minutes.\n4. Tests autour des seuils : **999, 1 000, 1 001** ppm pour la ligne 4 (le ventilateur ne démarre qu'à 1 001), **799, 800, 801** ppm pour la ligne 5 (il ne s'arrête qu'à 799). On teste les valeurs juste autour de chaque seuil, là où une erreur de signe (< au lieu de ≤) se voit."}$exo$::jsonb),
  ('7cb44eba-8094-52a0-80ca-2c337dfe27f0'::uuid, 3, 'application', $exo${"titre":"Le distributeur de croquettes connecté","consigne":"Analyse le comportement, l'architecture logicielle et la sécurité du produit ; justifie chaque proposition avec le cours.","enonce":"**Situation.** Un distributeur de croquettes connecté sert un chat trois fois par jour. Il fonctionne selon trois modes : **Auto** (distribution aux heures programmées), **Manuel** (distribution à la demande depuis l'application), **Défaut** (réservoir vide ou vis bloquée). Un bouton d'arrêt d'urgence doit couper le moteur de la vis en moins de **0,05 s**.\n\nLa boucle principale lit le capteur de poids du bol (0,3 s), puis envoie les données au serveur (0,1 s). Un compteur de distributions est stocké dans une variable entière non signée sur **8 bits** (valeurs de 0 à 255). L'application demande à l'inscription : nom, adresse postale, position GPS du téléphone en permanence, nom et poids du chat.\n\n1. Quel diagramme décrit ces trois modes ? Décris les transitions possibles entre les modes, avec une condition pour chacune.\n2. Si le bouton d'arrêt d'urgence est lu à chaque tour de boucle, l'exigence de 0,05 s est-elle respectée ? Que proposes-tu ?\n3. Au bout de combien de jours le compteur de distributions pose-t-il problème ? Comment s'appelle ce défaut et comment l'éviter ?\n4. L'objet est livré avec l'identifiant « admin » / « 0000 ». Propose trois mesures de sécurité.\n5. Quelles données demandées ne sont pas nécessaires au service ? Justifie avec le principe du RGPD.","bareme":[{"critere":"Diagramme d'états nommé et transitions Auto, Manuel, Défaut décrites avec leurs conditions","points":5},{"critere":"Temps de boucle de 0,4 s comparé à 0,05 s et interruption proposée","points":4},{"critere":"Débordement après 85 jours identifié et correction proposée","points":4},{"critere":"Trois mesures de sécurité pertinentes","points":4},{"critere":"Données non nécessaires identifiées et principe du RGPD cité","points":3}],"dureeMin":20,"corrige":"1. Un **diagramme d'états**. Transitions possibles :\n- Auto → Manuel : demande de distribution depuis l'application ; Manuel → Auto : distribution terminée ;\n- Auto ou Manuel → Défaut : réservoir détecté vide ou vis bloquée ;\n- Défaut → Auto : réservoir rempli et défaut acquitté par l'utilisateur.\nToute description cohérente, avec une condition par transition, est acceptée.\n2. Un tour de boucle dure 0,3 + 0,1 = **0,4 s** : l'appui peut attendre jusqu'à 0,4 s avant d'être lu, bien plus que 0,05 s → exigence **non respectée**. Il faut traiter le bouton par **interruption** : l'événement urgent est traité immédiatement, sans attendre la fin de la boucle.\n3. Trois distributions par jour : 255 / 3 = **85 jours**. Au-delà de 255, la variable **déborde** et le compteur devient faux : c'est un **effet de bord** (dépassement de capacité). Solution : une variable plus grande (16 ou 32 bits) ; on le repère par un test unitaire avec une valeur proche de 255.\n4. **Changer les identifiants par défaut** (mot de passe robuste imposé à l'installation), **chiffrer** les échanges (HTTPS, TLS), **mettre à jour** le logiciel de l'objet.\n5. L'**adresse postale** et surtout la **position GPS permanente** ne servent pas à nourrir un chat. Le RGPD impose de ne collecter que les **données nécessaires** au service : le nom (ou un pseudonyme) et les informations sur le chat suffisent."}$exo$::jsonb),
  ('82d9a027-dbaa-5e47-97a0-a779dce9af6a'::uuid, 1, 'application', $exo${"titre":"Rédiger une vérification qui rapporte tous les points","consigne":"Rédige ta réponse comme sur une copie : formule, application numérique, résultat avec unité, phrase de conclusion.","enonce":"**Situation.** Dans un sujet, on lit la question suivante :\n\n> « Vérifier que la batterie **36 V – 15 Ah** du fauteuil roulant permet **2 h** de fonctionnement pour une consommation moyenne de **240 W**. »\n\nOn rappelle : E = U × Q pour l'énergie stockée et E = P × t pour l'énergie consommée.\n\n1. Calcule l'énergie stockée dans la batterie en suivant les étapes d'un calcul bien rédigé.\n2. Calcule l'énergie nécessaire pour 2 h de fonctionnement.\n3. Rédige la phrase de conclusion, en comparant au critère et en donnant la marge.","bareme":[{"critere":"Énergie stockée rédigée en étapes : formule, application numérique, 540 Wh","points":8},{"critere":"Énergie nécessaire juste : 240 × 2 = 480 Wh","points":5},{"critere":"Conclusion comparant 540 Wh à 480 Wh, exigence satisfaite, marge d'environ 12,5 %","points":7}],"dureeMin":8,"corrige":"1. Formule : E = U × Q. Application numérique : E = 36 V × 15 Ah. Résultat : **E = 540 Wh**.\n2. Formule : E = P × t. Application numérique : E = 240 W × 2 h. Résultat : **E = 480 Wh**.\n3. Conclusion : « 540 Wh > 480 Wh : la batterie permet bien 2 h de fonctionnement, l'exigence est **satisfaite**, avec une marge de (540 − 480) / 480 = **12,5 %**, sous réserve de ne pas décharger complètement la batterie. » Un résultat seul rapporte peu : c'est la **comparaison au critère** et la conclusion qui rapportent tous les points."}$exo$::jsonb),
  ('82d9a027-dbaa-5e47-97a0-a779dce9af6a'::uuid, 2, 'application', $exo${"titre":"Corriger la copie de Théo","consigne":"Repère l'erreur dans chaque réponse, explique-la, puis rédige la réponse corrigée complète.","enonce":"**Situation.** Théo a rendu les trois réponses ci-dessous. Chacune contient une erreur classique.\n\n**Données utiles** : ω (rad/s) = 2π × N / 60 avec N en tr/min ; 1 Wh = 3 600 J ; η = P utile / P absorbée.\n\n> **Réponse A.** « Le moteur fournit un couple de 12 N·m à 1 500 tr/min. P = C × ω = 12 × 1 500 = 18 000 W. Le moteur de 2,2 kW ne convient pas. »\n>\n> **Réponse B.** « La batterie stocke 0,5 kWh, soit 500 J. »\n>\n> **Réponse C.** « P absorbée = 3 kW et P utile = 2 400 W, donc η = 2 400 / 3 = 800. »\n\n1. Pour la réponse A, explique l'erreur, refais le calcul et rédige la bonne conclusion.\n2. Pour la réponse B, explique l'erreur et donne l'énergie correcte en joules.\n3. Pour la réponse C, explique l'erreur et donne le bon rendement. Quel indice aurait dû alerter Théo ?\n4. Donne un conseil de méthode pour éviter ces trois erreurs.","bareme":[{"critere":"A : conversion oubliée, ω ≈ 157 rad/s, P ≈ 1,9 kW et conclusion corrigée","points":6},{"critere":"B : conversion kWh en J expliquée, 1 800 000 J","points":5},{"critere":"C : unités non homogènes, η = 0,8 et indice d'un rendement supérieur à 1","points":5},{"critere":"Conseil de méthode : poser les unités et convertir à chaque étape","points":4}],"dureeMin":12,"corrige":"1. Théo a utilisé la vitesse en **tr/min** au lieu de rad/s. ω = 2π × 1 500 / 60 ≈ **157 rad/s**. P = C × ω = 12 × 157 ≈ **1 885 W ≈ 1,9 kW**. Conclusion : « 1,9 kW < 2,2 kW : le moteur **convient**. » L'oubli de conversion inversait la conclusion.\n2. Il a confondu kWh et J. 0,5 kWh = 500 Wh = 500 × 3 600 = **1 800 000 J** (1,8 MJ).\n3. Il a divisé des watts par des kilowatts. 3 kW = 3 000 W, donc η = 2 400 / 3 000 = **0,8** (80 %). Indice : un rendement est toujours **inférieur à 1** ; 800 est impossible.\n4. Écrire les **unités à chaque étape** et **convertir** avant l'application numérique (tr/min en rad/s, kWh en J, kW en W) ; vérifier que le résultat est vraisemblable."}$exo$::jsonb),
  ('82d9a027-dbaa-5e47-97a0-a779dce9af6a'::uuid, 3, 'application', $exo${"titre":"Mini-sujet : le vélo cargo de livraison","consigne":"Traite ce mini-sujet comme une partie d'épreuve écrite : relève les données utiles, rédige chaque calcul complètement et conclus sur la problématique.","enonce":"**Mise en situation.** Une coopérative livre des colis en ville avec des vélos cargos à assistance électrique. **Problématique** : « La batterie actuelle permet-elle d'assurer une tournée complète ? »\n\n**Extrait du cahier des charges**\n\n| Id | Exigence | Critère |\n| 1.1 | Assister le livreur | Puissance d'assistance adaptée à la charge |\n| 1.3 | Assurer une tournée | 3 h d'assistance sans recharge |\n| 1.4 | Limiter la masse | Batterie de moins de 5 kg |\n\n**Dossier technique**\n- Batterie actuelle : **48 V – 14 Ah**.\n- Batterie proposée : **48 V – 17 Ah**.\n- Le fabricant garantit que **90 %** de l'énergie nominale est utilisable.\n- Consommation moyenne mesurée pendant une tournée : **220 W**.\n\n**Rappels** : E = U × Q ; E = P × t.\n\n1. Relève l'exigence liée à la problématique (identifiant et critère).\n2. Calcule l'énergie utilisable de la batterie actuelle.\n3. Calcule l'énergie nécessaire pour une tournée, puis conclus sur la batterie actuelle.\n4. Vérifie si la batterie proposée satisfait l'exigence ; donne la marge.\n5. Il te manque une donnée pour vérifier l'exigence 1.4 avec la batterie proposée : laquelle ? Que ferais-tu à l'examen face à une question bloquante ?\n6. Rédige la conclusion sur la problématique, en reprenant tes résultats.","bareme":[{"critere":"Exigence 1.3 relevée avec son critère de 3 h","points":3},{"critere":"Énergie utilisable actuelle juste : 672 Wh puis 604,8 Wh","points":4},{"critere":"Énergie nécessaire de 660 Wh et conclusion : batterie actuelle non conforme","points":5},{"critere":"Batterie proposée : 816 Wh puis 734,4 Wh utilisables, conforme avec une marge d'environ 11 %","points":5},{"critere":"Donnée manquante (masse) identifiée et conclusion rédigée sur la problématique","points":3}],"dureeMin":16,"corrige":"1. Exigence **1.3** « Assurer une tournée » — critère : **3 h d'assistance sans recharge**.\n2. E nominale = U × Q = 48 × 14 = **672 Wh**. E utilisable = 0,9 × 672 ≈ **605 Wh** (604,8 Wh).\n3. E nécessaire = P × t = 220 × 3 = **660 Wh**. 605 Wh < 660 Wh : la batterie actuelle **ne satisfait pas** l'exigence 1.3 (elle tient environ 605 / 220 ≈ 2,7 h).\n4. E nominale = 48 × 17 = **816 Wh** ; utilisable = 0,9 × 816 ≈ **734 Wh**. 734 Wh > 660 Wh : exigence 1.3 **satisfaite**, marge (734,4 − 660) / 660 ≈ **11 %**.\n5. Il manque la **masse** de la batterie proposée pour la comparer aux 5 kg de l'exigence 1.4. À l'examen, on signale la donnée manquante, on **passe à la question suivante** (les questions sont souvent indépendantes) et on y revient à la relecture.\n6. Conclusion : « Avec 605 Wh utilisables pour 660 Wh nécessaires, la batterie actuelle ne permet pas une tournée complète de 3 h. La batterie de 48 V – 17 Ah, avec 734 Wh utilisables, satisfait l'exigence 1.3 avec une marge d'environ 11 % ; il reste à vérifier sa masse (exigence 1.4) avant de la retenir. »"}$exo$::jsonb),
  ('32a3eb6f-ae4f-54c5-85c0-9590d2c4f453'::uuid, 1, 'application', $exo${"titre":"Concevoir, simuler ou expérimenter ?","consigne":"Réponds à chaque question en t'appuyant sur la démarche du cours.","enonce":"**Situation.** Au laboratoire, Yanis travaille sur un volet roulant motorisé.\n\n1. Classe chaque activité dans la bonne compétence (concevoir, simuler, expérimenter) :\n   a. il modifie le programme pour que le volet s'arrête dès qu'un obstacle est détecté ;\n   b. il mesure au chronomètre le temps de descente du volet ;\n   c. il lance un modèle numérique du moteur pour prévoir le courant de démarrage ;\n   d. il dessine en modeleur 3D une nouvelle pièce de fixation.\n2. Yanis doit câbler un capteur sur la carte de commande. Cite trois règles de sécurité à respecter avant et pendant la mise sous tension.\n3. Son temps de descente mesuré (22 s) ne correspond pas à celui prévu par la simulation (18 s). Yanis pense avoir échoué. Que lui conseilles-tu ?","bareme":[{"critere":"Quatre activités correctement classées (a et d concevoir, b expérimenter, c simuler)","points":8},{"critere":"Trois règles de sécurité citées","points":6},{"critere":"Écart présenté comme une occasion d'explication, avec une hypothèse","points":6}],"dureeMin":7,"corrige":"1. a. **Concevoir** (modifier un algorithme et un programme). b. **Expérimenter** (mettre en œuvre une mesure). c. **Simuler** (lancer une simulation pour prévoir une performance). d. **Concevoir** (définir une pièce en modeleur 3D).\n2. Règles : **câbler hors tension** ; **vérifier le câblage** avant la mise sous tension ; **repérer l'arrêt d'urgence** ; lire tout le sujet avant de toucher au matériel.\n3. Une mesure qui contredit la simulation n'est **pas un échec** : c'est l'occasion d'**expliquer l'écart**. Yanis doit le signaler, noter ses mesures avec leurs unités et proposer une **hypothèse** (frottements plus forts que dans le modèle, masse réelle du tablier différente, tension d'alimentation plus faible), puis la tester si possible."}$exo$::jsonb),
  ('32a3eb6f-ae4f-54c5-85c0-9590d2c4f453'::uuid, 2, 'application', $exo${"titre":"Le portail s'arrête-t-il assez vite ?","consigne":"Exploite le tableau de mesures, conclus sur la conformité et propose une modification argumentée.","enonce":"**Situation.** Problématique : « Le portail doit s'arrêter en **moins de 0,5 s** après la détection d'un obstacle. » Dans le programme actuel, la cellule de détection est lue à chaque tour de la boucle principale. La simulation prévoyait un temps d'arrêt de **0,30 s**. Au laboratoire, cinq essais donnent :\n\n| Essai | 1 | 2 | 3 | 4 | 5 |\n| Temps d'arrêt mesuré (s) | 0,42 | 0,38 | 0,55 | 0,40 | 0,45 |\n\n1. Calcule la moyenne des cinq mesures et relève la valeur maximale.\n2. Le portail est-il conforme à l'exigence ? Justifie : faut-il juger sur la moyenne ou sur le pire cas ?\n3. Propose deux hypothèses qui expliquent l'écart entre la simulation (0,30 s) et les mesures.\n4. Propose une modification de conception pour rendre le temps d'arrêt plus court et plus régulier, et décris comment tu vérifierais son effet.","bareme":[{"critere":"Moyenne juste (0,44 s) et maximum relevé (0,55 s)","points":5},{"critere":"Non-conformité justifiée par le pire cas de 0,55 s supérieur à 0,5 s","points":5},{"critere":"Deux hypothèses d'écart plausibles","points":5},{"critere":"Traitement de la cellule par interruption proposé et protocole de vérification décrit","points":5}],"dureeMin":12,"corrige":"1. Moyenne = (0,42 + 0,38 + 0,55 + 0,40 + 0,45) / 5 = 2,20 / 5 = **0,44 s**. Maximum : **0,55 s** (essai 3).\n2. La moyenne (0,44 s) respecte le critère, mais l'essai 3 (0,55 s > 0,5 s) ne le respecte pas. Pour une exigence de **sécurité**, il faut juger sur le **pire cas** : le portail n'est **pas conforme**.\n3. Hypothèses : la cellule n'est lue qu'une fois par tour de boucle, et la durée d'un tour **varie** selon les tâches exécutées (d'où la dispersion des mesures) ; l'**inertie** mécanique du portail (sa masse) ou les frottements ne sont pas modélisés fidèlement dans la simulation.\n4. Traiter la cellule par **interruption** au lieu de la lire à chaque tour de boucle : l'événement est traité immédiatement. Vérification : vérifier d'abord le comportement en simulation (diagramme d'états), puis refaire au moins cinq essais, mesurer le temps de réaction avec un **chronogramme**, noter les résultats dans un tableau et vérifier que **toutes** les mesures restent sous 0,5 s."}$exo$::jsonb),
  ('32a3eb6f-ae4f-54c5-85c0-9590d2c4f453'::uuid, 3, 'application', $exo${"titre":"Reconception d'un lampadaire : du protocole à la conclusion","consigne":"Construis la démarche complète de reconception : protocole de mesure, exploitation des résultats, analyse de l'écart et conclusion argumentée.","enonce":"**Situation.** Projet d'équipe : reconcevoir un lampadaire solaire pour **réduire sa consommation nocturne d'au moins 50 %**. L'équipe ajoute un détecteur de présence : la lampe reste à 20 % de sa puissance et passe à 100 % quand quelqu'un approche.\n\n**Matériel disponible** : maquette du lampadaire, wattmètre enregistreur, détecteur de présence, alimentation de laboratoire, ordinateur de simulation.\n\n**Résultats**\n\n| | Consommation sur une nuit |\n| Lampadaire d'origine (mesuré) | 480 Wh |\n| Lampadaire avec détecteur (simulé) | 190 Wh |\n| Lampadaire avec détecteur (mesuré) | 230 Wh |\n\n1. Rédige un protocole de mesure de la consommation nocturne (étapes, appareil, grandeur mesurée, conditions à garder identiques entre les deux essais).\n2. Calcule la réduction de consommation prévue par la simulation, puis la réduction mesurée, en %.\n3. Calcule l'écart entre mesure et simulation (en Wh et en % de la valeur simulée). Propose deux hypothèses pour l'expliquer.\n4. L'exigence du projet est-elle satisfaite ? Conclus.\n5. Montre que ce projet mobilise bien la matière, l'énergie et l'information.","bareme":[{"critere":"Protocole complet : étapes, wattmètre, grandeur mesurée, conditions identiques","points":5},{"critere":"Réductions justes : environ 60 % simulée et 52 % mesurée","points":5},{"critere":"Écart de 40 Wh (≈ 21 %) calculé et deux hypothèses plausibles","points":4},{"critere":"Conclusion sur l'exigence fondée sur la valeur mesurée","points":3},{"critere":"Matière, énergie et information identifiées dans le projet","points":3}],"dureeMin":20,"corrige":"1. Protocole attendu : **câbler hors tension** le wattmètre enregistreur entre l'alimentation et le lampadaire, vérifier, mettre sous tension ; enregistrer l'**énergie consommée (Wh)** sur une durée de nuit identique (par exemple 12 h) ; faire l'essai sans détecteur, puis avec détecteur, **dans les mêmes conditions** (même durée, même tension d'alimentation, même scénario de passages simulés) ; noter les résultats dans un tableau avec les unités.\n2. Simulation : (480 − 190) / 480 ≈ **60 %**. Mesure : (480 − 230) / 480 ≈ **52 %**.\n3. Écart : 230 − 190 = **40 Wh**, soit 40 / 190 ≈ **21 %** de la valeur simulée. Hypothèses : la **consommation propre du détecteur** (veille) n'a pas été modélisée ; les **passages** ont été plus nombreux ou plus longs pendant l'essai que dans le scénario simulé ; le temps de maintien à 100 % après détection est plus long que prévu. Un écart n'est pas un échec : il permet d'améliorer le modèle.\n4. On conclut sur la **mesure** : réduction de 52 % ≥ 50 % → l'exigence est **satisfaite**, mais avec une faible marge ; il faudrait confirmer sur plusieurs nuits.\n5. **Matière** : la maquette, le boîtier et la fixation du détecteur ; **énergie** : la consommation de la lampe et son stockage solaire ; **information** : le détecteur de présence et la commande qui règle la puissance de la lampe. Le projet est bien pluritechnologique."}$exo$::jsonb),
  ('52e7d094-4bba-545b-b866-603f9b785bc3'::uuid, 1, 'traduction', $exo${"titre":"Six cas, cinq déclinaisons","consigne":"Réponds à chaque question avec précision, en employant le vocabulaire du cours.","enonce":"1. Donne la fonction principale de chacun des **six cas** latins.\n2. À quelle déclinaison appartient chacun de ces noms ? Justifie par le nominatif et le génitif singulier : *rosa, rosae* ; *consul, consulis* ; *res, rei* ; *templum, templi* ; *manus, manus*.\n3. Énonce la **règle du neutre**. Pourquoi un mot terminé en **-a** peut-il poser problème ?","bareme":[{"critere":"Fonctions des six cas exactes (nominatif, vocatif, accusatif, génitif, datif, ablatif)","points":8},{"critere":"Cinq noms rangés dans la bonne déclinaison avec leur marque","points":7},{"critere":"Règle du neutre énoncée et ambiguïté du -a expliquée","points":5}],"dureeMin":8,"corrige":"1. **Nominatif** : sujet, attribut. **Vocatif** : interpellation. **Accusatif** : COD, but du mouvement. **Génitif** : complément du nom. **Datif** : COI, attribution. **Ablatif** : moyen, manière, lieu d'où l'on vient.\n2. *rosa, rosae* : **1re** déclinaison (-a, -ae). *consul, consulis* : **3e** (génitif en -is). *res, rei* : **5e** (-es, -ei). *templum, templi* : **2e**, neutre (-um, -i). *manus, manus* : **4e** (-us, -us).\n3. Au neutre, **le nominatif et l'accusatif sont toujours identiques**, et le **pluriel** se termine par **-a**. Un mot en -a peut donc être un **féminin singulier** (1re déclinaison, comme *rosa*) ou un **neutre pluriel** (comme *templa*) : c'est le **verbe** qui tranche."}$exo$::jsonb),
  ('52e7d094-4bba-545b-b866-603f9b785bc3'::uuid, 2, 'traduction', $exo${"titre":"Des roses pour le maître","consigne":"Applique la méthode de traduction du cours : analyse d'abord, traduis ensuite.","enonce":"**Phrase à traduire**\n\n> *Puellae rosas domino dant.*\n\n**Lexique et terminaisons utiles**\n- *puella, ae* (f.) : la jeune fille — 1re déclinaison : nominatif pluriel **-ae**, génitif et datif singulier **-ae**\n- *rosa, ae* (f.) : la rose — accusatif pluriel **-as**\n- *dominus, i* (m.) : le maître — datif singulier **-o**\n- *dant* : ils/elles donnent (3e personne du **pluriel**)\n\n1. Applique la méthode du cours étape par étape : repère le verbe, puis le nominatif, puis l'accusatif, puis les autres compléments.\n2. *Puellae* peut être un nominatif pluriel, un génitif singulier ou un datif singulier. Quel indice permet de trancher ?\n3. Donne ta traduction.","bareme":[{"critere":"Méthode suivie dans l'ordre : verbe, nominatif, accusatif, compléments","points":6},{"critere":"Puellae identifié comme nominatif pluriel grâce à l'accord avec dant","points":5},{"critere":"Rosas COD à l'accusatif et domino COI au datif identifiés","points":4},{"critere":"Traduction juste et correcte en français","points":5}],"dureeMin":10,"corrige":"1. **Verbe** : *dant*, 3e personne du pluriel (« ils/elles donnent »), en fin de proposition. **Nominatif** : le sujet doit être au pluriel pour s'accorder avec *dant* → *puellae* (nominatif pluriel). **Accusatif** : *rosas* (accusatif pluriel) → COD. **Autres compléments** : *domino*, datif singulier → COI, attribution (« au maître »).\n2. Le **verbe** tranche : *dant* est au pluriel, il lui faut un sujet au nominatif pluriel. Or aucun autre mot de la phrase ne peut l'être ; *puellae* est donc le **nominatif pluriel** (et non un génitif ou un datif singulier).\n3. **Traduction** : « Les jeunes filles donnent des roses au maître. » (« les roses » est accepté)."}$exo$::jsonb),
  ('52e7d094-4bba-545b-b866-603f9b785bc3'::uuid, 3, 'traduction', $exo${"titre":"Deux phrases, deux pièges en -a","consigne":"Analyse chaque mot (cas, nombre, fonction) avant de traduire, puis justifie tes choix.","enonce":"**Phrases à traduire**\n\n> 1. *Puella verba consulis audit.*\n> 2. *Domini templa rosis ornant.*\n\n**Lexique et terminaisons utiles**\n- *puella, ae* (f.) : la jeune fille (1re décl.) — *rosa, ae* (f.) : la rose ; ablatif pluriel **-is**\n- *verbum, i* (n.) : la parole — *templum, i* (n.) : le temple (2e décl., neutres) ; nominatif et accusatif pluriel **-a**\n- *dominus, i* (m.) : le maître (2e décl.) ; nominatif pluriel **-i**\n- *consul, consulis* (m.) : le consul (3e décl.)\n- *audit* : il/elle entend (singulier) — *ornant* : ils/elles ornent (pluriel)\n\n1. Dans la phrase 1, *puella* et *verba* se terminent tous deux par **-a**. Lequel est le sujet ? Justifie par la règle du neutre et par le verbe.\n2. Analyse *consulis* et donne sa fonction.\n3. Dans la phrase 2, analyse *domini*, *templa* et *rosis*.\n4. Traduis les deux phrases.\n5. En une ou deux phrases, explique pourquoi traduire dans l'ordre des mots aurait conduit à un contresens.","bareme":[{"critere":"Phrase 1 : puella sujet (féminin singulier, accord avec audit), verba neutre pluriel COD","points":5},{"critere":"Consulis génitif singulier, complément du nom de verba","points":3},{"critere":"Phrase 2 : domini nominatif pluriel, templa accusatif neutre pluriel, rosis ablatif de moyen","points":5},{"critere":"Deux traductions justes et en bon français","points":5},{"critere":"Explication : la terminaison, et non la place, donne la fonction","points":2}],"dureeMin":16,"corrige":"1. *verba* est un **neutre pluriel** (*verbum, i*, n.) : au neutre, nominatif et accusatif sont identiques et le pluriel est en -a. *puella* est un **féminin singulier** de la 1re déclinaison. Le **verbe** *audit* est au **singulier** : son sujet est donc *puella*. *verba*, pluriel, ne peut pas être sujet d'un verbe singulier : c'est l'**accusatif**, **COD**.\n2. *consulis* : **génitif singulier** de *consul* (3e déclinaison, génitif en -is) → **complément du nom** *verba* (« les paroles du consul »).\n3. *domini* : **nominatif pluriel** (2e décl.), sujet de *ornant* (pluriel). *templa* : neutre pluriel, nominatif ou accusatif ; le sujet étant déjà *domini*, c'est l'**accusatif**, **COD**. *rosis* : **ablatif pluriel** → complément de **moyen** (« avec des roses »).\n4. Phrase 1 : « **La jeune fille entend les paroles du consul.** » Phrase 2 : « **Les maîtres ornent les temples de roses** » (ou « avec des roses »).\n5. En latin, c'est la **terminaison** qui dit la fonction, pas la place du mot. Traduire dans l'ordre aurait pu faire de *verba* un sujet ou lire *templa* comme un féminin singulier : on aurait deviné au lieu d'analyser."}$exo$::jsonb),
  ('72027180-b57a-57c1-be3b-a044924efbe9'::uuid, 1, 'traduction', $exo${"titre":"Reconnaître les constructions","consigne":"Réponds à chaque question avec précision.","enonce":"1. Après quels types de verbes trouve-t-on une **proposition infinitive** ? À quels cas et mode sont son sujet et son verbe ? Traduis *Dico Marcum venire*.\n2. Qu'est-ce qu'un **ablatif absolu** ? Traduis *urbe capta* de façon correcte en français.\n3. Donne la forme et le sens de chacun des quatre participes du cours, avec l'exemple de *amare* (aimer).\n4. Que signifie *Carthago delenda est* ? Quelle forme verbale y est employée, et qu'exprime-t-elle ?","bareme":[{"critere":"Proposition infinitive : verbes de parole, pensée, perception ; sujet à l'accusatif, verbe à l'infinitif ; traduction juste","points":6},{"critere":"Ablatif absolu défini (nom + participe à l'ablatif, sans lien grammatical) et bien traduit","points":5},{"critere":"Quatre participes avec forme et sens exacts","points":5},{"critere":"Adjectif verbal en -ndus exprimant l'obligation, traduction juste","points":4}],"dureeMin":8,"corrige":"1. Après les verbes de **parole**, de **pensée** et de **perception**. Le sujet de la subordonnée est à l'**accusatif**, le verbe à l'**infinitif**. *Dico Marcum venire* : « **Je dis que Marcus vient.** »\n2. Un **nom et un participe à l'ablatif**, **sans lien grammatical** avec la principale. *Urbe capta* (« la ville ayant été prise ») se traduit par un complément circonstanciel : « **après la prise de la ville** », jamais mot à mot.\n3. **Présent actif** en -ns, -ntis : *amans*, « aimant ». **Parfait passif** en -tus, -a, -um : *amatus*, « ayant été aimé ». **Futur actif** en -turus : *amaturus*, « devant aimer ». **Adjectif verbal** en -ndus : *amandus*, « qui doit être aimé ».\n4. « **Carthage doit être détruite** » : c'est l'**adjectif verbal** (*delenda*), qui exprime l'**obligation**. C'est la formule de Caton, répétée à la fin de chacun de ses discours."}$exo$::jsonb),
  ('72027180-b57a-57c1-be3b-a044924efbe9'::uuid, 2, 'traduction', $exo${"titre":"Trois phrases, trois architectures","consigne":"Pour chaque phrase, nomme la construction, justifie ce qui permet de la reconnaître, puis traduis.","enonce":"**Phrases**\n\n> 1. *Puto consulem venire.*\n> 2. *Urbe capta, milites gaudent.*\n> 3. *Milites tam fortes sunt ut vincant.*\n\n**Lexique**\n- *puto* : je pense — *consul, consulis* (m.) : le consul ; *consulem* est l'accusatif — *venire* : venir (infinitif)\n- *urbs, urbis* (f.) : la ville ; *urbe* est l'ablatif — *capta* : participe parfait passif de *capere*, prendre\n- *miles, militis* (m.) : le soldat ; *milites* est le nominatif pluriel — *gaudent* : ils se réjouissent\n- *tam* : si, tellement — *fortes* : courageux — *sunt* : ils sont — *vincant* : subjonctif présent de *vincere*, vaincre (3e pers. du pluriel)\n\n1. Phrase 1 : quelle construction ? Justifie et traduis.\n2. Phrase 2 : nomme la construction de *urbe capta*, dis pourquoi il ne faut pas la traduire mot à mot, et traduis la phrase.\n3. Phrase 3 : *ut* + subjonctif exprime-t-il ici le **but** ou la **conséquence** ? Justifie et traduis.","bareme":[{"critere":"Phrase 1 : proposition infinitive reconnue (verbe de pensée, accusatif + infinitif) et bien traduite","points":6},{"critere":"Phrase 2 : ablatif absolu reconnu et rendu par un complément circonstanciel","points":6},{"critere":"Phrase 3 : conséquence justifiée par tam dans la principale, traduction « si… que »","points":6},{"critere":"Français correct dans les trois traductions","points":2}],"dureeMin":12,"corrige":"1. **Proposition infinitive** : *puto* est un verbe de **pensée** ; il est suivi d'un **accusatif** (*consulem*) et d'un **infinitif** (*venire*). Il ne faut pas chercher de COD mais une subordonnée. Traduction : « **Je pense que le consul vient.** »\n2. *Urbe capta* est un **ablatif absolu** : un nom (*urbe*) et un participe (*capta*) à l'ablatif, **sans lien grammatical** avec la principale (*milites gaudent*). Le mot à mot (« la ville ayant été prise ») sonne faux : le français le rend par un complément circonstanciel. Traduction : « **Après la prise de la ville, les soldats se réjouissent.** »\n3. **Conséquence** : l'adverbe *tam* (« si ») **annonce** la subordonnée dans la principale ; pour le but, rien ne l'annoncerait. Traduction : « **Les soldats sont si courageux qu'ils sont vainqueurs** » (ou « qu'ils vainquent »)."}$exo$::jsonb),
  ('72027180-b57a-57c1-be3b-a044924efbe9'::uuid, 3, 'traduction', $exo${"titre":"Le récit d'une victoire","consigne":"Analyse chaque construction, justifie ton identification, puis propose une traduction complète en bon français.","enonce":"**Texte**\n\n> *Hostibus victis, Caesar dicit Romam liberam esse. Milites tam fortes erant ut urbem caperent. Cum Marcus aeger esset, non venit.*\n\n**Lexique**\n- *hostis, hostis* (m.) : l'ennemi ; *hostibus* est l'ablatif pluriel — *victis* : participe parfait passif de *vincere*, vaincre (ablatif pluriel)\n- *dicit* : il dit — *Roma, ae* (f.) : Rome ; *Romam* est l'accusatif — *liberam* : libre (accusatif) — *esse* : être (infinitif)\n- *miles, militis* (m.) : le soldat — *tam* : si — *fortes* : courageux — *erant* : ils étaient\n- *urbem* : accusatif de *urbs*, la ville — *caperent* : subjonctif imparfait de *capere*, prendre (3e pers. du pluriel)\n- *cum* : conjonction — *aeger* : malade — *esset* : subjonctif imparfait de *esse* — *non venit* : il n'est pas venu\n\n1. Nomme et justifie la construction de *Hostibus victis*, puis celle de *Romam liberam esse*.\n2. Dans la deuxième phrase, *ut* + subjonctif exprime-t-il le but ou la conséquence ? Justifie.\n3. Dans la troisième phrase, que peut exprimer *cum* + subjonctif ? Quel sens retiens-tu ici, et pourquoi ?\n4. Traduis tout le texte.","bareme":[{"critere":"Hostibus victis : ablatif absolu justifié (nom + participe à l'ablatif, sans lien grammatical)","points":4},{"critere":"Romam liberam esse : proposition infinitive après verbe de parole, accusatif + infinitif","points":4},{"critere":"Ut de conséquence justifié par tam dans la principale","points":4},{"critere":"Cum + subjonctif : circonstance, cause ou opposition ; cause retenue et justifiée par le contexte","points":3},{"critere":"Traduction complète, juste, sans mot à mot pour l'ablatif absolu","points":5}],"dureeMin":18,"corrige":"1. *Hostibus victis* : **ablatif absolu**, un nom (*hostibus*) et un participe parfait passif (*victis*) à l'ablatif, **sans lien grammatical** avec la principale ; mot à mot « les ennemis ayant été vaincus », à rendre par un complément circonstanciel (« après la défaite des ennemis », « une fois les ennemis vaincus »). *Romam liberam esse* : **proposition infinitive** après *dicit*, verbe de **parole** : sujet à l'**accusatif** (*Romam*), verbe à l'**infinitif** (*esse*), attribut accordé (*liberam*). On ne cherche pas de COD mais une subordonnée : « que Rome est libre ».\n2. **Conséquence** : *tam* (« si ») dans la principale **annonce** la subordonnée. Pour un but, rien ne serait annoncé.\n3. *Cum* + subjonctif peut exprimer la **circonstance**, la **cause** ou l'**opposition** ; c'est le **contexte** qui tranche. Ici, la maladie de Marcus explique qu'il ne soit pas venu : sens de **cause** (« comme », « parce que »).\n4. **Traduction** : « **Après la défaite des ennemis, César dit que Rome est libre. Les soldats étaient si courageux qu'ils prirent la ville. Comme Marcus était malade, il n'est pas venu.** » (« une fois les ennemis vaincus » et « qu'ils s'emparèrent de la ville » sont acceptés)."}$exo$::jsonb),
  ('9f2f35db-9c91-50a8-87f1-60869cb7594e'::uuid, 1, 'traduction', $exo${"titre":"Les institutions de Rome","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Qu'est-ce que le *cursus honorum* ? Cite ses quatre étapes dans l'ordre.\n2. Pour le **Sénat**, les **comices** et les **tribuns de la plèbe**, dis qui y siège et quel est leur pouvoir.\n3. Que signifie **SPQR** et que dit cette formule ?\n4. Donne la date et l'événement : l'assassinat de César ; la fondation du principat.","bareme":[{"critere":"Cursus honorum défini, questure, édilité, préture, consulat dans l'ordre","points":5},{"critere":"Sénat, comices, tribuns : composition et pouvoir justes","points":7},{"critere":"SPQR développé et équilibre Sénat / peuple expliqué","points":4},{"critere":"15 mars 44 av. J.-C. et 27 av. J.-C. (Auguste)","points":4}],"dureeMin":7,"corrige":"1. Le *cursus honorum* est la **carrière des magistratures** romaines, parcourue dans un ordre fixe : **questure, édilité, préture, consulat**.\n2. **Sénat** : les anciens magistrats ; il donne l'orientation politique. **Comices** : le peuple assemblé ; ils votent les lois et élisent les magistrats. **Tribuns de la plèbe** : élus de la plèbe ; ils disposent du **droit de veto**.\n3. **SPQR** = *Senatus PopulusQue Romanus*, « le Sénat et le peuple romain » : la formule dit l'**équilibre revendiqué** entre le Sénat et le peuple.\n4. **15 mars 44 av. J.-C.** (les ides de mars) : César est assassiné. **27 av. J.-C.** : **Auguste** fonde le principat."}$exo$::jsonb),
  ('9f2f35db-9c91-50a8-87f1-60869cb7594e'::uuid, 2, 'traduction', $exo${"titre":"La République restaurée ?","consigne":"Lis le document, puis réponds aux questions en t'appuyant sur le cours.","enonce":"**Document – Auguste parle de lui-même** (*Res Gestae*, 34, traduction)\n\n> « Lors de mes sixième et septième consulats, après avoir éteint les guerres civiles, alors que j'étais maître de tout par le consentement universel, j'ai transféré la république de mon pouvoir à l'arbitrage du Sénat et du peuple romain. […] Depuis ce temps, j'ai surpassé tout le monde en autorité, mais je n'ai pas eu plus de pouvoir que ceux qui furent mes collègues dans chaque magistrature. »\n\n1. Replace ce texte dans la chronologie du cours : quelle crise précède, et quel régime Auguste fonde-t-il en 27 av. J.-C. ?\n2. Relève deux éléments du texte par lesquels Auguste affirme respecter les institutions républicaines.\n3. D'après le cours, que fait réellement l'Empire des formes républicaines ?\n4. Pourquoi le cours parle-t-il d'un « chef-d'œuvre de communication politique » à propos de la formule *Res publica restituta* ?","bareme":[{"critere":"Guerres civiles du Ier siècle av. J.-C. et principat fondé en 27 av. J.-C.","points":4},{"critere":"Deux éléments relevés (retour au Sénat et au peuple, magistratures, pas plus de pouvoir que ses collègues)","points":5},{"critere":"L'Empire garde les formes républicaines et en vide le contenu","points":5},{"critere":"Explication de la formule comme communication politique, texte lu avec recul critique","points":6}],"dureeMin":11,"corrige":"1. Au **Ier siècle av. J.-C.**, les **guerres civiles** minent la République ; César est assassiné le 15 mars 44 av. J.-C. En **27 av. J.-C.**, **Auguste** fonde le **principat**.\n2. Auguste dit avoir **transféré la république à l'arbitrage du Sénat et du peuple romain** (l'équilibre de *SPQR*) ; il se présente comme un **magistrat** parmi d'autres (consulats, collègues) et affirme **n'avoir pas eu plus de pouvoir** que ses collègues.\n3. L'Empire **garde les formes républicaines** (Sénat, magistratures, vocabulaire) **et en vide le contenu** : le pouvoir réel est concentré entre les mains d'Auguste.\n4. *Res publica restituta*, « la République restaurée », présente comme un retour à la tradition ce qui est en réalité un **changement de régime**. Auguste le dit lui-même : il a **surpassé tout le monde en autorité**. La formule rassure et légitime un pouvoir nouveau sous des apparences anciennes : c'est pourquoi le cours invite à la lire comme de la **communication politique**, et non comme une description fidèle."}$exo$::jsonb),
  ('9f2f35db-9c91-50a8-87f1-60869cb7594e'::uuid, 3, 'traduction', $exo${"titre":"Ce que Rome nous a laissé","consigne":"Rédige un développement organisé d'une vingtaine de lignes, appuyé sur des exemples précis du cours.","enonce":"**Sujet.** « Le Sénat et le peuple romain » : Rome se présentait comme une communauté de citoyens équilibrée.\n\nEn t'appuyant sur le cours, montre :\n1. comment les **institutions** de la République organisent cet équilibre revendiqué ;\n2. que la **société** romaine reste pourtant profondément inégalitaire et hiérarchisée (au moins trois notions) ;\n3. comment cet équilibre est vidé de son contenu au passage à l'**Empire** ;\n4. ce que Rome a malgré tout **légué** à nos sociétés.","bareme":[{"critere":"Institutions décrites avec précision : cursus honorum, Sénat, comices, tribuns et veto, SPQR","points":5},{"critere":"Au moins trois notions sociales justes (patriciens/plébéiens, patronus/cliens, esclavage, materfamilias, mos maiorum)","points":5},{"critere":"Passage à l'Empire daté et analysé (guerres civiles, 44 et 27 av. J.-C., formes gardées et vidées)","points":4},{"critere":"Héritage : droit romain, langues romanes, urbanisme, Cicéron, Tacite","points":4},{"critere":"Développement organisé et argumenté","points":2}],"dureeMin":20,"corrige":"1. **Les institutions** : la carrière politique suit le *cursus honorum* (questure, édilité, préture, consulat). Le **Sénat**, formé d'anciens magistrats, donne l'orientation politique ; les **comices**, le peuple assemblé, votent les lois et élisent ; les **tribuns de la plèbe**, élus de la plèbe, disposent d'un **droit de veto**. La formule *SPQR* (*Senatus PopulusQue Romanus*) dit cet **équilibre revendiqué** entre Sénat et peuple.\n2. **Une société hiérarchisée** : le corps civique est divisé entre **patriciens et plébéiens** ; le **clientélisme** (*patronus / cliens*) lie protection et soutien ; l'**esclavage** est massif, au cœur de l'économie et de la maison ; la **materfamilias** a un statut respecté mais **aucun droit politique** ; le **mos maiorum**, coutume des ancêtres, est la norme suprême et favorise la tradition.\n3. **Vers l'Empire** : au Ier siècle av. J.-C., les guerres civiles minent la République ; César est assassiné aux ides de mars (15 mars 44 av. J.-C.) ; en 27 av. J.-C., **Auguste** fonde le principat. L'Empire **garde les formes républicaines et en vide le contenu** ; la formule *Res publica restituta* est un chef-d'œuvre de communication politique.\n4. **L'héritage** : le **droit romain** irrigue nos codes civils ; le latin a donné les **langues romanes** ; l'**urbanisme** (forum, thermes, aqueducs) ; la rhétorique de **Cicéron** et l'historiographie de **Tacite** structurent notre manière d'argumenter et d'écrire l'histoire.\n\n**Conclusion attendue** : l'équilibre de *SPQR* est davantage revendiqué que réel, mais Rome a laissé des outils durables."}$exo$::jsonb),
  ('0eb1886a-d515-50b0-bc6a-0a6a3ffc2cfe'::uuid, 1, 'traduction', $exo${"titre":"Fatum, Parques et devins","consigne":"Réponds à chaque question en phrases complètes, en t'appuyant sur le cours.","enonce":"**Le destin chez les Romains**\n\n1. De quel verbe latin vient le mot *fatum* ? Que signifie ce verbe, et que nous dit-il sur la façon dont un Romain se représente le destin ?\n2. Qui sont les **Parques** ? Décris le rôle de chacune des trois, puis explique ce que montre le fait que même Jupiter ne peut défaire leur travail.\n3. Associe chaque personnage ou objet à ce qu'il observe ou à ce qu'il fait, et justifie en une phrase :\n   - a) l'augure ;\n   - b) l'haruspice ;\n   - c) la Sibylle de Cumes ;\n   - d) un prodige comme une pluie de sang.","bareme":[{"critere":"Fatum rattaché à fari (parler) et sens expliqué : le destin est ce qui a été dit une fois pour toutes","points":6},{"critere":"Rôle des Parques (filer, mesurer, couper) et conclusion : le fatum dépasse les dieux eux-mêmes","points":6},{"critere":"Les quatre associations justes : oiseaux, entrailles, prophétesse d'Apollon guide d'Énée, rupture de la pax deorum","points":8}],"dureeMin":7,"corrige":"1. *Fatum* vient du verbe *fari*, « parler ». Le destin est donc une **parole** : c'est **ce qui a été dit**, une fois pour toutes. Pour un Romain, le destin n'est pas une idée abstraite, c'est une parole prononcée qu'on ne peut plus reprendre.\n\n2. Les **Parques** (*Parcae*), calquées sur les Moires grecques, filent la vie de chacun : **l'une file, l'autre mesure, la troisième coupe** le fil. Même Jupiter ne peut défaire ce qu'elles ont filé : cela montre que le *fatum* **dépasse les dieux eux-mêmes** ; le roi des dieux n'est pas au-dessus du destin.\n\n3. \n- a) L'**augure** observe le **vol des oiseaux** (*auspicium*, de *avis* « oiseau » et *specere* « regarder »).\n- b) L'**haruspice**, venu d'Étrurie, lit les **entrailles des victimes**.\n- c) La **Sibylle de Cumes** est une **prophétesse d'Apollon** qui guide Énée aux Enfers (*Énéide*, VI) ; Rome conservait les *libri Sibyllini*, consultés en cas de crise.\n- d) Un **prodige** (*prodigium*) signale que la **pax deorum**, la paix avec les dieux, est **rompue**."}$exo$::jsonb),
  ('0eb1886a-d515-50b0-bc6a-0a6a3ffc2cfe'::uuid, 2, 'traduction', $exo${"titre":"Énée, exilé par le destin","consigne":"Traduis la phrase à l'aide du lexique, puis réponds aux questions en justifiant.","enonce":"**Phrase composée pour l'exercice**, d'après le début de l'*Énéide* :\n\n> *Aeneas, fato profugus, in Italiam venit.*\n\n*Lexique : Aeneas, ae (m.) = Énée ; fatum, i (n.) = le destin ; profugus, a, um = fugitif, exilé ; in + accusatif = vers, en ; Italia, ae (f.) = l'Italie ; venit = parfait de venio, « il vint, il est venu ».*\n\n1. Traduis la phrase mot à mot, puis en bon français.\n2. À quel cas est *fato* ? Quelle est sa fonction ? Explique ce que ce cas apporte au sens : pourquoi Énée part-il ?\n3. Chez Virgile, Énée doit abandonner Didon pour fonder la lignée d'où sortira Rome. Comment s'appelle sa vertu ? En quoi consiste-t-elle ?\n4. En quoi le héros romain s'oppose-t-il au héros de la révolte tragique ?","bareme":[{"critere":"Traduction juste : « Énée, exilé par le destin, vint (est venu) en Italie », mot à mot puis bon français","points":6},{"critere":"Fato identifié comme ablatif de cause, avec l'idée qu'Énée part parce que c'est écrit, non par peur","points":5},{"critere":"Pietas nommée et définie comme l'acceptation de son rôle","points":5},{"critere":"Opposition consentement / révolte tragique clairement formulée","points":4}],"dureeMin":10,"corrige":"1. Mot à mot : « Énée, par le destin fugitif, vers l'Italie vint. » En bon français : **« Énée, exilé par le destin, est venu (vint) en Italie. »**\n\n2. *Fato* est à l'**ablatif** : c'est un **ablatif de cause**, complément de *profugus*. Il dit **pourquoi** Énée est fugitif : il ne fuit pas par peur, il part **parce que c'est écrit**, parce que le destin l'a décidé. C'est pourquoi on traduit *fato profugus* par « exilé par le destin ».\n\n3. Sa vertu est la **pietas**. Elle consiste à **accepter le rôle** que le destin lui donne : fonder la lignée d'où sortira Rome, quitte à abandonner Didon. Énée ne choisit pas ; sa grandeur est d'obéir à sa mission.\n\n4. Le héros romain n'est pas grand parce qu'il échappe au destin, mais parce qu'il y **consent**. C'est l'opposé de la **révolte tragique**, où le héros se dresse contre le sort qui l'écrase. Énée, lui, fait sien ce qui a été dit (*fatum*)."}$exo$::jsonb),
  ('0eb1886a-d515-50b0-bc6a-0a6a3ffc2cfe'::uuid, 3, 'traduction', $exo${"titre":"Qui ordonne le monde, qui décide des vies ?","consigne":"Lis les documents, réponds aux questions 1 et 2, puis rédige le paragraphe argumenté demandé à la question 3.","enonce":"**Document 1 — Ovide, *Métamorphoses*, I (début)**\n\n> *Ante mare et terras et quod tegit omnia caelum / unus erat toto naturae vultus in orbe, / quem dixere chaos.*\n> « Avant la mer, les terres et le ciel qui couvre tout, la nature n'avait dans tout l'univers qu'un seul visage, qu'on a appelé chaos. »\n\nOvide raconte ensuite qu'un dieu (*deus et melior natura*) sépare les éléments, range le lourd en bas et le léger en haut ; l'homme vient en dernier.\n\n**Document 2 — Quatre récits de l'origine du monde**\n\n| Récit | Auteur | Ce qui crée le monde |\n| *Théogonie* | Hésiode | Des générations de dieux, du Chaos à Zeus |\n| *Timée* | Platon | Un démiurge qui copie un modèle parfait |\n| *Métamorphoses* | Ovide | Un dieu qui sépare et ordonne |\n| *De rerum natura* | Lucrèce | Aucun dieu : la rencontre des atomes |\n\n**Document 3** — Au deuxième vers de l'*Énéide*, Énée est dit *fato profugus*, « exilé par le destin ».\n\n1. D'après le document 1, comment le monde naît-il chez Ovide ? Quelle place l'homme y occupe-t-il, et qu'est-ce qui le distingue des autres êtres ?\n2. Montre, à l'aide du document 2, que Lucrèce se sépare des trois autres récits.\n3. **Paragraphe argumenté** (15 lignes environ) : « Pour un Romain, l'homme a-t-il prise sur l'ordre du monde et sur sa propre vie ? » Appuie-toi sur les documents et sur ce que tu sais des Parques, de la *pietas* d'Énée et des signes par lesquels les dieux parlent (augures, prodiges).","bareme":[{"critere":"Naissance du monde par un tri (séparer, ranger lourd et léger) et place de l'homme, dernier, visage levé vers le ciel","points":4},{"critere":"Lucrèce distingué : aucun dieu, la rencontre des atomes, contre dieux, démiurge ou dieu ordonnateur","points":4},{"critere":"Paragraphe : le destin comme parole qui dépasse même les dieux (fatum, Parques)","points":4},{"critere":"Paragraphe : la part de l'homme, consentir (pietas d'Énée) et lire les signes (augures, prodiges, pax deorum)","points":5},{"critere":"Paragraphe construit, avec une réponse nuancée et des exemples tirés des documents","points":3}],"dureeMin":17,"corrige":"1. Chez Ovide, le monde naît d'un **tri** : au commencement, la nature n'a qu'**un seul visage**, le **chaos** ; puis un dieu (*deus et melior natura*) **sépare** les éléments, range le **lourd en bas**, le **léger en haut**. Le monde est un **ordre** introduit dans la confusion. L'homme vient **en dernier** ; il est le seul être qui **lève le visage vers le ciel**.\n\n2. Hésiode fait naître le monde de générations de **dieux**, Platon d'un **démiurge** artisan, Ovide d'un **dieu** qui ordonne : dans les trois cas, une puissance divine est à l'origine. Lucrèce, au contraire, n'y met **aucun dieu** : le monde naît de la **rencontre des atomes**.\n\n3. **Paragraphe attendu (exemple de plan).**\n- **Un ordre qui ne dépend pas de l'homme.** Chez Ovide, c'est un dieu qui tire le monde du chaos ; l'homme arrive en dernier, dans un monde déjà rangé. Et la vie de chacun est réglée d'avance : le *fatum*, de *fari*, est **ce qui a été dit** ; les **Parques** filent, mesurent et coupent le fil de chaque vie, et **même Jupiter** ne peut défaire leur travail.\n- **Une marge pourtant : consentir.** Énée, *fato profugus*, ne choisit pas son exil ; mais sa **pietas** est d'**accepter** ce rôle. Le héros romain est grand parce qu'il **consent** au destin, non parce qu'il lui échappe.\n- **Une marge encore : écouter les dieux.** Les Romains **interrogent** les signes : l'augure observe les oiseaux, l'haruspice les entrailles ; un **prodige** avertit que la **pax deorum** est rompue, ce qui permet de la rétablir. L'homme ne décide pas de l'avenir, mais il peut l'entendre.\n- **Nuance :** Lucrèce refuse tout cela ; pour lui, aucun dieu ne crée le monde, qui naît des atomes.\n\nConclusion attendue : pour la plupart des Romains, l'homme n'a **pas prise** sur l'ordre du monde ni sur son destin, mais il garde une grandeur : **y consentir** et **en lire les signes**."}$exo$::jsonb),
  ('a4d78489-85e8-5176-9e2a-daf3772f8d8d'::uuid, 1, 'traduction', $exo${"titre":"Les familles maudites de Sénèque","consigne":"Réponds à chaque question en t'appuyant sur le cours.","enonce":"1. Qui est **Sénèque** ? Donne ses dates, son lien avec Néron et les deux sortes d'œuvres qu'il a écrites.\n2. Associe chaque tragédie à son crime et à sa famille :\n   - Pièces : *Thyeste* · *Agamemnon* · *Œdipe* · *Médée*.\n   - Crimes : a) une mère tue ses enfants après avoir été abandonnée par Jason ; b) un roi découvre qu'il a tué son père et épousé sa mère ; c) un homme sert à son frère la chair de ses propres fils ; d) une épouse tue son mari au retour de Troie.\n3. Que signifie le mot *furor* ? Et le mot *scelus* ?\n4. À la nourrice qui lui rappelle qu'elle a tout perdu, Médée répond : *Medea superest*. Traduis et explique ce que ces deux mots disent du personnage.","bareme":[{"critere":"Sénèque présenté : vers 4 av. – 65 ap. J.-C., précepteur puis conseiller de Néron, traités de sagesse et tragédies","points":4},{"critere":"Les quatre associations pièce, crime et famille justes (Atrides, Labdacides, la Colchidienne)","points":8},{"critere":"Furor (fureur, passion devenue folie) et scelus (le crime) définis","points":4},{"critere":"Medea superest traduit « il reste Médée » et interprété : un personnage réduit à sa seule volonté","points":4}],"dureeMin":7,"corrige":"1. **Sénèque** (vers 4 av. J.-C. – 65 ap. J.-C.) est un philosophe **stoïcien**, **précepteur puis conseiller de Néron**. Il a écrit des **traités de sagesse** et des **tragédies** d'une violence extrême (*Médée*, *Œdipe*, *Phèdre*, *Thyeste*, *Agamemnon*).\n\n2. \n- *Thyeste* → c) : Atrée sert à son frère la chair de ses propres fils — famille des **Atrides**.\n- *Agamemnon* → d) : Clytemnestre tue son époux au retour de Troie — les **Atrides**.\n- *Œdipe* → b) : le roi découvre qu'il a tué son père et épousé sa mère — les **Labdacides**.\n- *Médée* → a) : abandonnée par Jason, elle tue leurs enfants — **la Colchidienne**.\n\n3. *Furor* : la **fureur**, la **passion devenue folie** ; c'est le mot clé des tragédies de Sénèque. *Scelus* : **le crime**.\n\n4. *Medea superest* : **« il reste Médée »**. Médée a tout perdu, mais il lui reste **elle-même** : deux mots qui résument un personnage **réduit à sa seule volonté**. Le crime qu'elle va commettre n'est pas subi, il est **voulu et proclamé**."}$exo$::jsonb),
  ('a4d78489-85e8-5176-9e2a-daf3772f8d8d'::uuid, 2, 'traduction', $exo${"titre":"La vie comme une pièce de théâtre","consigne":"Traduis la phrase de Sénèque à l'aide du lexique, puis réponds aux questions.","enonce":"**Sénèque, *Lettres à Lucilius*** :\n\n> *Quomodo fabula, sic vita : non quam diu, sed quam bene acta sit, refert.*\n\n*Lexique : quomodo… sic… = de même que… ainsi… ; fabula, ae (f.) = la pièce de théâtre ; vita, ae (f.) = la vie ; non… sed… = non pas… mais… ; quam diu = combien de temps ; quam bene = à quel point bien ; acta sit = « elle a été jouée » (de ago, jouer une pièce) ; refert = il importe, ce qui compte.*\n\n1. Traduis la phrase en bon français.\n2. Explique l'idée de Sénèque : qu'est-ce qui compte dans une vie ? Qu'est-ce qui ne compte pas ?\n3. Selon Suétone, que demanda Auguste mourant à ses amis ? En quoi ce mot rejoint-il la phrase de Sénèque ?\n4. Cite deux œuvres modernes qui reprennent l'image du *theatrum mundi*, avec leur auteur, leur date et ce qu'elles en font.","bareme":[{"critere":"Traduction juste : il en va de la vie comme d'une pièce, ce qui compte n'est pas sa durée mais la qualité du jeu","points":7},{"critere":"Idée expliquée : bien jouer son rôle, quelle que soit sa longueur","points":4},{"critere":"Anecdote d'Auguste restituée et reliée à l'image de la vie jouée","points":4},{"critere":"Deux reprises modernes justes (Shakespeare 1599, Calderón 1635, Corneille 1636) avec leur apport","points":5}],"dureeMin":10,"corrige":"1. **« Il en va de la vie comme d'une pièce : ce qui compte, ce n'est pas sa durée, mais la qualité du jeu. »** (Mot à mot : « de même qu'une pièce, ainsi la vie : non pas combien longtemps, mais combien bien elle a été jouée, importe. »)\n\n2. Pour Sénèque, la vie est une **pièce** où chacun tient un **rôle**. Ce qui compte, ce n'est **pas la durée** (une vie courte n'est pas un échec), mais la **manière** dont on la joue : **bien jouer son rôle, quelle que soit sa longueur**. C'est une leçon stoïcienne : on ne choisit pas la durée, on choisit la qualité.\n\n3. Selon **Suétone**, Auguste mourant demanda à ses amis **s'il avait bien joué la comédie de la vie**. Comme chez Sénèque, la vie est une pièce, et on la juge à la **qualité du jeu**.\n\n4. Deux au choix :\n- **Shakespeare**, *Comme il vous plaira* (**1599**) : « **Le monde entier est un théâtre** ».\n- **Calderón**, *La vie est un songe* (**1635**) : le réel et l'illusion se confondent.\n- **Corneille**, *L'Illusion comique* (**1636**) : le **théâtre dans le théâtre**."}$exo$::jsonb),
  ('a4d78489-85e8-5176-9e2a-daf3772f8d8d'::uuid, 3, 'traduction', $exo${"titre":"Lire une tirade de fureur","consigne":"Lis la tirade, applique la méthode du cours, puis rédige la réponse argumentée de la question 4.","enonce":"**Tirade composée pour l'exercice**, à la manière de Sénèque. Une héroïne abandonnée se parle à elle-même :\n\n> *Surge, anime ! Dolor, ira, furor, adeste ! Magnum scelus paremus. Medea superest.*\n\n*Lexique : surge = impératif de surgo, « lève-toi » ; anime = vocatif de animus, « mon cœur » ; dolor, oris (m.) = la douleur ; ira, ae (f.) = la colère ; adeste = impératif pluriel de adsum, « soyez là » ; magnus, a, um = grand ; paremus = subjonctif présent de paro, « préparons » ; superest = « il reste ».*\n\n1. Traduis la tirade.\n2. Relève les **impératifs** et le **subjonctif de souhait**. Qu'expriment-ils ici ?\n3. Relève le vocabulaire de la passion. Quelle phrase a la forme d'une **sentence** brève ?\n4. **Réponse argumentée** (10 à 15 lignes) : pourquoi dit-on que la tragédie de Sénèque est « une leçon stoïcienne à l'envers » ? Compare avec l'Œdipe de Sophocle et dis ce que la raison stoïcienne aurait conseillé à l'héroïne.","bareme":[{"critere":"Traduction juste : « Lève-toi, mon cœur ! Douleur, colère, fureur, soyez là ! Préparons un grand crime. Il reste Médée. »","points":5},{"critere":"Impératifs (surge, adeste) et subjonctif (paremus) relevés : l'héroïne s'exhorte elle-même au crime","points":4},{"critere":"Vocabulaire de la passion (dolor, ira, furor, scelus) et sentence (Medea superest) repérés","points":3},{"critere":"Opposition Sophocle (le destin écrase) / Sénèque (le crime naît d'une passion qu'on aurait pu dominer)","points":5},{"critere":"Conseil de la raison stoïcienne : dominer la passion ; la pièce se lit en creux","points":3}],"dureeMin":17,"corrige":"1. **« Lève-toi, mon cœur ! Douleur, colère, fureur, soyez là ! Préparons un grand crime. Il reste Médée. »**\n\n2. **Impératifs** : *surge* (lève-toi), *adeste* (soyez là). **Subjonctif de souhait** : *paremus* (préparons). L'héroïne **s'exhorte elle-même au crime** : elle appelle ses passions comme des alliées. Le crime n'est pas subi, il est **voulu, préparé, proclamé**.\n\n3. Vocabulaire de la passion : *dolor* (la douleur), *ira* (la colère), *furor* (la fureur, la passion devenue folie), et *scelus* (le crime) qui en est l'aboutissement. **Sentence** : *Medea superest*, deux mots frappés comme une maxime, marque du style de Sénèque.\n\n4. **Réponse attendue.** Chez **Sophocle**, le **destin écrase Œdipe** : le héros est victime d'un sort qu'il ne peut éviter. Chez **Sénèque**, le crime **naît d'une passion** que le héros **aurait pu dominer** : dans la tirade, l'héroïne convoque elle-même douleur, colère et fureur, et décide de préparer le crime. La tragédie montre **ce que devient l'âme quand la passion l'emporte sur la raison**. Or le stoïcisme, que Sénèque défend dans ses traités, enseigne de **vivre selon la raison** et de dominer ses passions. La pièce montre exactement **l'inverse** de ce que conseille la sagesse : c'est une **leçon stoïcienne à l'envers**. Elle se lit **en creux** : la raison aurait conseillé à l'héroïne de **ne pas se laisser gouverner par sa colère**, de ne pas appeler le *furor*, mais de le maîtriser. Le paradoxe d'un philosophe auteur de tragédies si violentes n'est donc qu'apparent : le spectacle du crime enseigne, par contraste, la valeur de la raison."}$exo$::jsonb),
  ('1917545c-4cb7-59e5-a3c2-3ee1cafe0a40'::uuid, 1, 'traduction', $exo${"titre":"Ovide relégué : les faits","consigne":"Réponds à chaque question en phrases complètes.","enonce":"1. En quelle année Ovide doit-il quitter Rome ? Qui l'y oblige, et vers quel lieu ? Situe ce lieu aujourd'hui.\n2. Ovide dit avoir été perdu par *carmen et error*. Traduis ces deux mots et explique ce que l'on sait de chacune de ces deux causes.\n3. Ovide est-il **relégué** ou **exilé** ? Explique la différence entre les deux peines, puis dis comment Ovide se nomme lui-même dans ses vers.\n4. En quel vers les *Tristes* sont-ils écrits ? Décris-le.","bareme":[{"critere":"En 8 ap. J.-C., Auguste le relègue à Tomis, sur la mer Noire, l'actuelle Constanța en Roumanie","points":5},{"critere":"Carmen et error traduits ; le poème est l'Art d'aimer, l'erreur n'a jamais été dite","points":5},{"critere":"Relégation (ordre de l'empereur, citoyenneté et biens gardés) distinguée de l'exil ; Ovide se dit pourtant exul","points":6},{"critere":"Distique élégiaque : un hexamètre suivi d'un pentamètre, vers de la plainte","points":4}],"dureeMin":7,"corrige":"1. En **8 ap. J.-C.**, **Auguste** frappe Ovide de relégation à **Tomis**, au bord de la **mer Noire** (le Pont-Euxin), dans l'actuelle **Constanța, en Roumanie**. Il ne reverra jamais Rome.\n\n2. *Carmen et error* : **« un poème et une erreur »**. Le **poème**, c'est l'***Art d'aimer***, jugé contraire aux lois morales d'Auguste. L'**erreur**, Ovide ne l'a **jamais dite**.\n\n3. Ovide est **relégué**. La **relégation** (*relegatio*) est un **ordre de l'empereur, sans procès** : le condamné **garde sa citoyenneté et ses biens**. L'**exil** (*exilium*) est une peine **plus lourde** : **perte de la citoyenneté** et souvent des biens. Pourtant, dans ses vers, Ovide se dit ***exul***, « exilé ».\n\n4. Les *Tristes* sont écrits en **distiques élégiaques** : **un hexamètre suivi d'un pentamètre**. C'est le **vers de la plainte**."}$exo$::jsonb),
  ('1917545c-4cb7-59e5-a3c2-3ee1cafe0a40'::uuid, 2, 'traduction', $exo${"titre":"« C'est mon talent qui m'a perdu »","consigne":"Traduis à l'aide du lexique, puis réponds aux questions.","enonce":"**Document 1 — *Tristes*, III, 3** : malade, Ovide compose son épitaphe.\n\n> *Hic ego qui iaceo tenerorum lusor amorum / ingenio perii Naso poeta meo.*\n\n*Lexique : hic = ici ; qui iaceo = qui repose ; tenerorum lusor amorum = chantre des tendres amours ; ingenium, ii (n.) = le talent, le génie ; perii = parfait de pereo, « je péris » ; Naso, onis = Nason (le surnom d'Ovide) ; poeta, ae (m.) = le poète ; meus, a, um = mon.*\n\n**Document 2 — *Tristes*, III, 7**, lettre à Périlla, jeune poétesse :\n\n> *Ingenio tamen ipse meo comitorque fruorque.*\n> « Je suis pourtant accompagné de mon génie, et j'en jouis. »\n\n1. Traduis le document 1, d'abord mot à mot pour le second vers, puis en bon français.\n2. Analyse *ingenio* et *perii* (cas et valeur, temps et verbe). Pourquoi traduire par une tournure présentative ?\n3. Compare les deux documents : quel double rôle l'*ingenium* joue-t-il dans la vie d'Ovide exilé ?","bareme":[{"critere":"Traduction juste du distique : moi qui repose ici, chantre des tendres amours, le poète Nason, c'est mon talent qui m'a perdu","points":7},{"critere":"Ingenio ablatif de cause, perii parfait de pereo ; la tournure présentative rend l'insistance","points":6},{"critere":"Double rôle de l'ingenium : ce qui l'a perdu, ce qui le console et l'accompagne","points":7}],"dureeMin":11,"corrige":"1. Mot à mot (vers 2) : « par mon talent j'ai péri, Nason le poète ». En bon français : **« Moi qui repose ici, chantre des tendres amours, le poète Nason, c'est mon talent qui m'a perdu. »**\n\n2. *Ingenio* (accordé avec *meo*) est un **ablatif de cause** : c'est **à cause de** son talent qu'il a péri. *Perii* est le **parfait** de *pereo*, « je péris » : « j'ai péri ». On traduit par la **tournure présentative** « c'est mon talent qui m'a perdu » pour rendre l'**insistance** du latin, qui place *ingenio* en tête du vers.\n\n3. L'*ingenium* joue un **double rôle** :\n- dans le document 1, il est **ce qui l'a perdu** : le talent poétique a produit l'*Art d'aimer*, l'une des deux causes de sa relégation (*carmen et error*) ;\n- dans le document 2, il est **ce qui le sauve** : tout peut lui être enlevé, **sauf son génie**, qui l'**accompagne** à Tomis et dont il **jouit** encore.\n\nLe talent est donc à la fois la **cause** de l'exil et son **remède**, comme le *carmen*, poème qui a causé la perte et qui console."}$exo$::jsonb),
  ('1917545c-4cb7-59e5-a3c2-3ee1cafe0a40'::uuid, 3, 'traduction', $exo${"titre":"Les Tristes, un plaidoyer","consigne":"Lis les résumés, puis rédige un développement argumenté d'une vingtaine de lignes.","enonce":"**Quatre élégies du livre III des *Tristes***\n\n- **III, 1** : c'est le livre lui-même qui parle. Envoyé à Rome, il erre timidement de monument en monument et découvre que les bibliothèques publiques lui ferment leurs portes.\n- **III, 9** : Tomis devrait son nom à Médée, qui y aurait découpé son frère Absyrtos (en grec, *temnein*, « couper »).\n- **III, 10** : l'hiver scythe. L'Hister (le Danube) gèle, les barbares le traversent à cheval, le vin gèle dans les jarres et se boit… en morceaux.\n- **III, 12** : le printemps revient à Rome, pas à Tomis.\n\n**Sujet** : « Les *Tristes* ne sont pas un journal de voyage : c'est un plaidoyer. » Explique et justifie cette affirmation.\n\nTon développement doit :\n1. dire à qui s'adresse ce plaidoyer et ce qu'il cherche à obtenir ;\n2. montrer, avec au moins **trois** élégies ci-dessus, comment les détails deviennent des arguments ;\n3. employer et expliquer au moins **trois** de ces mots latins : *exul*, *patria*, *barbarus*, *carmen*, *ingenium*.","bareme":[{"critere":"Destinataire et but : Auguste, obtenir un lieu d'exil plus doux","points":4},{"critere":"Au moins trois élégies analysées : chaque détail (froid, barbarie, livre rejeté, printemps absent) devient un argument","points":7},{"critere":"Trois mots latins employés à bon escient et expliqués","points":5},{"critere":"Développement organisé et rédigé, qui répond au sujet","points":4}],"dureeMin":18,"corrige":"**Éléments attendus.**\n\n1. **Destinataire et but.** Les *Tristes* sont des lettres en vers envoyées de Tomis, mais le vrai destinataire, en dernier ressort, est **Auguste**. Chaque détail du froid et de la barbarie est un argument pour obtenir **un lieu d'exil plus doux**.\n\n2. **Les détails deviennent des arguments.**\n- **III, 10** : le Danube gelé, les barbares qui le traversent à cheval, le vin qui se boit en morceaux : Tomis est un lieu **extrême**, **dangereux** et **invivable**. Ces détails visent à émouvoir le prince.\n- **III, 9** : même le nom de la ville rappelle un **crime** (Médée découpant son frère) : Ovide vit dans un lieu marqué par la violence.\n- **III, 12** : le printemps revient à Rome, **pas à Tomis** : le contraste souligne tout ce qu'il a perdu.\n- **III, 1** : le livre rejeté des bibliothèques publiques montre que le poète est **exclu jusque dans son œuvre** ; sa détresse est celle d'un homme rejeté de Rome.\n\n3. **Les mots latins** (trois au choix) :\n- ***exul*** : « exilé ». Ovide n'est que **relégué** (il garde citoyenneté et biens), mais il se dit *exul* : il **dramatise** sa situation, ce qui sert le plaidoyer.\n- ***patria*** : « la terre des pères », **Rome, toujours regrettée**.\n- ***barbarus*** : celui qui ne parle ni latin ni grec ; les Gètes, les Sarmates… et bientôt Ovide lui-même, isolé par la langue.\n- ***carmen*** : le poème, **cause** de l'exil (*carmen et error*) et **remède**.\n- ***ingenium*** : le talent, qui l'a perdu (*ingenio perii*) et qui le sauve.\n\nConclusion attendue : les *Tristes* décrivent un lieu réel, mais **choisissent** et **mettent en avant** les détails pour **convaincre** : c'est de la poésie mise au service d'une **plaidoirie**."}$exo$::jsonb),
  ('f383dc99-8a45-5edf-ab4b-743fa80757bc'::uuid, 1, 'traduction', $exo${"titre":"Deux livres, deux départs","consigne":"Réponds à chaque question à partir du cours.","enonce":"Le programme limitatif associe les *Tristes* (livre III) d'Ovide et *La ferme africaine* de Karen Blixen.\n\n1. Présente **Karen Blixen** : nationalité, nom de plume, lieu et nature de son exploitation, date de son installation.\n2. Pourquoi Karen Blixen doit-elle quitter l'Afrique ? Où et quand écrit-elle *La ferme africaine* ?\n3. Complète la comparaison en quatre points (une phrase pour chacun) : **le départ** ; **le moment où l'auteur écrit** ; **le ton** ; **ce qui est perdu**.","bareme":[{"critere":"Blixen présentée : danoise, Isak Dinesen, plantation de café au pied des collines de Ngong, au Kenya, en 1914","points":5},{"critere":"Causes du retour (faillite, mort de Denys Finch Hatton en 1931, vente) ; écrit au Danemark, publié en 1937","points":5},{"critere":"Les quatre points de comparaison justes pour Ovide et pour Blixen","points":10}],"dureeMin":7,"corrige":"1. **Karen Blixen** (1885-1962) est une romancière **danoise** qui signe souvent **Isak Dinesen**. En **1914**, elle s'installe au **Kenya**, alors possession britannique, pour exploiter une **plantation de café** au pied des **collines de Ngong**, près de Nairobi.\n\n2. Dix-sept ans plus tard, tout s'effondre : la **ferme fait faillite**, son ami **Denys Finch Hatton meurt en 1931** dans l'accident de son avion, elle doit **vendre** et rentrer au **Danemark**. C'est là, **loin de l'Afrique**, qu'elle écrit *La ferme africaine* (**1937**).\n\n3. \n- **Le départ** : Ovide part **de force** (relégation par Auguste) ; Blixen part **par choix**, pour une vie nouvelle.\n- **Quand l'auteur écrit** : Ovide écrit **pendant l'exil, au présent** ; Blixen **après le retour, au passé**.\n- **Le ton** : chez Ovide, **la plainte et l'appel à l'aide** ; chez Blixen, **la mémoire, la gratitude, le deuil**.\n- **Ce qui est perdu** : pour Ovide, **Rome, la *patria*** ; pour Blixen, **la ferme, l'Afrique, un ami**."}$exo$::jsonb),
  ('f383dc99-8a45-5edf-ab4b-743fa80757bc'::uuid, 2, 'traduction', $exo${"titre":"Un même motif, deux intentions : le paysage","consigne":"Suis les quatre étapes de la méthode du rapprochement vue en cours et rédige chaque étape.","enonce":"**Document 1 — Ovide, *Tristes*, III, 10** (résumé) : l'hiver scythe. L'Hister (le Danube) gèle, les barbares le traversent à cheval, le vin gèle dans les jarres et se boit en morceaux.\n\n**Document 2 — Karen Blixen, *La ferme africaine***, première phrase :\n\n> « J'avais une ferme en Afrique, au pied des collines du Ngong. »\n\n**Document 3 — Un mot des *Tristes*** : *patria*, « la terre des pères ».\n\nConstruis un **rapprochement** sur le motif du **paysage** :\n1. Formule le motif commun de façon précise.\n2. Cite une expression latine traduite et la phrase de Blixen.\n3. Dis ce qui **rapproche** les deux textes, puis ce qui les **sépare** (contexte, époque, genre).\n4. Conclus : que révèle la confrontation, qu'aucune des deux œuvres ne dirait seule ?","bareme":[{"critere":"Motif commun précis : le paysage de l'éloignement, vu par un écrivain loin de chez lui","points":3},{"critere":"Citations exactes : un mot ou une expression latine traduite et la phrase de Blixen","points":4},{"critere":"Rapprochement puis différences : argument chez Ovide, souvenir chez Blixen ; exil forcé / aventure coloniale ; élégie / récit autobiographique","points":9},{"critere":"Conclusion sur ce que la confrontation révèle","points":4}],"dureeMin":12,"corrige":"1. **Motif commun** : le **paysage lointain**, décrit par un écrivain qui vit ou a vécu loin de sa terre d'origine.\n\n2. **Citations** : chez Ovide, la *patria*, « la terre des pères », Rome regrettée, s'oppose au paysage glacé de Tomis où l'**Hister gèle** ; chez Blixen : « **J'avais une ferme en Afrique, au pied des collines du Ngong.** »\n\n3. **Ce qui rapproche** : dans les deux œuvres, le paysage est celui d'un **ailleurs** qui a marqué une vie, et l'écriture naît de l'**éloignement** (ils écrivent parce qu'ils sont loin).\n**Ce qui sépare** :\n- l'**intention** : l'hiver de Tomis est un **argument** adressé à Auguste pour obtenir un exil plus doux ; la lumière des collines de Ngong est un **souvenir** ;\n- le **contexte** : un **exil forcé** par le pouvoir d'un côté, une **aventure coloniale** choisie de l'autre ;\n- le **temps de l'écriture** : Ovide écrit **pendant** l'exil, au présent ; Blixen **après** le retour, au passé (« J'avais ») ;\n- le **genre** : l'**élégie** en distiques, vers de la plainte, contre le **récit autobiographique** ;\n- l'**époque** : dix-neuf siècles les séparent.\n\n4. **Conclusion** : la confrontation montre que **le même motif sert deux intentions** : chez Ovide, le paysage hostile plaide ; chez Blixen, le paysage aimé est sauvé de l'oubli. Ensemble, les deux textes révèlent que le paysage, en littérature, dit moins le lieu que **le regard de celui qui l'a perdu**."}$exo$::jsonb),
  ('f383dc99-8a45-5edf-ab4b-743fa80757bc'::uuid, 3, 'traduction', $exo${"titre":"Partir à cause d'écrire, écrire parce qu'on est parti","consigne":"Rédige un essai court et organisé (deux parties, 25 lignes environ), qui confronte les deux œuvres dans chaque partie.","enonce":"Le programme résume l'enjeu ainsi :\n\n> « On part à cause de ce qu'on a écrit, ou l'on écrit parce qu'on est parti. »\n\n**Rappels** :\n- Ovide a été relégué à Tomis pour *carmen et error*, « un poème et une erreur » ; il écrit les *Tristes* pendant son exil.\n- Karen Blixen a quitté le Danemark en 1914 pour une ferme au Kenya ; elle écrit *La ferme africaine* après son retour, publiée en 1937.\n- Ovide se dit *barbarus* dans le livre V, parce que personne ne le comprend ; Blixen décrit Kikuyus, Masaïs et Somalis avec attachement.\n\n**Sujet** : Dans quelle mesure cette formule éclaire-t-elle les deux œuvres ?\n\nTon essai doit :\n1. formuler une problématique qui ne recopie pas le sujet ;\n2. montrer quelle œuvre illustre chaque moitié de la formule, puis comment chacune touche aussi l'autre ;\n3. traiter au moins un autre enjeu du cours : écrire pour survivre, le regard sur l'étranger ou le destin ;\n4. citer au moins un mot latin, traduit.","bareme":[{"critere":"Problématique formulée, distincte du sujet","points":3},{"critere":"Ovide illustre la première formule, Blixen la seconde, avec justification précise","points":5},{"critere":"Chaque œuvre touche aussi l'autre formule : Ovide écrit parce qu'il est loin, Blixen part avant d'écrire","points":4},{"critere":"Un autre enjeu traité avec nuance (écrire pour survivre, regard sur l'étranger, destin)","points":5},{"critere":"Essai confrontant les œuvres dans chaque partie, latin cité et traduit","points":3}],"dureeMin":20,"corrige":"**Problématique possible** : l'écriture est-elle la cause de l'éloignement ou sa conséquence, et que devient-elle quand on est loin ?\n\n**I. Une formule qui répartit les deux œuvres.**\n- **Ovide** illustre la **première moitié** : il **part à cause de ce qu'il a écrit**. Il est relégué pour *carmen et error*, « un poème et une erreur », le poème étant l'*Art d'aimer*. Son *ingenium* l'a perdu (*ingenio perii*).\n- **Blixen** illustre la **seconde** : **elle écrit parce qu'elle est partie**. Son départ est un choix (1914), et c'est une fois l'Afrique perdue, rentrée au Danemark, qu'elle écrit *La ferme africaine* (1937).\n\n**II. Une formule que chaque œuvre dépasse.**\n- **Chacun touche aussi l'autre formule** : Ovide **écrit aussi parce qu'il est parti** — les *Tristes* n'existent que par l'exil, lien avec Rome et arme de plaidoirie ; Blixen, elle, **est partie avant d'écrire**, et l'éloignement est la condition de son livre.\n- **Écrire pour survivre** : pour Ovide, l'écriture maintient le lien avec la *patria* et plaide auprès d'Auguste ; pour Blixen, elle sauve de l'oubli un monde disparu.\n- **Le regard sur l'étranger** (nuance attendue) : Ovide voit dans les Gètes et les Sarmates des « barbares », puis finit par se dire lui-même *barbarus*, « celui qui ne parle pas la langue », parce que personne ne le comprend ; Blixen décrit ses voisins africains comme des personnes, **sans échapper tout à fait au regard du colon de son temps**.\n- Ou **le destin** : Ovide accuse la colère d'un dieu (Auguste) et sa propre faute ; Blixen accepte les coups du sort avec une sorte de fierté aristocratique.\n\n**Conclusion** : la formule éclaire bien les deux œuvres, mais la confrontation montre qu'**écrire et partir sont liés dans les deux sens** : l'écriture peut causer l'éloignement, et l'éloignement fait naître l'écriture."}$exo$::jsonb),
  ('ccfa9fad-79b2-5e2e-9503-9928547b9265'::uuid, 1, 'traduction', $exo${"titre":"Tablettes, amulettes et philtres","consigne":"Réponds à chaque question en phrases complètes.","enonce":"1. Qu'est-ce qu'une **tablette d'exécration** (*tabella defixionum*) ? Décris le support, ce qu'on en fait, et où on la dépose.\n2. De quel verbe latin viennent les « défixions » ? Que signifie-t-il, et que dit-il du but de ces tablettes ?\n3. Donne deux exemples de personnes visées par ces tablettes. Que prouvent ces objets retrouvés par centaines ?\n4. Associe chaque objet à ce qu'il vise : amulette (*bulla*) · poupée percée · philtre.","bareme":[{"critere":"Tablette décrite : lame de plomb gravée de malédictions, roulée, percée d'un clou, jetée dans une tombe, un puits ou une source","points":6},{"critere":"Defigere, « clouer, fixer » : immobiliser l'adversaire","points":4},{"critere":"Deux cibles justes et conclusion : la magie est une pratique ordinaire, pas seulement un motif littéraire","points":5},{"critere":"Amulette : protéger ; poupée : envoûter ; philtre : faire aimer","points":5}],"dureeMin":7,"corrige":"1. Une **tablette d'exécration** est une **lame de plomb gravée de malédictions**. On la **roule**, on la **perce d'un clou**, puis on la **jette dans une tombe, un puits ou une source**.\n\n2. Les « défixions » viennent du verbe ***defigere***, **« clouer, fixer »**. Le verbe dit leur but : **immobiliser l'adversaire**, le « clouer » pour qu'il échoue.\n\n3. Deux exemples parmi : **un rival en amour**, **un voleur**, **un avocat adverse**, **l'aurige de l'écurie concurrente** au cirque. Ces objets, retrouvés par **centaines**, prouvent que la magie **n'est pas qu'un motif littéraire** : c'est une **pratique ordinaire**.\n\n4. \n- **Amulette** (la *bulla* portée par les enfants) → **protéger**.\n- **Poupée percée** (figurine d'argile ou de cire) → **envoûter**.\n- **Philtre** (mélange d'herbes et d'incantations) → **faire aimer**."}$exo$::jsonb),
  ('ccfa9fad-79b2-5e2e-9503-9928547b9265'::uuid, 2, 'traduction', $exo${"titre":"Une tablette contre un aurige","consigne":"Lis le document, puis réponds aux questions en t'appuyant sur le cours.","enonce":"**Document — Tablette composée pour l'exercice**, sur le modèle des tablettes retrouvées. Une lame de plomb, roulée et percée d'un clou, a été découverte au fond d'un puits près d'un cirque. On y lit :\n\n> *Defigo linguam et manus aurigae.*\n> « Je cloue la langue et les mains de l'aurige… » (suivent le nom de l'aurige et celui de ses chevaux ; le graveur demande qu'il tombe pendant la course.)\n\n*Lexique : defigo = je cloue, je fixe ; lingua, ae (f.) = la langue ; manus (acc. pluriel) = les mains ; auriga, ae (m.) = le cocher, l'aurige.*\n\n1. Traduis la phrase latine et identifie le verbe clé. Pourquoi viser la langue et les mains ?\n2. Relève dans la description tous les indices qui font de cet objet une tablette d'exécration.\n3. À l'aide des trois critères du cours, montre que ce geste relève de la **magie** et non de la **religion**.\n4. Rome redoute la magie et la condamne. Cite la plus ancienne loi du cours qui punit une pratique magique : que punit-elle exactement, et quel point commun a ce délit avec la tablette du document ?","bareme":[{"critere":"Traduction « je cloue la langue et les mains de l'aurige » ; defigo = immobiliser, empêcher d'agir","points":4},{"critere":"Indices relevés : plomb, roulée, clou, puits, malédiction visant un aurige","points":4},{"critere":"Trois critères appliqués : secret et privé, contrainte par la formule et non échange (do ut des), intérêt privé contre autrui","points":8},{"critere":"Loi des Douze Tables (milieu du Ve s. av. J.-C.) : attirer par ses chants les récoltes du voisin ; point commun : nuire à autrui par un rite","points":4}],"dureeMin":11,"corrige":"1. *Defigo linguam et manus aurigae* : **« Je cloue la langue et les mains de l'aurige. »** Le verbe clé est ***defigo*** (de *defigere*, « clouer, fixer ») : il s'agit d'**immobiliser** l'adversaire. On vise les **mains** pour qu'il ne puisse plus tenir les rênes et la **langue** pour qu'il ne puisse plus parler, encourager ses chevaux : on veut le rendre **impuissant** pendant la course.\n\n2. Indices : une **lame de plomb**, **roulée**, **percée d'un clou**, **jetée au fond d'un puits**, portant une **malédiction** contre un **aurige** de l'écurie concurrente. Tout correspond à la définition du cours.\n\n3. \n- **Secret et privé** : la tablette est cachée au fond d'un puits, alors que la religion est **publique, au grand jour**.\n- **Contrainte et non échange** : la religion **demande** aux dieux selon le principe ***do ut des***, « je donne pour que tu donnes » ; la tablette prétend **contraindre** par la **formule exacte** (« je cloue »).\n- **Intérêt privé contre autrui** : elle sert un parieur ou une écurie rivale **contre** un aurige, et non les **rites de la cité**.\nC'est donc de la **magie**.\n\n4. C'est la **loi des Douze Tables** (milieu du Ve siècle av. J.-C.) : elle punit celui qui, **par ses chants**, **attire les récoltes du voisin dans son champ**. Point commun avec la tablette : dans les deux cas, on cherche à **nuire à autrui** (voler sa récolte, faire tomber un aurige) **par un rite** (un chant, une formule gravée) et non par un acte ordinaire."}$exo$::jsonb),
  ('ccfa9fad-79b2-5e2e-9503-9928547b9265'::uuid, 3, 'traduction', $exo${"titre":"La magie, religion des autres ?","consigne":"Rédige un développement argumenté d'une vingtaine de lignes, en deux ou trois parties.","enonce":"**Sujet** : « Le mot *magus* dit déjà que la magie, c'est la religion des autres. » Explique cette affirmation, puis montre que Rome entretient avec la magie un rapport ambigu : elle la redoute, la condamne… et la pratique.\n\n**Pistes** (tu n'es pas obligé de toutes les suivre) :\n- l'origine du mot *magus* ;\n- ce qui sépare *religio* et *magia* ;\n- la loi et les procès : la loi des Douze Tables, Pline l'Ancien, Apulée ;\n- les objets retrouvés ;\n- les sorcières de la littérature : Canidia, Médée, Érichtho, Pamphile ; la Thessalie.","bareme":[{"critere":"Origine de magus (du perse, par le grec, prêtres des Perses) et sens de la formule expliqué","points":4},{"critere":"Opposition religio / magia précise : public / secret, demande / contrainte, cité / intérêt privé","points":4},{"critere":"Rome qui redoute et condamne : Douze Tables, Pline (livre XXX), procès d'Apulée et Apologie","points":4},{"critere":"Rome qui pratique et imagine : tablettes ordinaires, au moins deux sorcières littéraires avec auteur et œuvre","points":5},{"critere":"Développement construit, qui répond au sujet","points":3}],"dureeMin":18,"corrige":"**I. Le mot dit l'étranger.** Le mot ***magus*** vient **du perse, par le grec** : il désignait d'abord **les prêtres des Perses**. La magie est donc, dès son nom, la religion **des autres**, celle qu'on regarde de l'extérieur. De même, pour les Romains, la **Thessalie** est la **patrie des sorcières**, qu'on disait capables de **faire descendre la Lune** du ciel : la magie est rejetée **ailleurs**.\n\n**II. Une frontière nette en apparence.**\n| Religion (*religio*) | Magie (*magia*) |\n| publique, au grand jour | secrète, souvent de nuit |\n| demande aux dieux : *do ut des* | prétend les contraindre par la formule exacte |\n| rites de la cité | intérêt privé, souvent contre autrui |\n\n**III. Rome la redoute et la condamne.** Dès la **loi des Douze Tables** (milieu du Ve siècle av. J.-C.), elle punit celui qui attire par ses chants les récoltes du voisin. **Pline l'Ancien**, au livre **XXX** de l'*Histoire naturelle*, la qualifie de **plus trompeuse des pratiques**. Au IIe siècle, **Apulée** est **accusé de magie** pour avoir épousé une riche veuve, **Pudentilla** ; son discours de défense, l'***Apologie***, est un document unique.\n\n**IV. … et la pratique.** Les **tablettes d'exécration** retrouvées **par centaines** (contre un rival, un voleur, un avocat, un aurige) montrent une **pratique ordinaire**. La littérature en fait un grand sujet : **Canidia** chez **Horace** déterre des os et prépare un philtre ; **Médée** chez **Ovide** rajeunit Éson ; **Érichtho** chez **Lucain** ranime un cadavre pour qu'il prédise l'issue de la guerre civile ; **Pamphile** chez **Apulée** : Lucius, en volant son onguent, est changé en âne.\n\n**Conclusion** : la magie est « la religion des autres » par son **nom** et par la **frontière** que Rome trace ; mais cette frontière sert surtout à **condamner** ce qu'on pratique soi-même en secret."}$exo$::jsonb),
  ('8fc83035-70b5-53ee-82ab-bad804fd1919'::uuid, 1, 'traduction', $exo${"titre":"Les principes de Lucrèce","consigne":"Réponds à chaque question en t'appuyant sur le cours.","enonce":"1. Qui est **Lucrèce** ? Donne ses dates approximatives, le titre de son œuvre (latin et français) et le philosophe grec dont il met la pensée en vers.\n2. Contre quelles **deux terreurs** son poème veut-il délivrer les hommes ?\n3. Explique en une phrase chacun de ces principes :\n   - a) *nullam rem e nihilo gigni divinitus umquam* ;\n   - b) les *primordia*, *semina rerum* et l'*inane* ;\n   - c) le *clinamen* ;\n   - d) l'âme mortelle.\n4. Selon Lucrèce, les dieux existent-ils ? S'occupent-ils des hommes ?","bareme":[{"critere":"Lucrèce présenté : vers 98 – vers 55 av. J.-C., De rerum natura (De la nature des choses), physique d'Épicure","points":4},{"critere":"Les deux terreurs : la peur des dieux et la peur de la mort","points":4},{"critere":"Les quatre principes expliqués justement","points":8},{"critere":"Les dieux existent mais vivent heureux, loin du monde, sans s'occuper des hommes","points":4}],"dureeMin":7,"corrige":"1. **Lucrèce** (vers 98 – vers 55 av. J.-C.) est un poète dont on ne sait presque rien, sinon son grand poème en six livres, le ***De rerum natura***, « **De la nature des choses** ». Il y expose en vers la physique d'**Épicure**.\n\n2. Il veut délivrer les hommes de **la peur des dieux** et de **la peur de la mort**.\n\n3. \n- a) **Rien ne naît de rien** : aucun dieu ne crée à partir du néant.\n- b) Tout est fait d'**atomes et de vide** : les « **semences des choses** » (*primordia*, *semina rerum*) bougent dans le **vide** (*inane*).\n- c) Le ***clinamen*** est la **légère déviation** des atomes : cet écart minime rend possibles leurs **rencontres**… et la **liberté**.\n- d) L'**âme est mortelle** : faite d'atomes, elle **se disperse à la mort**.\n\n4. Lucrèce **ne nie pas l'existence des dieux** : ils vivent **heureux, loin du monde**, et **ne s'occupent pas des hommes**. Il leur retire tout pouvoir sur nous."}$exo$::jsonb),
  ('8fc83035-70b5-53ee-82ab-bad804fd1919'::uuid, 2, 'traduction', $exo${"titre":"Tantum religio potuit suadere malorum","consigne":"Traduis les deux phrases de Lucrèce à l'aide du lexique, puis réponds aux questions.","enonce":"**Lucrèce, *De rerum natura***\n\n> **Phrase A** (livre I) : *Tantum religio potuit suadere malorum !*\n> **Phrase B** : *Nil igitur mors est ad nos.*\n\n*Lexique : tantum… malorum = tant de maux, de crimes (malorum est au génitif pluriel) ; religio, onis (f.) = la religion ; potuit = parfait de possum, « a pu » ; suadere = conseiller ; nil = rien ; igitur = donc ; mors, mortis (f.) = la mort ; ad nos = pour nous.*\n\n1. Traduis les deux phrases.\n2. La phrase A conclut un récit : lequel ? Que s'est-il passé, et dans quel but ?\n3. Quel sens précis le mot *religio* a-t-il dans la phrase A ? Pourquoi est-ce important pour comprendre Lucrèce ?\n4. Dans la phrase B, relève le connecteur logique et dis ce qu'il indique. Explique l'idée : pourquoi la mort n'est-elle « rien pour nous » ?","bareme":[{"critere":"Traductions justes : « Tant la religion a pu conseiller de crimes ! » et « La mort n'est donc rien pour nous »","points":6},{"critere":"Sacrifice d'Iphigénie, immolée par son père pour obtenir des vents favorables","points":4},{"critere":"Religio = crainte superstitieuse, pas la piété sereine : Lucrèce ne nie pas les dieux","points":5},{"critere":"Igitur (donc) : conclusion d'un raisonnement ; là où la mort est, nous ne sommes plus","points":5}],"dureeMin":11,"corrige":"1. **A** : **« Tant la religion a pu conseiller de crimes ! »** **B** : **« La mort n'est donc rien pour nous. »**\n\n2. La phrase A conclut, au livre I, le récit du **sacrifice d'Iphigénie**, **immolée par son père** pour obtenir des **vents favorables**. Lucrèce y voit l'exemple même du crime qu'une croyance peut faire commettre.\n\n3. Ici, *religio* désigne **la crainte superstitieuse**, **pas la piété sereine**. C'est important : Lucrèce **ne nie pas l'existence des dieux** ; il attaque la **peur** des dieux, qui pousse les hommes au crime. Son poème veut délivrer de cette terreur.\n\n4. Le connecteur est ***igitur***, « **donc** » : il indique une **conclusion**, la phrase est l'aboutissement d'un raisonnement. L'idée : l'âme, faite d'atomes, **se disperse à la mort** ; **là où est la mort, nous ne sommes plus** ; il n'y a donc personne pour souffrir de la mort. Il est inutile de la craindre."}$exo$::jsonb),
  ('8fc83035-70b5-53ee-82ab-bad804fd1919'::uuid, 3, 'traduction', $exo${"titre":"Un augure qui doute des devins","consigne":"Lis le document, réponds aux questions 1 à 3, puis rédige la réponse argumentée de la question 4.","enonce":"**Cicéron, *De divinatione*, livre II** — Cicéron rapporte un mot de Caton l'Ancien :\n\n> *[Cato] mirari se aiebat quod non rideret haruspex haruspicem cum vidisset.*\n> « Caton disait qu'il s'étonnait qu'un haruspice ne rît pas quand il voyait un autre haruspice. »\n\n*Lexique : mirari = s'étonner ; se = lui-même (Caton) ; aiebat = il disait.*\n\n**Rappel** : Cicéron (106-43 av. J.-C.) est lui-même **augure**. Dans le *De divinatione* (44 av. J.-C.), il fait parler son frère Quintus pour la divination au livre I, puis la réfute lui-même au livre II.\n\n1. *Mirari se aiebat* : quelle construction reconnais-tu après *aiebat* ? Qu'indique-t-elle : Cicéron affirme-t-il ou rapporte-t-il ?\n2. Que veut dire Caton ? Quelle critique de la divination cette plaisanterie contient-elle ?\n3. Pourquoi est-il frappant qu'un augure écrive ce livre ? Comment Cicéron concilie-t-il sa fonction et son doute ? Emploie les mots *religio* et *superstitio*.\n4. **Réponse argumentée** (15 à 20 lignes) : Lucrèce et Cicéron combattent tous deux la peur superstitieuse. Montre ce qui les rapproche, puis ce qui sépare leurs méthodes et leurs positions.","bareme":[{"critere":"Proposition infinitive (se mirari) repérée : Cicéron rapporte le mot de Caton, il ne l'affirme pas lui-même","points":3},{"critere":"Sens de la plaisanterie : les haruspices savent qu'ils trompent, leur art n'est pas sérieux","points":3},{"critere":"Cicéron augure et sceptique : Nouvelle Académie ; religio (culte utile à la cité) distinguée de superstitio (peur excessive)","points":5},{"critere":"Rapprochement : lutter contre la crainte des dieux, au Ier siècle av. J.-C.","points":3},{"critere":"Différences : poète épicurien qui affirme (atomes, dieux indifférents) / avocat qui pèse le pour et le contre, suspend son jugement, garde la religio","points":6}],"dureeMin":18,"corrige":"1. Après *aiebat* (il disait), on trouve une **proposition infinitive** : *se mirari*, « qu'il s'étonnait ». Elle indique que Cicéron **rapporte** les paroles de Caton : ce n'est pas lui qui **affirme**, c'est Caton qu'il cite.\n\n2. Caton veut dire que deux haruspices qui se croisent devraient **éclater de rire** : chacun sait que l'autre, comme lui, **ne lit rien de vrai** dans les entrailles. La plaisanterie suggère que la divination est une **comédie** dont ses propres praticiens ne sont pas dupes.\n\n3. C'est frappant parce que Cicéron est lui-même **augure**, membre du collège qui **prend les auspices** : il critique la divination de l'intérieur. Il concilie les deux grâce à sa position de **Nouvelle Académie** : chercher le **plus probable** et **suspendre son jugement** quand on ne sait pas. Il distingue la ***religio***, **culte des ancêtres utile à la cité**, qu'il garde, de la ***superstitio***, **peur excessive qui asservit l'esprit**, qu'il combat.\n\n4. **Réponse attendue.**\n- **Ce qui les rapproche** : au **Ier siècle av. J.-C.**, tous deux s'attaquent à la **peur superstitieuse** ; tous deux refusent que la crainte des dieux gouverne l'esprit (Lucrèce dénonce la *religio* qui a conduit au sacrifice d'Iphigénie ; Cicéron la *superstitio*).\n- **Ce qui les sépare** :\n  - la **forme** : Lucrèce est un **poète**, qui expose en vers ; Cicéron un **avocat** qui fait dialoguer le pour (Quintus, livre I) et le contre (livre II) ;\n  - la **méthode** : Lucrèce **affirme** une doctrine, la physique d'**Épicure** (atomes, vide, rien ne naît de rien) ; Cicéron **doute**, pèse et **suspend son jugement** (Nouvelle Académie) ;\n  - la **position sur les dieux** : pour Lucrèce, les dieux vivent loin du monde et **ne s'occupent pas des hommes** ; Cicéron, lui, **garde la *religio*** utile à la cité et reste augure.\n\nConclusion : deux chemins, l'un **dogmatique** et poétique, l'autre **critique** et oratoire, vers le même but : délivrer l'esprit de la crainte."}$exo$::jsonb),
  ('56f70b98-1d1e-56bd-aae1-e9a823e43a0e'::uuid, 1, 'traduction', $exo${"titre":"La religion de la cité et les cultes à mystères","consigne":"Réponds à chaque question en phrases complètes.","enonce":"1. Pourquoi dit-on que la religion romaine traditionnelle n'est « ni un dogme ni une croyance intime » ? Quel est son but ?\n2. Cite les dieux de la triade du Capitole, puis les dieux qui protègent la maison.\n3. Qu'est-ce que la *pietas* ?\n4. Complète pour chaque culte à mystères son origine et une chose qu'il promet ou qui le caractérise : Cybèle · Isis · Mithra · Bacchus.\n5. Qu'offrent les cultes à mystères que la religion civique ne promet pas ?","bareme":[{"critere":"Religion = ensemble de rites qui garantissent la pax deorum","points":4},{"critere":"Triade (Jupiter, Junon, Minerve) ; Lares et Pénates","points":4},{"critere":"Pietas : devoir envers les dieux, la patrie et la famille","points":3},{"critere":"Quatre cultes justes : Phrygie, Égypte, Perse, Grèce, avec un trait pour chacun","points":6},{"critere":"Initiation personnelle et salut","points":3}],"dureeMin":7,"corrige":"1. La religion romaine traditionnelle est **un ensemble de rites**, non une croyance intime ni un dogme : ce qui compte, c'est d'accomplir les rites correctement. Son but est de garantir la ***pax deorum***, la paix avec les dieux.\n\n2. La **triade du Capitole** : **Jupiter, Junon, Minerve**. À la maison : les **Lares** et les **Pénates**. (On peut aussi citer Vesta et ses vestales, gardiennes du feu.)\n\n3. La ***pietas*** est **le devoir envers les dieux, la patrie et la famille**.\n\n4. \n- **Cybèle**, la *Magna Mater* : **Phrygie**, introduite à Rome en **204 av. J.-C.** ; renaissance, fécondité.\n- **Isis** : **Égypte** ; protection, salut après la mort.\n- **Mithra** : **Perse** ; culte masculin des soldats, dans des grottes ; le dieu tue un taureau.\n- **Bacchus** : **Grèce** ; l'extase ; le Sénat réprime les Bacchanales en **186 av. J.-C.**\n\n5. Venus d'Orient, ils offrent une **initiation personnelle** et un **salut**, ce que la religion civique ne promet pas."}$exo$::jsonb),
  ('56f70b98-1d1e-56bd-aae1-e9a823e43a0e'::uuid, 2, 'traduction', $exo${"titre":"Pline le Jeune face aux chrétiens","consigne":"Lis le document, puis réponds aux questions en justifiant.","enonce":"**Document — Pline le Jeune, *Lettres*, X, 96 (vers 112)**. Gouverneur de Bithynie, Pline écrit à l'empereur Trajan au sujet des chrétiens de sa province. Il rapporte qu'ils se réunissent avant l'aube et chantent un hymne *Christo quasi deo*.\n\n*Lexique : Christus, i (m.) = le Christ ; quasi = comme ; deus, i (m.) = le dieu ; Christo et deo sont au datif.*\n\n1. Traduis *Christo quasi deo* et explique ce que Pline a appris des pratiques des chrétiens.\n2. Rome tolère tous les dieux : pourquoi les chrétiens posent-ils pourtant un problème ?\n3. Que répond Trajan ? Explique la différence entre « rechercher » les chrétiens et punir ceux qui sont dénoncés.\n4. Replace dans l'ordre chronologique, avec leur date, ces quatre événements : l'édit de Thessalonique de Théodose ; Néron accuse les chrétiens après l'incendie de Rome ; la grande persécution de Dioclétien ; Constantin et Licinius accordent la liberté de culte.","bareme":[{"critere":"« Au Christ comme à un dieu » ; réunions avant l'aube et hymne chanté","points":4},{"critere":"Problème : Dieu unique et exclusif, refus d'honorer les dieux de la cité et l'empereur","points":5},{"critere":"Réponse de Trajan : ne pas les rechercher, mais punir ceux qui, dénoncés, refusent de sacrifier","points":5},{"critere":"Chronologie juste : 64, 303, 312-313, 380","points":6}],"dureeMin":11,"corrige":"1. *Christo quasi deo* : **« au Christ comme à un dieu »**. Pline a appris que les chrétiens **se réunissent avant l'aube** et **chantent un hymne au Christ comme à un dieu**.\n\n2. Rome tolère tous les dieux, **pourvu qu'on honore aussi ceux de la cité et l'empereur**. Or les chrétiens **refusent** : leur Dieu est **unique et exclusif**. Ils ne peuvent pas ajouter les dieux de Rome au leur.\n\n3. Trajan répond qu'**il ne faut pas les rechercher**, mais qu'il faut **punir ceux qui, dénoncés, refusent de sacrifier**. L'État ne part donc pas à la chasse aux chrétiens ; il ne les poursuit que s'ils sont **dénoncés** et s'ils **refusent** le sacrifice.\n\n4. \n- **64 ap. J.-C.** : après l'incendie de Rome, **Néron** accuse les chrétiens.\n- **303** : grande persécution de **Dioclétien**.\n- **312-313** : **Constantin**, vainqueur au pont Milvius, accorde avec **Licinius** la liberté de culte (dite « édit de Milan »).\n- **380** : l'**édit de Thessalonique** de Théodose fait du christianisme la religion de l'Empire."}$exo$::jsonb),
  ('56f70b98-1d1e-56bd-aae1-e9a823e43a0e'::uuid, 3, 'traduction', $exo${"titre":"Le christianisme contre la culture antique ?","consigne":"Rédige un développement argumenté d'une vingtaine de lignes, en deux parties.","enonce":"**Sujet** : « Le christianisme ne naît pas contre la culture antique. » Discute cette affirmation.\n\n**Données** :\n- Tacite (*Annales* XV, 44) rapporte que le Christ avait été supplicié sous Tibère par le procurateur Ponce Pilate.\n- Augustin (354-430) a été professeur de rhétorique avant de devenir évêque.\n- Tertullien, vers 200, écrit l'*Apologétique* ; Jérôme, à la fin du IVe siècle, la *Vulgate* ; Augustin, *La Cité de Dieu* après le sac de Rome par Alaric en 410.\n- *Paganus*, le « paysan », finit par désigner le païen ; *fides*, la bonne foi du contrat, devient la foi chrétienne.\n- En 380, l'édit de Thessalonique fait du christianisme la religion de l'Empire ; les cultes païens sont interdits en 391-392.\n\nMontre d'abord ce qui oppose le christianisme à la religion de Rome, puis comment il s'appuie sur la culture antique. Utilise au moins **trois** des données.","bareme":[{"critere":"Opposition : Dieu unique et exclusif contre religion de la cité ; persécutions ; puis interdiction des cultes païens","points":5},{"critere":"Appui sur la culture antique : il s'écrit en grec puis en latin, avec la rhétorique et la philosophie (Augustin)","points":5},{"critere":"Au moins trois œuvres ou données exploitées avec justesse (Tertullien, Vulgate, Cité de Dieu et 410…)","points":5},{"critere":"Les mots qui changent de sens (paganus, fides) interprétés","points":2},{"critere":"Développement en deux parties, avec conclusion nuancée","points":3}],"dureeMin":18,"corrige":"**I. Une religion qui s'oppose à celle de Rome.**\n- La religion de la cité est un ensemble de **rites** pour la *pax deorum* ; elle tolère tous les dieux pourvu qu'on honore ceux de la cité et l'empereur. Le christianisme, lui, a un Dieu **unique et exclusif** : les chrétiens refusent de sacrifier.\n- D'où les **persécutions** : Néron en **64**, la règle de Trajan (punir ceux qui, dénoncés, refusent de sacrifier), Dioclétien en **303**. Tacite rappelle que le Christ a été **supplicié sous Tibère** par Ponce Pilate.\n- Le retournement est complet : en **380**, l'édit de Thessalonique en fait la religion de l'Empire, et les **cultes païens sont interdits en 391-392**.\n\n**II. Mais une religion qui s'écrit avec la culture antique.**\n- Le christianisme s'écrit **en grec, puis en latin**, avec les outils de la **rhétorique** et de la **philosophie**.\n- **Augustin** a été **professeur de rhétorique** avant de devenir évêque ; dans *La Cité de Dieu*, écrite après le **sac de Rome par Alaric en 410**, il distingue la cité terrestre et la cité de Dieu.\n- **Tertullien** (*Apologétique*, vers 200) défend les chrétiens **devant les magistrats**, avec les armes de l'avocat.\n- **Jérôme** traduit la Bible **en latin** (la *Vulgate*), lue pendant plus de mille ans.\n- La langue elle-même passe d'un monde à l'autre : ***fides***, la bonne foi du contrat romain, devient la **foi** ; ***paganus***, le paysan, désigne le **païen**, parce que les campagnes restèrent longtemps fidèles aux anciens dieux.\n\n**Conclusion** : le christianisme s'oppose à la **religion** de Rome, mais il ne naît pas contre sa **culture** : il en reprend la langue, la rhétorique et la philosophie."}$exo$::jsonb),
  ('7b9550ee-1d89-52be-9a3c-6fa0cd4d45e4'::uuid, 1, 'traduction', $exo${"titre":"Stoïciens et épicuriens","consigne":"Réponds à chaque question à partir du cours.","enonce":"1. Pour chacune des deux écoles, **stoïcisme** et **épicurisme**, donne : le fondateur et le lieu ; en quoi consiste le bonheur ; l'attitude face au destin ; l'attitude face à la cité ; un auteur latin qui la représente.\n2. Que signifie le mot *ataraxie* ?\n3. Sur quel point les deux écoles s'accordent-elles ?","bareme":[{"critere":"Fondateurs et lieux : Zénon de Citium et Épicure, à Athènes","points":4},{"critere":"Bonheur, destin et cité justes pour chaque école","points":9},{"critere":"Auteurs latins : Sénèque ; Lucrèce (Horace s'en inspire) ; ataraxie = absence de trouble","points":4},{"critere":"Point commun : le sage ne dépend ni de la fortune ni de l'opinion des autres","points":3}],"dureeMin":7,"corrige":"1. \n| | Stoïcisme | Épicurisme |\n| Fondateur | **Zénon de Citium**, à Athènes (vers 300 av. J.-C.) | **Épicure**, à Athènes (IVe-IIIe siècle av. J.-C.) |\n| Le bonheur | La **vertu**, vivre selon la **raison** et la **nature** | Le **plaisir** compris comme **absence de trouble** |\n| Face au destin | L'**accepter** : il est rationnel | Il **n'existe pas** : les atomes et le hasard |\n| Face à la cité | **S'engager, servir** | **Vivre caché**, entre amis |\n| Auteur latin | **Sénèque** | **Lucrèce** (Horace s'en inspire souvent) |\n\n2. L'***ataraxie*** est l'**absence de trouble** : c'est ainsi que les épicuriens comprennent le plaisir.\n\n3. Stoïciens et épicuriens se disputent sur presque tout, mais s'accordent sur un point : **le sage ne dépend ni de la fortune ni de l'opinion des autres**."}$exo$::jsonb),
  ('7b9550ee-1d89-52be-9a3c-6fa0cd4d45e4'::uuid, 2, 'traduction', $exo${"titre":"Traduire carpe diem","consigne":"Traduis le vers d'Horace à l'aide du lexique, puis réponds aux questions.","enonce":"**Horace, *Odes*, I, 11**. Le poète s'adresse à une jeune femme, Leuconoé :\n\n> *Carpe diem, quam minimum credula postero.*\n\n*Lexique : carpo, is, ere = cueillir ; dies, ei (m.) = le jour ; quam minimum = le moins possible ; credulus, a, um + datif = qui se fie à ; posterus, a, um = suivant (ici : le jour suivant, le lendemain).*\n\n1. Traduis le vers en bon français.\n2. Analyse : *carpe* (mode, temps, verbe) ; *diem* (cas) ; *credula* (avec quoi s'accorde-t-il ?) ; *postero* (cas et construction).\n3. Que signifie exactement le verbe *carpere* ? Montre qu'on trahit Horace quand on comprend *carpe diem* comme « profite sans limite ».\n4. Cite une autre formule d'Horace et traduis-la. Qui était Horace (dates, origine, protecteur) ?","bareme":[{"critere":"Traduction juste : « Cueille le jour, et fie-toi le moins possible au lendemain »","points":5},{"critere":"Analyse juste : impératif présent de carpo, diem accusatif de dies, credula féminin (Leuconoé), postero datif","points":6},{"critere":"Carpere = cueillir un fruit mûr : goûter le présent, non s'étourdir","points":5},{"critere":"Autre formule traduite (aurea mediocritas ou non omnis moriar) et Horace présenté (65-8 av. J.-C., fils d'affranchi, ami de Mécène)","points":4}],"dureeMin":10,"corrige":"1. **« Cueille le jour, et fie-toi le moins possible au lendemain. »** (ou : « Cueille le jour, sans te fier le moins du monde au lendemain. »)\n\n2. \n- *Carpe* : **impératif présent** de *carpo*, « cueillir » : « cueille ».\n- *Diem* : **accusatif** de *dies*, le jour, complément d'objet de *carpe*.\n- *Credula* : s'accorde avec le **« tu » féminin** : Horace s'adresse à **Leuconoé**.\n- *Postero* : **datif**, complément de *credula* : « crédule envers le lendemain ».\n\n3. *Carpere*, c'est **cueillir un fruit mûr** : on le choisit au bon moment et on le **goûte**. Il ne s'agit **pas de s'étourdir** ni de profiter sans limite, mais de **goûter le présent**. Traduire par « profite sans limite » oublie la mesure : Horace est aussi le poète du **juste milieu**.\n\n4. Au choix : ***aurea mediocritas*** (*Odes* II, 10), le « **juste milieu d'or** », entre la pauvreté et le luxe ; ***non omnis moriar*** (*Odes* III, 30), « **je ne mourrai pas tout entier** », grâce à l'œuvre. Horace (**65-8 av. J.-C.**) est **fils d'affranchi**, devenu **ami de Mécène**."}$exo$::jsonb),
  ('7b9550ee-1d89-52be-9a3c-6fa0cd4d45e4'::uuid, 3, 'traduction', $exo${"titre":"Que faire du temps qui nous est donné ?","consigne":"Traduis la phrase de Sénèque, puis rédige un développement argumenté d'une vingtaine de lignes.","enonce":"**Document 1 — Sénèque, *Lettres à Lucilius*, 1** :\n\n> *Vindica te tibi.* « Revendique-toi pour toi-même. »\n> *Omnia, Lucili, aliena sunt, tempus tantum nostrum est.*\n\n*Lexique : omnia = toutes choses, tout ; Lucili = vocatif de Lucilius ; alienus, a, um = qui appartient à autrui, étranger ; tempus, oris (n.) = le temps ; tantum = seulement ; noster, tra, trum = à nous.*\n\n**Document 2 — Sénèque, *De la brièveté de la vie*** : nous n'avons pas peu de temps, nous en perdons beaucoup.\n\n**Document 3 — Horace, *Odes*, I, 11** : *Carpe diem*, « Cueille le jour ».\n\n1. Traduis la seconde phrase du document 1.\n2. Que veut dire *Vindica te tibi* ? Quel reproche Sénèque adresse-t-il aux hommes dans le document 2 ?\n3. **Développement argumenté** : « Le stoïcien et l'épicurien donnent-ils la même leçon sur le temps et sur la mort ? » Confronte Sénèque et Horace, puis élargis à la mort (Lucrèce, Sénèque, Cicéron). Termine en montrant comment Sénèque a vécu ses principes.","bareme":[{"critere":"Traduction : « Tout, Lucilius, nous est étranger : seul le temps est à nous »","points":4},{"critere":"Vindica te tibi : reprends possession de ton temps ; nous perdons beaucoup de temps","points":3},{"critere":"Convergence : le temps présent est notre seul bien, il faut le saisir ; différences d'écoles (vertu / absence de trouble)","points":6},{"critere":"La mort : nil igitur mors est ad nos, s'y préparer chaque jour, vieillesse selon Cicéron","points":4},{"critere":"Mort de Sénèque : ordre de Néron en 65, conjuration de Pison, veines ouvertes en consolant ses proches","points":3}],"dureeMin":18,"corrige":"1. ***Omnia, Lucili, aliena sunt, tempus tantum nostrum est*** : **« Tout, Lucilius, nous est étranger : seul le temps est à nous. »**\n\n2. *Vindica te tibi*, « revendique-toi pour toi-même », c'est-à-dire **reprends possession de ton temps**. Dans *De la brièveté de la vie*, Sénèque reproche aux hommes non pas d'avoir peu de temps, mais **d'en perdre beaucoup**.\n\n3. **Développement attendu.**\n- **Une leçon commune** : pour Sénèque, le **temps** est le seul bien qui nous appartienne vraiment, et il ne faut pas le laisser filer. Pour Horace, il faut **cueillir le jour** sans se fier au lendemain. Les deux invitent à **vivre le présent** plutôt qu'à le remettre à plus tard. Ils s'accordent aussi sur un point : le sage **ne dépend ni de la fortune ni de l'opinion des autres**.\n- **Deux chemins différents** : le **stoïcien** cherche le bonheur dans la **vertu**, vivre selon la raison, et **accepte** le destin ; Sénèque **dirige la conscience** d'un ami, avec des impératifs exigeants. **Horace**, qui s'inspire souvent de l'**épicurisme**, propose une sagesse **souriante** : goûter le présent comme un fruit mûr, dans le **juste milieu** (*aurea mediocritas*), l'idéal épicurien étant l'**absence de trouble**.\n- **Face à la mort** : **Lucrèce** : *nil igitur mors est ad nos*, « la mort n'est rien pour nous » ; **Sénèque** : **s'y préparer chaque jour**, c'est apprendre à vivre **libre** ; **Cicéron** (*De senectute*) : la vieillesse n'est pas un malheur pour qui a bien vécu. Horace, lui, espère survivre par l'œuvre : *non omnis moriar*.\n- **Sénèque a vécu ses principes** : accusé d'avoir trempé dans la **conjuration de Pison**, il reçoit de **Néron** l'ordre de mourir en **65** et **s'ouvre les veines en consolant ses proches**.\n\nConclusion : la **même leçon** sur le prix du temps présent, mais par deux voies, la **vertu** exigeante d'un côté, le **plaisir mesuré** de l'autre."}$exo$::jsonb),
  ('260e98c0-9992-5d62-9829-ea2e987d430b'::uuid, 1, 'traduction', $exo${"titre":"L'Histoire naturelle de Pline","consigne":"Réponds à chaque question en t'appuyant sur le cours.","enonce":"1. Présente **Pline l'Ancien** : dates, fonctions, titre de son œuvre, nombre de livres, dédicataire.\n2. Que dit Pline avoir rassemblé, et à partir de quoi ?\n3. Associe chaque groupe de livres à son contenu : livre II · livres III-VI · livre VII · livres VIII-XI · livres XXXIII-XXXVII.\n4. Donne le sens et un héritier français de : *natura* · *mundus* · *scientia*. De quel verbe vient *natura* ?","bareme":[{"critere":"Pline présenté : 23-79, officier et haut fonctionnaire, Histoire naturelle en 37 livres dédiée à Titus","points":5},{"critere":"Vingt mille faits tirés de deux mille volumes","points":3},{"critere":"Les cinq associations justes","points":7},{"critere":"Sens et héritiers justes ; natura vient de nasci, naître","points":5}],"dureeMin":7,"corrige":"1. **Pline l'Ancien** (**23-79 ap. J.-C.**), **officier et haut fonctionnaire**, consacre ses nuits à lire et à prendre des notes. Il écrit l'***Histoire naturelle*** en **37 livres**, dédiés au futur empereur **Titus**.\n\n2. Il dit avoir rassemblé **vingt mille faits** tirés de **deux mille volumes**.\n\n3. \n- **Livre II** : le monde, les astres, les phénomènes du ciel.\n- **Livres III-VI** : la géographie de l'univers connu.\n- **Livre VII** : l'homme.\n- **Livres VIII-XI** : les animaux.\n- **Livres XXXIII-XXXVII** : métaux, peinture, sculpture, pierres précieuses.\n\n4. \n- ***natura*** (de ***nasci***, **naître**) : ce qui fait naître et croître → **nature, naturel**.\n- ***mundus*** : le monde ordonné, mais aussi la parure → **monde, mondain**.\n- ***scientia*** : la connaissance → **science**."}$exo$::jsonb),
  ('260e98c0-9992-5d62-9829-ea2e987d430b'::uuid, 2, 'traduction', $exo${"titre":"Le Vésuve, 79","consigne":"Remets le récit dans l'ordre, puis réponds aux questions en justifiant.","enonce":"**Le récit de Pline le Jeune, en désordre**\n\n- A. À Stabies, sous la pluie de cendres et de pierres, Pline l'Ancien meurt.\n- B. Un nuage immense s'élève au-dessus du Vésuve.\n- C. Pline l'Ancien fait armer des navires.\n- D. Pompéi et Herculanum sont ensevelies.\n\n1. Remets les étapes dans l'ordre du cours.\n2. Quelle fonction Pline l'Ancien occupait-il en 79, et où ? Quelles sont les **deux** raisons pour lesquelles il fait armer des navires ?\n3. À quoi Pline le Jeune compare-t-il le nuage ? Décris la forme évoquée.\n4. Qui raconte cet événement, à qui, et dans quels textes ?\n5. Qu'appelle-t-on aujourd'hui une **éruption plinienne** ? Pourquoi ce nom ?","bareme":[{"critere":"Ordre du cours : B, C, A, D","points":3},{"critere":"Commandant de la flotte de Misène, baie de Naples ; secourir les habitants et observer le phénomène","points":5},{"critere":"Pin parasol : un tronc très haut, puis des branches","points":4},{"critere":"Pline le Jeune, son neveu, dans deux lettres à Tacite (VI, 16 et VI, 20)","points":4},{"critere":"Éruption à colonne verticale géante, nommée d'après Pline","points":4}],"dureeMin":11,"corrige":"1. Ordre du cours : **B** (le nuage s'élève) → **C** (Pline fait armer des navires) → **A** (il meurt à Stabies) → **D** (Pompéi et Herculanum sont ensevelies).\n\n2. En 79, Pline l'Ancien **commande la flotte de Misène**, dans la **baie de Naples**. Il fait armer des navires pour **secourir les habitants** et pour **observer le phénomène**. À Stabies, il meurt, **sans doute asphyxié**.\n\n3. Pline le Jeune compare le nuage à un **pin parasol** : **un tronc très haut**, puis **des branches** qui s'étalent.\n\n4. C'est son neveu, **Pline le Jeune**, qui raconte l'événement dans **deux lettres à l'historien Tacite** (*Lettres* **VI, 16** et **VI, 20**).\n\n5. Les volcanologues appellent **éruption plinienne** une éruption qui projette une **colonne verticale géante**. Le **nom de Pline** est resté à ce type d'éruption, celle que décrit le récit de son neveu et dont son oncle est mort."}$exo$::jsonb),
  ('260e98c0-9992-5d62-9829-ea2e987d430b'::uuid, 3, 'traduction', $exo${"titre":"Recenser ou comprendre la nature ?","consigne":"Rédige un développement argumenté d'une vingtaine de lignes, en deux ou trois parties.","enonce":"**Données** :\n- **Pline l'Ancien**, *Histoire naturelle* : 37 livres ; vingt mille faits tirés de deux mille volumes ; il décrit les peuples fabuleux des confins de la terre avec le même sérieux que la culture de la vigne. Il meurt en 79 en voulant observer l'éruption du Vésuve et secourir les habitants.\n- **Sénèque**, *Questions naturelles* : il cherche les causes des séismes, des vents, des comètes, des crues du Nil ; il évoque le tremblement de terre de Campanie de 62 ou 63. Sa conviction : l'âme qui connaît les causes cesse de trembler.\n- **La médecine** : Galien (IIe siècle), médecin de Pergame installé à Rome, écrit en grec ; Celse (Ier siècle) rédige en latin un *De medicina*.\n\n**Sujet** : « Les Romains ont voulu comprendre le monde en le recensant. » Montre ce que cette formule dit de Pline, puis en quoi Sénèque cherche autre chose. Conclus sur ce que Rome doit aux Grecs et sur l'héritage de ce savoir.","bareme":[{"critere":"Pline : un savoir qui accumule plus qu'il ne vérifie (compilation, merveilleux mêlé à l'observation)","points":5},{"critere":"Pline aussi observateur : sa mort en voulant observer l'éruption, l'éruption plinienne","points":3},{"critere":"Sénèque cherche les causes ; connaître les causes délivre de la peur","points":5},{"critere":"Dette envers les Grecs (Galien écrit en grec, quatre humeurs d'Hippocrate) et héritage (mots, éruption plinienne)","points":4},{"critere":"Développement construit et nuancé","points":3}],"dureeMin":18,"corrige":"**I. Pline : recenser.** L'*Histoire naturelle* embrasse **tout** : astres, géographie, hommes, animaux, plantes, remèdes, métaux, arts, en **37 livres**, avec **vingt mille faits** tirés de **deux mille volumes**. Pline **mêle observation, compilation et récits merveilleux** : il décrit les peuples fabuleux avec le même sérieux que la culture de la vigne. C'est un savoir qui **accumule plus qu'il ne vérifie** : la formule du sujet lui convient parfaitement.\n**Nuance** : Pline est aussi un **observateur** ; en 79, il meurt en voulant **observer l'éruption** et **secourir les habitants**, et son nom est resté à l'**éruption plinienne**.\n\n**II. Sénèque : comprendre les causes.** Dans les *Questions naturelles*, Sénèque ne se contente pas de recenser : il **cherche les causes** des séismes, des vents, des comètes, des crues du Nil ; il part d'un fait récent, le **séisme de Campanie de 62 ou 63**. Son but est moral : **comprendre la nature délivre de la peur**, car **l'âme qui connaît les causes cesse de trembler**.\n\n**III. Une dette et un héritage.** Les Romains doivent beaucoup aux **Grecs** : en médecine, **Galien**, installé à Rome, **écrit en grec** et reprend la théorie des **quatre humeurs d'Hippocrate** ; en latin, **Celse** rédige un *De medicina* d'une grande clarté. L'héritage reste vivant : l'**éruption plinienne**, et les mots **nature** (*natura*, de *nasci*), **monde** (*mundus*), **science** (*scientia*).\n\n**Conclusion** : la formule vaut surtout pour **Pline** ; Sénèque montre qu'un Romain pouvait aussi chercher à **comprendre** pour se **libérer de la peur**."}$exo$::jsonb),
  ('985d9f4c-20ce-540e-a10e-21efdcd3ee47'::uuid, 1, 'traduction', $exo${"titre":"Les trois exigences de Vitruve","consigne":"Réponds à chaque question en phrases complètes.","enonce":"1. Qui est **Vitruve** ? À qui dédie-t-il son œuvre ? Comment s'intitule-t-elle, combien de livres compte-t-elle et qu'a-t-elle d'unique ?\n2. Donne le sens des trois exigences de l'architecture selon Vitruve : *firmitas*, *utilitas*, *venustas*. D'où vient le mot *venustas* ?\n3. Un architecte construit une école. Donne pour chacune des trois exigences un exemple concret de ce qu'il doit respecter.\n4. Quel artiste de la Renaissance s'est inspiré de Vitruve, et pour quel dessin ? De quoi traite le livre X du traité ?","bareme":[{"critere":"Vitruve présenté : De architectura, dix livres, dédié à Auguste, seul traité d'architecture antique conservé","points":4},{"critere":"Firmitas (solidité), utilitas (utilité, commodité), venustas (beauté, de Venus)","points":6},{"critere":"Trois exemples concrets adaptés à l'école","points":6},{"critere":"Léonard de Vinci, l'Homme de Vitruve (corps dans un cercle et un carré) ; livre X : les machines","points":4}],"dureeMin":7,"corrige":"1. **Vitruve** est l'architecte qui dédie à **Auguste** son ***De architectura*** en **dix livres**, **le seul traité d'architecture antique conservé**.\n\n2. \n- ***firmitas*** : **la solidité** ;\n- ***utilitas*** : **l'utilité, la commodité** ;\n- ***venustas*** : **la beauté** ; le mot vient de ***Venus***.\n\n3. Exemples attendus (toute réponse cohérente est acceptée) :\n- *firmitas* : des **fondations** qui descendent **jusqu'au sol dur**, des murs solides ;\n- *utilitas* : un bâtiment **adapté à son usage** : des salles de classe assez grandes et éclairées, une cour, des couloirs larges ;\n- *venustas* : des **proportions harmonieuses**, une façade agréable à regarder.\n\n4. Vitruve décrit les proportions du corps humain, **inscrit dans un cercle et un carré** ; quinze siècles plus tard, **Léonard de Vinci** en tire son dessin de l'***Homme de Vitruve***. Le **livre X** traite des **machines** : grues, pompes, roues hydrauliques, machines de guerre."}$exo$::jsonb),
  ('985d9f4c-20ce-540e-a10e-21efdcd3ee47'::uuid, 2, 'traduction', $exo${"titre":"Bâtir à la romaine","consigne":"Lis la situation, puis réponds aux questions en t'appuyant sur le cours.","enonce":"**Situation.** Nour visite le pont du Gard avec sa classe. Le guide annonce : « Ce pont ne porte ni route ni chemin, et l'eau qu'il transportait ne passait par aucune pompe. »\n\n1. Qu'est-ce que le pont du Gard portait ? Quand a-t-il été bâti ? Comment l'eau pouvait-elle arriver sans pompe ?\n2. Montre que ce monument répond aux trois exigences de Vitruve (*firmitas*, *utilitas*, *venustas*).\n3. Qui était Frontin, et qu'a-t-il écrit ?\n4. Explique ce qu'est le **béton romain** (*opus caementicium*), sa composition et sa qualité remarquable. Quel monument en montre la prouesse ?\n5. De quels mots anciens viennent « artisan », « technique » et « machine » ? Que nous apprend le fait que *ars* désigne à la fois l'artisan et l'artiste ?","bareme":[{"critere":"Pont du Gard : aqueduc de Nîmes au-dessus du Gardon, Ier siècle, eau conduite par la seule pente","points":4},{"critere":"Les trois exigences appliquées de façon pertinente","points":5},{"critere":"Frontin, curator aquarum à la fin du Ier siècle, traité sur l'alimentation en eau de Rome","points":3},{"critere":"Béton : chaux, eau, cailloux, cendre volcanique, durcit sous l'eau ; coupole du Panthéon","points":4},{"critere":"Étymologies justes (ars, technè, machina) ; les Anciens ne séparaient pas savoir-faire et art","points":4}],"dureeMin":12,"corrige":"1. Le pont du Gard porte **l'aqueduc de Nîmes** au-dessus du **Gardon** ; il date du **Ier siècle**. L'eau vient de loin **par la seule pente** : c'est la gravité qui la fait couler, sans pompe.\n\n2. \n- ***firmitas*** : il est **encore debout** après près de deux mille ans : c'est la preuve de sa **solidité** ;\n- ***utilitas*** : il **sert** à conduire l'eau jusqu'à Nîmes en franchissant la rivière ;\n- ***venustas*** : ses **arches** superposées ont des **proportions harmonieuses**, il est beau à voir.\n\n3. **Frontin**, ***curator aquarum*** (responsable des eaux de Rome) **à la fin du Ier siècle**, a écrit **un traité sur l'alimentation en eau** de Rome.\n\n4. Le **béton romain** (*opus caementicium*) est fait de **chaux, eau, cailloux et cendre volcanique** ; il a la qualité remarquable de **durcir même sous l'eau**. La **coupole du Panthéon**, reconstruit sous Hadrien, en montre la prouesse : **plus de 43 mètres** de diamètre, percée d'un **oculus**, **jamais dépassée en béton non armé**.\n\n5. « Artisan » vient du latin ***ars*** ; « technique » du grec ***technè*** ; « machine » de ***machina***, **emprunté au grec**. Que *ars* (comme *technè*) désigne à la fois le **savoir-faire de l'artisan** et **l'œuvre de l'artiste** montre que **les Anciens ne séparaient pas les deux**."}$exo$::jsonb),
  ('985d9f4c-20ce-540e-a10e-21efdcd3ee47'::uuid, 3, 'traduction', $exo${"titre":"Dédale, Pygmalion : l'inventeur et son œuvre","consigne":"Traduis les deux citations d'Ovide à l'aide du lexique, puis rédige la réponse argumentée de la question 3.","enonce":"**Ovide, *Métamorphoses***\n\n> **A** (livre VIII) — Dédale à Icare : *medio ut limite curras.*\n> **B** (livre X) — sur la statue de Pygmalion : *ars adeo latet arte sua.*\n\n*Lexique : medius, a, um = qui est au milieu ; limes, itis (m.) = le chemin, la voie ; ut curras = « que tu coures » (subjonctif) ; ars, artis (f.) = l'art ; adeo = tellement, tant ; latet = se cache ; arte sua = par son propre art (ablatif).*\n\n1. Traduis les deux citations. Dans quelle situation chacune est-elle prononcée ou écrite ?\n2. Résume les trois mythes d'artistes du cours (Dédale et Icare, Pygmalion, Arachné) en indiquant le livre des *Métamorphoses*.\n3. **Réponse argumentée** (15 à 20 lignes) : « Dans les mythes d'Ovide, est-ce la technique qui est dangereuse, ou celui qui s'en sert ? » Appuie-toi sur les trois mythes et montre ce qu'ils disent encore à notre imaginaire technique.","bareme":[{"critere":"Traductions justes : « tiens-toi (cours) dans la voie du milieu » ; « tant l'art se cache par son art même »","points":5},{"critere":"Situations : conseil de Dédale avant le vol ; statue si parfaite qu'on la croirait vivante","points":3},{"critere":"Les trois mythes résumés avec leur livre (VIII, X, VI)","points":4},{"critere":"Argument : Icare désobéit, c'est l'ivresse de l'utilisateur qui est en cause ; Arachné défie une déesse","points":5},{"critere":"Héritage : Pygmalion ancêtre des créatures qui s'animent, Dédale ingénieur dépassé par son invention","points":3}],"dureeMin":18,"corrige":"1. **A** : ***medio ut limite curras*** : **« tiens-toi dans la voie du milieu »** (mot à mot : « que tu coures par la voie du milieu »). C'est le **conseil de Dédale à son fils** avant le vol : ne voler ni trop haut ni trop bas.\n**B** : ***ars adeo latet arte sua*** : **« tant l'art se cache par son art même »**. Ovide parle de la **statue de Pygmalion**, si parfaite qu'**on la croirait vivante** : l'art est si réussi qu'on ne le voit plus.\n\n2. \n- **Dédale et Icare** (livre **VIII**) : l'inventeur fabrique des **ailes de plumes et de cire** ; son fils **vole trop près du soleil et tombe**.\n- **Pygmalion** (livre **X**) : le sculpteur **tombe amoureux de sa statue d'ivoire**, que **Vénus rend vivante**.\n- **Arachné** (livre **VI**) : la tisserande **défie Minerve** et **devient araignée**.\n\n3. **Réponse attendue.** Chez Ovide, **la technique n'est pas en cause** : les ailes de Dédale **fonctionnent**, et le père a donné la règle (*medio ut limite curras*). C'est Icare qui **désobéit** : le danger vient de l'**ivresse** de celui qui s'en sert. Arachné, elle, est punie non pour son art de tisserande mais pour avoir **défié Minerve** : là encore, c'est l'orgueil de l'artiste, non son savoir-faire, qui la perd. Pygmalion, enfin, montre la technique à son sommet : l'art est si parfait qu'il **se cache** (*ars adeo latet arte sua*) et que l'œuvre semble vivre, jusqu'à ce que Vénus l'anime.\n**Ce qu'ils disent encore** : **Pygmalion** est l'ancêtre de **tous les récits de créatures qui s'animent**, de **Pinocchio aux robots humanoïdes** ; **Dédale** est celui de l'**ingénieur que dépasse son invention**, puisqu'il perd son fils par elle.\n\nConclusion : la technique ouvre des possibles ; c'est la **mesure**, la « voie du milieu », qui décide si elle sauve ou si elle perd."}$exo$::jsonb),
  ('d9677dfd-4d59-5791-aaec-2cb1704a791a'::uuid, 1, 'traduction', $exo${"titre":"Situer les sites de mare nostrum","consigne":"Réponds à chaque question en t'appuyant sur le cours.","enonce":"1. Que signifie *mare nostrum* ? À partir de quand tous les rivages de la Méditerranée appartiennent-ils au même empire ?\n2. Pour chaque site, donne le **pays actuel** et **un fait à connaître** :\n   - a) Carthage ;\n   - b) Leptis Magna ;\n   - c) Timgad ;\n   - d) Éphèse ;\n   - e) Palmyre ;\n   - f) Pompéi et Herculanum.\n3. Cite deux villes de France où l'on voit la Gaule romaine, avec un monument pour l'une d'elles.","bareme":[{"critere":"Mare nostrum = « notre mer » ; au IIe siècle, tous ses rivages appartiennent au même empire","points":4},{"critere":"Les six sites justes : pays actuel et fait précis","points":12},{"critere":"Nîmes et Arles, avec un monument (Maison carrée, arènes, théâtre)","points":4}],"dureeMin":7,"corrige":"1. *Mare nostrum* signifie **« notre mer »** : c'est ainsi que les Romains appelaient la Méditerranée. Au **IIe siècle**, **tous ses rivages** appartiennent au **même empire**.\n\n2. \n- a) **Carthage** — **Tunisie** : rivale de Rome **détruite en 146 av. J.-C.**, puis refondée en colonie romaine.\n- b) **Leptis Magna** — **Libye** : ville natale de l'empereur **Septime Sévère**, qui l'embellit.\n- c) **Timgad** — **Algérie** : colonie **fondée sous Trajan vers 100**, au **plan en damier** parfait.\n- d) **Éphèse** — **Turquie** : la **bibliothèque de Celsus**, au IIe siècle.\n- e) **Palmyre** — **Syrie** : carrefour caravanier ; monuments **dynamités par l'État islamique en 2015**.\n- f) **Pompéi et Herculanum** — **Italie** : **ensevelies en 79 par le Vésuve** ; fouilles depuis le XVIIIe siècle.\n\n3. **Nîmes** et **Arles** : la **Maison carrée** (Nîmes), les **arènes**, le **théâtre**."}$exo$::jsonb),
  ('d9677dfd-4d59-5791-aaec-2cb1704a791a'::uuid, 2, 'traduction', $exo${"titre":"Lire le plan d'une ville romaine","consigne":"Lis la description, puis réponds aux questions en employant le vocabulaire du cours.","enonce":"**Description d'une ville imaginaire**, fondée par Rome au bord de la Méditerranée.\n\n> Deux grandes rues droites traversent la ville : l'une va du nord au sud, l'autre de l'est à l'ouest. À leur croisement s'ouvre une vaste place ; sur un côté se dresse un grand bâtiment où l'on rend la justice, sur l'autre un temple. Plus loin, on trouve des bains publics, un édifice en demi-cercle pour les pièces de théâtre, et un grand édifice ovale pour les spectacles. L'eau arrive par un long ouvrage venu des collines.\n\n1. Donne le nom latin des deux grandes rues, en précisant laquelle est laquelle.\n2. Nomme la place et les deux bâtiments qui la bordent.\n3. Nomme les quatre autres équipements décrits.\n4. Pourquoi parle-t-on d'une « grammaire urbaine » commune à tout l'Empire ? Cite une ville du cours qui en offre un exemple parfait, et dis pourquoi.\n5. Explique la phrase du cours : « Rome romanise sans toujours contraindre. »","bareme":[{"critere":"Cardo (nord-sud) et decumanus (est-ouest)","points":4},{"critere":"Forum, basilique (tribunal) et temple","points":4},{"critere":"Thermes, théâtre, amphithéâtre, aqueduc","points":4},{"critere":"Même plan partout ; Timgad, plan en damier parfait, fondée sous Trajan","points":4},{"critere":"Romaniser : adopter le décor et la vie à la romaine, par attrait plus que par force","points":4}],"dureeMin":11,"corrige":"1. La rue **nord-sud** est le ***cardo*** ; la rue **est-ouest** est le ***decumanus***.\n\n2. La place est le ***forum***, à leur croisement. Il est bordé par la **basilique** (le **tribunal**, où l'on rend la justice) et par le **temple**.\n\n3. Les bains publics sont les **thermes** ; l'édifice en demi-cercle est le **théâtre** ; l'édifice ovale est l'**amphithéâtre** ; l'ouvrage qui apporte l'eau est l'**aqueduc**.\n\n4. On parle de « grammaire urbaine » parce que **partout dans l'Empire** on retrouve **les mêmes éléments, disposés de la même façon** : deux rues principales, le forum à leur croisement, la basilique et le temple, puis thermes, théâtre, amphithéâtre, aqueduc. **Timgad**, en Algérie, colonie **fondée sous Trajan vers 100**, en offre un exemple parfait avec son **plan en damier**.\n\n5. **Vivre à la romaine, c'est adopter ce décor** : les habitants des provinces prennent l'habitude des thermes, des spectacles, du forum. Rome n'a pas besoin de tout imposer par la force : l'**attrait** de ce mode de vie suffit souvent à faire adopter les usages romains. C'est ainsi que Rome **romanise sans toujours contraindre**."}$exo$::jsonb),
  ('d9677dfd-4d59-5791-aaec-2cb1704a791a'::uuid, 3, 'traduction', $exo${"titre":"La Méditerranée antique, un héritage en jeu","consigne":"Rédige un développement argumenté d'une vingtaine de lignes, en deux ou trois parties.","enonce":"**Document 1 — Horace** : *Graecia capta ferum victorem cepit*, « la Grèce conquise a conquis son farouche vainqueur ».\n\n**Document 2 — Lieux de culture** : la première bibliothèque publique de Rome est ouverte par Asinius Pollion en 39 av. J.-C. ; la villa des Papyrus d'Herculanum a livré des rouleaux carbonisés, surtout de philosophie épicurienne, qu'on commence à lire grâce à l'imagerie numérique ; les plus riches achèvent leurs études à Athènes ou à Rhodes, comme Cicéron.\n\n**Document 3 — Reprises modernes** : le Panthéon de Paris, la colonne Vendôme, l'Arc de triomphe de l'Étoile, l'église de la Madeleine.\n\n**Document 4** — En 2015, l'État islamique dynamite des monuments de Palmyre.\n\n**Sujet** : Pourquoi la Méditerranée romaine reste-t-elle, aujourd'hui encore, un héritage vivant et un enjeu ? Appuie-toi sur les quatre documents et sur tes connaissances.","bareme":[{"critere":"Doc. 1 expliqué : Rome apprend de la Grèce, la culture circule autour de la Méditerranée","points":4},{"critere":"Doc. 2 exploité : bibliothèques, écoles (litterator, grammaticus, rhetor), savoir encore en cours de découverte","points":4},{"critere":"Doc. 3 : chaque reprise associée à son modèle antique","points":4},{"critere":"Patrimoine menacé (pillages, guerres, tourisme, montée des eaux) ; Palmyre : détruire, c'est vouloir effacer une mémoire commune","points":5},{"critere":"Développement construit qui répond au sujet","points":3}],"dureeMin":18,"corrige":"**I. Une culture qui circule.** La formule d'Horace, *Graecia capta ferum victorem cepit*, dit que Rome, victorieuse par les armes, a été **conquise par la culture grecque** : **Rome n'a jamais cessé d'apprendre de la Grèce**. Les élites vont achever leurs études à **Athènes** ou à **Rhodes**, comme Cicéron. Le savoir se transmet dans les **écoles** (lire chez le *litterator*, les auteurs chez le *grammaticus*, l'art de parler chez le *rhetor*) et dans les **bibliothèques publiques** : Asinius Pollion en **39 av. J.-C.**, Auguste sur le Palatin, Trajan une double bibliothèque, grecque et latine.\n\n**II. Un héritage vivant.** Ce savoir se découvre encore : les rouleaux carbonisés de la **villa des Papyrus** commencent à être lus grâce à l'**imagerie numérique**. L'art romain est repris par les modernes : le **Panthéon de Paris** (et le Capitole de Washington) s'inspire du Panthéon et de sa coupole ; la **colonne Vendôme**, de la **colonne Trajane** ; l'**Arc de triomphe de l'Étoile**, des arcs de triomphe ; la **Madeleine**, de la **Maison carrée** de Nîmes. Les villes antiques sont encore **habitées, fouillées ou menacées**.\n\n**III. Un enjeu contemporain.** Le patrimoine est **en danger** : **pillages, guerres, tourisme de masse, montée des eaux**. La destruction de **Palmyre** en **2015** montre qu'un site antique reste un **enjeu politique** : **le détruire, c'est vouloir effacer une mémoire commune**.\n\n**Conclusion** : parce qu'elle a été un espace commun de culture, la Méditerranée romaine appartient encore à tous ; c'est pour cela qu'on la **fouille**, qu'on la **copie**… et qu'on veut parfois la **détruire**."}$exo$::jsonb),
  ('ab199434-cffe-5ac2-a025-c9a33d1cc3b6'::uuid, 1, 'traduction', $exo${"titre":"Reconnaître eo, fero, fio et les autres","consigne":"Traduis chaque phrase, puis identifie le verbe souligné en gras.","enonce":"**Phrases composées pour l'exercice.**\n\n1. *Miles in castra **redit**.*\n2. *Servi aquam **ferunt**.*\n3. ***Noli** timere, puer !*\n4. *Gaius flumen transire **ausus est**.*\n5. *Me **paenitet** culpae meae.*\n6. *Magister iratus **fit**.*\n\n*Lexique : miles, itis (m.) = le soldat ; castra, orum (n. pl.) = le camp ; servus, i (m.) = l'esclave ; aqua, ae (f.) = l'eau ; timeo, ere = craindre, avoir peur ; puer, i (m.) = l'enfant ; flumen, inis (n.) = le fleuve ; culpa, ae (f.) = la faute ; magister, tri (m.) = le maître ; iratus, a, um = en colère.*\n\n**a)** Traduis les six phrases.\n**b)** Pour chaque verbe en gras, donne le verbe d'origine (première personne du présent) et son sens, puis dis ce qui est irrégulier ou particulier dans son emploi.","bareme":[{"critere":"Six traductions justes","points":10},{"critere":"Verbes identifiés : redeo, fero, nolo, audeo, paenitet, fio","points":6},{"critere":"Particularités expliquées : noli + infinitif, parfait passif à sens actif, accusatif et génitif avec paenitet, fio passif de facio","points":4}],"dureeMin":8,"corrige":"**a) Traductions**\n1. **Le soldat revient au camp.**\n2. **Les esclaves portent de l'eau.**\n3. **N'aie pas peur, enfant !** (Ne crains pas.)\n4. **Gaius a osé traverser le fleuve.**\n5. **Je me repens de ma faute.** (mot à mot : « il me repent de ma faute »)\n6. **Le maître se met en colère.** (devient furieux)\n\n**b) Identification**\n1. *redit* : de ***redeo***, « revenir », composé de ***eo*** (aller) ; il suit le modèle de *eo* (3e personne du singulier du présent).\n2. *ferunt* : de ***fero***, « porter » (*fero, fers, ferre, tuli, latum*) : verbe à **trois radicaux**.\n3. *noli* : impératif de ***nolo***, « ne pas vouloir » ; ***noli + infinitif*** exprime la **défense** : « ne… pas ».\n4. *ausus est* : de ***audeo***, « oser », **semi-déponent** : parfait de **forme passive** mais de **sens actif** : « il a osé », et non « il a été osé ».\n5. *paenitet* : verbe **non personnel** (3e personne du singulier seulement), « on se repent » : **accusatif** de la personne (*me*), **génitif** de la cause (*culpae meae*).\n6. *fit* : de ***fio***, « devenir, être fait », qui **sert de passif à *facio***."}$exo$::jsonb),
  ('ab199434-cffe-5ac2-a025-c9a33d1cc3b6'::uuid, 2, 'traduction', $exo${"titre":"Marcus veut partir pour Rome","consigne":"Traduis le texte à l'aide du lexique, puis réponds aux questions de langue.","enonce":"**Texte composé pour l'exercice.**\n\n> *Marcus Romam ire vult ; pater autem mavult eum domi manere. « Noli abire, fili ! » inquit pater. Sed Marcus abire ausus est. Nunc eum paenitet stultitiae suae : Roma magna urbs est, et ibi miser fit.*\n\n*Lexique : Romam = à Rome (avec mouvement) ; autem = or, mais ; eum = lui (accusatif) ; domi = à la maison ; maneo, ere = rester ; abeo, ire = partir ; inquit = dit-il ; fili = vocatif de filius, « mon fils » ; nunc = maintenant ; stultitia, ae (f.) = la sottise ; urbs, urbis (f.) = la ville ; ibi = là ; miser, era, erum = malheureux.*\n\n1. Traduis le texte.\n2. Identifie *vult*, *mavult* et *noli* : verbe d'origine, sens, et construction qui suit chacun.\n3. Explique la construction de *eum paenitet stultitiae suae*.\n4. Mets au parfait, en gardant le sens actif : *Marcus gaudet* ; *Marcus ludere solet* (ludo, ere = jouer).","bareme":[{"critere":"Traduction juste et en bon français, sans contresens sur mavult, noli abire, ausus est, fit","points":9},{"critere":"Vult (volo), mavult (malo, vouloir plutôt) et noli (nolo, défense) identifiés avec leur infinitif","points":4},{"critere":"Paenitet : accusatif de la personne (eum), génitif de la cause (stultitiae)","points":3},{"critere":"Gavisus est ; solitus est ludere","points":4}],"dureeMin":12,"corrige":"1. **Traduction** : « **Marcus veut aller à Rome ; or son père préfère qu'il reste à la maison. « Ne pars pas, mon fils ! » dit le père. Mais Marcus a osé partir. Maintenant, il se repent de sa sottise : Rome est une grande ville, et là il devient malheureux.** »\n\n2. \n- *vult* : de ***volo***, « vouloir » (*volo, vis, velle, volui*) ; suivi de l'infinitif *ire* : « il veut aller ».\n- *mavult* : de ***malo***, « préférer » (*magis volo*, vouloir plutôt) ; suivi d'une proposition infinitive (*eum domi manere*) : « il préfère qu'il reste ».\n- *noli* : impératif de ***nolo***, « ne pas vouloir » ; ***noli + infinitif*** (*abire*) exprime la **défense** : « ne pars pas ».\n\n3. *Paenitet* est un verbe **non personnel** (3e personne du singulier) : la personne qui se repent est à l'**accusatif** (*eum*), la cause du repentir au **génitif** (*stultitiae suae*). Mot à mot : « il le repent de sa sottise » → « il se repent de sa sottise ».\n\n4. *Gaudeo* et *soleo* sont **semi-déponents** : au parfait, forme passive, sens actif.\n- *Marcus gaudet* → ***Marcus gavisus est*** (« Marcus s'est réjoui »).\n- *Marcus ludere solet* → ***Marcus ludere solitus est*** (« Marcus a eu l'habitude de jouer »)."}$exo$::jsonb),
  ('ab199434-cffe-5ac2-a025-c9a33d1cc3b6'::uuid, 3, 'traduction', $exo${"titre":"Deux frères vont aux jeux","consigne":"Traduis le texte, puis analyse les points de langue demandés en justifiant chaque réponse.","enonce":"**Texte composé pour l'exercice.**\n\n> *Nemo non ludos amat. Duo fratres, Gaius et Lucius, spectatum ludos eunt. « Num tibi licet sine patre abire ? » rogat Gaius. Lucius, qui felix esse videtur, respondet : « Pater nobis abire permisit. » Uterque gaudet : ludi enim mirabiles visu sunt.*\n\n*Lexique : ludi, orum (m. pl.) = les jeux ; amo, are = aimer ; frater, tris (m.) = le frère ; spectatum = supin de specto, regarder ; rogo, are = demander ; sine + ablatif = sans ; respondeo, ere = répondre ; permisit = parfait de permitto, « permettre » ; enim = en effet ; mirabilis, e = admirable ; visu = supin de video, voir.*\n\n1. Traduis le texte.\n2. Relève les **deux supins**. Pour chacun, dis s'il est en *-um* ou en *-u* et ce qu'il exprime.\n3. *Nemo non* : quelle est la valeur de cette double négation ? Traduis.\n4. *Num* : quelle réponse Gaius attend-il ? Explique la construction de *licet*.\n5. *Videtur* : quelle construction ? *Eunt* : de quel verbe, à quelle forme ?\n6. Mets *Uterque gaudet* au parfait et traduis.","bareme":[{"critere":"Traduction juste et fluide du texte","points":7},{"critere":"Spectatum (-um, but, après verbe de mouvement) et visu (-u, complète un adjectif)","points":4},{"critere":"Nemo non = tout le monde ; num attend « non » ; licet + datif de la personne + infinitif","points":4},{"critere":"Videtur en construction personnelle (il semble être) ; eunt = 3e pers. pluriel du présent de eo","points":3},{"critere":"Uterque gavisus est : l'un et l'autre s'est réjoui","points":2}],"dureeMin":18,"corrige":"1. **Traduction** : « **Tout le monde aime les jeux. Deux frères, Gaius et Lucius, vont voir les jeux. « Est-ce qu'il t'est permis de partir sans ton père ? » demande Gaius. Lucius, qui semble être heureux, répond : « Notre père nous a permis de partir. » L'un et l'autre se réjouissent : en effet, les jeux sont admirables à voir.** »\n\n2. \n- ***spectatum*** : supin en ***-um***, après un **verbe de mouvement** (*eunt*) : il exprime le **but** : « ils vont (pour) voir ». Comme *eo cubitum*, « je vais me coucher ».\n- ***visu*** : supin en ***-u***, il **complète un adjectif** (*mirabiles*) : « admirables à voir ». Comme *mirabile dictu*.\n\n3. *Nemo non* : la **double négation vaut une affirmation** : « personne ne… pas » = « **tout le monde** ». *Nemo non ludos amat* : « Tout le monde aime les jeux. »\n\n4. *Num* attend la réponse « **non** » : Gaius pense que son frère n'a pas la permission. *Licet*, « il est permis », verbe non personnel, se construit avec le **datif de la personne** (*tibi*) et l'**infinitif** (*abire*) : « il t'est permis de partir ».\n\n5. *Videtur* : ***videor*** en **construction personnelle** : *Lucius felix esse videtur*, « Lucius **semble être** heureux » (et non « on voit Lucius »). *Eunt* : **3e personne du pluriel du présent** de ***eo***, « aller » : « ils vont ».\n\n6. *Gaudeo* est **semi-déponent** (parfait *gavisus sum*) : ***Uterque gavisus est***, « **l'un et l'autre s'est réjoui** » (*uterque* se construit au singulier)."}$exo$::jsonb),
  ('66f3bb3a-0541-5237-9f2f-ff0e00bec190'::uuid, 1, 'traduction', $exo${"titre":"Les règles du style indirect","consigne":"Réponds à chaque question en t'appuyant sur le cours.","enonce":"1. Au style indirect, que devient :\n   - a) une principale déclarative ?\n   - b) une principale d'ordre ou de défense ?\n   - c) une subordonnée ?\n   - d) *ego*, *meus*, qui désignent celui qui parle ?\n2. Traduis et explique la forme du verbe :\n   - a) *Odi et amo* (Catulle) ;\n   - b) *memento mori* ;\n   - c) *novi*.\n3. Traduis *puer decem annos natus* et indique à quel cas est *annos* et pourquoi.\n4. Traduis *O tempora, o mores !* À quel cas sont *tempora* et *mores* ?","bareme":[{"critere":"Les quatre transformations justes : infinitive, subjonctif, subjonctif, se / suus","points":8},{"critere":"Parfaits à sens de présent : je hais et j'aime ; souviens-toi que tu vas mourir (impératif de memini) ; je sais","points":6},{"critere":"Un enfant de dix ans ; annos accusatif de durée","points":3},{"critere":"« Quelle époque, quelles mœurs ! » ; accusatif exclamatif avec o","points":3}],"dureeMin":7,"corrige":"1. \n- a) Une principale déclarative devient une **proposition infinitive** (sujet à l'accusatif).\n- b) Une principale d'ordre ou de défense passe au **subjonctif**.\n- c) **Toute subordonnée** passe au **subjonctif**.\n- d) *ego*, *meus* deviennent ***se***, ***suus***.\n\n2. \n- a) *Odi et amo* : **« Je hais et j'aime. »** *Odi* est un **parfait à sens de présent** ; *amo* un présent. Deux formes, deux présents en français.\n- b) *Memento mori* : **« Souviens-toi que tu vas mourir. »** *Memento* est l'**impératif** de ***memini***, parfait à sens de présent (« je me souviens »).\n- c) *Novi* : parfait de *nosco* : **« je sais, je connais »** (« j'ai appris », donc je connais).\n\n3. *Puer decem annos natus* : **« un enfant de dix ans »** (mot à mot : « enfant né depuis dix ans »). *Annos* est un **accusatif de durée**.\n\n4. *O tempora, o mores !* : **« Quelle époque, quelles mœurs ! »** (Cicéron). *Tempora* et *mores* sont à l'**accusatif exclamatif**, avec *o*."}$exo$::jsonb),
  ('66f3bb3a-0541-5237-9f2f-ff0e00bec190'::uuid, 2, 'traduction', $exo${"titre":"Rapporter les paroles des ambassadeurs","consigne":"Traduis, analyse et transforme les phrases en justifiant chaque changement.","enonce":"**Phrases composées pour l'exercice.**\n\n**A. Discours direct** : *Legati dixerunt : « Nos pacem petimus, quod bellum timemus. »*\n**A'. Style indirect** : *Legati dixerunt se pacem petere, quod bellum timerent.*\n\n**B.** *Marcus dicit se librum legere quem pater emerit.*\n\n**C. Discours direct** : *Consul dixit : « Ego patriam meam amo. »*\n\n*Lexique : legatus, i (m.) = l'ambassadeur ; pax, pacis (f.) = la paix ; peto, ere = demander ; quod = parce que ; bellum, i (n.) = la guerre ; timeo, ere = craindre ; liber, bri (m.) = le livre ; lego, ere = lire ; emerit = subjonctif parfait de emo, acheter ; consul, is (m.) = le consul ; patria, ae (f.) = la patrie.*\n\n1. Traduis A'.\n2. Compare A et A' : relève les trois changements et justifie chacun par une règle du style indirect. Pourquoi *timerent* est-il à l'imparfait ?\n3. Traduis B. Pourquoi *emerit* est-il au subjonctif ? Ce subjonctif a-t-il un sens propre ? Comment le traduit-on ?\n4. Mets C au style indirect, puis traduis ta phrase.","bareme":[{"critere":"Traduction de A' : « Les ambassadeurs dirent qu'ils demandaient la paix parce qu'ils craignaient la guerre »","points":4},{"critere":"Trois changements justifiés : nos → se, petimus → infinitive petere, timemus → subjonctif ; imparfait = simultanéité après un passé","points":6},{"critere":"B traduit ; emerit au subjonctif de dépendance (relative dans une infinitive), sans sens propre, traduit par un indicatif","points":5},{"critere":"C transformé : Consul dixit se patriam suam amare, et traduit","points":5}],"dureeMin":12,"corrige":"1. A' : **« Les ambassadeurs dirent qu'ils demandaient la paix, parce qu'ils craignaient la guerre. »**\n\n2. Trois changements :\n- ***nos* → *se*** : au style indirect, le pronom qui désigne ceux qui parlent devient le **réfléchi** *se*.\n- ***petimus* → *petere*** : la principale **déclarative** devient une **proposition infinitive** (sujet à l'accusatif : *se*).\n- ***timemus* → *timerent*** : la **subordonnée** (*quod…*) passe au **subjonctif**.\n*Timerent* est à l'**imparfait** à cause de la **concordance des temps** : la principale *dixerunt* est au **passé**, et la crainte est **simultanée** : après un passé, la simultanéité s'exprime par le **subjonctif imparfait**.\n\n3. B : **« Marcus dit qu'il lit le livre que son père a acheté. »** *Emerit* est au subjonctif parce que la relative dépend d'une **proposition infinitive** (*se librum legere*) : c'est l'**attraction modale** (on est au style indirect). Ce subjonctif **n'a pas de sens propre** : il signale seulement la **dépendance**. On le **traduit par un indicatif** (« a acheté »). Il est au **parfait** : après un présent (*dicit*), l'antériorité s'exprime par le subjonctif parfait.\n\n4. C au style indirect : ***Consul dixit se patriam suam amare.*** — **« Le consul dit qu'il aimait sa patrie. »** (*ego* → *se*, *meam* → *suam*, *amo* → infinitive *amare*.)"}$exo$::jsonb),
  ('66f3bb3a-0541-5237-9f2f-ff0e00bec190'::uuid, 3, 'traduction', $exo${"titre":"Laocoon devant le cheval","consigne":"Traduis, analyse et transforme en justifiant chaque réponse par une règle du cours.","enonce":"**Document 1 — Virgile, *Énéide*, II** : Laocoon devant le cheval de Troie.\n\n> *Quidquid id est, timeo Danaos et dona ferentes.*\n\n*Lexique : id = cela ; timeo = je crains ; Danai, orum (m. pl.) = les Grecs ; et = même ; donum, i (n.) = le présent, le cadeau ; ferentes = participe présent de fero, « portant ».*\n\n**Document 2 — La même idée au style indirect** (phrase composée pour l'exercice) :\n\n> *Laocoon clamavit se Danaos timere, quidquid id esset.*\n\n*Lexique : clamavit = parfait de clamo, crier.*\n\n**Document 3 — Phrase composée** : *Laocoon dixit : « Ego equum timeo, quia Graeci dolosi sunt. »*\n\n*Lexique : equus, i (m.) = le cheval ; quia = parce que ; dolosus, a, um = rusé.*\n\n1. Traduis le document 1 en bon français.\n2. Quelle est la nature de *quidquid* ? De quel mot est-il le neutre, et que signifie-t-il ?\n3. Traduis le document 2. Explique la forme de *timere* et celle de *esset* (mode et temps).\n4. Mets le document 3 au style indirect et justifie chaque transformation.\n5. On lit dans un texte un long passage à l'infinitif et au subjonctif, sans verbe introducteur visible. Que dois-tu en conclure et que dois-tu chercher ?","bareme":[{"critere":"Doc. 1 : « Quoi que ce soit, je crains les Grecs, même quand ils apportent des présents »","points":4},{"critere":"Quidquid : relatif indéfini, neutre de quisquis, « quoi que ce soit, tout ce qui »","points":3},{"critere":"Doc. 2 traduit ; timere infinitive ; esset subjonctif (subordonnée) imparfait (simultanéité après un passé)","points":5},{"critere":"Doc. 3 transformé : Laocoon dixit se equum timere, quia Graeci dolosi essent ; changements justifiés","points":5},{"critere":"Discours rapporté : chercher qui parle quelques lignes plus haut","points":3}],"dureeMin":18,"corrige":"1. **« Quoi que ce soit, je crains les Grecs, même quand ils apportent des présents. »** C'est Laocoon devant le cheval de Troie.\n\n2. ***Quidquid*** est un **relatif indéfini** : c'est le **neutre de *quisquis*** (« quiconque, qui que ce soit qui »). Il signifie « **tout ce qui, quoi que ce soit** ».\n\n3. Doc. 2 : **« Laocoon cria qu'il craignait les Grecs, quoi que ce fût. »**\n- ***timere*** : infinitif : la principale déclarative *timeo* devient une **proposition infinitive** (sujet *se*, qui remplace *ego*).\n- ***esset*** : **subjonctif**, car au style indirect **toute subordonnée passe au subjonctif** ; **imparfait**, car la principale (*clamavit*) est au **passé** et le fait est **simultané** (concordance des temps).\n\n4. ***Laocoon dixit se equum timere, quia Graeci dolosi essent.*** — « Laocoon dit qu'il craignait le cheval parce que les Grecs étaient rusés. »\n- *ego* → ***se*** (celui qui parle) ;\n- principale déclarative *timeo* → **proposition infinitive** *timere* ;\n- subordonnée *quia… sunt* → **subjonctif** *essent* ;\n- **imparfait** du subjonctif : simultanéité après un verbe au passé (*dixit*).\n\n5. C'est presque toujours du **discours rapporté** (style indirect) : il faut **chercher qui parle quelques lignes plus haut**. Les subjonctifs des subordonnées y sont alors des subjonctifs de dépendance, à traduire par l'indicatif."}$exo$::jsonb),
  ('d1a49723-16cf-5d45-b63e-b705c78946f7'::uuid, 1, 'traduction', $exo${"titre":"Les mots du destin et du sacré","consigne":"Réponds à chaque question en t'appuyant sur le cours.","enonce":"1. Pour chacun de ces mots latins, donne le **sens premier** et **un héritier français** : *fatum* · *fortuna* · *monstrum* · *sacer* · *templum* · *augurium*.\n2. D'où viennent les mots *fatum* et *monstrum* (verbe d'origine et sens) ?\n3. Explique le sens premier des verbes « inaugurer » et « contempler ».\n4. Qu'est-ce qu'un **doublet** ? Donne le mot populaire et le mot savant issus de *hospitale* et de *potionem*.","bareme":[{"critere":"Six mots : sens premier et héritier justes","points":9},{"critere":"Fatum de fari (parler) ; monstrum de monere (avertir)","points":3},{"critere":"Inaugurer : prendre les auspices avant d'ouvrir un bâtiment ; contempler : observer le templum céleste","points":4},{"critere":"Doublet défini (mot populaire / mot savant) ; hôtel / hôpital ; poison / potion","points":4}],"dureeMin":7,"corrige":"1. \n- ***fatum*** : ce qui a été dit → **fatal, fatalité** ;\n- ***fortuna*** : le sort, bon ou mauvais → **fortune, fortuit** ;\n- ***monstrum*** : signe envoyé par les dieux → **monstre, montrer** ;\n- ***sacer*** : mis à part pour les dieux ; aussi maudit → **sacré, sacrifice** ;\n- ***templum*** : espace du ciel découpé par l'augure → **temple, contempler** ;\n- ***augurium*** : présage tiré des oiseaux → **augure, inaugurer**.\n\n2. *Fatum* vient de ***fari***, **« parler »** ; *monstrum* vient de ***monere***, **« avertir »**.\n\n3. **Inaugurer**, c'était **prendre les auspices avant d'ouvrir un bâtiment** ; **contempler**, c'était **observer le *templum* céleste**, l'espace du ciel découpé par l'augure.\n\n4. Un **doublet**, c'est un même mot latin qui a donné **deux mots français** : un mot **populaire**, usé par des siècles de bouche à oreille, et un mot **savant**, recopié plus tard par les lettrés.\n- *hospitale* → **hôtel** (populaire) / **hôpital** (savant) ;\n- *potionem* → **poison** (populaire) / **potion** (savant)."}$exo$::jsonb),
  ('d1a49723-16cf-5d45-b63e-b705c78946f7'::uuid, 2, 'traduction', $exo${"titre":"Question de lexique : monstrum","consigne":"Applique les quatre étapes de la méthode de la question de lexique, en rédigeant chaque étape.","enonce":"**Deux phrases composées pour l'exercice.**\n\n> **Phrase 1** : *Monstrum in caelo apparuit ; senatus deos timuit.*\n> **Phrase 2** : *Cyclops, monstrum horrendum, pastores terrebat.*\n\n*Lexique : caelum, i (n.) = le ciel ; apparuit = parfait de appareo, apparaître ; senatus, us (m.) = le Sénat ; timuit = parfait de timeo, craindre ; Cyclops, opis (m.) = le Cyclope ; horrendus, a, um = effrayant ; pastor, oris (m.) = le berger ; terrebat = imparfait de terreo, effrayer.*\n\n1. Traduis les deux phrases.\n2. Donne le **sens premier** du mot *monstrum*, avec son étymologie.\n3. Relève ses **emplois** dans les deux phrases : le mot a-t-il le même sens ?\n4. Dis le **sens en contexte** dans chaque phrase et ce qu'il apporte à la compréhension (pourquoi le Sénat a-t-il peur dans la phrase 1 ?).\n5. **Ouvre** : cite deux héritiers français et explique le lien de chacun avec le sens premier.","bareme":[{"critere":"Deux traductions justes","points":4},{"critere":"Sens premier : signe envoyé par les dieux, de monere, avertir","points":4},{"critere":"Deux emplois distingués : avertissement divin / créature effrayante","points":5},{"critere":"Sens en contexte expliqué : le Sénat craint les dieux parce que le signe vient d'eux","points":4},{"critere":"Héritiers monstre et montrer, reliés au sens premier","points":3}],"dureeMin":12,"corrige":"1. **Phrase 1** : **« Un prodige apparut dans le ciel ; le Sénat craignit les dieux. »** **Phrase 2** : **« Le Cyclope, monstre effrayant, effrayait les bergers. »**\n\n2. **Sens premier** : *monstrum* vient de ***monere***, **« avertir »** : c'est un **signe envoyé par les dieux**, un avertissement.\n\n3. **Emplois** : le mot n'a **pas le même sens** dans les deux phrases.\n- Phrase 1 : un **signe** qui **apparaît dans le ciel** ;\n- Phrase 2 : une **créature** effrayante, le Cyclope.\n\n4. **Sens en contexte** :\n- Phrase 1 : c'est le **sens premier**, un **avertissement des dieux**. Voilà pourquoi le Sénat **craint les dieux** : le signe vient d'eux, il annonce quelque chose, et il faut comprendre ce qu'ils veulent dire.\n- Phrase 2 : le mot désigne un **être hors du commun et effrayant**, le sens qui a donné notre « monstre ». L'adjectif *horrendum* souligne la peur qu'il inspire.\n\n5. **Ouverture** : deux héritiers français :\n- **monstre** : l'être extraordinaire, qu'on regardait comme un signe ;\n- **montrer** : faire voir, comme le signe divin **montre** ce que veulent les dieux.\nLe même mot latin a ainsi donné l'idée de **signe** et celle de **créature effrayante**."}$exo$::jsonb),
  ('d1a49723-16cf-5d45-b63e-b705c78946f7'::uuid, 3, 'traduction', $exo${"titre":"Ovide exilé : les mots de l'homme","consigne":"Traduis la phrase, puis réponds aux questions en justifiant par l'étymologie.","enonce":"**Phrase composée pour l'exercice.**\n\n> *Ovidius, exul, procul a patria vivit ; sed humanitas eius non perit : carmina scribit.*\n\n*Lexique : Ovidius, ii = Ovide ; exul, ulis (m.) = l'exilé ; procul a + ablatif = loin de ; patria, ae (f.) = la patrie ; vivo, ere = vivre ; humanitas, atis (f.) = voir cours ; eius = son, sa ; pereo, ire = périr ; carmen, inis (n.) = le poème ; scribo, ere = écrire.*\n\n1. Traduis la phrase.\n2. Explique la formation de *exsilium*, et ce que l'étymologie dit de la situation d'Ovide.\n3. Quel est le sens de *humanitas* chez Cicéron ? Comment le traduire ici, et pourquoi ce mot convient-il ?\n4. *Homo* est parent de *humus*. Explique ce lien et l'opposition qu'il suppose. Quel mot grec correspond à *homo* ?\n5. Classe ces mots selon leur racine latine et donne le sens de chaque racine : *captif*, *effet*, *mission*, *évident*, *aqueduc*, *capable*, *providence*, *infection*, *émettre*, *éducation*.","bareme":[{"critere":"Traduction juste : Ovide, exilé, vit loin de sa patrie ; mais sa culture ne périt pas : il écrit des poèmes","points":4},{"critere":"Exsilium = ex + solum (le sol) : hors de sa terre, appliqué à Ovide","points":4},{"critere":"Humanitas : culture et bienveillance, ce qui rend l'homme vraiment humain, l'éducation ; justifié ici","points":4},{"critere":"Homo / humus : l'homme est le terrestre, opposé aux dieux ; anthropos","points":3},{"critere":"Classement juste des dix mots en cinq racines, avec leur sens","points":5}],"dureeMin":18,"corrige":"1. **« Ovide, exilé, vit loin de sa patrie ; mais sa culture ne périt pas : il écrit des poèmes. »**\n\n2. *Exsilium* est formé de ***ex-*** (hors de) + ***solum***, **le sol** : l'exil, c'est être **hors de sa terre**. Le mot convient à Ovide, arraché à Rome, à sa *patria*, et qui vit loin d'elle.\n\n3. Chez **Cicéron**, *humanitas* désigne la **culture** et la **bienveillance** : **ce qui rend l'homme vraiment humain, l'éducation**. Ici, on peut traduire par « **sa culture** » : même loin de Rome, Ovide garde ce qui fait de lui un homme cultivé, puisqu'il **continue d'écrire des poèmes**. L'exil lui ôte sa terre, pas son *humanitas*.\n\n4. *Homo* est **parent de *humus***, **la terre** : l'homme est **le terrestre**, **opposé aux dieux**, qui sont célestes. Le mot grec correspondant est ***anthropos***.\n\n5. \n- ***cap-*** (**prendre**) : captif, capable ;\n- ***fac-/fec-*** (**faire**) : effet, infection ;\n- ***mitt-/miss-*** (**envoyer**) : mission, émettre ;\n- ***vid-/vis-*** (**voir**) : évident, providence ;\n- ***duc-*** (**conduire**) : aqueduc, éducation."}$exo$::jsonb),
  ('2cd8f882-359e-5065-a5bc-56f1c4a841f7'::uuid, 1, 'traduction', $exo${"titre":"Connaître l'épreuve écrite","consigne":"Réponds à chaque question à partir du cours.","enonce":"1. Quelle est la durée de l'épreuve écrite ? Quel document est autorisé ?\n2. De combien de textes le corpus se compose-t-il ? Décris chacun d'eux.\n3. Recopie et complète le tableau des points :\n\n| Partie | Question | Points |\n| Étude de la langue | Traduction d'environ … mots | … |\n| | Un fait de langue | … |\n| | Une notion clé du lexique | … |\n| Compréhension et interprétation | … | … |\n\n4. Quels sont les deux temps de la question sur le fait de langue ?\n5. Décris l'oral de contrôle : durée de préparation, travail demandé, déroulement.","bareme":[{"critere":"4 heures ; dictionnaire latin-français (le Gaffiot, en général)","points":3},{"critere":"Trois textes : texte latin de l'œuvre antique (300 mots au plus), extrait de l'œuvre moderne, court texte antique en traduction","points":5},{"critere":"Tableau juste : 90 mots / 6, fait de langue 2, lexique 2, essai sur les trois textes 10","points":6},{"critere":"Identifier (1 pt) puis interpréter (1 pt)","points":2},{"critere":"Oral : 20 min de préparation, commentaire et traduction de 25 mots au plus, 10 min d'exposé et 10 min d'entretien","points":4}],"dureeMin":7,"corrige":"1. L'épreuve écrite dure **4 heures**, avec un **dictionnaire latin-français** (le Gaffiot, en général).\n\n2. Le corpus compte **trois textes** : le **texte latin** de l'œuvre antique au programme (**300 mots au plus**, avec sa traduction, sauf le passage à traduire) — pour 2026-2028, les *Tristes*, livre III ; un **extrait de l'œuvre moderne** du programme (*La ferme africaine*) ; un **court texte antique donné en traduction**.\n\n3. \n| Partie | Question | Points |\n| Étude de la langue | Traduction d'environ **90** mots de l'œuvre antique | **6** |\n| | Un fait de langue : identifier et interpréter | **2** |\n| | Une notion clé du lexique, expliquée en contexte | **2** |\n| Compréhension et interprétation | **Un essai organisé sur les trois textes du corpus** | **10** |\n\n4. **Identifier** précisément la forme (cas, mode, temps, fonction) : **1 point** ; puis **interpréter** (ce que cette forme apporte au sens : une insistance, une cause, une plainte…) : **1 point**.\n\n5. **Vingt minutes de préparation** : un passage d'une vingtaine de lignes de l'œuvre antique à **commenter en lien avec l'œuvre moderne**, et un extrait de **25 mots au plus à traduire**. Puis **dix minutes d'exposé** (lecture du latin comprise) et **dix minutes d'entretien**."}$exo$::jsonb),
  ('2cd8f882-359e-5065-a5bc-56f1c4a841f7'::uuid, 2, 'traduction', $exo${"titre":"Traduire un distique en sept étapes","consigne":"Applique la méthode de traduction du cours au distique ci-dessous, en montrant ton travail à chaque étape.","enonce":"**Chapeau** : Ovide, relégué à Tomis et malade, écrit à sa femme et compose l'épitaphe qu'il voudrait voir sur sa tombe (*Tristes*, III, 3).\n\n> *Hic ego qui iaceo tenerorum lusor amorum / ingenio perii Naso poeta meo.*\n\n*Lexique : hic = ici ; iaceo, ere = être étendu, reposer ; tener, era, erum = tendre ; lusor, oris (m.) = celui qui joue, le chantre ; amor, oris (m.) = l'amour ; ingenium, ii (n.) = le talent ; pereo, ire, perii = périr ; Naso, onis (m.) = Nason ; poeta, ae (m.) = le poète ; meus, a, um = mon.*\n\n1. Qui parle, et de quoi ? (étape 1)\n2. Relève les verbes conjugués et délimite les propositions ; identifie le mot de liaison. (étapes 2 et 3)\n3. Dans chaque proposition, trouve le sujet, puis les compléments ; relève les accords qui permettent de rassembler les mots séparés. (étape 4)\n4. Donne une traduction exacte, puis une traduction en bon français. (étape 6)\n5. **Fait de langue** : identifie *ingenio* (cas, fonction), puis interprète ce que cette forme apporte au sens.","bareme":[{"critere":"Situation comprise : Ovide lui-même, dans son épitaphe, parle de sa perte","points":2},{"critere":"Deux verbes conjugués (iaceo, perii), deux propositions, relatif qui (antécédent ego)","points":4},{"critere":"Sujet ego (avec lusor et Naso poeta en apposition) ; accords tenerorum… amorum et ingenio… meo","points":4},{"critere":"Traduction exacte puis en bon français","points":6},{"critere":"Ingenio : ablatif de cause, identifié puis interprété (le talent comme cause de sa perte, insistance)","points":4}],"dureeMin":13,"corrige":"1. **Qui parle** : Ovide lui-même, dans l'**épitaphe** qu'il compose, malade, à Tomis. **De quoi** : de la **cause de sa perte**.\n\n2. **Verbes conjugués** : ***iaceo*** et ***perii***, donc **deux propositions** :\n- la **relative** *qui iaceo* (introduite par le relatif ***qui***, antécédent ***ego***) ;\n- la **principale** *hic ego… ingenio perii Naso poeta meo*.\n\n3. \n- Relative : sujet ***qui*** (= *ego*), verbe *iaceo*.\n- Principale : sujet ***ego***, verbe ***perii*** ; ***lusor*** et ***Naso poeta*** sont en **apposition** au sujet ; ***hic*** complément de lieu.\n- **Accords** : ***tenerorum… amorum*** (génitif pluriel, complément de *lusor*) ; ***ingenio… meo*** (ablatif singulier), séparés par le vers mais rassemblés par l'accord. Le distique forme **une seule phrase**, comme souvent chez Ovide.\n\n4. **Traduction exacte** : « Ici, moi qui repose, chantre des tendres amours, par mon talent j'ai péri, (moi) Nason le poète. »\n**En bon français** : **« Moi qui repose ici, chantre des tendres amours, le poète Nason, c'est mon talent qui m'a perdu. »**\n\n5. **Identifier** : *ingenio* est un **ablatif** (accordé avec *meo*), **ablatif de cause** : « à cause de mon talent ». **Interpréter** : la forme fait du **talent poétique la cause de sa perte** — le poème (*carmen*) qui a valu la relégation — ; placé en tête du vers, il est mis en **relief** : d'où la tournure présentative « c'est mon talent qui m'a perdu », qui rend l'**insistance** et la **plainte** du poète."}$exo$::jsonb),
  ('2cd8f882-359e-5065-a5bc-56f1c4a841f7'::uuid, 3, 'traduction', $exo${"titre":"Préparer l'essai : écrire loin de chez soi","consigne":"Rédige l'introduction complète et le plan détaillé de l'essai (pas la totalité du développement).","enonce":"**Corpus réduit pour l'exercice** (deux textes au lieu de trois).\n\n**Texte 1 — Ovide, *Tristes*, livre III** :\n- III, 7, à Périlla : *Ingenio tamen ipse meo comitorque fruorque*, « je suis pourtant accompagné de mon génie, et j'en jouis » ;\n- III, 10 : l'hiver de Tomis ; le Danube gèle, le vin gèle dans les jarres et se boit en morceaux ;\n- III, 12 : le printemps revient à Rome, pas à Tomis.\n\n**Texte 2 — Karen Blixen, *La ferme africaine*** (1937), écrit au Danemark après la perte de la ferme :\n> « J'avais une ferme en Afrique, au pied des collines du Ngong. »\n\n**Sujet de l'essai** : « L'écriture peut-elle sauver ce que l'éloignement a fait perdre ? »\n\n1. Analyse la question : relève ses mots clés et la tension qu'elle contient.\n2. Formule une problématique qui ne recopie pas la question.\n3. Rédige l'introduction.\n4. Propose un plan détaillé en deux ou trois parties : pour chaque partie, une idée directrice et, pour chaque paragraphe, un exemple précis tiré des **deux** textes, avec au moins une citation latine traduite.","bareme":[{"critere":"Question analysée : mots clés (sauver, éloignement, perdre) et tension relevée","points":3},{"critere":"Problématique pertinente, différente de la question","points":3},{"critere":"Introduction complète : amorce, présentation des textes, problématique, annonce du plan","points":4},{"critere":"Plan progressif qui confronte les textes dans chaque partie, au moins un exemple de Blixen par partie","points":7},{"critere":"Latin cité avec parcimonie et toujours traduit, exemples précis et analysés","points":3}],"dureeMin":20,"corrige":"1. **Analyse** : *sauver* (préserver de la disparition, mais aussi obtenir un salut), *éloignement* (l'exil forcé d'Ovide, le retour contraint de Blixen), *perdre* (Rome, la ferme, un monde). **Tension** : l'écriture naît de la perte, mais peut-elle vraiment la réparer, ou seulement la dire ?\n\n2. **Problématique possible** : l'écriture n'est-elle qu'une plainte sur ce qui est perdu, ou un moyen de le retenir, voire de le reconquérir ?\n\n3. **Introduction (exemple)** : amorce sur ceux qui écrivent parce qu'ils sont loin ; présentation : Ovide, relégué à Tomis en 8 ap. J.-C., écrit les *Tristes* pendant son exil ; Karen Blixen, rentrée au Danemark, écrit *La ferme africaine* (1937) après avoir tout perdu au Kenya ; problématique ; annonce du plan.\n\n4. **Plan détaillé (exemple)**\n**I. Écrire pour dire la perte.**\n- Ovide peint un lieu hostile (III, 10 : le Danube et le vin gelés) et l'absence du printemps (III, 12) : la plainte, au présent.\n- Blixen ouvre sur un imparfait : « **J'avais** une ferme en Afrique » : la perte est dite dès la première phrase, au passé.\n**II. Écrire pour garder ce qui reste.**\n- Ovide : *Ingenio tamen ipse meo comitorque fruorque*, « je suis pourtant accompagné de mon génie, et j'en jouis » : le talent le suit en exil et le console.\n- Blixen : l'écriture **sauve de l'oubli un monde disparu** ; la lumière des collines du Ngong devient un souvenir.\n**III. Écrire pour agir : un salut différent.**\n- Pour Ovide, l'écriture est une **arme de plaidoirie** : chaque détail est un argument adressé à Auguste pour obtenir un exil plus doux ; il veut sauver non un souvenir mais **sa propre situation**.\n- Pour Blixen, il n'y a rien à obtenir : l'écriture sauve la **mémoire**, pas la ferme.\n\n**Conclusion attendue** : l'écriture ne rend pas ce qui est perdu, mais elle le **garde** (Blixen) ou tente de le **reconquérir** (Ovide) ; même motif, deux intentions."}$exo$::jsonb),
  ('6ab42e25-fe1b-5f8c-8cb9-e2cd780f2fdf'::uuid, 1, 'traduction', $exo${"titre":"Translating a voice","consigne":"Traduis le passage en français, puis réponds à la question en anglais.","enonce":"**Document (invented memoir).**\n\n> For years, I wrote in secret. My notebooks were full of sentences I never dared to say out loud. When my teacher read one of my poems to the class, I wanted to disappear. But something changed that day: for the first time, people were listening to me. I had found my voice, and I was not going to lose it again.\n\n1. Translate the passage into French.\n2. In two or three sentences, explain which key notion of the chapter this passage illustrates (*voice*, *coming of age*, *empowerment*…). Justify with one precise element of the text.","bareme":[{"critere":"Sens fidèle du passage, sans contresens ni omission","points":8},{"critere":"Français correct et naturel (temps du récit, tournures idiomatiques, « found my voice »)","points":6},{"critere":"Notion identifiée en anglais et justifiée par un élément précis du texte","points":6}],"dureeMin":8,"corrige":"1. Traduction proposée :\n« Pendant des années, j'ai écrit en secret. Mes carnets étaient remplis de phrases que je n'avais jamais osé dire à voix haute. Quand mon professeur a lu l'un de mes poèmes à la classe, j'ai eu envie de disparaître. Mais ce jour-là, quelque chose a changé : pour la première fois, on m'écoutait. J'avais trouvé ma voix, et je n'allais plus la perdre. »\nPoints de vigilance : *for years* → « pendant des années » (et non « depuis ») ; *never dared to say out loud* → « n'avais jamais osé dire à voix haute » ; *people were listening to me* → « on m'écoutait » ; *I had found my voice* → « j'avais trouvé ma voix ».\n2. Expected answer (example): *The passage illustrates the notion of* **voice** *and* **empowerment**. *The narrator moves from silence (\"I wrote in secret\", \"never dared to say out loud\") to being heard (\"people were listening to me\"). Finding one's voice is a step in a* **coming-of-age** *story: saying \"I\" gives the narrator a place among others.*"}$exo$::jsonb),
  ('6ab42e25-fe1b-5f8c-8cb9-e2cd780f2fdf'::uuid, 2, 'traduction', $exo${"titre":"Writing the self as a political act","consigne":"Rédige en anglais un paragraphe argumenté d'environ 150 mots, en t'appuyant sur au moins deux œuvres ou discours du cours.","enonce":"**Subject.** In many works studied this year, telling one's own story is not only a private matter.\n\n> \"Why can writing about oneself be a political act?\"\n\nWrite a structured paragraph (about 150 words) that:\n1. defines the idea in your own words;\n2. uses at least **two** precise references from the course (author, title, date), chosen among the *voices from the margins* or the *speeches that shaped history*;\n3. uses at least two logical connectors (*however*, *therefore*, *whereas*…) and one key notion of the chapter (*voice*, *memoir*, *testimony*, *empowerment*, *double consciousness*…).","bareme":[{"critere":"Idée centrale formulée : dire « je » quand ce droit a été refusé est une prise de position","points":5},{"critere":"Au moins deux références exactes du cours (auteur, œuvre, date) mises au service de l'argument","points":6},{"critere":"Notion clé du chapitre employée à bon escient","points":3},{"critere":"Anglais correct, connecteurs variés et justes, longueur respectée","points":6}],"dureeMin":12,"corrige":"Éléments attendus et exemple de paragraphe :\n\n*Writing about oneself can be a political act because saying \"I\" is a way of claiming a place in a society that has denied you that right. For authors from the margins, the* **memoir** *is therefore not an intimate genre. Maya Angelou's* I Know Why the Caged Bird Sings *(1969) turns the story of her life into a means of survival, whereas Toni Morrison, in* Beloved *(1987), gives voice to the memory of slavery through a novel. In the same way, Malala Yousafzai's speech at the UN (2013) draws its authority from* **testimony**: *her personal experience speaks for millions of girls. However, this voice is never completely free: as W. E. B. Du Bois explained with the notion of* **double consciousness**, *one always sees oneself through the eyes of others. Telling one's own story is precisely a way to answer that gaze.*\n\nAutres références acceptées : Langston Hughes et la Harlem Renaissance (années 1920) ; Zora Neale Hurston, *Their Eyes Were Watching God* (1937), la langue vernaculaire devenue littérature ; Martin Luther King, *I Have a Dream* (1963) ; Barack Obama, discours de campagne (2008), le récit personnel adossé au récit national. Toute référence doit être exacte et reliée à l'argument, pas simplement citée."}$exo$::jsonb),
  ('6ab42e25-fe1b-5f8c-8cb9-e2cd780f2fdf'::uuid, 3, 'traduction', $exo${"titre":"From Whitman to the margins: who says \"I\"?","consigne":"Rédige en anglais une mini-synthèse d'environ 250 mots : dégage une problématique et fais dialoguer les deux documents avec tes connaissances du cours.","enonce":"**Document A (invented essay extract).**\n\n> The American dream was first written in the first person singular. Its founding texts praise the individual who trusts himself, who needs no one, who can even leave society behind to find out who he really is.\n\n**Document B (invented testimony, a young poet speaking at a school event).**\n\n> They told me my language was wrong, my accent was wrong, my story did not belong in books. So I wrote it anyway. Every poem I read tonight is a way of saying: I am here, and I am part of this country too.\n\n**Task.** Write a short synthesis (about 250 words) in English:\n1. an introduction with a clear problem (*problématique*) linking the two documents;\n2. a development in two parts that makes the documents **dialogue** (no \"document A, then document B\"), using at least **three** references from the course (the founding American self and the voices from the margins);\n3. a short conclusion.","bareme":[{"critere":"Problématique claire qui relie les deux documents et tient jusqu'à la conclusion","points":5},{"critere":"Documents mis en dialogue (pas de résumé successif), idées essentielles de chacun comprises","points":5},{"critere":"Au moins trois références exactes du cours (Whitman, Emerson, Thoreau, Hughes, Hurston, Angelou, Morrison…)","points":4},{"critere":"Anglais correct, connecteurs variés (however, whereas, therefore, insofar as)","points":4},{"critere":"Structure complète (introduction, deux parties, conclusion) et longueur respectée","points":2}],"dureeMin":20,"corrige":"**Problématique possible :** *To what extent is the American \"I\" both a founding ideal and a right that some had to conquer?*\n\n**Part 1 – The \"I\" as a founding ideal.** Document A reminds us that the American self is born in the first person: Walt Whitman's *Song of Myself* (1855) builds a voice that embraces the whole nation, Emerson's *Self-Reliance* (1841) makes trusting oneself a principle, and Thoreau's *Walden* (1854) shows a man withdrawing from society to find himself. The individual is at the heart of the American dream.\n\n**Part 2 – An \"I\" that had to be conquered.** However, whereas Document A presents the \"I\" as natural, Document B shows that it was denied to some: the young poet was told her language \"was wrong\". Writing becomes a political act and a claim to belong (\"I am part of this country too\"). This echoes Langston Hughes and the Harlem Renaissance in the 1920s, Zora Neale Hurston, who turned vernacular language into literature in *Their Eyes Were Watching God* (1937), or Maya Angelou's memoir (1969). Du Bois's *double consciousness* explains this tension: one sees oneself through the eyes of a society that excludes you. Therefore, the voices from the margins do not reject the founding \"I\": they use it to contest the dream from within.\n\n**Conclusion.** The American self was first written by those who could take their place for granted; its contestation is personal too, insofar as saying \"I\" is already taking a stand.\n\nLe correcteur valorise : la problématique annoncée puis reprise ; le dialogue explicite entre A et B (connecteurs d'opposition) ; des références exactes ; une langue simple et juste plutôt que brillante et fautive."}$exo$::jsonb),
  ('5bebdf5b-9432-5b85-870a-0c3f83dfcab2'::uuid, 1, 'traduction', $exo${"titre":"Arriving at Ellis Island","consigne":"Traduis le passage en français, puis réponds à la question de vocabulaire.","enonce":"**Document (invented letter from a young migrant, 1907).**\n\n> Dear Mother, we arrived at Ellis Island yesterday morning after twelve days at sea. We waited for hours in a huge hall, surrounded by people speaking languages I had never heard. A doctor looked at my eyes and a man asked me my name. Tonight I am sleeping in New York, but my heart is still at home.\n\n1. Translate the letter into French.\n2. Give the French translation of these words from the course and use **two** of them in an English sentence about this letter: *uprooting*, *homeland*, *belonging*, *diaspora*.","bareme":[{"critere":"Sens fidèle de la lettre, sans contresens (after twelve days at sea, I had never heard, my heart is still at home)","points":8},{"critere":"Français correct et naturel, temps cohérents","points":5},{"critere":"Quatre mots traduits justement et deux réemployés dans une phrase anglaise correcte","points":7}],"dureeMin":8,"corrige":"1. Traduction proposée :\n« Chère maman, nous sommes arrivés à Ellis Island hier matin, après douze jours en mer. Nous avons attendu pendant des heures dans une immense salle, entourés de gens qui parlaient des langues que je n'avais jamais entendues. Un médecin m'a examiné les yeux et un homme m'a demandé mon nom. Ce soir, je dors à New York, mais mon cœur est resté au pays. »\nPoints de vigilance : *after twelve days at sea* → « après douze jours en mer » ; *languages I had never heard* → plus-que-parfait « que je n'avais jamais entendues » ; *my heart is still at home* → « mon cœur est resté / est encore au pays ».\n2. *uprooting* = **déracinement** ; *homeland* = **patrie, pays d'origine** ; *belonging* = **appartenance** ; *diaspora* = **diaspora** (dispersion d'une population hors de son territoire d'origine).\nExemple : *The letter expresses the pain of* **uprooting**: *the young migrant is in New York, but his* **homeland** *is still in his heart.*"}$exo$::jsonb),
  ('5bebdf5b-9432-5b85-870a-0c3f83dfcab2'::uuid, 2, 'traduction', $exo${"titre":"Melting pot or salad bowl?","consigne":"Rédige en anglais un paragraphe argumenté d'environ 150 mots.","enonce":"**Document (invented interview).**\n\n> \"My grandparents changed their name when they arrived in America. They stopped speaking their language at home, because they wanted their children to be 'real Americans'. My parents made the opposite choice: we speak two languages, we cook the dishes of our grandparents, and I have never felt less American for it.\" — Daniela, 17\n\n**Task.** In about 150 words:\n1. explain the two metaphors used to describe what becomes of migrants in America (*melting pot* and *salad bowl*): what each one asserts and what it assumes;\n2. show which generation of Daniela's family illustrates each metaphor;\n3. give your own opinion, using at least one reference from the course (Ellis Island, or a novel about the second generation).","bareme":[{"critere":"Les deux métaphores expliquées : ce qu'elles affirment et ce qu'elles supposent","points":6},{"critere":"Application juste au document (grands-parents = melting pot, parents = salad bowl)","points":5},{"critere":"Opinion argumentée avec au moins une référence exacte du cours","points":4},{"critere":"Anglais correct, connecteurs, longueur respectée","points":5}],"dureeMin":12,"corrige":"Éléments attendus :\n- ***Melting pot*** : tout fond dans un alliage commun ; elle suppose que **l'assimilation est la condition d'entrée**.\n- ***Salad bowl*** : chacun garde sa saveur dans le plat ; elle suppose que **la différence n'empêche pas l'appartenance**.\n- Les **grands-parents** (changement de nom, abandon de la langue) illustrent le *melting pot* ; les **parents** (bilinguisme, cuisine transmise, sentiment d'être pleinement américaine) illustrent le *salad bowl*.\n\nExemple de paragraphe :\n*Two metaphors describe what becomes of migrants in America. The melting pot asserts that all cultures melt into a common alloy, which assumes that assimilation is the price of entry. Daniela's grandparents followed this model: they changed their name and gave up their language. Whereas the melting pot erases differences, the salad bowl claims that each culture keeps its own flavour, since difference does not prevent belonging. Daniela's parents chose this path, and she has \"never felt less American\". In my opinion, the salad bowl is closer to today's reality. Jhumpa Lahiri's novel* The Namesake *(2003) shows a second generation living between two belongings: it is difficult, however it is not a failure to belong. Therefore, being American no longer means forgetting where one comes from, as it often did for the millions who passed through Ellis Island between 1892 and 1954.*"}$exo$::jsonb),
  ('5bebdf5b-9432-5b85-870a-0c3f83dfcab2'::uuid, 3, 'traduction', $exo${"titre":"What is a border?","consigne":"Rédige en anglais une mini-synthèse d'environ 250 mots : dégage une problématique et fais dialoguer les documents avec tes connaissances du cours.","enonce":"**Document A (invented news report).**\n\n> On the road between two Irish villages, nothing marks the border: no wall, no checkpoint, just a change in the colour of the road signs. Yet since the Brexit vote, local farmers wonder whether they will one day need papers to sell their milk on the other side.\n\n**Document B (invented testimony).**\n\n> \"I came to Britain as a child in the 1960s, with my mother, on her British passport. I went to school here, I worked here all my life. Then one day a letter told me I had no right to be here. I had not moved. The border had moved.\" — Winston, 68\n\n**Task.** Write a short synthesis (about 250 words) in English:\n1. an introduction with a clear problem;\n2. a development in two parts that makes the documents dialogue, using at least **two** references from the course (borders today, empire and colonisation, migration);\n3. a short conclusion answering the problem.","bareme":[{"critere":"Problématique claire sur la nature de la frontière, tenue jusqu'à la conclusion","points":5},{"critere":"Documents compris et mis en dialogue : frontière invisible (Irlande) et frontière juridique (Windrush)","points":5},{"critere":"Au moins deux références exactes du cours (mur mexicain, Brexit, génération Windrush, Empire…)","points":4},{"critere":"Idée centrale : une frontière est un dispositif juridique et un imaginaire, elle peut se déplacer sans que la carte change","points":3},{"critere":"Anglais correct, connecteurs variés, structure et longueur respectées","points":3}],"dureeMin":20,"corrige":"**Problématique possible :** *Is a border only a line on a map?*\n\n**Part 1 – A border can be invisible, and still be a problem.** Document A describes the Irish border as almost invisible: nothing marks it on the road. However, Brexit has turned this invisible border into a political problem again: trade and movement may be controlled once more. Whereas the wall on the Mexican border shows the border as a physical and political device, the Irish case shows that a border exists even when it cannot be seen.\n\n**Part 2 – A border can move without the map changing.** Document B goes further. Winston never crossed any line, yet \"the border had moved\": like the **Windrush generation**, British citizens who arrived from the former Empire were made illegal retroactively. The border here is a **legal device** — a matter of papers, status and citizenship — rather than a place. This is a legacy of the British Empire, which once covered a quarter of the earth's land: people from its colonies came to live in Britain, and later found that belonging was not guaranteed.\n\n**Conclusion.** A border is therefore not only a line: it is a **legal device** and an **imaginary**. That is why it can move without the map changing, and why it shapes lives even when it is invisible.\n\nLe correcteur valorise : une problématique reprise dans la conclusion ; le dialogue explicite entre A et B ; l'emploi juste de *border*, *citizenship*, *belonging*, *homeland* ; des références exactes, sans invention de dates ni de chiffres."}$exo$::jsonb),
  ('bc890172-e120-5718-9825-d10397ef290e'::uuid, 1, 'traduction', $exo${"titre":"Know your exam","consigne":"Réponds en anglais, en phrases complètes.","enonce":"1. How long does the written LLCER exam last in *terminale*? What are its two parts, and how long should the synthesis be?\n2. How long does the oral exam last? What does it consist of?\n3. Complete each sentence with the right connector: *however*, *whereas*, *therefore*.\n   a. The first document celebrates the individual, ______ the second one criticises him.\n   b. The synthesis must follow a problem; ______, a plan in three blocks \"document 1, 2, 3\" is off topic.\n   c. The student knew the works well; ______, she lost points because she misread the instructions.","bareme":[{"critere":"Écrit : 3 h 30, synthèse d'un dossier de trois documents (environ 500 mots) puis traduction ou transposition","points":8},{"critere":"Oral : 20 minutes, présentation d'un dossier personnel puis entretien avec le jury","points":6},{"critere":"Trois connecteurs justes : whereas, therefore, however","points":6}],"dureeMin":7,"corrige":"1. *The written exam lasts* **3 hours 30 minutes**. *The first part is a* **synthesis** *in English of a file of* **three documents**, *about* **500 words** *long; the second part is a* **translation** *or a* **transposition** *of a short passage.*\n2. *The oral exam lasts* **20 minutes**. *The candidate presents a* **personal file** *of documents studied during the year, then has an* **interview with the jury**.\n3. a. **whereas** (opposition between two things at the same time).\n   b. **therefore** (consequence).\n   c. **however** (opposition / concession)."}$exo$::jsonb),
  ('bc890172-e120-5718-9825-d10397ef290e'::uuid, 2, 'traduction', $exo${"titre":"Fixing a failed synthesis plan","consigne":"Lis le plan d'élève, explique en anglais ce qui ne va pas, puis propose un plan corrigé.","enonce":"**The file.** Three documents on the theme *Identity and the self*: an extract from an American essay praising self-reliance; a poem by a young writer of the second generation of migrants; a photograph of a crowd at a 1960s civil rights march.\n\n**Lucie's plan.**\n\n> Introduction: I present the three documents.\n> Part 1: Document 1 is about self-reliance.\n> Part 2: Document 2 is a poem about two cultures.\n> Part 3: Document 3 shows a march.\n> Conclusion: The three documents are about identity.\n\n1. Explain in English why this plan would be considered off topic, even if the English were perfect.\n2. Write a problem (*problématique*) that could link the three documents.\n3. Propose a new plan in two or three parts, where each part uses several documents. Use at least two connectors from the course.","bareme":[{"critere":"Défaut expliqué : résumé successif sans problématique commune, documents qui ne dialoguent pas","points":6},{"critere":"Problématique pertinente reliant les trois documents","points":5},{"critere":"Plan croisé où chaque partie mobilise plusieurs documents","points":6},{"critere":"Anglais correct et connecteurs justes (however, whereas, therefore, insofar as)","points":3}],"dureeMin":12,"corrige":"1. *Lucie's plan summarises the documents one after the other. A synthesis is not a successive summary: it must bring out a* **common problem** *and make the documents* **dialogue**. *A plan in three blocks \"document 1, document 2, document 3\" is off topic, even if it is well written, and her conclusion only repeats the theme instead of answering a question.*\n2. Exemple de problématique : *Is identity something one builds alone, or something one conquers with and against others?*\n3. Exemple de plan :\n- **I. Building oneself alone**: *the essay praises self-reliance (doc 1); however, the poem (doc 2) shows that a young writer cannot define herself without her two cultures.*\n- **II. Claiming an identity together**: *whereas doc 1 focuses on the individual, the photograph (doc 3) shows a collective voice; the poem (doc 2) also speaks for a whole generation.*\n- **III. (optional) A personal voice that becomes political**: *saying \"I\" is taking a stand, insofar as some were denied that right; therefore the three documents answer each other.*\nChaque partie croise au moins deux documents ; la conclusion répond à la problématique."}$exo$::jsonb),
  ('bc890172-e120-5718-9825-d10397ef290e'::uuid, 3, 'traduction', $exo${"titre":"Introduction and plan under time pressure","consigne":"En temps limité, rédige en anglais l'introduction complète d'une synthèse et son plan détaillé.","enonce":"**The file (theme: Travels, territories, borders).**\n\n- **Document A**: an extract from a novel in which a colonial officer describes his arrival in a village as \"bringing civilisation\".\n- **Document B**: an extract from a novel written by an African author, telling the arrival of the same kind of officers from the villagers' point of view.\n- **Document C**: a newspaper article about people who arrived in Britain from the Caribbean after the Second World War and were later told they had no right to stay.\n\n**Task.**\n1. Write the full introduction of the synthesis in English (about 120 words): a hook, a presentation of the file, a problem, and the announcement of the plan.\n2. Write a detailed plan in two or three parts: for each part, give its main idea and the documents it combines, and one reference from the course that could enrich it.\n3. In two sentences, explain what the jury looks at first in a synthesis, according to the course.","bareme":[{"critere":"Introduction complète : accroche, présentation du dossier, problématique, annonce du plan","points":6},{"critere":"Problématique qui relie les trois documents (le récit impérial et son renversement, la frontière qui se déplace)","points":4},{"critere":"Plan croisé et cohérent, chaque partie combinant plusieurs documents avec une référence exacte du cours","points":5},{"critere":"Critères du jury restitués : problématique qui tient, connecteurs, langue correcte, exemples précis","points":2},{"critere":"Anglais correct et connecteurs variés","points":3}],"dureeMin":20,"corrige":"1. Exemple d'introduction :\n*\"The sun never sets on the British Empire\": this famous phrase sums up the pride of an empire that once covered a quarter of the earth's land. The three documents of this file look at that history from different sides: a colonial officer who claims to bring civilisation (A), villagers who see the same arrival from the other shore (B), and a newspaper article on Caribbean migrants later told they had no right to stay in Britain (C). Who tells the story of empire, and what is left of it today? We will first see how the imperial narrative is rewritten by the colonised, then how its borders still shape lives long after its end.*\n2. Exemple de plan :\n- **I. One arrival, two stories (A and B)**: *the officer's \"civilisation\" versus the villagers' point of view; postcolonial literature rewrites the imperial narrative.* Référence : Chinua Achebe, *Things Fall Apart* (1958), l'arrivée des colons vue du village igbo.\n- **II. The legacy of empire: belonging in question (B and C)**: *the colonised became citizens and migrants; however, belonging was not guaranteed.* Référence : la génération Windrush, citoyens britanniques rendus illégaux rétroactivement.\n- **III. (optional) A border that moves (A and C)**: *a border is a legal device and an imaginary, it can move without the map changing.* Référence : le Brexit et la frontière irlandaise.\n3. *The jury first looks at the* **problem**: *it must hold from the beginning to the end and not be decorative. Then it values varied, correct connectors, correct English before brilliant English, and precise rather than numerous examples.*"}$exo$::jsonb),
  ('ad15b82e-d413-5ee2-9631-49ba82ebfcc7'::uuid, 1, 'traduction', $exo${"titre":"Satire and protest: the key notions","consigne":"Réponds en anglais aux questions 1 et 2 (phrases complètes), puis traduis les expressions de la question 3.","enonce":"**Committed art: what do you know?**\n\n1. Define **satire** and **irony** in two or three sentences. Then explain why Jonathan Swift’s *A Modest Proposal* (1729) is a good example of both.\n\n2. For each work below, give its author (or performer) and say in one sentence **what it denounces**:\n   - a. *Gin Lane* (1751)\n   - b. *The Jungle* (1906)\n   - c. *Strange Fruit* (1939)\n   - d. *The Grapes of Wrath* (1939)\n\n3. Translate into English: **dénoncer** · **une chanson engagée** · **sensibiliser** · **l’art engagé**.","bareme":[{"critere":"Satire et ironie définies correctement, exemple de Swift expliqué (proposition de manger les enfants des pauvres, ton impassible)","points":8},{"critere":"Quatre œuvres attribuées à leur auteur avec leur cible exacte","points":8},{"critere":"Quatre traductions justes (to denounce/condemn, a protest song, to raise awareness, committed/engaged art)","points":4}],"dureeMin":8,"corrige":"**1. Model answer**\n*Satire attacks a vice or an injustice by making it ridiculous. Its main weapon is irony: saying the opposite of what you think and counting on the reader to restore the real meaning. In A Modest Proposal, Swift calmly “proposes” that the children of the poor Irish should be eaten by the rich. The narrator calculates and argues without emotion, and this deadpan tone makes the horror of Irish poverty visible.*\n\nÀ trouver : définition de la satire (rendre ridicule pour faire honte), de l’ironie (dire le contraire de ce qu’on pense), la « proposition » de Swift, et l’idée d’ironie **impassible**.\n\n**2.**\n- a. *Gin Lane* — William Hogarth (engraving): the ravages of gin/alcohol in the poor districts of London.\n- b. *The Jungle* — Upton Sinclair (novel): working conditions in the Chicago slaughterhouses (the scandal led to a food-hygiene law).\n- c. *Strange Fruit* — Billie Holiday (song): lynchings in the American South; the “strange fruit” are hanged bodies.\n- d. *The Grapes of Wrath* — John Steinbeck (novel): the exodus of ruined farmers to California.\n\n2 points par œuvre (1 pour l’auteur, 1 pour la cible).\n\n**3.** dénoncer → *to denounce* (ou *to condemn*) · une chanson engagée → *a protest song* · sensibiliser → *to raise awareness* · l’art engagé → *committed art* (ou *engaged art*). 1 point chacune."}$exo$::jsonb),
  ('ad15b82e-d413-5ee2-9631-49ba82ebfcc7'::uuid, 2, 'traduction', $exo${"titre":"A protest song from a mill town","consigne":"Lis la chanson (texte inventé pour l’exercice), puis analyse-la en anglais en suivant les quatre étapes de la méthode du cours. Environ 150 mots.","enonce":"**Document — *Thank You, Sir* (protest song, invented for this test)**\n\n> Thank you, sir, for the twelve-hour day,\n> Thank you, sir, for the shilling pay,\n> My little girl coughs by the spinning wheel —\n> Thank you, sir, it’s a generous deal.\n> Your house on the hill has a hundred lights,\n> Ours has a candle for winter nights.\n> So raise your glass, and we’ll raise ours too:\n> An empty glass, sir. Thank you.\n\n**Task.** Write an analysis of about 150 words in English. Follow the method:\n1. **The target**: who or what is denounced?\n2. **The device**: which procédé(s) does the song use? Quote the text.\n3. **The audience**: who is the song trying to convince?\n4. **The effect**: what could such a song change? Compare briefly with **one** protest song studied in class.","bareme":[{"critere":"Cible identifiée : le patron d’usine, l’exploitation des ouvriers (journées de 12 h, salaire, travail des enfants)","points":4},{"critere":"Ironie repérée et expliquée (thank you, generous deal) avec citations ; contraste riche/pauvre ou pathos de l’enfant qui tousse","points":6},{"critere":"Destinataire et effet discutés, comparaison pertinente avec une chanson du cours","points":5},{"critere":"Anglais correct, connecteurs, environ 150 mots","points":5}],"dureeMin":12,"corrige":"**Model answer (about 150 words)**\n\n*This song denounces the exploitation of mill workers by a rich factory owner, the “sir” of the title: twelve-hour days, a miserable “shilling pay” and even child labour (“My little girl coughs by the spinning wheel”). Its main device is irony. The workers keep saying “thank you” and call their situation “a generous deal”, which means exactly the opposite: they are thanking the man who ruins them. The song also relies on pathos, with the sick child, and on a sharp contrast between the “hundred lights” of the owner’s house and the single “candle” of the workers. The audience is double: the workers, who can sing it together, and the public, whose awareness it wants to raise. Like Billie Holiday’s Strange Fruit, which uses the image of “strange fruit” to denounce lynchings, it turns a simple image into an accusation, and may push opinion to demand better laws.*\n\n**Points attendus**\n- Cible : le patron / le système de l’usine, l’exploitation.\n- Procédé : **ironie** (dire le contraire), répétition de *thank you*, **pathos** (l’enfant), **contraste/symbole** (lumières / bougie, verre vide).\n- Destinataire : ouvriers et opinion publique ; *to raise awareness*.\n- Effet : sensibiliser, créer un scandale, peser sur une loi (comme *The Jungle* a mené à une loi sur l’hygiène alimentaire).\n- Comparaison acceptée avec *Strange Fruit*, *Mississippi Goddam* ou *Blowin’ in the Wind*, à condition que ce qui en est dit soit exact."}$exo$::jsonb),
  ('ad15b82e-d413-5ee2-9631-49ba82ebfcc7'::uuid, 3, 'traduction', $exo${"titre":"Laughing, painting, singing: three ways to protest","consigne":"Rédige en anglais une synthèse d’environ 250 mots qui croise les trois documents (textes et description inventés pour l’exercice) et s’appuie sur les œuvres du cours.","enonce":"**Document A — A satirical newspaper column (invented)**\n\n> The City Council has at last found a solution to homelessness: from Monday, benches in the park will be fitted with metal spikes. The homeless, we are told, will sleep far more comfortably on the pavement, where the view is better. The Council estimates that this bold reform will cost only £40,000 — a small price for the pleasure of never seeing a poor person again.\n\n**Document B — Description of a stencil (invented)**\n\nOn a wall near a train station, an anonymous artist has sprayed a black-and-white stencil: a child in a school uniform holds a balloon shaped like a house; the string is being cut by a pair of giant scissors held by a hand wearing a gold ring. Nobody commissioned it. The caption reads: “Rent due.”\n\n**Document C — A singer interviewed (invented)**\n\n> “I don’t write songs to win arguments. I write them so that people who never thought about eviction suddenly feel it in their stomach.”\n\n**Consigne.** *Show how the three documents denounce the same injustice with different weapons, and discuss what makes committed art effective. Refer to at least one work studied in class.*","bareme":[{"critere":"Les trois documents croisés (pas présentés l’un après l’autre), nommés doc. A, B, C, avec de brèves citations","points":5},{"critere":"Procédés distingués : ironie impassible (A), symbole et support non commandé (B), émotion/pathos (C)","points":5},{"critere":"Réflexion sur l’efficacité (cible, destinataire, effet) et renvoi exact à au moins une œuvre du cours (Swift, Banksy, Holiday…)","points":5},{"critere":"Anglais riche et correct, connecteurs, introduction et conclusion, environ 250 mots","points":5}],"dureeMin":20,"corrige":"**Model synthesis (about 250 words)**\n\n*All three documents denounce the same injustice, the fate of the poor who lose their homes, but each uses a different weapon.*\n\n*The newspaper column (doc. A) relies on irony. Like Jonathan Swift in A Modest Proposal (1729), the writer pretends to approve of a cruel measure and describes it calmly, with figures (“only £40,000”). The deadpan tone makes the absurdity obvious: the “bold reform” is only a way of “never seeing a poor person again”.*\n\n*Whereas doc. A makes us laugh, the stencil (doc. B) speaks through a symbol. The balloon shaped like a house suggests that a home is fragile, and the hand with a gold ring points at the rich who cut the string. Like Banksy’s stencils, it appears on a wall that nobody commissioned: the street itself becomes a place of denunciation, visible to everyone.*\n\n*The singer (doc. C), on the other hand, rejects argument and chooses emotion: she wants people to “feel it in their stomach”. This recalls Billie Holiday’s Strange Fruit (1939), which turns lynchings into a haunting image.*\n\n*What makes committed art effective, then? All three documents target an audience that does not yet care and try to raise awareness. Yet their effects differ: satire shames the powerful, the image strikes passers-by, the song moves the listener. All in all, committed art works when its form makes an injustice impossible to ignore.*\n\n**Points attendus** : croisement des documents dès l’introduction ; ironie impassible (A) rapprochée de Swift ; symbole et mur non commandé (B) rapproché de Banksy ; pathos (C) ; méthode cible / procédé / destinataire / effet ; connecteurs (*whereas, like, on the other hand, yet, all in all*)."}$exo$::jsonb),
  ('0d8ff6f5-24d4-508e-ad5e-f6d97cc33e79'::uuid, 1, 'traduction', $exo${"titre":"Art on trial: key dates and arguments","consigne":"Réponds en anglais, en phrases complètes.","enonce":"**Banned, tried, defended**\n\n1. What happened to James Joyce’s *Ulysses* in the United States in 1922 and in **1933**? And to D. H. Lawrence’s *Lady Chatterley’s Lover* in **1960**? Which argument saved both books?\n\n2. What was the **Hays Code**? Give its dates, two things it forbade, and explain how film-makers adapted to it.\n\n3. Give **two arguments** used to limit what art can show and **two arguments** used to protect it.","bareme":[{"critere":"Ulysses interdit (1922) puis déclaré non obscène (1933, juge Woolsey), Penguin acquitté (1960), argument de la valeur littéraire","points":8},{"critere":"Code Hays : 1934-1968, interdits (crime impuni, nudité…), cinéastes qui suggèrent (fondu enchaîné)","points":6},{"critere":"Deux arguments pour limiter et deux pour protéger, exacts et en anglais correct","points":6}],"dureeMin":8,"corrige":"**1.** *Ulysses was banned in the United States when it came out in 1922. In 1933, Judge Woolsey declared that it was not obscene. In 1960, the publisher Penguin was acquitted in the Lady Chatterley’s Lover trial, and the novel sold millions of copies. In both cases, the argument that saved the book was its literary value: it justified what the book showed.*\n\n**2.** *The Hays Code was applied in Hollywood from 1934 to 1968. It forbade showing crime going unpunished, nudity and certain subjects. Film-makers learnt to suggest instead of showing: a dissolve (fade) could replace a scene. It was later replaced by the age-rating system.*\n\n**3.** *To limit: protecting young people; respecting beliefs; public order. To protect: freedom of speech (the First Amendment in the United States); art must be able to shock in order to make people think; yesterday’s censor looks ridiculous tomorrow.*\n\nDeux arguments exacts de chaque côté suffisent."}$exo$::jsonb),
  ('0d8ff6f5-24d4-508e-ad5e-f6d97cc33e79'::uuid, 2, 'traduction', $exo${"titre":"Should the school library ban this novel?","consigne":"Lis la lettre (inventée pour l’exercice), puis rédige en anglais une réponse argumentée d’environ 150 mots, en suivant la méthode « entrer dans une polémique ».","enonce":"**Document — Letter to a local newspaper (invented)**\n\n> Dear Editor,\n> Last week my fourteen-year-old son brought home a novel from the school library. It describes violence and bad language on almost every page. I do not want my taxes to pay for books that corrupt children. Parents have a right to protect their families. This novel must be removed from the library at once.\n> — A worried father\n\n**Task.** Write a reply to the editor (about 150 words, in English). You must:\n1. **identify the two camps** and what each one speaks in the name of;\n2. **distinguish** what a book shows from what it is accused of;\n3. use at least **two arguments** from the debate studied in class and **one historical example** of a trial;\n4. **conclude with nuance**.","bareme":[{"critere":"Camps identifiés (parent qui veut protéger la jeunesse / défenseurs de la liberté d’expression)","points":4},{"critere":"Distinction entre ce que l’œuvre montre et ce qu’on lui reproche ; arguments du cours réemployés","points":6},{"critere":"Exemple historique exact (Ulysses 1933, Lady Chatterley 1960, Howl 1957…) et conclusion nuancée","points":5},{"critere":"Anglais correct, registre de la lettre, vocabulaire du chapitre (to ban, censorship, freedom of speech…)","points":5}],"dureeMin":12,"corrige":"**Model reply (about 150 words)**\n\n*Dear Editor,*\n*I understand the worried father who wrote last week. He speaks in the name of protecting young people, which is a real concern. But those who defend the library speak in the name of freedom of speech, which matters just as much.*\n\n*We must distinguish what a novel shows from what it is accused of: describing violence is not approving of it. Art must sometimes shock in order to make us think. History also shows that yesterday’s censor often looks ridiculous today. Joyce’s Ulysses was banned in the United States before a judge declared it not obscene in 1933, and Penguin was acquitted in 1960 for publishing Lady Chatterley’s Lover, because these books had literary value.*\n\n*Banning a book would only spark a debate and make it more attractive. Perhaps the answer is not a ban but a conversation: teachers and parents could read it with the children. Standards change with time.*\n\n**Points attendus** : les deux camps et ce au nom de quoi ils parlent ; la distinction œuvre / réception ; au moins deux arguments du tableau (protéger la jeunesse, respecter les croyances, ordre public / liberté d’expression, choquer pour faire penser, le censeur ridicule demain) ; un exemple exact ; une conclusion nuancée (les critères changent avec les époques)."}$exo$::jsonb),
  ('0d8ff6f5-24d4-508e-ad5e-f6d97cc33e79'::uuid, 3, 'traduction', $exo${"titre":"Who decides what art may show?","consigne":"Rédige en anglais une synthèse d’environ 250 mots croisant les trois documents (inventés pour l’exercice) et tes connaissances du chapitre.","enonce":"**Document A — Extract from a play about a trial (invented)**\n\n> PROSECUTOR. Would you give this book to your daughter?\n> WITNESS (a professor). I would give it to her when she is ready to read it — as I would give her Shakespeare.\n> PROSECUTOR. Shakespeare did not write such words.\n> WITNESS. Shakespeare wrote worse. We simply stopped noticing.\n\n**Document B — An old film critic remembers (invented)**\n\n> “In the films of my youth, the lovers kissed, the picture faded, and the next scene began. We were not shown anything, and we understood everything.”\n\n**Document C — From an art magazine (invented)**\n\n> “When a painting partly shredded itself at an auction, the public laughed at the buyer. Then its price went up. The scandal had become part of the work.”\n\n**Consigne.** *Using the three documents and the examples studied in class, show who decides what art is allowed to show, and how the answer changes over time.*","bareme":[{"critere":"Documents croisés et nommés : procès et argument de la valeur littéraire (A), code et art de suggérer (B), scandale intégré à l’œuvre (C)","points":6},{"critere":"Exemples du cours exacts et bien reliés (Woolsey 1933, Penguin 1960, Code Hays 1934-1968, Girl with Balloon de Banksy…)","points":5},{"critere":"Réflexion sur les acteurs (juges, censeurs, public, marché) et sur l’évolution des critères, conclusion nuancée","points":5},{"critere":"Anglais riche et correct, connecteurs, environ 250 mots","points":4}],"dureeMin":20,"corrige":"**Model synthesis (about 250 words)**\n\n*The three documents show that the question “what may art show?” has been answered by very different people: judges, censors and, finally, the public itself.*\n\n*In doc. A, a trial becomes the place where literature is judged. The prosecutor fears for young readers, while the professor defends the book in the name of its literary value and compares it to Shakespeare. This is exactly the argument that saved Joyce’s Ulysses, declared not obscene by Judge Woolsey in 1933, and Lady Chatterley’s Lover, whose publisher Penguin was acquitted in 1960.*\n\n*Doc. B moves from the courtroom to the film studio. The critic remembers a time when the picture “faded” instead of showing a love scene. This echoes the Hays Code, applied in Hollywood from 1934 to 1968: censorship did not make desire disappear, it taught film-makers to suggest. Paradoxically, “we understood everything”.*\n\n*Doc. C, however, shows a later situation in which the scandal is no longer a punishment but an asset. Like Banksy’s Girl with Balloon, which partly destroyed itself after its sale in 2018 and gained value, the work uses controversy as a material.*\n\n*In short, those who decide change with time: the judge, then the censor, then the market and the public. What shocked yesterday often seems harmless today, which is why the critic can smile. Yet the debate between protecting and freeing remains open.*\n\n**Points attendus** : croisement ; valeur littéraire ; Code Hays et suggestion ; scandale récupéré par le marché ; idée que les critères changent avec les époques ; connecteurs (*while, however, paradoxically, in short, yet*)."}$exo$::jsonb),
  ('4536204e-6ca9-5503-a353-90734005fe75'::uuid, 1, 'traduction', $exo${"titre":"Ethos, pathos, logos and the figures of speech","consigne":"Réponds en anglais. Pour la question 2, nomme la figure ET explique-la en une phrase.","enonce":"**The tools of persuasion**\n\n1. Define Aristotle’s three levers: **ethos**, **pathos** and **logos** (one sentence each).\n\n2. The four sentences below come from an invented speech by a student candidate. Name the **figure of speech** used in each one and explain it.\n   - a. “We will work harder, we will listen better, we will fight longer.”\n   - b. “Do we really want another year of silence?”\n   - c. “A school for students, students for the school.”\n   - d. “Ideas that unite, a voice that listens, a team that acts.”\n\n3. For sentence b, say which of the three levers it mostly appeals to, and why.","bareme":[{"critere":"Ethos (crédibilité), pathos (émotions), logos (logique, faits) définis correctement","points":6},{"critere":"Figures identifiées : anaphore (a), question rhétorique (b), chiasme (c), tricolon (d) — avec une explication","points":10},{"critere":"Levier de la phrase b justifié (pathos : frustration, désir de changement), anglais correct","points":4}],"dureeMin":8,"corrige":"**1.** *Ethos is the credibility of the speaker (“As a mother, as a doctor…”). Pathos appeals to the emotions of the audience. Logos relies on logic and facts: figures, reasoning.*\n\n**2.**\n- a. *Anaphora: “we will” is repeated at the beginning of each clause, which creates rhythm and determination.*\n- b. *Rhetorical question: no answer is expected, the answer (“no”) is obvious to the audience.*\n- c. *Chiasmus: a crossed structure A-B / B-A (school – students / students – school).*\n- d. *Tricolon: a series of three parallel groups, which sounds complete and memorable.*\n\n(Accepter aussi « tricolon » en plus d’« anaphore » pour la phrase a : c’est une série de trois ; mais l’anaphore doit être nommée.)\n\n**3.** *Sentence b mostly appeals to pathos: “another year of silence” plays on the audience’s frustration and makes them want change, rather than proving something with facts.*"}$exo$::jsonb),
  ('4536204e-6ca9-5503-a353-90734005fe75'::uuid, 2, 'traduction', $exo${"titre":"Analysing a speech for the planet","consigne":"Lis le discours (inventé pour l’exercice) et analyse-le en anglais en suivant les quatre étapes de la méthode du cours (environ 150 mots).","enonce":"**Document — Speech by Maya, 17, at a town council meeting (invented)**\n\n> Good evening. My name is Maya. I am not an expert, I am not a politician — I am the person who will still live in this town in 2080.\n> Last year, the river flooded three times. Three times! The council spent £200,000 on repairs, and nothing on prevention.\n> My little brother asked me if our house would float away. What do you answer a six-year-old?\n> We can wait, we can talk, we can hope. Or we can act.\n> Ask not what the river will cost us — ask what our silence will cost the river.\n\n**Task.** Analyse this speech in about 150 words:\n1. **Context**: who speaks, to whom, why?\n2. **Structure**: how does it progress?\n3. **Devices**: ethos, pathos, logos and at least **two** figures of speech (quote them).\n4. **Effect**: what is the speaker trying to change?","bareme":[{"critere":"Contexte et structure dégagés (présentation, faits, anecdote, climax, appel final)","points":5},{"critere":"Les trois leviers repérés avec citations (ethos modeste, logos chiffré, pathos du petit frère)","points":6},{"critere":"Au moins deux figures nommées et citées (tricolon/anaphore, question rhétorique, chiasme imitant Kennedy)","points":5},{"critere":"Anglais correct, environ 150 mots, effet visé expliqué","points":4}],"dureeMin":12,"corrige":"**Model answer (about 150 words)**\n\n*Maya, a 17-year-old, speaks to the town council to convince them to invest in flood prevention. Her speech moves from a presentation of herself to facts, then to a personal story, and ends with a call to action.*\n\n*She builds a modest but strong ethos: she is “not an expert”, but she will “still live in this town in 2080”, so she has a right to speak. She then uses logos: the river flooded “three times” and £200,000 was spent on repairs, “nothing on prevention”. Pathos follows with her little brother’s question, a rhetorical question she leaves unanswered. The anaphora and tricolon “We can wait, we can talk, we can hope” prepares the climax “Or we can act”. Her last sentence is a chiasmus imitating Kennedy’s “Ask not what your country can do for you”, which gives her words historical weight. Her aim is to sway the council from talking to acting.*\n\n**Points attendus** : contexte ; progression ; ethos / logos / pathos avec citations ; figures (anaphore, tricolon, question rhétorique, chiasme, écho de Kennedy) ; effet (faire basculer — *to sway* — la décision du conseil)."}$exo$::jsonb),
  ('4536204e-6ca9-5503-a353-90734005fe75'::uuid, 3, 'traduction', $exo${"titre":"Turning a crowd, turning a jury","consigne":"Rédige en anglais un essai d’environ 250 mots qui croise les deux documents et le film au programme.","enonce":"**Document A — Shakespeare, *Julius Caesar* (c. 1599)**\n\nAfter Caesar’s murder, Mark Antony addresses the Roman crowd. He begins with “Friends, Romans, countrymen, lend me your ears” and keeps repeating that Brutus, one of the murderers, is “an honourable man” — until the phrase means its opposite and the crowd turns against Brutus.\n\n**Document B — A jury room (scene invented for this test)**\n\n> JUROR 3 (shouting). It’s obvious! The kid did it! Everybody heard him threaten his father!\n> JUROR 5 (quietly). Everybody? The woman across the street said she heard it through a closed window, with a train passing. Could you hear anything with a train passing?\n> (Silence. Juror 3 sits down.)\n\n**Consigne.** *Is persuasion a matter of loud voices? Compare the strategies of Mark Antony (doc. A), of Juror 5 (doc. B) and of Juror 8 in Sidney Lumet’s* 12 Angry Men *(1957).*","bareme":[{"critere":"Document A analysé : répétition ironique de « an honourable man », retournement de la foule, pathos","points":5},{"critere":"Document B analysé : question qui installe le doute, logos contre voix forte, silence final","points":4},{"critere":"12 Angry Men mobilisé avec exactitude (11 contre 1, doute raisonnable, écoute, huis clos, préjugés)","points":6},{"critere":"Essai construit (introduction, parties croisées, conclusion nuancée), anglais riche, environ 250 mots","points":5}],"dureeMin":20,"corrige":"**Model essay (about 250 words)**\n\n*Persuasion is often imagined as a battle of loud voices. The documents suggest that it is rather an art of timing, questions and doubt.*\n\n*In Julius Caesar (doc. A), Mark Antony never attacks Brutus openly. He flatters the crowd (“Friends, Romans, countrymen”) and repeats that Brutus is “an honourable man” until the words become ironic. His strength lies in pathos and irony: he lets the crowd reach the conclusion by itself, which is why it turns so violently.*\n\n*Juror 5 in doc. B uses a different weapon: logos. Whereas Juror 3 shouts that “the kid did it”, Juror 5 asks a simple question about the train. He does not claim that the boy is innocent; he shows that a piece of evidence is fragile. The silence that follows proves that a quiet question can defeat a loud certainty.*\n\n*This is exactly the method of Juror 8 (Henry Fonda) in 12 Angry Men. At the first vote, eleven jurors vote guilty. He does not say the young man is innocent; he says he has a reasonable doubt, and he sways the others one by one through arguments and questions. The film also shows that prejudice weighs as much as evidence, and the closed room, with the camera getting closer, makes the pressure visible.*\n\n*In conclusion, the loudest voice rarely wins. Antony manipulates emotions, Juror 5 and Juror 8 appeal to reason, but all three understand that listening and doubt are what change minds.*\n\n**Points attendus** : ironie et pathos d’Antoine ; question et logos du juré 5 ; juré n° 8, doute raisonnable, 11 votes coupables au départ, écoute et préjugés ; distinction manipulation / raisonnement dans la conclusion."}$exo$::jsonb),
  ('1c30cae9-94e2-54bc-b83f-fb92f04ce3ca'::uuid, 1, 'traduction', $exo${"titre":"Gilead and its ancestors","consigne":"Réponds en anglais, en phrases complètes.","enonce":"**Dystopia as a warning**\n\n1. What is **Gilead** in Margaret Atwood’s *The Handmaid’s Tale* (1985)? What is the role of the **Handmaids**?\n\n2. What does the narrator’s name, **Offred**, mean? Why is it significant?\n\n3. How does the novel end (the **Historical Notes**)?\n\n4. Match each dystopia with the threat it imagines: *Brave New World* (1932) · *Nineteen Eighty-Four* (1949) · *Fahrenheit 451* (1953).","bareme":[{"critere":"Gilead (théocratie remplaçant les États-Unis, lecture littérale de la Bible, natalité effondrée) et rôle des servantes","points":6},{"critere":"Sens de Offred (Of Fred) et privation de l’identité expliquée","points":4},{"critere":"Historical Notes : colloque d’historiens en 2195, cassettes, légèreté glaçante","points":4},{"critere":"Trois dystopies associées à leur menace exacte, anglais correct","points":6}],"dureeMin":8,"corrige":"**1.** *In the near future, the United States has become the Republic of Gilead, a theocracy based on a literal reading of the Bible. The birth rate has collapsed, so fertile women become Handmaids: dressed in red, they are assigned to a Commander in order to give him a child.*\n\n**2.** *“Offred” means “Of Fred”: the woman who belongs to Fred, her Commander. Even her name has been taken from her; she is stripped of her identity and defined as a possession.*\n\n**3.** *The novel ends with “Historical Notes”: in 2195, at an academic conference, historians comment on Offred’s story, found on cassette tapes — with a lightness that is chilling.*\n\n**4.** *Brave New World: happiness imposed through conditioning and a drug, soma. Nineteen Eighty-Four: total surveillance (Big Brother) and an impoverished language (Newspeak). Fahrenheit 451: books burnt by firemen.*"}$exo$::jsonb),
  ('1c30cae9-94e2-54bc-b83f-fb92f04ce3ca'::uuid, 2, 'traduction', $exo${"titre":"Reading a dystopian extract","consigne":"Lis l’extrait (texte inventé pour l’exercice) et analyse-le en anglais en suivant la méthode « lire une dystopie » (environ 150 mots).","enonce":"**Document — Extract from a dystopian short story (invented)**\n\n> They took my name on the first day and gave me a number: 4-11. Numbers do not need to be loved, the Warden says. Every morning the screen in my room asks how I slept, and every morning I answer “Very well, thank you”, because the screen knows when I lie.\n> We are not allowed to read. But at night I recite the names of the streets of my old town, one by one, in the dark. Mill Lane. Chapel Road. Rose Street. As long as I remember them, the town still exists, and so do I.\n\n**Task.** In about 150 words:\n1. identify the **real starting point** that is pushed to the extreme;\n2. study the **power**: surveillance, language, identity;\n3. show how the narrator **resists**;\n4. compare with **Offred** in *The Handmaid’s Tale* on one precise point.","bareme":[{"critere":"Point de départ réel identifié (surveillance par les écrans, effacement de l’individu)","points":4},{"critere":"Formes du pouvoir analysées avec citations (nom remplacé par un numéro, écran qui surveille, lecture interdite)","points":5},{"critere":"Résistance par la mémoire et les mots expliquée","points":5},{"critere":"Comparaison exacte avec Offred (nom retiré, mémoire, phrase latine…), anglais correct, environ 150 mots","points":6}],"dureeMin":12,"corrige":"**Model answer (about 150 words)**\n\n*This extract takes a real feature of our world, screens that collect information about us, and pushes it to the extreme: the screen “knows when I lie”. Power works through surveillance, through the ban on reading, and above all through the loss of identity, since the narrator’s name is replaced by a number, “4-11”. The Warden’s sentence, “Numbers do not need to be loved”, shows that the regime wants to kill feelings.*\n\n*Yet the narrator resists in secret, through memory and words: reciting the names of streets keeps her past alive (“so do I”). Like Offred in The Handmaid’s Tale, whose name means “Of Fred”, she has been stripped of her name, and like her she tells herself her story to survive. Offred remembers her life before, her husband Luke and her daughter, and repeats the Latin sentence “Nolite te bastardes carborundorum” as an inner password.*\n\n**Points attendus** : point de départ réel ; surveillance, langue/lecture, identité ; résistance par la mémoire ; comparaison précise (nom retiré, mémoire, « se raconter pour survivre », phrase latine)."}$exo$::jsonb),
  ('1c30cae9-94e2-54bc-b83f-fb92f04ce3ca'::uuid, 3, 'traduction', $exo${"titre":"Why do we still read The Handmaid’s Tale?","consigne":"Rédige en anglais une synthèse d’environ 250 mots croisant les trois documents (B et C inventés pour l’exercice).","enonce":"**Document A — What Atwood says about her novel (from the course)**\n\nMargaret Atwood has often repeated that she put nothing in the book that had not **already happened somewhere** in human history. Dystopia, in this view, does not invent: it gathers.\n\n**Document B — A news report (invented)**\n\n> Outside the parliament yesterday, forty women stood in silence, dressed in long red cloaks and white bonnets. They did not shout. One held a sign: “Fiction is not a manual.”\n\n**Document C — Extract from an invented conference transcript, year 2240**\n\n> PROFESSOR: Our documents on the so-called Age of Screens are, alas, incomplete. (Laughter.) We must avoid judging our ancestors too severely: they had their reasons.\n\n**Consigne.** *Using the documents and your knowledge of* The Handmaid’s Tale*, explain why dystopia can be read as a warning, and show the role of memory and testimony.*","bareme":[{"critere":"Doc. A relié à l’idée de dystopie qui rassemble et avertit ; lien avec la théocratie de Gilead","points":5},{"critere":"Doc. B relié au costume rouge devenu symbole de manifestation ; passage de la fiction à l’engagement","points":4},{"critere":"Doc. C rapproché des Historical Notes (2195) : légèreté glaçante, témoignage réduit à un document","points":5},{"critere":"Synthèse construite, documents croisés, anglais riche, environ 250 mots","points":6}],"dureeMin":20,"corrige":"**Model synthesis (about 250 words)**\n\n*The three documents explain why a novel published in 1985 is still read, banned and quoted today: dystopia is a warning, and memory is its main weapon.*\n\n*According to Atwood (doc. A), nothing in The Handmaid’s Tale is purely invented. Gilead, a theocracy that controls women’s bodies after the collapse of the birth rate, gathers practices that already existed somewhere. This is why the novel is a warning rather than a fantasy: it shows where real tendencies could lead.*\n\n*The protest described in doc. B shows that readers have taken this warning seriously. The red cloaks and white bonnets of the Handmaids have become a symbol of demonstrations for women’s rights. The silent women turn the novel into a political language, and their sign, “Fiction is not a manual”, reminds us that the book describes what must not happen.*\n\n*Doc. C, however, echoes the Historical Notes at the end of the novel, when historians in 2195 comment on Offred’s tapes with jokes and detachment. Here too the professor laughs and refuses to judge. Both texts show the danger of forgetting: a testimony can become a mere “document”.*\n\n*This is why memory is central. Offred tells her story to survive, clinging to her memories and to the words “Nolite te bastardes carborundorum”. In short, dystopia warns the present, protest keeps the warning alive, and the ironic historians remind us that listening to victims is never guaranteed.*\n\n**Points attendus** : avertissement ; costume rouge ; Historical Notes ; mémoire et témoignage ; lien au présent (méthode, étape 4)."}$exo$::jsonb),
  ('3edc9320-5552-5631-a8ef-50658c242b78'::uuid, 1, 'traduction', $exo${"titre":"From the sonnet to the Romantic poem","consigne":"Réponds en anglais aux questions 1 et 2, puis traduis les mots de la question 3.","enonce":"**Feelings in words**\n\n1. Describe the structure of a **Shakespearean sonnet**. What is the role of the final **couplet**? What does Sonnet 18 (“Shall I compare thee to a summer’s day?”) promise the beloved person?\n\n2. In the 1800 Preface to the *Lyrical Ballads*, Wordsworth defines poetry as “the spontaneous overflow of powerful feelings”, an emotion “recollected in tranquillity”. Explain this definition in your own words.\n\n3. Translate into French: **grief** · **longing** · **to convey an emotion** · **mute** · **a close-up**.","bareme":[{"critere":"Structure exacte (14 vers, trois quatrains, distique final qui retourne ou résume) et promesse du Sonnet 18","points":8},{"critere":"Définition de Wordsworth reformulée : émotion ressentie puis reprise à distance, dans le calme","points":7},{"critere":"Cinq traductions justes","points":5}],"dureeMin":8,"corrige":"**1.** *A Shakespearean sonnet has fourteen lines: three quatrains and a final couplet, which turns around or sums up the idea. In Sonnet 18, the poet says that summer passes, but the poem itself will make the beloved person eternal.*\n\n**2.** *For Wordsworth, poetry is born from strong emotions that overflow naturally. But the poem is not written in the heat of the moment: the emotion is felt first, then remembered later, calmly, from a distance, and shaped into words.*\n\n**3.** grief → le chagrin, le deuil · longing → le désir, la nostalgie · to convey an emotion → transmettre une émotion · mute → muet · a close-up → un gros plan. 1 point chacune."}$exo$::jsonb),
  ('3edc9320-5552-5631-a8ef-50658c242b78'::uuid, 2, 'traduction', $exo${"titre":"A poem about an empty chair","consigne":"Lis le poème (inventé pour l’exercice) et analyse en anglais l’expression de l’émotion en suivant la méthode du cours (environ 150 mots).","enonce":"**Document — *The Chair* (poem invented for this test)**\n\n> Her chair still faces the window — why?\n> Nobody sits there. Nobody tries.\n> The tea goes cold at half past four,\n> The clock insists, and nothing more.\n> I dust her glasses every day\n> As if the dust could stay away,\n> As if the light, if kept the same,\n> Could make the evening call her name.\n\n**Task.** In about 150 words:\n1. **name** the emotion as precisely as possible;\n2. show **what carries it** (images, objects, rhythm, rhyme, silence);\n3. distinguish the **emotion felt** from the **emotion shaped** by the poem;\n4. explain the **effect** on the reader.","bareme":[{"critere":"Émotion nommée avec précision (grief, longing) et justifiée","points":4},{"critere":"Ce qui porte l’émotion analysé avec citations (objets du quotidien, négations, rimes régulières, répétition de as if)","points":7},{"critere":"Distinction émotion vécue / émotion mise en forme, et effet sur le lecteur","points":5},{"critere":"Anglais correct, vocabulaire de l’analyse, environ 150 mots","points":4}],"dureeMin":12,"corrige":"**Model answer (about 150 words)**\n\n*The poem conveys grief, mixed with longing: the speaker has lost a woman, probably a mother or a wife, and cannot accept her absence. The emotion is never named. It is carried by everyday objects: the chair “still faces the window”, the tea “goes cold”, the glasses are dusted “every day”. The negations (“Nobody sits there. Nobody tries.”) make the emptiness felt, and the clock that “insists” turns time into something cruel. The repetition of “As if” shows the speaker’s useless rituals, a way of refusing death.*\n\n*The emotion felt is raw, but the poem shapes it with regular rhymes (why / tries, four / more) and a calm rhythm, as if the pain were “recollected in tranquillity”, in Wordsworth’s words. The effect on the reader is all the stronger because nothing is shouted: we understand the loss through silence and details.*\n\n**Points attendus** : émotion précise (grief / longing) ; objets, négations, rimes, anaphore de *as if* ; distinction vécue / mise en forme ; effet (émotion suggérée, lecteur qui reconstruit)."}$exo$::jsonb),
  ('3edc9320-5552-5631-a8ef-50658c242b78'::uuid, 3, 'traduction', $exo${"titre":"What do we say when words fail?","consigne":"Rédige en anglais une synthèse d’environ 250 mots croisant les trois documents (A et C écrits pour l’exercice).","enonce":"**Document A — Description of a sequence (written for this test)**\n\nIn Jane Campion’s *The Piano* (1993), Ada, a mute Scottish woman, has been sent to New Zealand with her daughter Flora. Her piano has been left on the beach. In a long shot, Ada plays on the sand, the sea behind her; then close-ups show her hands on the keys while Michael Nyman’s music fills the soundtrack. Flora dances around her.\n\n**Document B — William Wordsworth, Preface to the *Lyrical Ballads* (1800)**\n\n> Poetry is “the spontaneous overflow of powerful feelings”, taking its origin from emotion “recollected in tranquillity”.\n\n**Document C — Poem by a student (invented)**\n\n> I had a thousand words for you.\n> I kept them all. I gave you two:\n> “Goodbye.” “Be well.” — and then the door.\n> The silence said a thousand more.\n\n**Consigne.** *Show how the three documents explore the expression of emotions, and discuss whether silence can convey emotion as powerfully as words.*","bareme":[{"critere":"Doc. A analysé : piano comme voix d’Ada, mains, paysage, plans (plan d’ensemble, gros plans), silence comme choix","points":6},{"critere":"Doc. B expliqué et confronté aux deux autres (émotion qui déborde / émotion retenue)","points":4},{"critere":"Doc. C analysé (contraste mille mots / deux mots, le silence qui parle)","points":4},{"critere":"Réponse nuancée à la question, documents croisés, anglais riche, environ 250 mots","points":6}],"dureeMin":20,"corrige":"**Model synthesis (about 250 words)**\n\n*The three documents all ask how emotion finds a form, but they give it different voices: music, poetry and silence.*\n\n*For Wordsworth (doc. B), poetry is an “overflow” of powerful feelings: emotion must come out in words, even if it is shaped later, “in tranquillity”. Doc. C seems to contradict him. The speaker had “a thousand words” but only says two, and it is “the silence” that “said a thousand more”. Yet the poem itself is made of words: the silence is conveyed through the contrast between what is said and what is kept.*\n\n*The Piano (doc. A) goes further, since Ada is mute. The music of Michael Nyman becomes her voice, and the close-ups on her hands show that her body speaks for her. The long shot of the beach links her joy to the open landscape, while Flora’s dance translates her mother’s feelings, as she translates her signs elsewhere in the film. For Campion, silence is not a lack but a choice: Ada refuses to speak to a world that does not listen.*\n\n*Can silence be as powerful as words, then? The documents suggest that it can, provided it is given a form: rhythm, music, framing. Emotion needs a medium, but not necessarily language. In the end, Wordsworth’s overflow and Ada’s silence meet: both transform a raw feeling into something the reader or spectator can share.*\n\n**Points attendus** : piano = voix, mains, cadrage ; définition de Wordsworth ; silence comme forme ; conclusion nuancée ; croisement des trois documents."}$exo$::jsonb),
  ('940e8774-a42c-592e-8728-65c6f8a7bd87'::uuid, 1, 'traduction', $exo${"titre":"Masks in Much Ado About Nothing","consigne":"Réponds en anglais, en phrases complètes.","enonce":"**All the world’s a stage**\n\n1. In Kenneth Branagh’s *Much Ado About Nothing* (1993), what is the “**merry war**” between Beatrice and Benedick, and what does it hide?\n\n2. The whole play relies on staged situations. List the **four** main ones and say who organises each.\n\n3. Explain the pun in the title (*nothing* / *noting*).\n\n4. What does the sociologist **Erving Goffman** say about social life?","bareme":[{"critere":"Merry war : joute de mots d’esprit qui cache leur amour","points":4},{"critere":"Les quatre mises en scène (bal masqué, gulling scenes, fausse preuve de Don John, fausse mort de Hero)","points":8},{"critere":"Jeu de mots nothing/noting (épier, remarquer) et idée de Goffman (scène et coulisses)","points":6},{"critere":"Anglais correct","points":2}],"dureeMin":8,"corrige":"**1.** *Beatrice and Benedick fight a “merry war” of witty remarks: they mock each other constantly to hide the fact that they love each other.*\n\n**2.** *(a) A masked ball where everyone speaks behind a mask. (b) Two gulling scenes: Benedick’s friends, then Beatrice’s, deliberately let themselves be overheard to convince them that they are loved. (c) A false proof: Don John makes people believe that Hero is unfaithful. (d) A false death: Hero pretends to be dead so that her name can be cleared.*\n\n**3.** *In Shakespeare’s time, “nothing” and “noting” were pronounced almost the same. “Noting” means spying, observing, taking note: everybody watches everybody — and misinterprets what they see.*\n\n**4.** *In The Presentation of Self in Everyday Life (1956), Goffman describes social life as a theatre: everyone has a stage, where they play a role, and backstage, where they drop it.*"}$exo$::jsonb),
  ('940e8774-a42c-592e-8728-65c6f8a7bd87'::uuid, 2, 'traduction', $exo${"titre":"A speaker who betrays himself","consigne":"Lis le monologue (inventé pour l’exercice) et analyse-le en anglais en suivant la méthode « étudier une mise en scène de soi » (environ 150 mots).","enonce":"**Document — *My Old Partner* (dramatic monologue, invented)**\n\nA businessman shows a visitor around his office.\n\n> That photograph? My old partner, Tom. A fine man.\n> Too fine, perhaps. He smiled at everyone —\n> The cleaners, the clients, even my competitors.\n> I told him, once or twice, a smile costs money.\n> He did not listen. So I stopped telling him.\n> I bought his shares. He left. He had to, didn’t he?\n> Now, shall we sign? Please — sit in his chair.\n\n**Task.** In about 150 words:\n1. **Who speaks, and to whom?** What role is he playing?\n2. Show the **gap** between what he shows and what he is.\n3. Find the **moment when the mask slips**.\n4. What is the **author’s attitude** to him? Compare with one work studied in class.","bareme":[{"critere":"Situation d’énonciation identifiée : monologue dramatique, auditeur muet, homme d’affaires aimable","points":4},{"critere":"Écart entre façade et réalité analysé avec citations (fine man / too fine, a smile costs money)","points":6},{"critere":"Moment où le masque tombe repéré (I stopped telling him… He had to, didn’t he? sit in his chair)","points":4},{"critere":"Regard de l’auteur et comparaison exacte (My Last Duchess de Browning), anglais correct","points":6}],"dureeMin":12,"corrige":"**Model answer (about 150 words)**\n\n*This is a dramatic monologue: a businessman speaks to a silent visitor who has come to sign a deal. He plays the role of the generous, nostalgic partner (“A fine man”). But a gap soon appears between his polite words and what he reveals. “Too fine, perhaps” turns praise into criticism, and “a smile costs money” shows that he judges people only by profit.*\n\n*The mask slips in the last lines. “So I stopped telling him. I bought his shares. He left” suggests that he pushed Tom out, and the question “He had to, didn’t he?” sounds like a self-justification. Offering the visitor Tom’s chair is almost a threat.*\n\n*The author clearly criticises him: the speaker betrays himself without noticing it. This is exactly the device of Robert Browning’s “My Last Duchess” (1842), in which a duke reveals his cruelty while speaking.*\n\n**Points attendus** : monologue dramatique et auditeur muet ; façade / réalité ; basculement final ; regard critique de l’auteur ; comparaison exacte avec Browning (ou, accepté, avec Don John qui monte une fausse mise en scène)."}$exo$::jsonb),
  ('940e8774-a42c-592e-8728-65c6f8a7bd87'::uuid, 3, 'traduction', $exo${"titre":"Do we ever stop playing a role?","consigne":"Rédige en anglais un essai d’environ 250 mots croisant les documents (B inventé pour l’exercice) et les œuvres du chapitre.","enonce":"**Document A — *Much Ado About Nothing* (Branagh, 1993)**\n\nIn the gulling scenes, Benedick’s friends, then Beatrice’s, pretend not to know they are being overheard and describe how much each one secretly loves the other. Both fall into the trap — and fall in love.\n\n**Document B — A post on social media (invented)**\n\n> Took 47 pictures to get this one. Pretended to laugh at nothing. Edited the sky. Caption: “Just a normal Tuesday #nofilter”. 312 likes. Felt lonely anyway.\n\n**Document C — Shakespeare, *As You Like It***\n\n> “All the world’s a stage, and all the men and women merely players.”\n\n**Consigne.** *Using the documents and the works studied in class, discuss whether we ever stop playing a role. Refer to Goffman and to at least one other work of the chapter.*","bareme":[{"critere":"Doc. A analysé : la mise en scène qui crée un sentiment vrai ; masque qui révèle autant qu’il cache","points":5},{"critere":"Doc. B analysé : image de soi fabriquée, écart façade / coulisses, rapproché de Goffman et du selfie (2013)","points":5},{"critere":"Doc. C et au moins une autre œuvre du chapitre mobilisés avec exactitude (Wilde, Douglass, Angelou, Browning…)","points":5},{"critere":"Essai construit, réponse nuancée, anglais riche, environ 250 mots","points":5}],"dureeMin":20,"corrige":"**Model essay (about 250 words)**\n\n*“All the world’s a stage,” says Shakespeare (doc. C): if life is theatre, can we ever take off our mask?*\n\n*Doc. A suggests that masks can reveal the truth. In the gulling scenes of Much Ado About Nothing, Benedick and Beatrice are manipulated by a staged conversation, yet the love it “reveals” was already there, hidden behind their “merry war”. The fiction brings out a real feeling.*\n\n*Doc. B shows a darker side. The user takes “47 pictures”, pretends to laugh and writes “#nofilter”, which is ironic since everything is filtered. This illustrates Erving Goffman’s idea that social life is a theatre with a stage and backstage: online, we show only the stage. It is no coincidence that “selfie” became Oxford’s word of the year in 2013. But the last sentence, “Felt lonely anyway”, is the backstage: the mask brings likes, not connection.*\n\n*Other works show that playing a role can also be a way of existing. In The Importance of Being Earnest (1895), Oscar Wilde’s heroes invent a double to escape social conventions; Frederick Douglass, in his Narrative (1845), conquers his “I” by telling his own story.*\n\n*So, do we ever stop playing? Probably not: we always speak in front of someone, and the audience changes the role. But there is a difference between a mask that frees, like Wilde’s or Douglass’s, and a mask that imprisons, like the lonely post. Perhaps authenticity lies not in having no mask but in choosing it.*\n\n**Points attendus** : croisement ; Goffman (scène/coulisses) ; gulling scenes ; au moins une autre œuvre exacte ; conclusion nuancée."}$exo$::jsonb),
  ('d8c7e280-6eae-5f02-a681-ffd3244a5fbc'::uuid, 1, 'traduction', $exo${"titre":"The Bildungsroman and Boyhood","consigne":"Réponds en anglais, en phrases complètes.","enonce":"**Coming of age**\n\n1. What is a **Bildungsroman**? Name its **four** stages as presented in class.\n\n2. Who first used the word **epiphany** in literature in this sense, and what does it mean?\n\n3. J. M. Coetzee’s *Boyhood* (1997) is an autobiography with two unusual features: the **person** and the **tense** of the narrative. Name them and explain their effect.","bareme":[{"critere":"Définition du roman de formation et quatre étapes (départ, épreuves, épiphanie, retour/nouveau regard)","points":8},{"critere":"Épiphanie : révélation soudaine, mot de Joyce","points":4},{"critere":"Troisième personne (distance, refus du je) et présent (pas de sagesse d’adulte) avec leur effet","points":8}],"dureeMin":8,"corrige":"**1.** *A Bildungsroman is a coming-of-age novel: it follows a young hero who loses illusions and gains a new way of seeing the world. Its four stages are: departure (leaving family, village, childhood); trials (humiliation, injustice, disappointed love); the epiphany, a moment of revelation; and the return or the new outlook, when the hero sees what he did not see before.*\n\n**2.** *The word “epiphany” in this sense comes from James Joyce: it is a sudden revelation, a moment when the character suddenly understands something essential.*\n\n**3.** *Boyhood is told in the third person (“he”), not “I”: the autobiography refuses the “I” and keeps the child at a distance. It is also written in the present tense: there is no adult wisdom looking back, we stay in the child’s moment.*"}$exo$::jsonb),
  ('d8c7e280-6eae-5f02-a681-ffd3244a5fbc'::uuid, 2, 'traduction', $exo${"titre":"A lie in the playground","consigne":"Lis l’extrait (texte inventé pour l’exercice) et analyse-le en anglais en suivant la méthode « repérer l’initiation dans un texte » (environ 150 mots).","enonce":"**Document — Extract from a novel (invented)**\n\n> On the first day at the new school, a boy with red hair asks him what his father does. He says: “He’s a doctor.” He does not know why he says it. His father sells shoes.\n> Now the lie lives with him. When the red-haired boy says his mother has a cough, he feels everyone looking at him. At night he practises words he has heard on the radio: temperature, prescription. He is nine. He understands, for the first time, that a lie is not something you say once; it is something you have to keep feeding.\n\n**Task.** In about 150 words:\n1. describe the **starting situation** and the **trigger**;\n2. show the **transformation**: what does the boy know at the end?\n3. study the **point of view** (person, tense) and its effect;\n4. compare with **one** element of Coetzee’s *Boyhood*.","bareme":[{"critere":"Situation de départ et élément déclencheur identifiés (nouvelle école, question, mensonge)","points":4},{"critere":"Transformation expliquée : découverte que le mensonge doit être entretenu (épiphanie), citation à l’appui","points":5},{"critere":"Point de vue analysé : 3e personne et présent, distance et immédiateté","points":5},{"critere":"Comparaison exacte avec Boyhood (mensonge sur la religion catholique, 3e personne, présent), anglais correct","points":6}],"dureeMin":12,"corrige":"**Model answer (about 150 words)**\n\n*At the beginning, a nine-year-old boy arrives at a new school, still innocent. The trigger is a simple question about his father, to which he answers with an unexplained lie: “He’s a doctor”, when his father “sells shoes”.*\n\n*The transformation is the discovery of the weight of a lie. He must practise medical words and he fears his classmates’ eyes. The last sentence is an epiphany: “a lie is not something you say once; it is something you have to keep feeding.” He loses part of his innocence.*\n\n*The text is written in the third person and in the present tense: the narrator does not judge the child with adult wisdom, we live the moment with him, but from a certain distance.*\n\n*This strongly echoes Boyhood, where the child declares himself Catholic at random at school and must then keep up the lie, in the same third-person present narration.*\n\n**Points attendus** : situation, déclencheur, transformation, point de vue ; comparaison précise avec *Boyhood*."}$exo$::jsonb),
  ('d8c7e280-6eae-5f02-a681-ffd3244a5fbc'::uuid, 3, 'traduction', $exo${"titre":"Does growing up mean finding one’s place?","consigne":"Rédige en anglais une synthèse d’environ 250 mots croisant les trois documents (B inventé pour l’exercice) et les romans du chapitre.","enonce":"**Document A — Charlotte Brontë, *Jane Eyre* (1847)**\n\n> “I am no bird; and no net ensnares me.”\n\n**Document B — Extract from a short story (invented)**\n\n> At Grandpa’s seventieth birthday, someone made a joke about “those people” from the estate across the river, and everyone laughed. Ruth laughed too, then stopped. She looked at the faces around the table, the faces she had loved all her life, and for the first time they looked like strangers.\n\n**Document C — About *Boyhood* (from the course)**\n\n*Boyhood* reverses the Bildungsroman: the child does not learn to find his place; he learns that he **has none** — and it is from this gap that the writer will be born.\n\n**Consigne.** *Using the documents and the novels studied in class, show that coming of age can mean finding one’s place, but also refusing it or discovering that one has none.*","bareme":[{"critere":"Doc. A : conquête de l’indépendance (trouver sa place en se libérant)","points":4},{"critere":"Doc. B : épiphanie et perte d’innocence face aux préjugés de la famille, rapprochée de To Kill a Mockingbird ou de Holden","points":5},{"critere":"Doc. C : Boyhood inverse le roman de formation (entre deux langues, sans place, naissance de l’écrivain)","points":5},{"critere":"Synthèse construite, documents croisés, conclusion nuancée, anglais riche, environ 250 mots","points":6}],"dureeMin":20,"corrige":"**Model synthesis (about 250 words)**\n\n*The Bildungsroman traditionally leads a young hero from innocence to a new outlook. The three documents show that this new outlook does not always mean finding one’s place.*\n\n*For Jane Eyre (doc. A), growing up means conquering independence. “I am no bird; and no net ensnares me” expresses the determination of an orphan who refuses to be caged and builds her own place in the world. Here, initiation is a victory.*\n\n*Doc. B presents a darker initiation. At a family party, Ruth suddenly sees the prejudice of the people she loves: the laughter becomes the trigger of an epiphany, and “for the first time they looked like strangers”. Like Scout in To Kill a Mockingbird, who discovers the racism of her village through the trial defended by her father, Ruth loses her innocence and must now choose between belonging and judging. She finds her place only by stepping away from her family, as Holden Caulfield rejects the “phony” adult world.*\n\n*Coetzee’s Boyhood (doc. C) goes further still. The child, from an English-speaking family among Afrikaners, belongs fully to no camp and hides his secrets. He does not find his place: he discovers that he has none. Yet this gap is fruitful, since it gives birth to the writer.*\n\n*To conclude, coming of age can mean conquering a place (Jane), leaving the one given to us (Ruth, Holden) or accepting that there is none (Coetzee’s child). In every case, the hero gains a clearer vision, even if it is a lonely one.*\n\n**Points attendus** : trois modèles d’initiation ; exemples exacts du cours ; croisement ; conclusion nuancée."}$exo$::jsonb),
  ('1382e2f0-889e-5964-9811-4f6ca0e5db11'::uuid, 1, 'traduction', $exo${"titre":"The first sentence of Pride and Prejudice","consigne":"Réponds en anglais, en phrases complètes.","enonce":"**First impressions**\n\n> “It is a truth universally acknowledged, that a single man in possession of a good fortune, must be in want of a wife.” — Jane Austen, *Pride and Prejudice* (1813)\n\n1. Explain why this first sentence is **ironic**. What does it really mean?\n\n2. What is the **entail**, and why does it make marriage a question of survival for the Bennet sisters?\n\n3. After reading Darcy’s letter, Elizabeth says: “Till this moment I never knew myself.” What has she understood?\n\n4. What was the working title of the novel, and why does it suit the story?","bareme":[{"critere":"Ironie de la première phrase expliquée (ce sont les familles qui cherchent un riche mari)","points":6},{"critere":"Entail : Longbourn reviendra à un cousin faute de fils ; mariage vital pour les filles","points":5},{"critere":"Sens de la phrase d’Elizabeth : vérité sur Wickham, son propre préjugé","points":5},{"critere":"First Impressions et son lien avec l’intrigue, anglais correct","points":4}],"dureeMin":8,"corrige":"**1.** *The sentence claims to state a universal truth, but it means the opposite: it is not rich young men who are looking for a wife, it is families with daughters who are looking for a rich husband. The narrator’s irony mocks the marriage market from the very first line.*\n\n**2.** *The Bennets have five daughters and no son. Because of the entail, their estate, Longbourn, will go to a male cousin. Without a good marriage, the daughters will have no home and no fortune: marriage is a question of survival.*\n\n**3.** *Darcy’s letter reveals the truth about Wickham, whom she had trusted. Elizabeth realises that she misjudged both men: she, who was proud of her judgement, was blinded by prejudice.*\n\n**4.** *The working title was First Impressions. It suits the story because the whole plot starts with a bad first impression (Darcy finds Elizabeth “tolerable”) and shows how both characters must correct their own way of seeing.*"}$exo$::jsonb),
  ('1382e2f0-889e-5964-9811-4f6ca0e5db11'::uuid, 2, 'traduction', $exo${"titre":"Misjudging at a party","consigne":"Lis l’extrait (texte inventé pour l’exercice), réponds en anglais aux questions 1 à 3, puis traduis en français la phrase de la question 4.","enonce":"**Document — Extract from a novel (invented)**\n\n> Mr Harcourt did not dance. He stood by the window all evening, as if the room were beneath him. Clara was quite certain of it: a man who would not dance with the doctor’s daughters could only be proud, and a proud man was surely a cruel one. How right she had been to laugh at him with her sister! Yet when the old servant dropped a tray, it was Mr Harcourt, and no one else, who knelt to help him.\n\n1. Identify the passages written in **free indirect speech** and explain the effect.\n2. Show how Clara **misjudges** Mr Harcourt, and which detail contradicts her.\n3. Compare this scene with Elizabeth’s **first impression** of Darcy in *Pride and Prejudice*.\n4. Translate into French: “How right she had been to laugh at him with her sister!”","bareme":[{"critere":"Discours indirect libre repéré (Clara was quite certain… How right she had been…) et effet expliqué (on entend ses pensées et ses erreurs)","points":6},{"critere":"Erreur de jugement analysée : fierté supposée, raisonnement hâtif, détail du plateau","points":5},{"critere":"Comparaison exacte avec le bal (tolerable), orgueil et préjugé partagés","points":5},{"critere":"Traduction juste et idiomatique","points":4}],"dureeMin":12,"corrige":"**1.** *“Clara was quite certain of it: a man who would not dance… could only be proud, and a proud man was surely a cruel one. How right she had been…!” is free indirect speech: we hear Clara’s thoughts without quotation marks, in the narrator’s voice. The effect is ironic: we share her certainty and, at the same time, we feel it is excessive.*\n\n**2.** *Clara builds a quick chain of conclusions: he does not dance → he is proud → he is cruel. The adverbs “quite certain”, “only”, “surely” show her overconfidence. The last sentence contradicts her: Mr Harcourt is the only one who kneels to help the old servant, a humble and kind gesture.*\n\n**3.** *The scene recalls the ball in Pride and Prejudice, where Darcy judges Elizabeth only “tolerable” and she never forgets it. In both cases a heroine with a quick mind forms a first impression that proves wrong. As in Austen, pride and prejudice are shared: the man seems proud, but the woman is prejudiced.*\n\n**4.** « Comme elle avait eu raison de se moquer de lui avec sa sœur ! » (accepter « Qu’elle avait eu raison de rire de lui avec sa sœur ! »). Le plus-que-parfait anglais (*had been*) se rend par le plus-que-parfait ; *how* exclamatif → « comme / que »."}$exo$::jsonb),
  ('1382e2f0-889e-5964-9811-4f6ca0e5db11'::uuid, 3, 'traduction', $exo${"titre":"A school of judgement, then and now","consigne":"Rédige en anglais une synthèse d’environ 250 mots croisant les trois documents (C inventé pour l’exercice).","enonce":"**Document A — Jane Austen, *Pride and Prejudice* (1813), first sentence**\n\n> “It is a truth universally acknowledged, that a single man in possession of a good fortune, must be in want of a wife.”\n\n**Document B — Charlotte Lucas, explaining why she has accepted Mr Collins**\n\n> “I am not romantic, you know.”\n\n**Document C — From a magazine article (invented)**\n\n> On dating apps, users decide in under two seconds. A profile picture, a job title, a height: swipe left or right. “We’ve never had so much choice,” says one psychologist, “and we’ve never judged so fast.”\n\n**Consigne.** *Using the documents and your knowledge of the novel, show how* Pride and Prejudice *is a novel about learning to judge, and discuss whether its lesson still speaks to us.*","bareme":[{"critere":"Doc. A : ironie, marché du mariage, argent et jugement","points":4},{"critere":"Doc. B : mariage de raison de Charlotte, liberté limitée d’une femme sans fortune","points":4},{"critere":"Apprentissage du jugement expliqué avec l’intrigue (bal, première demande, lettre, réparation) et orgueil/préjugé partagés","points":6},{"critere":"Doc. C croisé avec le roman, réponse nuancée, anglais riche, environ 250 mots","points":6}],"dureeMin":20,"corrige":"**Model synthesis (about 250 words)**\n\n*Pride and Prejudice was first called First Impressions, and the three documents show that judging others, and ourselves, is its real subject.*\n\n*The first sentence (doc. A) already teaches us to read carefully. Its “universal truth” is ironic: in the world of the gentry, it is families with daughters who seek a rich husband. Judging here means seeing money behind the words of love.*\n\n*Charlotte Lucas (doc. B) judges lucidly, but coldly. By accepting Mr Collins because she is “not romantic”, she reminds us that a woman without fortune has little freedom: with the entail and without a dowry, marriage is survival.*\n\n*Elizabeth, on the contrary, judges too fast. At the ball, Darcy finds her “tolerable”; she decides he is proud and believes Wickham’s lies. It takes Darcy’s letter for her to admit: “Till this moment I never knew myself.” Darcy, too, must correct his pride after his humiliating first proposal. Pride and prejudice are shared, and each character must correct his or her own way of seeing, which makes the novel a school of judgement.*\n\n*Doc. C suggests that this lesson is more relevant than ever. Dating apps turn every encounter into a first impression made “in under two seconds”, based on a picture and a job title, much like the Bennets’ neighbours judging a man by his fortune. Austen’s answer remains valid: the first look is often wrong, and only time, listening and self-criticism allow us to know others — and ourselves.*\n\n**Points attendus** : ironie ; Charlotte et le mariage de raison ; intrigue en quatre temps ; apprentissage partagé ; actualisation nuancée."}$exo$::jsonb),
  ('da087fe6-17ae-5218-8544-b9463f48c24b'::uuid, 1, 'traduction', $exo${"titre":"Moon Palace: a name, a journey, a moon","consigne":"Réponds en anglais, en phrases complètes.","enonce":"**Go West**\n\n1. Why is the narrator of Paul Auster’s *Moon Palace* (1989) called **Marco Stanley Fogg**?\n\n2. Summarise the four stages of Marco’s story: **the fall**, **the meeting**, **the revelation**, **the departure**.\n\n3. What historical event forms the background of the novel, and what does the **Moon** symbolise?\n\n4. What was the **Frontier**, according to Frederick Jackson Turner’s thesis (1893)?","bareme":[{"critere":"Nom expliqué : Marco Polo, Henry Morton Stanley, Phileas Fogg","points":4},{"critere":"Quatre étapes exactes (Central Park, Thomas Effing, Solomon Barber son père, marche jusqu’au Pacifique)","points":8},{"critere":"Premiers pas sur la Lune (juillet 1969) et symbolique (ailleurs, rêve, solitude, dernière frontière)","points":4},{"critere":"Thèse de la Frontier : identité américaine forgée par la conquête de l’Ouest, limite mouvante","points":4}],"dureeMin":8,"corrige":"**1.** *His name is made of three explorers or travellers: Marco Polo, Henry Morton Stanley and Phileas Fogg (Around the World in Eighty Days). It announces a novel of travel and exploration.*\n\n**2.** *The fall: after the death of his uncle Victor, Marco sells the books he inherited one by one and ends up living without money in Central Park. The meeting: he becomes the reader of an old, blind and tyrannical man, Thomas Effing, who tells him about his youth as a painter in the western desert (Utah). The revelation: through Effing, Marco discovers Effing’s son, Solomon Barber, who turns out to be his own father. The departure: alone, Marco crosses the country on foot to the Pacific coast, where he watches the moon rise.*\n\n**3.** *The novel takes place when man walks on the Moon, in July 1969. The Moon stands for elsewhere, dreams and solitude — the last frontier.*\n\n**4.** *For Turner, the Frontier was the moving line between colonised land and the “wilderness”; the conquest of the West forged American identity.*"}$exo$::jsonb),
  ('da087fe6-17ae-5218-8544-b9463f48c24b'::uuid, 2, 'traduction', $exo${"titre":"Driving into the desert","consigne":"Lis l’extrait (texte inventé pour l’exercice) et analyse-le en anglais en suivant la méthode « analyser un récit de voyage » (environ 150 mots).","enonce":"**Document — Extract from a travel narrative (invented)**\n\n> I left Chicago with two hundred dollars and my mother’s old car. I told everyone I was going to see the Pacific. The truth is, I was leaving a job, a man and a name I no longer recognised.\n> In Nevada the road became a line drawn with a ruler. No houses, no signs, only the wind. An old woman at a gas station asked me where I was going. “West,” I said. She laughed: “Honey, everybody says that. What are you running from?”\n> That night I slept in the car and, for the first time in years, I was not afraid of the silence.\n\n**Task.** In about 150 words:\n1. What is the **reason for leaving**: flight, quest or necessity?\n2. Describe the **space crossed** and what it means.\n3. What does the **encounter** change?\n4. Relate the text to the **myth of the West** and to one work studied in class.","bareme":[{"critere":"Motif du départ analysé : fuite plus que quête, citation à l’appui","points":4},{"critere":"Espace ouvert et vide analysé (route à la règle, désert, silence) comme épreuve et libération","points":5},{"critere":"Rencontre et transformation expliquées (question de la vieille femme, peur du silence dépassée)","points":5},{"critere":"Lien exact au mythe de l’Ouest et à une œuvre du cours (Moon Palace, On the Road…), anglais correct","points":6}],"dureeMin":12,"corrige":"**Model answer (about 150 words)**\n\n*The narrator claims she is on a quest, “to see the Pacific”, but she admits the truth: she is running away from a job, a man and “a name I no longer recognised”. Her journey is a flight that becomes a search for herself.*\n\n*The space she crosses is open and empty: the road is “a line drawn with a ruler”, with “only the wind”. The Nevada desert is both a trial and a liberation, a place where she can lose herself.*\n\n*The encounter with the old woman acts as a revelation: her question, “What are you running from?”, forces the narrator to face her motives. At the end, she is “not afraid of the silence”: she has changed.*\n\n*The text rewrites the American myth of going West, the Frontier. Like Marco in Moon Palace, who crosses the country on foot to the Pacific coast, she goes West to find herself.*\n\n**Points attendus** : fuite / quête ; espace ouvert, épreuve ; rencontre révélatrice ; mythe de l’Ouest ; comparaison exacte (Marco, ou Kerouac et la Beat Generation)."}$exo$::jsonb),
  ('da087fe6-17ae-5218-8544-b9463f48c24b'::uuid, 3, 'traduction', $exo${"titre":"Going West: conquest or self-discovery?","consigne":"Rédige en anglais une synthèse d’environ 250 mots croisant les trois documents (B et C inventés pour l’exercice) et les œuvres du chapitre.","enonce":"**Document A — The Frontier thesis (from the course)**\n\nIn 1893, Frederick Jackson Turner argued that American identity had been forged by the conquest of the West, along the Frontier, the moving line between colonised land and what was called the “wilderness”.\n\n**Document B — Letter from a settler, 1850s (invented)**\n\n> We have crossed the river at last. The land ahead belongs to no one, the guide says, and it will belong to us. The Indians we met yesterday watched us pass without a word.\n\n**Document C — Extract from a novel (invented)**\n\n> He had walked three thousand miles to reach the ocean, and when he got there, he understood that he had not been going anywhere. He had been going away from himself — and, very slowly, back.\n\n**Consigne.** *Using the documents and the works studied in class, show that the journey West has been both a conquest of territory and a quest for the self, and point out what the myth hides.*","bareme":[{"critere":"Doc. A et B : conquête du territoire, mythe fondateur, Lewis et Clark ou Turner mobilisés avec exactitude","points":5},{"critere":"Ce que le mythe cache : dépossession des peuples amérindiens (silence des Indiens, terre « à personne »)","points":5},{"critere":"Doc. C rapproché de Moon Palace (marche jusqu’au Pacifique, se perdre pour se trouver)","points":5},{"critere":"Synthèse construite, documents croisés, anglais riche, environ 250 mots","points":5}],"dureeMin":20,"corrige":"**Model synthesis (about 250 words)**\n\n*In the United States, going West is a founding myth. The three documents show that this journey has two faces: the conquest of land and the conquest of oneself.*\n\n*For Turner (doc. A), the Frontier made Americans: the expedition of Lewis and Clark, who crossed the continent to the Pacific in 1804-1806, opened a space that the settlers of doc. B consider empty. The land “belongs to no one” and “will belong to us”: the West is a territory to be taken.*\n\n*Yet doc. B also reveals what the myth hides. The “Indians” who watch the settlers “without a word” are the people living on this supposedly empty land. The conquest of the “wilderness” was achieved at the price of the dispossession of Native American peoples, a reality the heroic narrative long ignored.*\n\n*Doc. C, on the contrary, turns the journey inward. The hero walks “three thousand miles” and discovers that he was travelling “away from himself — and back”. This echoes Paul Auster’s Moon Palace, in which Marco Stanley Fogg, after the western desert and the revelation of his father, crosses the country on foot to the Pacific coast and watches the moon rise. The desert becomes a trial where one gets lost in order to be found; Kerouac’s On the Road, too, turned the road into a way of life.*\n\n*All in all, the journey West moved from territorial conquest to self-discovery. But a lucid reading must keep both in mind: the myth of freedom was also a story of dispossession.*\n\n**Points attendus** : conquête (Turner, Lewis et Clark) ; dépossession ; quête de soi (Moon Palace) ; croisement ; nuance."}$exo$::jsonb),
  ('12615912-bf39-57ad-ad42-5a532e32c878'::uuid, 1, 'traduction', $exo${"titre":"Roots, land and oil","consigne":"Réponds en anglais, en phrases complètes.","enonce":"**Heritage and dispossession**\n\n1. In “Digging” (1966), Seamus Heaney writes: “Between my finger and my thumb / The squat pen rests. / I’ll dig with it.” What does the poet inherit from his father and grandfather, and how does he **transform** it?\n\n2. In Martin Scorsese’s *Killers of the Flower Moon* (2023), why did the **Osage** nation become one of the richest peoples in the world in the 1920s? What were the **headrights**?\n\n3. Explain the mechanism of the murders in three verbs.\n\n4. What was the **Indian Removal Act** (1830) and what did it lead to?","bareme":[{"critere":"Heaney : la bêche des ancêtres devient la plume, héritage transformé et non imité","points":5},{"critere":"Osage : terre aride où l’on découvre du pétrole ; headrights transmis par héritage","points":6},{"critere":"Mécanisme : épouser, tuer, hériter (orchestré par William Hale)","points":5},{"critere":"Indian Removal Act et Trail of Tears, anglais correct","points":4}],"dureeMin":8,"corrige":"**1.** *Heaney’s father and grandfather dug the earth. The poet will not dig with a spade but with his pen: he inherits their work and their gestures, but transforms them into writing. Heritage is not imitated, it is transformed.*\n\n**2.** *The Osage were driven to an arid land, where oil was discovered: they became one of the richest peoples in the world. The headrights were the rights to the oil revenue, and they were passed on by inheritance.*\n\n**3.** *To marry, to kill, to inherit: white men married Osage women, then murdered their families to inherit the headrights. William Hale, a respected “friend of the Osage”, orchestrated the murders.*\n\n**4.** *The Indian Removal Act of 1830 forced Native American nations off their lands towards reservations; it led to the “Trail of Tears”.*"}$exo$::jsonb),
  ('12615912-bf39-57ad-ad42-5a532e32c878'::uuid, 2, 'traduction', $exo${"titre":"A granddaughter remembers","consigne":"Lis le témoignage (inventé pour l’exercice) et analyse-le en anglais en suivant la méthode « étudier un héritage dans un document » (environ 150 mots).","enonce":"**Document — Testimony recorded for a local museum (invented)**\n\n> My grandmother never spoke of the farm. We only found the papers after her death: a deed, a map, and a letter from a lawyer saying the land had been “legally transferred”. She was twelve when they left. She kept one thing: a wooden spoon her father had carved.\n> Today I teach our language to children on Saturdays. There are eleven of them. My grandmother would say it is not much. I say it is eleven more than nobody.\n\n**Task.** In about 150 words:\n1. Which **land, language and memory** are at stake?\n2. **Who transmits, who receives, who is dispossessed?**\n3. How does the speaker **repair** what was lost?\n4. What is the **point of view**: from inside or outside the community? Compare with *Killers of the Flower Moon*.","bareme":[{"critere":"Terre, langue et mémoire identifiées avec citations (ferme, papiers, cuillère, langue enseignée)","points":5},{"critere":"Transmission et dépossession analysées (grand-mère, silence, transfert « légal »)","points":5},{"critere":"Réparation expliquée : transmettre la langue, témoigner","points":4},{"critere":"Point de vue intérieur et comparaison exacte avec le film (point de vue d’Ernest et de Mollie, qui a le droit de raconter), anglais correct","points":6}],"dureeMin":12,"corrige":"**Model answer (about 150 words)**\n\n*Three things are at stake: a farm, a language and the memory of a family. The land was lost through a “legally transferred” deed, which suggests a dispossession disguised as law. The grandmother transmitted almost nothing: her silence shows the wound, and only a carved wooden spoon survives.*\n\n*The granddaughter receives the papers after her death, but she also chooses to receive the language and pass it on. Teaching it to eleven children is her way of repairing: “eleven more than nobody”. Heritage is not a museum object, it is transformed into action.*\n\n*The point of view is from inside the community, which gives the voice to those who were dispossessed. In Killers of the Flower Moon, by contrast, the dispossession of the Osage also came through legal means (marriages, guardians, notaries), and Scorsese questions who has the right to tell this story, appearing himself in a radio show at the end.*\n\n**Points attendus** : terre / langue / mémoire ; transmission et silence ; réparation ; point de vue ; comparaison exacte (dépossession par des voies « légales », point de vue d’Ernest et de Mollie, scène finale de Scorsese)."}$exo$::jsonb),
  ('12615912-bf39-57ad-ad42-5a532e32c878'::uuid, 3, 'traduction', $exo${"titre":"Who has the right to tell the story?","consigne":"Rédige en anglais une synthèse d’environ 250 mots croisant les trois documents (C inventé pour l’exercice).","enonce":"**Document A — Seamus Heaney, “Digging” (1966), last lines**\n\n> Between my finger and my thumb\n> The squat pen rests.\n> I’ll dig with it.\n\n**Document B — The end of *Killers of the Flower Moon* (Scorsese, 2023), described in the course**\n\nScorsese tells the story from the point of view of Ernest and Mollie, not of the investigator. At the end, he appears himself in a radio show that tells the affair as entertainment.\n\n**Document C — A museum label (invented)**\n\n> *This map was drawn in 1832 by a government surveyor. It shows the lands of a nation removed under the Indian Removal Act of 1830. The names written on it are not the names the people gave to these places.*\n\n**Consigne.** *Show how the documents deal with heritage and dispossession, and discuss who has the right to tell the story of a dispossessed community.*","bareme":[{"critere":"Doc. A : héritage transformé, écrire comme on creuse, la voix de l’intérieur","points":4},{"critere":"Doc. B : choix du point de vue, apparition de Scorsese, récit-divertissement interrogé","points":5},{"critere":"Doc. C : le récit du vainqueur (noms imposés), Trail of Tears, dépossession par la carte","points":5},{"critere":"Réponse nuancée sur le droit de raconter, documents croisés, anglais riche, environ 250 mots","points":6}],"dureeMin":20,"corrige":"**Model synthesis (about 250 words)**\n\n*The three documents deal with what a community inherits and what it loses, and they raise a delicate question: who has the right to tell this story?*\n\n*Heaney (doc. A) writes from inside his community. The Irish poet will “dig” with his pen as his father and grandfather dug the earth: heritage is not imitated but transformed. The one who tells the story belongs to it.*\n\n*The map in doc. C shows the opposite situation. Drawn by a “government surveyor” after the Indian Removal Act of 1830, which led to the Trail of Tears, it replaces the names that the people gave to their land. Telling, here, is a form of possession: the dispossessed lose their land and their words.*\n\n*Scorsese (doc. B) is aware of this danger. As an outsider, he refuses to make the white investigator of the Bureau of Investigation the hero; he tells the story through Ernest, the husband who takes part in the plot, and Mollie, the Osage woman whose family is murdered. By appearing at the end in a radio show that turns the murders into entertainment, he questions his own position and that of all storytellers who profit from other people’s tragedies.*\n\n*So who may tell the story? The community first, as Heaney shows. But an outsider can also repair, provided he names the dead, gives the voice to the victims and admits his point of view. What must be avoided is the map-maker’s attitude: telling in order to erase.*\n\n**Points attendus** : héritage transformé ; carte et noms imposés ; choix de Scorsese ; méthode (qui transmet, qui est dépossédé, comment l’œuvre répare, quel point de vue) ; nuance."}$exo$::jsonb),
  ('78461573-4832-56ea-a87d-8d444add1c3a'::uuid, 1, 'traduction', $exo${"titre":"Words for leaving home","consigne":"Réponds en anglais aux questions 1 et 2, puis traduis les expressions de la question 3.","enonce":"**Migration and exile**\n\n1. Explain the difference between an **emigrant**, an **immigrant**, an **exile**, a **refugee** and a **diaspora**.\n\n2. Sum up the five stages of Eilis Lacey’s story in Colm Tóibín’s *Brooklyn* (2009): the crossing, settling in, love, return, choice.\n\n3. Translate into English: **le mal du pays** · **s’installer** · **être déchiré entre deux pays** · **un nouveau venu** · **s’intégrer**.","bareme":[{"critere":"Cinq mots distingués avec justesse (celui qui part / arrive, départ contraint, fuite d’un danger, communauté dispersée)","points":7},{"critere":"Cinq étapes exactes (homesickness, pension et emploi, Tony, mort de Rose et Jim Farrell, Miss Kelly et retour à Brooklyn)","points":8},{"critere":"Cinq traductions justes","points":5}],"dureeMin":8,"corrige":"**1.** *An emigrant and an immigrant are the same person seen from the two shores: the emigrant is the one who leaves, the immigrant the one who arrives. An exile leaves by force, with no possible return. A refugee flees a danger and is protected by international law. A diaspora is a community scattered outside its land of origin.*\n\n**2.** *(1) The crossing: Eilis leaves Enniscorthy for Brooklyn and suffers from homesickness. (2) Settling in: she lives in a boarding house for girls, works as a shop assistant and takes evening classes in bookkeeping. (3) Love: she meets Tony, a young Italian-American plumber, and they marry secretly. (4) The return: the death of her sister Rose calls her back to Ireland, where Jim Farrell courts her. (5) The choice: a gossip, Miss Kelly, discovers her marriage, and Eilis goes back to Brooklyn.*\n\n**3.** le mal du pays → *homesickness* · s’installer → *to settle (in)* · être déchiré entre deux pays → *to be torn between two countries* · un nouveau venu → *a newcomer* · s’intégrer → *to fit in*."}$exo$::jsonb),
  ('78461573-4832-56ea-a87d-8d444add1c3a'::uuid, 2, 'traduction', $exo${"titre":"A letter from Brooklyn, 1952","consigne":"Lis la lettre (inventée pour l’exercice), réponds en anglais aux questions 1 à 3, puis traduis en français les deux phrases de la question 4.","enonce":"**Document — Letter from Nora to her sister in Ireland (invented)**\n\n> Dear Kathleen,\n> The store is very big and very bright, and the ladies are kind. I have bought a blue coat. On Sundays I walk to the river and look at the ships, but I do not think of anything in particular.\n> Mrs Brennan says I am settling in well. I have not told her that I keep your last letter under my pillow. Please tell Mammy I am happy.\n> Your loving sister, Nora\n\n1. What does Nora **say** about her new life, and what does she **not say**? Quote the text.\n2. How is **homesickness** suggested rather than stated?\n3. Compare Nora with **Eilis** in *Brooklyn* on one precise point.\n4. Translate into French: “I have not told her that I keep your last letter under my pillow. Please tell Mammy I am happy.”","bareme":[{"critere":"Écart entre ce qui est dit (big, bright, kind, happy) et ce qui est tu, avec citations","points":5},{"critere":"Mal du pays suggéré par les gestes et les silences (lettre sous l’oreiller, bateaux, négation)","points":5},{"critere":"Comparaison exacte avec Eilis (homesickness, lettres, écriture sobre)","points":4},{"critere":"Traduction juste (present perfect, présent de l’habitude, registre)","points":6}],"dureeMin":12,"corrige":"**1.** *Nora describes a pleasant life: the store is “very big and very bright”, the ladies are “kind”, she has “bought a blue coat”, and she asks her sister to tell their mother she is “happy”. What she does not say is that she is lonely and misses home.*\n\n**2.** *Homesickness is never named. It appears in gestures and silences: she watches the ships on Sundays, the ships that could take her home, and adds “I do not think of anything in particular”, a denial that says the opposite. She hides her sister’s letter under her pillow and has not told Mrs Brennan. “Please tell Mammy I am happy” sounds like a request to be believed.*\n\n**3.** *Like Eilis in Brooklyn, Nora suffers from a homesickness that she cannot say, and her feelings can be read in gestures and silences. Letters play the same role: they are the fragile link with the family left behind. Tóibín’s writing, too, is sober, almost without comment.*\n\n**4.** « Je ne lui ai pas dit que je garde ta dernière lettre sous mon oreiller. Dis à Maman, s’il te plaît, que je suis heureuse. » Attendus : *I have not told her* → passé composé (« je ne lui ai pas dit ») ; *I keep* → présent d’habitude ; *Mammy* → « Maman » ; accord au féminin de « heureuse »."}$exo$::jsonb),
  ('78461573-4832-56ea-a87d-8d444add1c3a'::uuid, 3, 'traduction', $exo${"titre":"Exile: one departure or two?","consigne":"Rédige en anglais une synthèse d’environ 250 mots croisant les trois documents (B inventé pour l’exercice).","enonce":"**Document A — Emma Lazarus, “The New Colossus” (1883), engraved on the pedestal of the Statue of Liberty**\n\n> “Give me your tired, your poor,\n> Your huddled masses yearning to breathe free”\n\n**Document B — Extract from a short story (invented)**\n\n> When Grace came back to Kingston after twenty years in London, her cousins laughed at her accent. “You talk like the Queen now,” they said. In London, people had asked her every week where she was *really* from. She stood in her mother’s kitchen and realised that she was a foreigner in both places.\n\n**Document C — About Colm Tóibín’s *Brooklyn* (from the course)**\n\nExile is not one departure but **two**: you leave your country, then, when you return, you discover that you have changed. Eilis becomes herself by learning to **choose**.\n\n**Consigne.** *Using the documents and your knowledge of* Brooklyn *and of the history of migration, show how migration transforms identity.*","bareme":[{"critere":"Doc. A : promesse d’accueil de l’Amérique (Ellis Island, Famine irlandaise) analysée","points":4},{"critere":"Doc. B : double étrangeté, Windrush generation, accent et identité assignée","points":5},{"critere":"Doc. C et Brooklyn : deux départs, retour après la mort de Rose, choix final d’Eilis","points":6},{"critere":"Synthèse construite, documents croisés, anglais riche, environ 250 mots","points":5}],"dureeMin":20,"corrige":"**Model synthesis (about 250 words)**\n\n*The three documents show that migration is not a simple movement from one place to another: it transforms the person who leaves, sometimes to the point of making her a stranger everywhere.*\n\n*Emma Lazarus’s poem (doc. A) expresses the promise of America: the “huddled masses yearning to breathe free” will be welcomed. This promise was real for millions of people, such as the Irish who fled the Great Famine of 1845-1852, or the immigrants who passed through Ellis Island between 1892 and 1954. Arriving meant hoping for a new life.*\n\n*But doc. B shows the price of this new life. Grace, who may belong to the Windrush generation of Caribbeans who came to Britain from 1948, is asked in London where she is “really” from, and laughed at in Kingston for her accent. She is “a foreigner in both places”: her identity is assigned by others on both shores.*\n\n*This echoes the idea of doc. C. In Brooklyn, Eilis Lacey leaves Enniscorthy in the 1950s and suffers from homesickness. When Rose’s death calls her back to Ireland, she discovers that she has changed: people finally see her as someone, and Jim Farrell courts her. Exile is therefore a second departure. Yet Eilis, unlike Grace, turns this division into freedom: for the first time, she chooses, and goes back to Brooklyn.*\n\n*In the end, migration makes people torn between two countries. For some it is a wound; for others, like Eilis, it is the moment when they become themselves.*\n\n**Points attendus** : promesse d’accueil ; double étrangeté ; deux départs ; choix d’Eilis ; repères historiques exacts."}$exo$::jsonb),
  ('e91ce959-c6d3-5ae0-b23c-d0814e555034'::uuid, 1, 'traduction', $exo${"titre":"Americanah: title, blog and single story","consigne":"Réponds en anglais, en phrases complètes.","enonce":"**Becoming Black in America**\n\n1. What does the word **“Americanah”** mean in Nigeria, and why does Ifemelu fear becoming one?\n\n2. What is Chimamanda Ngozi Adichie’s talk ***The Danger of a Single Story*** (2009) about?\n\n3. Why does Ifemelu start a **blog** in the United States, and how does she describe race in it?\n\n4. What difference does the novel make between being **African** and being **African American** in the United States?","bareme":[{"critere":"Sens du surnom Americanah et crainte d’Ifemelu (peut-on rentrer chez soi quand on a changé ?)","points":5},{"critere":"Conférence : danger de réduire un peuple à une seule histoire","points":4},{"critere":"Blog : observations sur la race, construction sociale apprise","points":5},{"critere":"Distinction africain / afro-américain et identité assignée, anglais correct","points":6}],"dureeMin":8,"corrige":"**1.** *In Nigeria, “Americanah” is a mocking nickname for someone who comes back from the United States with American manners: a forced accent, new tastes. Ifemelu fears becoming one, and wonders whether one can go home after having changed.*\n\n**2.** *In The Danger of a Single Story, Adichie warns against reducing a people to a single story, a single stereotype.*\n\n**3.** *In America, Ifemelu writes a blog with an ironic title (“Raceteenth or Various Observations About American Blacks… by a Non-American Black”). She describes race as a social construct that she had to learn: she did not think of herself as black before coming to America.*\n\n**4.** *The novel separates two experiences that are often confused: being African in the United States and being African American. Ifemelu discovers an identity that is assigned to her from the outside, by the way others see her skin colour.*"}$exo$::jsonb),
  ('e91ce959-c6d3-5ae0-b23c-d0814e555034'::uuid, 2, 'traduction', $exo${"titre":"A blog post about hair","consigne":"Lis le billet de blog (inventé pour l’exercice) et analyse-le en anglais en suivant la méthode « croiser migration et identité » (environ 150 mots).","enonce":"**Document — Blog post by Awa, a Senegalese student in Chicago (invented)**\n\n> Day 214. My manager says my braids are “not very professional”. At home in Dakar, nobody ever called my hair a problem. Here, it is a question: are you angry, are you political, are you going to be “difficult”?\n> I have two choices. I can relax my hair and become invisible. Or I can keep it and become a symbol. Nobody asked me if I wanted to be a symbol. I just wanted to go to work.\n> Tomorrow I will wear my braids. Not because I am angry. Because they are mine.\n\n**Task.** In about 150 words:\n1. How did Awa **see herself before** leaving?\n2. What **identity is assigned** to her in the new country?\n3. What **strategy** does she choose?\n4. Compare with the role of **hair** in *Americanah*.","bareme":[{"critere":"Identité d’avant (à Dakar, cheveux sans enjeu) et identité assignée (professionnelle ? politique ? « difficile ») avec citations","points":6},{"critere":"Stratégie analysée : résister sans colère, affirmer ce qui est à soi ; dilemme invisible / symbole","points":5},{"critere":"Comparaison exacte avec Americanah (salon de tressage, cheveux comme choix politique, blog)","points":5},{"critere":"Anglais correct, environ 150 mots","points":4}],"dureeMin":12,"corrige":"**Model answer (about 150 words)**\n\n*In Dakar, Awa never thought about her hair: “nobody ever called my hair a problem”. In Chicago, her braids become a question. Her manager’s remark assigns her an identity from the outside: she might be “angry”, “political” or “difficult”, a stereotype she did not choose.*\n\n*She faces a dilemma: relaxing her hair to “become invisible” or keeping it and becoming “a symbol”. She finally chooses to resist, but without anger: “Because they are mine.” Writing the blog is itself a strategy, a way of analysing what is happening to her.*\n\n*This is very close to Americanah. The novel opens in a hair-braiding salon, and relaxing or keeping natural hair is presented as a political choice. Like Awa, Ifemelu uses a blog to analyse race as a social construct that she discovers only in America.*\n\n**Points attendus** : identité avant / assignée ; stratégies (s’adapter, résister, écrire) ; comparaison précise avec le roman."}$exo$::jsonb),
  ('e91ce959-c6d3-5ae0-b23c-d0814e555034'::uuid, 3, 'traduction', $exo${"titre":"Americanah and Brooklyn: can you go home again?","consigne":"Rédige en anglais une synthèse d’environ 250 mots qui croise les documents (B inventé pour l’exercice) et compare les deux romans au programme.","enonce":"**Document A — About the two novels (from the course)**\n\nBoth novels follow a young woman who leaves alone for America, torn between two shores. But Eilis (*Brooklyn*, 1950s) fits into a white, Catholic community, whereas Ifemelu (*Americanah*, 1990s-2000s) discovers that her **skin colour** defines her place.\n\n**Document B — Extract from a novel (invented)**\n\n> At the airport in Lagos, her mother cried, her uncle took her suitcase, and a boy selling phone cards called her “Madam America”. In the taxi, she noticed that she had started counting the potholes, as a tourist would. She stopped herself. This was not a place to visit. It was home — wasn’t it?\n\n**Consigne.** *Compare how* Americanah *and* Brooklyn *present the experience of migration and return, and discuss whether one can really go home after emigrating.*","bareme":[{"critere":"Comparaison des arrivées : intégration d’Eilis dans une communauté blanche et catholique / race assignée à Ifemelu","points":5},{"critere":"Retours comparés (Eilis après la mort de Rose ; Ifemelu à Lagos treize ans plus tard, peur d’être une Americanah)","points":5},{"critere":"Doc. B analysé (regard de touriste, surnom, question finale) et relié au titre Americanah","points":5},{"critere":"Synthèse construite, réponse nuancée, anglais riche, environ 250 mots","points":5}],"dureeMin":20,"corrige":"**Model synthesis (about 250 words)**\n\n*Brooklyn and Americanah both follow a young woman who leaves alone for America and is torn between two shores. Yet their experiences differ deeply, and both novels ask whether one can go home again.*\n\n*As doc. A explains, Eilis Lacey, in the 1950s, fits into a white, Catholic community: her difficulties are loneliness, homesickness and work. Ifemelu, in the 1990s-2000s, discovers something else: in the United States her skin colour defines her place, and she “becomes black” there. Her blog analyses race as a social construct, whereas Eilis’s identity is never questioned in this way.*\n\n*Both heroines return. After Rose’s death, Eilis goes back to Enniscorthy and realises that she has changed: people now see her as someone. Ifemelu returns to Lagos after thirteen years, fearing to be an “Americanah”, the mocking name for those who come back with American manners. Doc. B captures this fear: the heroine is called “Madam America” and catches herself looking at her city “as a tourist would”. Her final question, “It was home — wasn’t it?”, expresses the doubt of all returning migrants.*\n\n*Can one go home, then? Not to the same home, because the migrant has changed and so has the country. Eilis answers by choosing Brooklyn; Ifemelu chooses Lagos, but a Lagos she must rediscover, while her love story with Obinze resists the continents. Going home is possible only if home is chosen again, not simply found.*\n\n**Points attendus** : comparaison précise des deux romans ; retour et regard changé ; sens du titre ; nuance finale ; connecteurs (*whereas, yet, both*)."}$exo$::jsonb),
  ('8be651c1-81b1-5064-9a60-37b007963788'::uuid, 1, 'traduction', $exo${"titre":"Love Laws and Small Things","consigne":"Réponds en anglais, en phrases complètes.","enonce":"**Invisible borders**\n\n1. In Arundhati Roy’s *The God of Small Things* (1997), what do the **Love Laws** say? Which characters break them, and why is it a transgression?\n\n2. Explain the title: what is the difference between the **Big Things** and the **Small Things**? Who is the “God of Small Things”?\n\n3. How is the story **told** (time, order)? What is the effect?\n\n4. Give two dates of the history of India mentioned in class and say what they correspond to.","bareme":[{"critere":"Love Laws (who should be loved, and how, and how much) ; Ammu et Velutha, caste haute et intouchable","points":6},{"critere":"Titre expliqué : Histoire, caste, politique / gestes intimes ; Velutha, dieu des petites choses","points":5},{"critere":"Récit fragmenté entre 1969 et 1993, issue connue d’avance, on apprend comment","points":5},{"critere":"Deux repères exacts (British Raj 1858-1947, indépendance et Partition 1947…), anglais correct","points":4}],"dureeMin":8,"corrige":"**1.** *The Love Laws are the laws that say “who should be loved, and how. And how much.” Ammu, a divorced woman from a high caste, and Velutha, an untouchable carpenter, break them by loving each other. Crossing the border of caste is a transgression, and they are punished with extreme violence.*\n\n**2.** *The Big Things are History, caste and politics; the Small Things are a gesture, a look, a night. Velutha is the God of Small Things, and the big things finally crush him.*\n\n**3.** *The story moves between 1969 (the tragedy) and 1993 (Rahel’s return), in fragments and without chronological order. We know the outcome from the beginning and learn little by little how it happened.*\n\n**4.** *The British Raj (1858-1947): India ruled directly by the British Crown. 1947: independence and Partition between India and Pakistan, with violence and the displacement of millions of people.* (Accepter aussi : 1981, *Midnight’s Children* ; 1997, Booker Prize du roman.)"}$exo$::jsonb),
  ('8be651c1-81b1-5064-9a60-37b007963788'::uuid, 2, 'traduction', $exo${"titre":"A child’s English","consigne":"Lis l’extrait (texte inventé pour l’exercice, à la manière d’un récit à hauteur d’enfant) et analyse en anglais son écriture (environ 150 mots).","enonce":"**Document — Extract from a novel (invented)**\n\n> The Grown-Ups had a Serious Talk in the dining room. Mina listened at the door with her ear and her whole self. She heard the words Not Our Kind and Before It’s Too Late. Then the door opened and Aunt Lila said, “Bedtime,” which meant Goaway.\n> In bed, Mina read the word STOP on her toy sign backwards: POTS. It sounded better. Pots were for cooking, and nobody got hurt by pots.\n\n**Task.** In about 150 words:\n1. Identify **three** techniques of this child’s language (capitals, joined words, words read backwards…).\n2. Explain what each technique **reveals** about the child’s view of the adults’ world.\n3. What **invisible border** is suggested by the adults’ words?\n4. Explain why such a use of English can be called **postcolonial** in Arundhati Roy’s novel.","bareme":[{"critere":"Trois procédés identifiés avec citations (majuscules inattendues, mots collés, mot lu à l’envers)","points":6},{"critere":"Effet de chaque procédé expliqué (regard d’enfant, sens caché, désir de protection)","points":6},{"critere":"Frontière invisible repérée (Not Our Kind : caste, classe…)","points":3},{"critere":"Geste postcolonial expliqué (anglais de l’ancien colonisateur réinventé), anglais correct","points":5}],"dureeMin":12,"corrige":"**Model answer (about 150 words)**\n\n*The extract is written at the height of a child. First, unexpected capitals (“the Grown-Ups”, “a Serious Talk”, “Not Our Kind”) turn the adults’ words into mysterious titles: Mina does not understand them, but she feels they are important and threatening. Second, joined words: “Goaway” shows how she hears “Bedtime” — as a rejection. Third, a word read backwards: STOP becomes POTS, which “sounded better”; the child reinvents language to protect herself from danger (“nobody got hurt”).*\n\n*“Not Our Kind” suggests an invisible border, of caste or class, that the adults want to guard “Before It’s Too Late”.*\n\n*In The God of Small Things, Roy uses the same techniques (words cut or joined, capitals like “Things Can Change in a Day”, words read backwards). Reinventing English, the language of the former colonizer, is a postcolonial gesture: the language is taken back and reshaped.*\n\n**Points attendus** : trois procédés ; effets ; frontière invisible ; geste postcolonial."}$exo$::jsonb),
  ('8be651c1-81b1-5064-9a60-37b007963788'::uuid, 3, 'traduction', $exo${"titre":"Borders that are on no map","consigne":"Rédige en anglais une synthèse d’environ 250 mots croisant les trois documents (B inventé pour l’exercice).","enonce":"**Document A — Arundhati Roy, *The God of Small Things* (1997)**\n\nThe Love Laws are the laws that lay down “who should be loved, and how. And how much.”\n\n**Document B — Extract from a short story (invented)**\n\n> Every afternoon, Ravi, the gardener’s son, and Priya, the owner’s daughter, played cricket behind the mango trees, where the house could not see them. The day her father found them, he said nothing to Ravi. He only told the gardener that the garden would no longer need him.\n\n**Document C — The Partition of 1947 (from the course)**\n\nIn 1947, India became independent and was partitioned: India and Pakistan separated, with violence and the displacement of millions of people.\n\n**Consigne.** *Using the documents and your knowledge of* The God of Small Things*, show how invisible borders (caste, class, religion) can be as violent as borders on a map, and who guards them.*","bareme":[{"critere":"Doc. A et le roman : Love Laws, Ammu et Velutha, punition, complicité de la police et du Parti","points":6},{"critere":"Doc. B : frontière de classe, gardiens (le père), sanction silencieuse qui frappe le plus faible","points":5},{"critere":"Doc. C : frontière tracée sur la carte, violence, lien avec les frontières invisibles","points":4},{"critere":"Synthèse construite, documents croisés, anglais riche, environ 250 mots","points":5}],"dureeMin":20,"corrige":"**Model synthesis (about 250 words)**\n\n*Some borders are drawn on maps; others exist only in people’s minds. The three documents suggest that the second kind can be just as violent as the first.*\n\n*Doc. C recalls a very visible border: the Partition of 1947, which separated India and Pakistan and caused violence and the displacement of millions of people. A line on a map, drawn at the end of the British Raj, broke lives.*\n\n*The Love Laws (doc. A) draw a different border, which no map shows: they decide “who should be loved, and how. And how much.” In The God of Small Things, Ammu, a divorced woman of high caste, and Velutha, an untouchable carpenter, cross it. The punishment is extremely violent, with the complicity of the police and even of the local Communist Party. The border is guarded by the family, the institutions and the political party alike.*\n\n*Doc. B shows the same mechanism on a smaller scale. The children play “where the house could not see them”, as if their friendship had to hide. The father, guardian of the class border, does not shout: he simply dismisses the gardener. As in Roy’s novel, it is the weakest who pays.*\n\n*These borders are violent precisely because they are invisible: they seem natural and are rarely questioned. Roy’s title opposes the Big Things, History, caste and politics, to the Small Things, a game, a look, a love, and shows how the first crush the second. Yet by telling these small things, literature makes the invisible borders visible.*\n\n**Points attendus** : trois frontières ; gardiens (famille, institutions, police, parti) ; Big / Small Things ; croisement ; conclusion."}$exo$::jsonb),
  ('10158543-c8bc-5b81-b270-816ca083e3cc'::uuid, 1, 'traduction', $exo${"titre":"Three men in a room","consigne":"Réponds en anglais, en phrases complètes.","enonce":"**Pinter’s room**\n\n1. Present the three characters of Harold Pinter’s *The Caretaker* (1960) and say what each one wants.\n\n2. Why does Davies keep talking about **Sidcup**? What does Sidcup represent?\n\n3. Define the **comedy of menace** and the adjective **Pinteresque**.\n\n4. How does the play end for Davies?","bareme":[{"critere":"Aston (l’abri de jardin), Mick (propriétaire, imprévisible), Davies (vagabond, Bernard Jenkins) et ce qu’ils veulent","points":7},{"critere":"Sidcup : papiers d’identité jamais récupérés, identité qu’on ne prouve pas","points":5},{"critere":"Comedy of menace (Irving Wardle) et Pinteresque définis","points":5},{"critere":"Fin : Davies chassé par les deux frères, anglais correct","points":3}],"dureeMin":8,"corrige":"**1.** *Aston, the elder brother, is calm and slow; he does odd jobs and dreams of building a garden shed. Mick, his younger brother, owns the house; he is unpredictable and ironic. Davies is a tramp whom Aston takes in; he also calls himself Bernard Jenkins, and he wants to keep a place in the room, as caretaker.*\n\n**2.** *Davies says he must go to Sidcup to get back his identity papers, left with someone “fifteen years” ago. He never goes: he waits for good weather or good shoes. Sidcup is the horizon that is never reached, the identity that cannot be proved.*\n\n**3.** *The comedy of menace (an expression of the critic Irving Wardle) makes us laugh while a threat hangs in the air without our knowing where it comes from. “Pinteresque” describes this climate of diffuse menace, heavy silences and apparently banal dialogue.*\n\n**4.** *The two brothers come together again, and Davies, who has played one against the other too much, is thrown out.*"}$exo$::jsonb),
  ('10158543-c8bc-5b81-b270-816ca083e3cc'::uuid, 2, 'traduction', $exo${"titre":"Who has the key?","consigne":"Lis la scène (inventée pour l’exercice, à la manière de Pinter) et analyse-la en anglais en suivant la méthode « analyser une scène de théâtre » (environ 150 mots).","enonce":"**Document — A scene (invented)**\n\n*A small room. One bed, one chair. RAY stands by the door. LEN sits on the bed.*\n\n> RAY. That’s my bed.\n> LEN. I know.\n> *Pause.*\n> RAY. You’re sitting on it.\n> LEN. I know.\n> *Silence.*\n> RAY. I’ve got the key, you know.\n> LEN. Have you?\n> RAY. I have.\n> LEN. *(taking a key from his pocket)* So have I.\n> *Long silence. RAY sits on the chair.*\n\n**Task.** In about 150 words:\n1. describe the **space** and its objects;\n2. analyse the **power struggle**: who dominates, and when does it switch?\n3. study the **unsaid**: pauses, silences, repetitions;\n4. describe the **effect on the audience** and link it to *The Caretaker*.","bareme":[{"critere":"Espace analysé : pièce minuscule, lit et chaise comme enjeux de territoire","points":4},{"critere":"Rapport de force et bascule repérés (la clé sortie de la poche, Ray qui s’assoit sur la chaise)","points":6},{"critere":"Non-dit analysé (pauses, silences, répétition de I know)","points":5},{"critere":"Effet (rire et malaise) et lien exact avec The Caretaker, anglais correct","points":5}],"dureeMin":12,"corrige":"**Model answer (about 150 words)**\n\n*The space is tiny: one bed and one chair. These objects become a territory, and the question is who may sit where.*\n\n*At first Ray seems to dominate: he stands, claims the bed (“That’s my bed”) and plays his trump card, “I’ve got the key”. Len answers only “I know”, a calm repetition that refuses to give in. The balance switches when Len takes out his own key: Ray’s power disappears, and he ends up sitting on the chair, accepting the lower place.*\n\n*Most of the meaning lies in what is not said: the pauses and silences are heavy with threat, and nobody explains why they both have a key. Language is used to dominate, not to communicate.*\n\n*The audience laughs at the absurd dialogue but feels uneasy: this is a comedy of menace. As in The Caretaker, a room is a territory, the key a sign of power, and the one without a place risks ending up outside.*\n\n**Points attendus** : espace ; rapport de force et bascule ; pauses, silences, répétitions ; *comedy of menace* ; lien précis avec la pièce (lit offert à Davies, rivalité des frères, Davies chassé)."}$exo$::jsonb),
  ('10158543-c8bc-5b81-b270-816ca083e3cc'::uuid, 3, 'traduction', $exo${"titre":"The room as a territory","consigne":"Rédige en anglais un essai d’environ 250 mots en t’appuyant sur la pièce et sur les deux citations (la seconde est inventée pour l’exercice).","enonce":"**Document A — From the course**\n\n> “In *The Caretaker*, the room is a territory: who sleeps there, who has the key, who may stay. Power relations are played out word by word — and the one who has no place of his own ends up outside.”\n\n**Document B — A theatre critic (invented)**\n\n> “Nothing happens in this play, and yet I left the theatre exhausted, as if I had watched a war.”\n\n**Consigne.** *Using the documents and your knowledge of* The Caretaker*, explain how Pinter turns a single room into a territory at war. Your essay should deal with the space, the characters’ power struggle, language and silence, and identity.*","bareme":[{"critere":"Espace analysé : chambre en désordre, seau, lit, clé ; la pièce comme territoire","points":5},{"critere":"Rapport de force exact : offres de Mick et d’Aston, Davies qui monte les frères l’un contre l’autre, Davies chassé","points":5},{"critere":"Langage et silences (pauses, répétitions, passé invérifiable), monologue d’Aston, Sidcup et identité","points":6},{"critere":"Doc. B exploité, essai construit, anglais riche, environ 250 mots","points":4}],"dureeMin":20,"corrige":"**Model essay (about 250 words)**\n\n*The critic in doc. B is right: “nothing happens” in The Caretaker, and yet the play feels like a war. Pinter turns one room into a battlefield.*\n\n*The space itself is a territory. The play takes place in a cluttered room in a house in west London, with an old bucket hanging from the ceiling to catch a leak. A bed, a key, a place to stay: these simple things become the stakes of the conflict. As doc. A says, the question is who sleeps there and who may stay.*\n\n*The power struggle is constantly shifting. Aston takes Davies in and offers him a bed; Mick, the owner, first threatens him, then offers him the job of caretaker, and Aston does the same. Davies tries to set the brothers against each other to secure his place, but he plays too much: the brothers come together again and he is thrown out.*\n\n*The war is fought with words and silences. The pauses and silences written by Pinter weigh more than the lines; repetitions and absurd dialogue serve to defend oneself or to dominate. No one can prove his past: Davies uses a false name, Bernard Jenkins, and never goes to Sidcup to get his papers. At the end of Act II, Aston’s long monologue about his internment and electric shocks reveals the wounds under the calm.*\n\n*This is the essence of the comedy of menace: we laugh, but we feel a threat everywhere. In Pinter’s room, the one who has no place of his own, and no proof of who he is, ends up outside.*\n\n**Points attendus** : espace ; rapport de force exact ; langage et silence ; identité (Sidcup, faux nom) ; *comedy of menace*."}$exo$::jsonb),
  ('d29170a6-b507-5a0d-abeb-bdf01882733d'::uuid, 1, 'traduction', $exo${"titre":"The synthesis: rules and connectors","consigne":"Réponds en français ou en anglais aux questions 1 et 2 ; la question 3 se fait en anglais.","enonce":"**Writing a synthesis**\n\n1. Give the format of the written exam of LLCER in Terminale: duration, the two parts, points, expected length of the synthesis.\n\n2. List the **six steps** of the method, in order. Why must a synthesis **not** present the documents one after the other?\n\n3. Classify these connectors by function (add · oppose · concede · conclude · compare): **moreover** · **whereas** · **although** · **therefore** · **likewise** · **however** · **admittedly** · **in addition** · **thus** · **similarly**.","bareme":[{"critere":"Format exact : 3 h 30, synthèse sur 16 points (environ 500 mots, 3 ou 4 documents), traduction ou transposition sur 4","points":6},{"critere":"Six étapes dans l’ordre et principe du croisement expliqué","points":8},{"critere":"Dix connecteurs correctement classés","points":6}],"dureeMin":8,"corrige":"**1.** L’écrit dure **3 h 30**. Partie 1 : synthèse en anglais d’un dossier de **trois ou quatre documents**, guidée par deux ou trois consignes, **16 points**, environ **500 mots**. Partie 2 : **traduction** vers le français d’un passage d’environ 500 signes **ou transposition** en français, **4 points**.\n\n**2.** (1) Lire les consignes avant les documents ; (2) identifier chaque document (nature, auteur, date, point de vue) ; (3) surligner les idées, une couleur par consigne ; (4) trouver les liens (échos, oppositions, évolutions) ; (5) bâtir le plan (introduction avec problématique, une partie par consigne, conclusion qui ouvre) ; (6) rédiger et relire. Une synthèse **croise** les documents : chaque paragraphe répond à une idée et fait dialoguer au moins deux documents ; les présenter l’un après l’autre revient à un résumé, pas à une mise en relation.\n\n**3.**\n- Add: *moreover, in addition*\n- Oppose: *whereas, however*\n- Concede: *although, admittedly*\n- Conclude: *therefore, thus*\n- Compare: *likewise, similarly*\n\n(Critère sur 6 : retirer 1 point par connecteur mal classé.)"}$exo$::jsonb),
  ('d29170a6-b507-5a0d-abeb-bdf01882733d'::uuid, 2, 'traduction', $exo${"titre":"An introduction and a plan","consigne":"À partir de la présentation du dossier (documents inventés pour l’exercice), rédige en anglais une introduction d’environ 80 mots puis le plan détaillé de ta synthèse.","enonce":"**The file**\n\n- **Doc. A** — extract from a novel (2015): a Nigerian teenager arrives in London and is ashamed of her accent at school.\n- **Doc. B** — a photograph (1960s): a group of newly arrived Caribbean workers smiling on a railway platform in England, carrying suitcases.\n- **Doc. C** — a newspaper article (2021): a survey shows that most young migrants in the UK feel “at home” after five years, but still feel judged by their accent.\n\n**Consignes of the exam**\n1. *Show how the documents present the first experience of arriving in a new country.*\n2. *Explain what, according to the documents, helps or prevents migrants from feeling at home.*\n\n**Your task**\n- Write the **introduction** (about 80 words): present the file and state a problematic.\n- Give a **detailed plan**: for each consigne, two ideas, each crossing at least two documents, with one connector.","bareme":[{"critere":"Introduction qui présente les trois documents (nature, date) et pose une problématique","points":7},{"critere":"Plan : une partie par consigne, dans l’ordre","points":4},{"critere":"Chaque idée croise au moins deux documents avec un lien pertinent (écho, opposition, évolution)","points":6},{"critere":"Anglais correct, connecteurs variés","points":3}],"dureeMin":12,"corrige":"**Model introduction (about 80 words)**\n\n*This file deals with the experience of migrants arriving in Britain. It brings together an extract from a 2015 novel about a Nigerian teenager in London (doc. A), a 1960s photograph of Caribbean workers on a railway platform (doc. B) and a 2021 newspaper article based on a survey of young migrants (doc. C). How do these documents show that arriving in a new country is both a hope and a trial, and what makes it possible to feel at home?*\n\n**Model plan**\n\n**I. The first experience of arrival (consigne 1)**\n1. *A moment of hope*: the smiling workers of doc. B contrast with the shame of the teenager in doc. A — **whereas** the photograph shows confidence, the novel reveals vulnerability.\n2. *Being judged*: the accent that shames the girl (doc. A) is **also** what young migrants still feel judged by (doc. C).\n\n**II. What helps or prevents feeling at home (consigne 2)**\n1. *Time and community*: doc. C shows that most feel at home after five years; **similarly**, the group in doc. B suggests that arriving together helps.\n2. *The obstacle of others’ eyes*: **however**, docs. A and C show that the accent keeps migrants foreign in others’ eyes.\n\n**Conclusion (ouverture)** : *feeling at home depends as much on the host country as on the migrant.*\n\nToute idée juste qui croise deux documents est acceptée ; ce qui est refusé : un plan document par document, une consigne oubliée."}$exo$::jsonb),
  ('d29170a6-b507-5a0d-abeb-bdf01882733d'::uuid, 3, 'traduction', $exo${"titre":"Writing a synthesis paragraph","consigne":"Lis les trois documents (inventés pour l’exercice) et rédige en anglais UN paragraphe de synthèse d’environ 200 mots répondant à la consigne.","enonce":"**Document A — Extract from a novel (invented)**\n\n> The first winter, Tomas wrote to his mother every Sunday. He described the snow, the factory, the church. He never mentioned that he ate alone.\n\n**Document B — Description of a poster (invented), 1950s**\n\nA smiling family stands in front of a large white house with a car. In the foreground, the caption: “A new life is waiting for you.”\n\n**Document C — Extract from an interview (invented), 2019**\n\n> “People think the hardest part is the journey. It isn’t. The hardest part is the Tuesday afternoon, three months later, when nobody knows your name.”\n\n**Consigne.** *Show how the documents present the gap between the dream of emigration and the reality of arrival.*\n\n**Requirements**: cross the three documents (no document-by-document presentation), name them (doc. A, B, C), quote briefly, use at least three different connectors, and do not give your personal opinion.","bareme":[{"critere":"Les trois documents croisés et nommés dès les premières phrases, citations brèves","points":6},{"critere":"Écart rêve / réalité analysé : promesse de l’affiche, silence des lettres, solitude ordinaire","points":6},{"critere":"Point de vue de chaque document correctement identifié (propagande, récit, témoignage)","points":3},{"critere":"Au moins trois connecteurs de fonctions différentes, anglais correct, environ 200 mots, pas d’avis hors sujet","points":5}],"dureeMin":18,"corrige":"**Model paragraph (about 200 words)**\n\n*While the 1950s poster (doc. B) sells emigration as a dream, the two texts reveal a much lonelier reality. The poster shows a smiling family in front of a “large white house” with a car, and its caption promises that “a new life is waiting for you”: it is an advertisement, designed to make people leave. In contrast to this image of immediate happiness, Tomas, in the novel extract (doc. A), describes “the snow, the factory, the church” to his mother, but “never mentioned that he ate alone”. His letters hide the gap between what he hoped for and what he lives, as if he wanted to protect the dream for those who stayed behind. Similarly, the woman interviewed in 2019 (doc. C) explains that the real difficulty is not the journey but ordinary loneliness, “the Tuesday afternoon, three months later, when nobody knows your name”. Thus, although the three documents come from different periods and genres, they all show that the reality of arrival lies less in dramatic events than in isolation. Therefore, the dream of emigration is built on images, whereas its reality is made of silences.*\n\n**Points attendus** : croisement immédiat ; les trois documents nommés et cités ; identification du point de vue (affiche publicitaire, récit, témoignage) ; connecteurs (*while, in contrast to, similarly, thus, although, therefore, whereas*) ; aucune opinion personnelle."}$exo$::jsonb),
  ('c493af3a-5294-5010-b7a8-92a4f2be6bb0'::uuid, 1, 'traduction', $exo${"titre":"Five traps in five sentences","consigne":"Traduis en français les cinq phrases, puis nomme en une ligne le piège de chacune.","enonce":"**Traduis en français.**\n\n1. I have lived in this town for ten years.\n2. Actually, she never read the letter.\n3. He swam across the river.\n4. Eventually, they sold the house.\n5. The children went to the library every Saturday.\n\nPour chaque phrase, indique en une ligne le **piège** (temps, faux ami, chassé-croisé…).","bareme":[{"critere":"Present perfect + for rendu par le présent et depuis (phrase 1)","points":4},{"critere":"Faux amis actually, eventually, library correctement traduits (phrases 2, 4, 5)","points":9},{"critere":"Chassé-croisé de la phrase 3 (traverser à la nage)","points":4},{"critere":"Pièges nommés et français correct","points":3}],"dureeMin":7,"corrige":"1. **J’habite dans cette ville depuis dix ans.** Piège : le *present perfect* + *for* exprime une durée qui continue → présent + « depuis » (et non « j’ai vécu… pendant dix ans »).\n2. **En fait, elle n’a jamais lu la lettre.** Piège : faux ami *actually* = « en fait », pas « actuellement ».\n3. **Il traversa la rivière à la nage.** (« Il a traversé la rivière à la nage » accepté.) Piège : chassé-croisé — l’anglais met le mouvement dans la particule (*across*), le français dans le verbe (« traverser »), la manière passe en complément (« à la nage »).\n4. **Finalement, ils vendirent la maison.** (« ils ont vendu » accepté.) Piège : faux ami *eventually* = « finalement », pas « éventuellement ».\n5. **Les enfants allaient à la bibliothèque tous les samedis.** Piège : faux ami *library* = « bibliothèque », pas « librairie » ; l’habitude (*every Saturday*) appelle l’imparfait."}$exo$::jsonb),
  ('c493af3a-5294-5010-b7a8-92a4f2be6bb0'::uuid, 2, 'traduction', $exo${"titre":"Translating a narrative passage","consigne":"Traduis en français le passage (texte inventé pour l’exercice, environ 500 signes), dans un français correct et fidèle au ton.","enonce":"**Document — Extract from a novel (invented)**\n\n> When Anna came home, the house was silent. She tiptoed up the stairs and pushed open her brother’s door. He was sitting on the floor, surrounded by old photographs. He pretended not to have heard her. Actually, he had been crying. She sat down beside him without a word. Eventually, he handed her a picture of their father, young and laughing, on a beach she had never seen.\n\nAttention au **prétérit** dans un récit, aux **verbes à particule**, aux **faux amis** et au ton.","bareme":[{"critere":"Temps du récit rendus (passé simple ou passé composé cohérent, imparfait, plus-que-parfait pour had been crying)","points":5},{"critere":"Chassé-croisé de tiptoed up the stairs et pushed open rendus idiomatiquement","points":5},{"critere":"Faux amis pretended, actually, eventually correctement traduits","points":6},{"critere":"Sens complet (rien d’oublié ni d’ajouté), ton sobre, français correct","points":4}],"dureeMin":12,"corrige":"**Traduction modèle**\n\nQuand Anna rentra, la maison était silencieuse. Elle monta l’escalier sur la pointe des pieds et poussa la porte de son frère. Il était assis par terre, entouré de vieilles photographies. Il fit semblant de ne pas l’avoir entendue. En fait, il avait pleuré. Elle s’assit à côté de lui sans un mot. Finalement, il lui tendit une photo de leur père, jeune et riant, sur une plage qu’elle n’avait jamais vue.\n\n**Points attendus**\n- Temps : passé simple (ou passé composé employé de façon cohérente) pour les actions ; imparfait pour la description (*was silent, was sitting*) ; plus-que-parfait pour *had been crying* et *had never seen*.\n- *tiptoed up the stairs* → « monta l’escalier sur la pointe des pieds » (chassé-croisé) ; *pushed open* → « poussa (ouvrit) la porte ».\n- *pretended* → « fit semblant » (pas « prétendit ») ; *Actually* → « En fait » (pas « actuellement ») ; *Eventually* → « Finalement » (pas « éventuellement »).\n- Accord : « entendue » (Anna) ; « vue » (la plage).\n- *laughing* → « riant » ou « qui riait » ; *handed* → « tendit »."}$exo$::jsonb),
  ('c493af3a-5294-5010-b7a8-92a4f2be6bb0'::uuid, 3, 'traduction', $exo${"titre":"Translate, justify, transpose","consigne":"Partie A : traduis les trois phrases et justifie chaque choix. Partie B : transpose le texte en français (environ 80 mots). Les textes sont inventés pour l’exercice.","enonce":"**Partie A — Traduis et justifie en une ou deux lignes chaque choix.**\n\n1. She was given a room at the back of the house.\n2. The boy came running into the kitchen.\n3. I have never been back since.\n\n**Partie B — Transposition.** Rends compte en français, avec tes propres mots, des idées principales de ce texte, sans citer ni commenter.\n\n> Many people believe that translation is a matter of finding the right words. Translators know better. A sentence carries a rhythm, a tone, sometimes a joke that only works in one language. Translating it word for word is like copying a melody note by note on the wrong instrument: every note is correct, and the music is gone. A good translation, therefore, is not the most literal one, but the one that makes the reader feel what the original reader felt.","bareme":[{"critere":"Passif rendu naturellement (On lui donna / On lui attribua une chambre…) avec justification","points":4},{"critere":"Forme en -ing et particule rendues (arriva en courant dans la cuisine) avec justification","points":4},{"critere":"Present perfect de bilan rendu (Je n’y suis jamais retourné depuis) avec justification","points":4},{"critere":"Transposition fidèle aux idées et au point de vue, reformulée sans citer ni commenter, concise","points":8}],"dureeMin":20,"corrige":"**Partie A**\n1. **On lui donna une chambre à l’arrière de la maison.** (« On lui attribua… », « On lui a donné… » acceptés.) Le passif anglais avec un complément d’attribution (*She was given*) n’a pas d’équivalent naturel : « Elle fut donnée une chambre » est impossible. On passe par « on ».\n2. **Le garçon arriva dans la cuisine en courant.** (« entra en courant dans la cuisine » accepté.) *came running* : le verbe de mouvement *came* + *into* devient « arriver / entrer dans », la forme en *-ing* devient un gérondif « en courant » ; « vint courant » est un calque fautif.\n3. **Je n’y suis jamais retourné(e) depuis.** Le *present perfect* exprime ici un bilan qui touche au présent, sans durée qui continue : le passé composé convient ; « y » rend le lieu sous-entendu par *back*.\n\n**Partie B — Transposition modèle (environ 80 mots)**\nL’auteur conteste l’idée courante selon laquelle traduire consisterait seulement à trouver les mots justes. Selon lui, une phrase porte aussi un rythme, un ton, parfois un trait d’humour propre à une langue. Une traduction mot à mot ressemble à une mélodie recopiée note pour note sur un instrument inadapté : exacte dans le détail, elle perd la musique. La bonne traduction n’est donc pas la plus littérale, mais celle qui fait éprouver au lecteur ce qu’éprouvait le lecteur de l’original.\n\nAttendus pour la transposition : les quatre idées (idée reçue ; ce que porte une phrase ; comparaison de la mélodie ; définition de la bonne traduction), reformulées, sans citation ni commentaire personnel, en conservant le point de vue de l’auteur."}$exo$::jsonb),
  ('aa6ff3eb-9c30-549a-9fe5-b939820131fb'::uuid, 1, 'traduction', $exo${"titre":"The oral exam and the personal portfolio","consigne":"Réponds en anglais, en phrases complètes.","enonce":"**Your personal portfolio**\n\n1. How long does the LLCER oral exam last in Terminale? Is there any preparation time? How is it divided?\n\n2. What must the **personal portfolio** contain (number of documents, types of documents, limits)?\n\n3. What gives the portfolio its **unity**?\n\n4. Name the **two** skills the examiner assesses, and the level expected at the end of Terminale.","bareme":[{"critere":"20 minutes sans préparation : 10 minutes de présentation au plus, 10 minutes d’échange","points":6},{"critere":"Composition : au moins quatre documents, un extrait d’œuvre intégrale, textes littéraires, au plus deux œuvres d’art visuel, tous du monde anglophone","points":7},{"critere":"Unité donnée par une problématique","points":3},{"critere":"Parole en continu et interaction ; B2 (C1 pour certaines compétences), anglais correct","points":4}],"dureeMin":7,"corrige":"**1.** *The oral exam lasts twenty minutes, with no preparation time. For up to ten minutes, I present my portfolio in English, justifying the choice of documents and explaining their logic; then for ten minutes I talk with the examiner, who asks me to go deeper, clarify and defend my ideas.*\n\n**2.** *The portfolio contains at least four documents (four to six), linked to the themes studied: at least one extract from one of the complete works studied in class, literary texts, at most two works of visual art (painting, poster, film extract, photograph…), and possibly a document of another kind (article, speech). All the documents come from the English-speaking world.*\n\n**3.** *Its unity comes from a problematic: this question turns the documents into a whole, not a collection.*\n\n**4.** *The examiner assesses continuous speech and interaction. The level expected at the end of Terminale is B2, and C1 for some skills.*"}$exo$::jsonb),
  ('aa6ff3eb-9c30-549a-9fe5-b939820131fb'::uuid, 2, 'traduction', $exo${"titre":"What is wrong with this portfolio?","consigne":"Lis le dossier proposé par Léo, repère en anglais ce qui ne respecte pas les règles ou la méthode, puis propose une version corrigée.","enonce":"**Léo’s portfolio — theme “Voyages, territoires, frontières”**\n\nTitle: *Travelling*\n\n1. A painting by the French artist Claude Monet showing a train station in Paris (1877).\n2. A photograph of Ellis Island in 1905.\n3. A poster for the film *Killers of the Flower Moon* (2023).\n4. A still from *Brooklyn* (the 2015 film adaptation of Colm Tóibín’s novel).\n5. A newspaper article about cheap flights in Europe, taken from an English website.\n\nLéo’s class has studied *Brooklyn* (Tóibín, 2009) as its complete literary work for this theme.\n\n**Task.**\n1. List **four problems** in this portfolio (rules or method) and explain each one.\n2. Propose a corrected portfolio: a **problematic** in English and a list of four or five documents (you may keep some of Léo’s documents), respecting the rules.","bareme":[{"critere":"Problèmes repérés : plus de deux œuvres d’art visuel (quatre images)","points":4},{"critere":"Problèmes repérés : document non anglophone (Monet), aucun extrait de l’œuvre intégrale étudiée (roman), aucun texte littéraire","points":5},{"critere":"Problème de méthode : pas de problématique (un simple titre), collection plutôt que dossier","points":3},{"critere":"Dossier corrigé cohérent : problématique, extrait du roman, textes littéraires, au plus deux images, documents anglophones","points":8}],"dureeMin":12,"corrige":"**1. Problems**\n- *Too many visual works: documents 1 to 4 are all images, but the portfolio may contain at most two works of visual art.*\n- *Document 1 is by a French painter: all documents must come from the English-speaking world.*\n- *There is no extract from the complete work studied in class: a still from the film adaptation is not an extract from Tóibín’s novel. There are no literary texts at all.*\n- *“Travelling” is only a title, not a problematic: the documents form a collection, not a whole.* (Accepter aussi : l’article sur les vols low-cost est hors de l’axe, sans lien évident avec les autres documents.)\n\n**2. Corrected portfolio (example)**\nProblematic: ***Can one ever really go home after emigrating?***\n1. An extract from *Brooklyn* (Colm Tóibín, 2009): Eilis back in Enniscorthy after Rose’s death.\n2. “The New Colossus” (Emma Lazarus, 1883), the poem engraved on the Statue of Liberty.\n3. An extract from *The Lonely Londoners* (Sam Selvon, 1956).\n4. The photograph of Ellis Island in 1905 (one visual work).\n5. A newspaper article on the Windrush generation (another kind of document).\n\nToute proposition qui respecte les règles (au moins quatre documents, un extrait de l’œuvre intégrale, des textes littéraires, au plus deux œuvres visuelles, tous anglophones) et porte une vraie question est acceptée."}$exo$::jsonb),
  ('aa6ff3eb-9c30-549a-9fe5-b939820131fb'::uuid, 3, 'traduction', $exo${"titre":"Building and presenting a portfolio","consigne":"Construis un dossier à partir de la banque de documents, puis rédige en anglais le début de ta présentation orale (environ 200 mots).","enonce":"**Document bank (axis “L’expression des émotions”)**\n\n- A. An extract from *The Piano* (Jane Campion, 1993): Ada wins back her piano, key by key, in exchange for lessons.\n- B. Shakespeare, Sonnet 18 (“Shall I compare thee to a summer’s day?”).\n- C. A poem by Emily Dickinson, “Hope is the thing with feathers”.\n- D. A painting by a French artist of a woman crying.\n- E. A photograph by the American photographer Dorothea Lange.\n- F. A newspaper article about sign language in schools, from a British newspaper.\n- G. A poster for a Hollywood musical comedy.\n- H. The preface to the *Lyrical Ballads* (Wordsworth, 1800): poetry as “the spontaneous overflow of powerful feelings”.\n\nThe complete work studied in class for this theme is *The Piano*.\n\n**Task.**\n1. Choose **five** documents, respecting the rules, and justify **in one line** each choice (and one document you reject, with the reason).\n2. Write a **problematic** in English.\n3. Write the **beginning of your oral presentation** (about 200 words): introduce your problematic and explain the logic linking the documents, as you would say it to the examiner, without reading.","bareme":[{"critere":"Sélection conforme (extrait de The Piano, textes littéraires, au plus deux œuvres visuelles, rejet justifié de D ou G)","points":5},{"critere":"Problématique claire, en anglais, liée à l’axe","points":3},{"critere":"Présentation : logique de l’enchaînement expliquée, liens précis entre les documents, connaissances exactes","points":7},{"critere":"Anglais oral fluide et riche (connecteurs, vocabulaire de l’analyse), environ 200 mots","points":5}],"dureeMin":20,"corrige":"**1. Selection (example)**\n- A *The Piano* — the complete work studied, required; the heart of the question.\n- B Sonnet 18 — emotion given a strict form (14 lines).\n- C Dickinson — emotion in brief images.\n- H Wordsworth — a theory of poetic emotion.\n- F article on sign language — another way of speaking without words (a document of another kind).\n(E, the Lange photograph, can replace one text: at most two visual works in all.)\n- Rejected: **D**, by a French artist (not from the English-speaking world); **G**, no link with the problematic.\n\n**2. Problematic** : ***What do we say when words fail?***\n\n**3. Model presentation (about 200 words)**\n*My portfolio asks a simple question: what do we say when words fail? I started from Jane Campion’s film The Piano, which I studied in class. Its heroine, Ada, is mute, and yet she is one of the most expressive characters I know: her piano, and Michael Nyman’s music, are her voice. In the scene I chose, she wins back her piano key by key, which shows that recovering her instrument means recovering herself.*\n*I then wanted to see how poets deal with emotion. Wordsworth defines poetry as “the spontaneous overflow of powerful feelings”: for him, emotion must come out in words. Shakespeare’s Sonnet 18, on the contrary, shows emotion controlled by a strict form of fourteen lines, and Emily Dickinson compresses it into short images, like hope as “the thing with feathers”.*\n*Finally, the article on sign language brings me back to Ada, who signs: it shows that language is not only made of spoken words.*\n*So my documents move from silence to words and back to silence, and they suggest that when words fail, emotion always finds another form.*\n\nAttendus : règles respectées ; liens explicites ; pas de lecture de notes ; justifications précises."}$exo$::jsonb),
  ('9e1162b2-61ad-52db-b09c-fc7948bfc2c3'::uuid, 1, 'traduction', $exo${"titre":"The analysis toolbox","consigne":"Traduis les termes (question 1 vers l’anglais, question 2 vers le français), puis réponds en anglais à la question 3.","enonce":"**Words to analyse**\n\n1. Translate into English: **une strophe** · **un dramaturge** · **un narrateur non fiable** · **au premier plan** · **une légende (sous une image)** · **une contre-plongée**.\n\n2. Translate into French: **a simile** · **understatement** · **a tracking shot** · **a voice-over** · **to depict** · **free indirect speech**.\n\n3. Name the figure of speech in each example and explain it briefly:\n   - a. “sweet sorrow”\n   - b. “lonely as a cloud”\n   - c. “It’s a bit chilly” (said at −20 °C)","bareme":[{"critere":"Six traductions justes vers l’anglais","points":6},{"critere":"Six traductions justes vers le français","points":6},{"critere":"Figures identifiées et expliquées : oxymore, comparaison (simile), litote (understatement)","points":8}],"dureeMin":8,"corrige":"**1.** une strophe → *a stanza* · un dramaturge → *a playwright* · un narrateur non fiable → *an unreliable narrator* · au premier plan → *in the foreground* · une légende → *a caption* · une contre-plongée → *a low-angle shot*.\n\n**2.** *a simile* → une comparaison (avec *like* ou *as*) · *understatement* → la litote · *a tracking shot* → un travelling · *a voice-over* → une voix off · *to depict* → dépeindre, représenter · *free indirect speech* → le discours indirect libre.\n\n**3.**\n- a. *An oxymoron: two opposite terms are joined (“sweet” and “sorrow”).*\n- b. *A simile: a comparison introduced by “as”.*\n- c. *Understatement: saying less in order to suggest more — at −20 °C, it is much more than “a bit chilly”.*"}$exo$::jsonb),
  ('9e1162b2-61ad-52db-b09c-fc7948bfc2c3'::uuid, 2, 'traduction', $exo${"titre":"Describing and interpreting a cartoon","consigne":"À partir de la description du dessin (inventé pour l’exercice), rédige en anglais une analyse d’environ 150 mots en suivant les quatre étapes de la méthode « décrire avant d’interpréter ».","enonce":"**Document — A cartoon published in a British magazine (invented), 2022**\n\n- **Au premier plan, à gauche** : un homme en costume, très grand, assis sur une pile de livres fermés, lit un téléphone.\n- **Au centre** : une petite fille tend un livre ouvert vers lui ; elle est dessinée beaucoup plus petite.\n- **À l’arrière-plan, à droite** : une bibliothèque municipale dont la porte porte l’écriteau « CLOSED ».\n- **Légende en bas** : “Don’t worry, sweetheart — it’s all online now.”\n\n**Task.** In about 150 words, in English:\n1. **identify** the document;\n2. **describe** it precisely with the vocabulary of image analysis (foreground, background, left-hand side, caption…);\n3. **interpret** the details (“this suggests…”, “this conveys…”); name the figure of speech used in the caption;\n4. **relate** it to a debate.","bareme":[{"critere":"Document identifié (cartoon, British magazine, 2022)","points":2},{"critere":"Description précise avec le vocabulaire de l’image (foreground, background, on the left/right-hand side, caption)","points":7},{"critere":"Interprétation des contrastes de taille, des livres fermés, de la porte fermée ; ironie de la légende repérée","points":7},{"critere":"Anglais correct, verbes de l’analyse (suggest, convey, depict, contrast with), environ 150 mots","points":4}],"dureeMin":12,"corrige":"**Model answer (about 150 words)**\n\n*This document is a cartoon published in a British magazine in 2022. In the foreground, on the left-hand side, a very tall man in a suit is sitting on a pile of closed books while looking at his phone. In the centre, a much smaller girl holds out an open book to him. In the background, on the right-hand side, we can see a public library with a “CLOSED” sign on its door. The caption at the bottom reads: “Don’t worry, sweetheart — it’s all online now.”*\n\n*The contrast in size conveys the power of the adult over the child. The fact that he sits on closed books suggests that he literally crushes culture. The closed library depicts the disappearance of shared public places. The caption is ironic: it pretends to reassure the girl, but the picture shows that something has been lost. The cartoon contributes to the debate on the closure of libraries and the place of screens in children’s lives.*\n\n**Points attendus** : identification ; description ordonnée avec le vocabulaire technique ; interprétation (contraste de taille, livres fermés, porte fermée) ; ironie de la légende ; ouverture sur un débat."}$exo$::jsonb),
  ('9e1162b2-61ad-52db-b09c-fc7948bfc2c3'::uuid, 3, 'traduction', $exo${"titre":"A film sequence and a poem","consigne":"Analyse en anglais la séquence et le poème (inventés pour l’exercice), puis rédige un paragraphe de synthèse d’environ 150 mots qui les relie.","enonce":"**Document A — Description of a film sequence (invented)**\n\n1. Plan d’ensemble en **plongée** : une vieille femme seule au milieu d’une gare immense et vide.\n2. **Travelling** lent vers elle ; la bande-son ne fait entendre que le bruit d’une horloge.\n3. **Gros plan** sur ses mains qui serrent un billet de train.\n4. **Contre-plongée** : elle se redresse et marche vers le quai. **Voix off** : “I had waited long enough.”\n\n**Document B — Poem (invented)**\n\n> The station clock, a patient judge,\n> Counts every second I won’t budge.\n> My ticket, like a folded prayer,\n> Grows heavy in the empty air.\n> A little late? A little brave.\n> A little more than I once gave.\n\n**Task.**\n1. For Document A, name and interpret the effect of **each** of the four shots and of the soundtrack.\n2. For Document B, identify **three** figures of speech (quote them) and interpret them.\n3. Write a **paragraph of about 150 words** in English showing how both documents convey the same emotion with different tools.","bareme":[{"critere":"Plans analysés : plongée qui écrase, travelling qui rapproche, gros plan sur les mains, contre-plongée qui grandit ; bande-son et voix off","points":6},{"critere":"Trois figures identifiées et interprétées (métaphore de l’horloge juge, comparaison like a folded prayer, understatement/anaphore de A little)","points":6},{"critere":"Paragraphe qui croise les deux documents et nomme l’émotion (solitude puis courage)","points":5},{"critere":"Anglais riche, vocabulaire technique et verbes de l’analyse","points":3}],"dureeMin":20,"corrige":"**1. Document A**\n- *Shot 1: a long shot, filmed from a high angle — the high-angle shot crushes the old woman, who looks tiny and lonely in the huge empty station.*\n- *Shot 2: a slow tracking shot towards her — the camera gets closer, as if we were entering her inner world; the soundtrack, reduced to a ticking clock, conveys the weight of time and waiting.*\n- *Shot 3: a close-up on her hands holding a ticket — the emotion is in the gesture: anxiety, but also determination.*\n- *Shot 4: a low-angle shot — it makes her look taller: she has gained strength. The voice-over “I had waited long enough” confirms her decision.*\n\n**2. Document B**\n- *Metaphor: “The station clock, a patient judge” — time is personified as a judge who watches the speaker’s hesitation.*\n- *Simile: “My ticket, like a folded prayer” — the ticket becomes something sacred, a fragile hope; it “grows heavy”, which shows the weight of the decision.*\n- *Understatement and repetition: “A little late? A little brave. / A little more than I once gave.” — saying “a little” suggests a great deal of courage.* (Accepter aussi : rimes suivies, question rhétorique.)\n\n**3. Model paragraph (about 150 words)**\n*Both documents depict the same moment: a lonely person who hesitates, then finds the courage to leave. However, they convey this emotion with different tools. The film relies on framing and sound: the high-angle long shot crushes the old woman, the ticking clock on the soundtrack stresses the weight of waiting, and the final low-angle shot makes her grow as she walks to the platform. Similarly, the poem turns the clock into “a patient judge”, but it uses images instead of camera angles. The ticket, compared to “a folded prayer”, carries the same hope as the close-up on the hands in the film. Finally, whereas the voice-over states the decision directly, the poem prefers understatement: “A little brave” suggests much more courage than it says. In both cases, solitude gradually turns into courage.*"}$exo$::jsonb),
  ('88acc2d9-6dc3-597b-9766-9128fb8b5501'::uuid, 1, 'redaction', $exo${"titre":"La démarche marketing en quatre étapes","consigne":"Réponds à chaque question en phrases complètes, avec le vocabulaire du cours.","enonce":"1. Définis le **marketing** en une phrase.\n2. Cite, dans l'ordre, les **quatre étapes** de la démarche marketing.\n3. Pour chacune des trois études suivantes, indique s'il s'agit d'une étude **documentaire**, **qualitative** ou **quantitative**, et justifie en une phrase :\n   - a) Une marque de jus de fruits consulte les statistiques de l'INSEE sur la consommation des ménages.\n   - b) Elle réunit huit consommateurs pendant deux heures pour comprendre pourquoi ils hésitent à acheter des jus bio.\n   - c) Elle fait remplir un questionnaire à 1 200 personnes représentatives de la population.","bareme":[{"critere":"Définition du marketing : détecter un besoin non satisfait (exprimé ou non) et y répondre par une offre qui crée de la valeur","points":6},{"critere":"Les quatre étapes citées dans l'ordre : analyser le marché, choisir cibles et positionnement, définir l'offre, mettre en œuvre et contrôler","points":6},{"critere":"Les trois études correctement classées et justifiées","points":8}],"dureeMin":7,"corrige":"1. Le **marketing** consiste à détecter un **besoin non satisfait**, exprimé ou non par le client, et à y répondre par une **offre qui crée de la valeur**.\n\n2. Les quatre étapes :\n   1. **analyser le marché** (étude de marché, veille) ;\n   2. **choisir** ses cibles et son positionnement ;\n   3. **définir l'offre** : produit, prix, distribution, communication ;\n   4. **mettre en œuvre** puis **contrôler** les résultats.\n\n3. a) Étude **documentaire** : elle exploite des données qui existent déjà (statistiques de l'INSEE).\n   b) Étude **qualitative** : une réunion de groupe sert à comprendre les motivations et les freins (ici, l'hésitation à acheter bio), pas à mesurer.\n   c) Étude **quantitative** : un questionnaire administré à un échantillon représentatif sert à mesurer."}$exo$::jsonb),
  ('88acc2d9-6dc3-597b-9766-9128fb8b5501'::uuid, 2, 'redaction', $exo${"titre":"Trottin'Ville : louer plutôt que vendre","consigne":"Lis la situation, puis réponds aux questions en justifiant avec des indices du texte et les notions du cours.","enonce":"**Situation.**\n\n> Trottin'Ville vendait des trottinettes électriques en magasin. Ses vendeurs ont remarqué que beaucoup d'acheteurs ne s'en servaient que pour aller à la gare, et craignaient surtout les pannes. L'entreprise propose désormais un **abonnement mensuel à 25 €** : la trottinette est prêtée, entretenue et réparée par l'entreprise. Au bout de trois mois, elle compte **80 abonnés**. Chaque mois, l'entretien et les pièces (consommations intermédiaires) lui coûtent **700 €**.\n\n1. Quel **besoin** des clients Trottin'Ville a-t-elle détecté ? Ce besoin était-il exprimé ?\n2. S'agit-il d'une innovation de produit ou d'une innovation de **modèle économique** ? Justifie.\n3. Calcule la **valeur ajoutée mensuelle** dégagée par l'abonnement (formule, calcul, résultat).\n4. Explique pourquoi cette création de valeur reste **incertaine**.","bareme":[{"critere":"Besoin identifié (se déplacer jusqu'à la gare sans souci de panne) et caractère non exprimé justifié","points":5},{"critere":"Innovation de modèle économique justifiée : même produit, autre façon de le proposer et de se faire payer (abonnement)","points":5},{"critere":"Valeur ajoutée : formule, 80 × 25 = 2 000 €, 2 000 − 700 = 1 300 € par mois","points":6},{"critere":"Incertitude expliquée : dépend de la capacité à satisfaire le besoin dans la durée (abonnés qui restent, coûts d'entretien)","points":4}],"dureeMin":11,"corrige":"1. Le besoin n'est pas de **posséder** une trottinette, mais de **se déplacer jusqu'à la gare** sans se soucier des pannes. Il n'était **pas exprimé** : ce sont les vendeurs qui l'ont repéré en observant l'usage et les craintes des acheteurs.\n\n2. C'est une **innovation de modèle économique** : le produit (la trottinette) ne change pas ; ce qui change, c'est **la façon de le proposer** (prêt entretenu) et **la façon de se faire payer** (abonnement mensuel au lieu d'une vente). Le cours rappelle qu'innover, c'est parfois changer la façon de proposer un produit et de se faire payer.\n\n3. Valeur ajoutée = chiffre d'affaires − consommations intermédiaires.\n   - Chiffre d'affaires mensuel = 80 × 25 = **2 000 €**.\n   - Valeur ajoutée = 2 000 − 700 = **1 300 € par mois**.\n   L'abonnement crée donc de la valeur pour l'entreprise.\n\n4. La création de valeur est **incertaine** : elle dépend de la capacité de Trottin'Ville à satisfaire le besoin **dans la durée**. Si des abonnés résilient, si les réparations coûtent plus que prévu ou si un concurrent propose mieux, le chiffre d'affaires baisse ou les consommations intermédiaires augmentent, et la valeur ajoutée diminue. Trois mois de résultats ne garantissent pas la rentabilité."}$exo$::jsonb),
  ('88acc2d9-6dc3-597b-9766-9128fb8b5501'::uuid, 3, 'redaction', $exo${"titre":"Roue Libre, un atelier vélo associatif","consigne":"Analyse la situation en mobilisant les notions du cours. Chaque réponse doit être justifiée par un indice du document.","enonce":"**Document.**\n\n> Roue Libre est une association qui répare les vélos des habitants d'un quartier populaire à petit prix et forme des jeunes sans diplôme à la mécanique. Son conseil d'administration envisage d'ouvrir un **service de vélos cargos en location** pour les familles et les artisans du quartier. Avant de se lancer, la présidente veut « comprendre ce qui freine les familles » puis « savoir combien seraient prêtes à louer ».\n>\n> Données de l'année écoulée : chiffre d'affaires (réparations et adhésions) **48 000 €** ; consommations intermédiaires (pièces, électricité, loyer de l'atelier) **19 500 €**.\n\n1. Quelle **approche marketing** correspond le mieux à la démarche de Roue Libre ? Justifie en la distinguant des deux autres approches.\n2. Propose les **études** à mener pour répondre aux deux questions de la présidente, en justifiant chaque choix.\n3. Calcule la **valeur ajoutée** de l'année écoulée.\n4. Pour une association comme Roue Libre, en quoi consiste la **création de valeur** d'un nouveau service ? Ne te limite pas à l'aspect financier.","bareme":[{"critere":"Approche identifiée (marketing de la demande ou de l'usager, partir des besoins et de l'intérêt du quartier) et distinguée du marketing de l'offre","points":4},{"critere":"Étude qualitative pour comprendre les freins et étude quantitative sur échantillon pour mesurer, justifiées","points":5},{"critere":"Valeur ajoutée : formule et 48 000 − 19 500 = 28 500 €","points":4},{"critere":"Création de valeur associative : couverture des coûts ou équilibre budgétaire, et dimension sociale (formation, accès à la mobilité)","points":5},{"critere":"Réponses structurées et appuyées sur des indices du document","points":2}],"dureeMin":18,"corrige":"1. Roue Libre **part des besoins des habitants** (familles, artisans) et veut les interroger avant de lancer l'offre : c'est une démarche fondée sur les attentes, proche du **marketing de la demande** et, par sa mission d'intérêt général, du **marketing de l'usager** (partir des besoins des usagers et de l'intérêt général). Ce n'est pas le **marketing de l'offre**, où l'organisation lance d'abord une innovation que le marché adopte ensuite. Accepter demande ou usager si c'est justifié.\n\n2. - « Comprendre ce qui freine les familles » : **étude qualitative** (entretiens, réunion de groupe de quelques familles) pour faire émerger motivations et freins (prix, stationnement, peur de ne pas savoir conduire un vélo cargo…).\n   - « Savoir combien seraient prêtes à louer » : **étude quantitative**, questionnaire sur un **échantillon représentatif** des habitants, pour **mesurer**.\n   - En complément, une **étude documentaire** (statistiques sur le quartier) et une **veille** sur les offres existantes sont possibles.\n\n3. Valeur ajoutée = chiffre d'affaires − consommations intermédiaires = 48 000 − 19 500 = **28 500 €**.\n\n4. Pour une association, un produit n'est lancé que s'il crée de la valeur, c'est-à-dire s'il permet au moins de **couvrir ses coûts** / d'atteindre un **équilibre budgétaire** (pas de recherche de rentabilité pour des associés). Mais la valeur s'apprécie aussi dans sa **dimension sociale** : accès à une mobilité peu chère pour les familles, outil de travail pour les artisans, nouvelles occasions de former les jeunes du quartier. Cette valeur reste **incertaine** : elle dépendra de la capacité à satisfaire ces besoins **dans la durée**."}$exo$::jsonb),
  ('71777efb-52c9-5a2b-9992-b982cafbb2f0'::uuid, 1, 'redaction', $exo${"titre":"Ressources et besoin en fonds de roulement","consigne":"Réponds à chaque question ; pose les calculs.","enonce":"1. Classe les ressources suivantes en ressources **tangibles** ou **intangibles** : un entrepôt, une marque connue, un brevet, un stock de farine, le savoir-faire des pâtissiers, une camionnette de livraison.\n2. Pourquoi les ressources intangibles fondent-elles souvent les **compétences distinctives** d'une organisation ?\n3. Une boulangerie industrielle présente : stocks **25 000 €**, créances clients **35 000 €**, dettes fournisseurs **40 000 €**. Calcule son **besoin en fonds de roulement** (BFR) et dis ce qu'il représente.","bareme":[{"critere":"Les six ressources correctement classées (tangibles : entrepôt, stock, camionnette ; intangibles : marque, brevet, savoir-faire)","points":7},{"critere":"Explication : les ressources intangibles sont difficiles à imiter","points":5},{"critere":"BFR = 25 000 + 35 000 − 40 000 = 20 000 €, avec sa signification (argent immobilisé par le cycle d'exploitation)","points":8}],"dureeMin":7,"corrige":"1. - **Tangibles** (physiques) : l'entrepôt, le stock de farine, la camionnette de livraison.\n   - **Intangibles** (immatérielles) : la marque connue, le brevet, le savoir-faire des pâtissiers.\n\n2. Les ressources intangibles (marque, savoir-faire, réputation, brevets) sont **difficiles à imiter** par les concurrents : on peut acheter la même machine, pas la même réputation ni le même savoir-faire. Elles fondent donc les **compétences distinctives** de l'organisation.\n\n3. BFR = (stocks + créances clients) − dettes fournisseurs = (25 000 + 35 000) − 40 000 = **20 000 €**.\n   Le BFR représente **l'argent immobilisé par le cycle d'exploitation** : la boulangerie doit financer 20 000 € parce qu'elle détient des stocks et attend le paiement de ses clients, alors que ses fournisseurs ne lui accordent que 40 000 € de délai."}$exo$::jsonb),
  ('71777efb-52c9-5a2b-9992-b982cafbb2f0'::uuid, 2, 'redaction', $exo${"titre":"La trésorerie tendue de Menuiserie Lacaze","consigne":"Pose chaque calcul (formule, calcul, résultat en euros), puis interprète.","enonce":"**Données du bilan fonctionnel de Menuiserie Lacaze (en euros).**\n\n| Élément | Montant |\n|---|---|\n| Ressources stables | 320 000 |\n| Emplois stables | 270 000 |\n| Stocks | 45 000 |\n| Créances clients | 38 000 |\n| Dettes fournisseurs | 23 000 |\n\n1. Calcule le **fonds de roulement net global** (FRNG) et explique ce qu'il représente.\n2. Calcule le **besoin en fonds de roulement** (BFR).\n3. Calcule la **trésorerie nette** et interprète le résultat.\n4. Le gérant obtient que ses clients le paient plus vite : les créances clients tombent à **25 000 €**. Recalcule le BFR et la trésorerie nette. Qu'en conclus-tu ?","bareme":[{"critere":"FRNG = 320 000 − 270 000 = 50 000 €, avec sa signification","points":5},{"critere":"BFR = 45 000 + 38 000 − 23 000 = 60 000 €","points":4},{"critere":"Trésorerie nette = 50 000 − 60 000 = − 10 000 € et interprétation : le FRNG ne couvre pas le BFR","points":6},{"critere":"Nouveau BFR 47 000 €, trésorerie + 3 000 € et conclusion sur l'effet des délais clients","points":5}],"dureeMin":11,"corrige":"1. FRNG = ressources stables − emplois stables = 320 000 − 270 000 = **50 000 €**. C'est ce qui reste des ressources durables une fois les investissements financés : 50 000 € sont disponibles pour financer l'exploitation.\n\n2. BFR = (stocks + créances clients) − dettes fournisseurs = (45 000 + 38 000) − 23 000 = **60 000 €**. Le cycle d'exploitation immobilise 60 000 €.\n\n3. Trésorerie nette = FRNG − BFR = 50 000 − 60 000 = **− 10 000 €**.\n   Le FRNG **ne couvre pas** le BFR : il manque 10 000 €. La trésorerie est négative, l'entreprise dépend de financements à court terme (découvert). Sa situation est tendue.\n\n4. Nouveau BFR = (45 000 + 25 000) − 23 000 = **47 000 €**.\n   Nouvelle trésorerie nette = 50 000 − 47 000 = **+ 3 000 €**.\n   En réduisant le délai de paiement de ses clients, l'entreprise diminue l'argent immobilisé par son cycle d'exploitation : le FRNG couvre désormais le BFR et la trésorerie redevient positive. Le décalage entre paiement des fournisseurs et encaissement des clients est bien la source du besoin de financement."}$exo$::jsonb),
  ('71777efb-52c9-5a2b-9992-b982cafbb2f0'::uuid, 3, 'redaction', $exo${"titre":"Atelier Brunet : financer une machine et préparer les compétences","consigne":"Analyse la situation : pose les calculs, puis argumente en t'appuyant sur les données et les notions du cours.","enonce":"**Document 1 — La situation.**\n\n> L'Atelier Brunet (35 salariés) découpe des pièces métalliques. Pour répondre à une grosse commande d'un constructeur de tramways, il veut acquérir une machine de découpe laser à commande numérique d'une valeur de **120 000 €**. Trois solutions sont étudiées : un **emprunt bancaire**, un **crédit-bail**, ou une **augmentation de capital** en faisant entrer un nouvel associé. Les deux associés actuels tiennent à garder le contrôle de l'entreprise.\n>\n> La machine exige des compétences en programmation que personne ne maîtrise aujourd'hui. Deux opérateurs expérimentés sont volontaires pour se former ; il manquera encore un programmeur. La commande du constructeur arrive par vagues : certains mois, l'activité double.\n\n**Document 2 — Bilan fonctionnel actuel (en euros).**\n\n| Ressources stables | Emplois stables | Stocks | Créances clients | Dettes fournisseurs |\n|---|---|---|---|---|\n| 600 000 | 540 000 | 70 000 | 55 000 | 95 000 |\n\n1. Calcule le FRNG, le BFR et la trésorerie nette, puis interprète.\n2. Compare les **trois solutions de financement** de la machine (un avantage et un point d'attention pour chacune).\n3. Quelle solution recommandes-tu ? Justifie avec les données.\n4. Montre que l'entreprise a besoin d'une démarche de **GPEC** et présente les mesures à prévoir.\n5. Comment l'entreprise peut-elle faire face aux **pics d'activité** de la commande ?","bareme":[{"critere":"FRNG 60 000 €, BFR 30 000 €, trésorerie nette + 30 000 € et interprétation","points":5},{"critere":"Les trois financements comparés : avantage et point d'attention de chacun, conformes au cours","points":4},{"critere":"Recommandation cohérente et justifiée par la volonté de garder le contrôle et la situation financière","points":4},{"critere":"GPEC : écart entre besoins futurs et compétences actuelles, formation des deux opérateurs et recrutement d'un programmeur","points":4},{"critere":"Flexibilité : intérim, CDD, sous-traitance ou indépendants pour les pics d'activité","points":3}],"dureeMin":20,"corrige":"1. - FRNG = 600 000 − 540 000 = **60 000 €**.\n   - BFR = (70 000 + 55 000) − 95 000 = **30 000 €**.\n   - Trésorerie nette = 60 000 − 30 000 = **+ 30 000 €**.\n   Le FRNG couvre le BFR : la trésorerie est positive. Mais 30 000 € ne suffisent pas à payer comptant une machine de 120 000 € : un financement est nécessaire.\n\n2. | Solution | Avantage | Point d'attention |\n|---|---|---|\n| Emprunt bancaire | Les associés gardent le pouvoir | Intérêts et remboursements à assurer |\n| Crédit-bail | Pas de décaissement initial, option d'achat | Coût total plus élevé |\n| Augmentation de capital | Fonds propres, pas de remboursement | Dilution du pouvoir : un nouvel associé entre |\n\n3. Les associés veulent **garder le contrôle** : l'augmentation de capital est donc peu adaptée (dilution du pouvoir). Entre emprunt et crédit-bail, le **crédit-bail** préserve la trésorerie (pas de décaissement initial, trésorerie de 30 000 € conservée) ; l'**emprunt** coûte en général moins cher au total mais impose des remboursements. Toute recommandation entre crédit-bail et emprunt est acceptée si elle est justifiée par ces éléments.\n\n4. La nouvelle machine crée un **besoin de compétences** (programmation) qui n'existe pas dans l'entreprise. La **GPEC** compare les besoins futurs aux ressources actuelles et prévoit :\n   - des **formations** pour les deux opérateurs volontaires (compétences à développer) ;\n   - un **recrutement** pour le programmeur manquant (compétence absente) ;\n   - éventuellement une **mobilité** interne vers le nouveau poste.\n   Il faut anticiper : une ressource ne vaut que si elle est disponible au bon moment.\n\n5. Pour gagner en **flexibilité** face aux vagues de commandes, l'entreprise peut recourir à l'**intérim** ou à des **CDD** pendant les pics, à des **travailleurs indépendants** ou à la **sous-traitance** d'une partie de la production."}$exo$::jsonb),
  ('0efbf3ad-2544-5023-ba3f-62bd3c427ffb'::uuid, 1, 'redaction', $exo${"titre":"Modes de production et flux","consigne":"Réponds à chaque question en une ou deux phrases précises.","enonce":"1. Associe chaque exemple à un **mode de production** (à l'unité, en série, en continu, en discontinu) et justifie :\n   - a) un chantier naval qui construit un voilier sur mesure ;\n   - b) une usine qui assemble chaque jour des milliers de smartphones identiques ;\n   - c) une cimenterie dont les fours ne s'arrêtent jamais ;\n   - d) une imprimerie qui imprime un lot d'affiches, puis change ses réglages pour un lot de brochures.\n2. Définis la production en **flux tendus** et donne un de ses inconvénients.\n3. Cite les quatre étapes de la **roue de Deming**.","bareme":[{"critere":"Les quatre modes correctement associés et justifiés","points":8},{"critere":"Flux tendus définis (produire à la commande, au plus juste, peu de stocks) et inconvénient (vulnérabilité aux ruptures)","points":7},{"critere":"Roue de Deming : planifier, faire, vérifier, agir","points":5}],"dureeMin":7,"corrige":"1. a) **À l'unité** : produit sur mesure, grande flexibilité, coût élevé.\n   b) **En série** : produits standardisés fabriqués en grandes quantités, ce qui réduit les coûts.\n   c) **En continu** : le flux de production est ininterrompu.\n   d) **En discontinu** : production par lots successifs, avec changements de réglage.\n\n2. Produire en **flux tendus** (flux tirés), c'est produire **à la commande**, **au plus juste**, avec **peu de stocks**. Inconvénient : l'organisation est **vulnérable aux ruptures** d'approvisionnement (un fournisseur en retard bloque la production), et la disponibilité n'est pas immédiate.\n\n3. La roue de Deming, outil d'amélioration continue : **planifier, faire, vérifier, agir**."}$exo$::jsonb),
  ('0efbf3ad-2544-5023-ba3f-62bd3c427ffb'::uuid, 2, 'redaction', $exo${"titre":"Fromagerie des Causses : garder la gamme Frais ?","consigne":"Pose les calculs (formule, calcul, résultat), puis interprète pour aider la direction à décider.","enonce":"**Situation.**\n\n> La Fromagerie des Causses fabrique deux gammes. La direction envisage de supprimer la gamme **Frais**, jugée « pas assez rentable » parce que son coût complet dépasse son chiffre d'affaires.\n\n| Gamme | Chiffre d'affaires | Charges variables | Charges fixes spécifiques |\n|---|---|---|---|\n| Affinés | 250 000 € | 140 000 € | 50 000 € |\n| Frais | 90 000 € | 55 000 € | 20 000 € |\n\nCharges fixes communes (direction, loyer) : **60 000 €**.\n\n1. Distingue une **charge directe** d'une **charge indirecte**, avec un exemple pris dans une fromagerie.\n2. Calcule la **marge sur coût spécifique** de chaque gamme.\n3. Calcule le **résultat global** de la fromagerie.\n4. Faut-il supprimer la gamme Frais ? Calcule le résultat sans elle (en supposant que ses charges spécifiques disparaissent et que les charges communes restent) et conclus.","bareme":[{"critere":"Charges directe et indirecte définies avec un exemple pertinent","points":4},{"critere":"Marges sur coût spécifique : Affinés 60 000 €, Frais 15 000 €, formule posée","points":6},{"critere":"Résultat global = 60 000 + 15 000 − 60 000 = 15 000 €","points":4},{"critere":"Résultat sans Frais = 0 € et conclusion : la gamme contribue à couvrir les charges communes, il ne faut pas la supprimer","points":6}],"dureeMin":12,"corrige":"1. Une **charge directe** est affectée sans calcul intermédiaire à un produit (ex. le lait consommé pour la gamme Affinés, la main-d'œuvre directe de l'atelier Frais). Une **charge indirecte** est commune à plusieurs produits et doit être répartie selon une clé (ex. le loyer, la direction).\n\n2. Marge sur coût spécifique = CA − (charges variables + charges fixes spécifiques).\n   - Affinés : 250 000 − (140 000 + 50 000) = 250 000 − 190 000 = **60 000 €**.\n   - Frais : 90 000 − (55 000 + 20 000) = 90 000 − 75 000 = **15 000 €**.\n\n3. Résultat global = 60 000 + 15 000 − 60 000 = **15 000 €**.\n\n4. Sans la gamme Frais, sa marge disparaît : résultat = 60 000 − 60 000 = **0 €**. Le résultat baisserait de 15 000 €.\n   La gamme Frais a une marge sur coût spécifique **positive** : elle couvre ses propres charges et **contribue à couvrir les charges communes**. Même si elle paraît déficitaire en coût complet (à cause de la part de charges communes qu'on lui affecte), la supprimer **aggraverait** le résultat. Il vaut mieux la garder, et chercher à améliorer sa marge."}$exo$::jsonb),
  ('0efbf3ad-2544-5023-ba3f-62bd3c427ffb'::uuid, 3, 'redaction', $exo${"titre":"Boisdoux : flux tendus, qualité et coûts","consigne":"Analyse la situation en mobilisant les notions du cours. Pose les calculs et justifie chaque proposition.","enonce":"**Document 1 — Un fabricant de meubles en bois.**\n\n> Boisdoux fabriquait ses meubles d'après ses prévisions de ventes et les stockait dans un grand entrepôt. Depuis un an, il ne lance la fabrication qu'à réception des commandes et a fermé la moitié de l'entrepôt. En mars, son unique fournisseur de panneaux de chêne a livré avec trois semaines de retard : une centaine de clients ont attendu leur table. Par ailleurs, les réclamations sur des pieds de chaise mal fixés se multiplient, alors que l'entreprise est certifiée ISO 9001.\n\n**Document 2 — Données de l'année (en euros).**\n\n| Gamme | Chiffre d'affaires | Charges variables | Charges fixes spécifiques |\n|---|---|---|---|\n| Tables | 300 000 | 180 000 | 70 000 |\n| Chaises | 150 000 | 100 000 | 60 000 |\n| Étagères | 120 000 | 70 000 | 30 000 |\n\nCharges fixes communes : **45 000 €**.\n\n1. Montre que Boisdoux est passé des **flux poussés** aux **flux tendus**. Présente un avantage et un risque de ce choix, en t'appuyant sur le document 1.\n2. Calcule la marge sur coût spécifique de chaque gamme et le résultat global.\n3. Que se passerait-il si l'on supprimait la gamme Chaises (ses charges spécifiques disparaissant) ? Quel argument pourrait conduire à la garder malgré tout ?\n4. La certification ISO 9001 suffit-elle à garantir la qualité ? Propose une démarche pour réduire les défauts des chaises.","bareme":[{"critere":"Passage aux flux tendus montré avec indices, avantage (moins de stocks) et risque (retard du fournisseur) illustrés","points":5},{"critere":"Marges : Tables 50 000 €, Chaises − 10 000 €, Étagères 20 000 € ; résultat global 15 000 €","points":5},{"critere":"Sans Chaises, résultat 25 000 € (+ 10 000 €) ; argument pour la garder (offre complète tables-chaises, image, relance)","points":4},{"critere":"ISO atteste une démarche mais la qualité se juge à la satisfaction client ; démarche qualité préventive avec la roue de Deming appliquée","points":4},{"critere":"Analyse structurée, appuyée sur les documents","points":2}],"dureeMin":20,"corrige":"1. Avant, Boisdoux produisait **selon des prévisions puis stockait** (flux poussés, « grand entrepôt »). Désormais, il ne fabrique **qu'à réception des commandes** et a fermé la moitié de l'entrepôt : c'est la production en **flux tendus**, au plus juste.\n   - Avantage : **moins de stocks**, donc moins de coûts de stockage (moitié de l'entrepôt fermée).\n   - Risque : **vulnérabilité aux ruptures** d'approvisionnement ; avec un **fournisseur unique**, trois semaines de retard ont bloqué une centaine de commandes.\n\n2. Marge sur coût spécifique = CA − (charges variables + charges fixes spécifiques).\n   - Tables : 300 000 − 250 000 = **50 000 €**.\n   - Chaises : 150 000 − 160 000 = **− 10 000 €**.\n   - Étagères : 120 000 − 100 000 = **20 000 €**.\n   - Résultat global = 50 000 − 10 000 + 20 000 − 45 000 = **15 000 €**.\n\n3. La gamme Chaises ne couvre même pas ses propres charges. Sans elle : 50 000 + 20 000 − 45 000 = **25 000 €**, soit 10 000 € de plus. Mais on peut vouloir la garder : les clients achètent souvent tables et chaises **ensemble**, et une offre sans chaises pourrait faire perdre des ventes de tables ; la gamme peut aussi être **relancée** (baisser ses coûts, augmenter ses prix) ou gardée pour l'**image**.\n\n4. La norme ISO 9001 **atteste une démarche**, mais la qualité se juge au final par la **satisfaction du client** : les réclamations montrent qu'elle n'est pas atteinte. Boisdoux doit passer du simple **contrôle** à une **démarche qualité** qui **prévient** plutôt que corriger, en suivant la **roue de Deming** :\n   - **planifier** : analyser les causes du défaut (vis, collage, gabarit) et fixer un objectif ;\n   - **faire** : modifier la méthode d'assemblage, former les monteurs ;\n   - **vérifier** : contrôler des échantillons, suivre le nombre de réclamations ;\n   - **agir** : généraliser ce qui marche, puis recommencer (amélioration continue)."}$exo$::jsonb),
  ('4c36fda0-88df-58a9-8572-9470f217411b'::uuid, 1, 'redaction', $exo${"titre":"Le vocabulaire du numérique en production","consigne":"Réponds en une ou deux phrases par question, avec le vocabulaire du cours.","enonce":"1. Définis la **dématérialisation** et donne un exemple.\n2. Qu'est-ce qu'un **flux de travaux** (*workflow*) ?\n3. Quel est le rôle d'un **progiciel de gestion intégré** (PGI) ?\n4. Associe chaque technologie à son usage :\n   - Technologies : informatique en nuage ; objets connectés ; intelligence artificielle ; données ouvertes.\n   - Usages : a) des capteurs mesurent les vibrations d'une machine pour prévoir une panne ; b) une application réutilise les données publiques de trafic ; c) un logiciel accessible partout met à jour des produits à distance ; d) un programme apprend à reconnaître une pièce défectueuse sur des photos.","bareme":[{"critere":"Dématérialisation définie avec un exemple, workflow défini","points":8},{"critere":"PGI : base de données unique reliant achats, production, stocks, ventes et comptabilité","points":4},{"critere":"Les quatre associations justes","points":8}],"dureeMin":7,"corrige":"1. La **dématérialisation** remplace le papier par des documents numériques. Exemple : la facture électronique, le bon de commande numérique, la signature électronique.\n\n2. Le **flux de travaux** (*workflow*) automatise l'enchaînement des tâches : un document passe automatiquement d'un acteur à l'autre, avec des validations et des alertes.\n\n3. Le **PGI** joue un rôle central : une **base de données unique** relie les achats, la production, les stocks, les ventes et la comptabilité.\n\n4. - Informatique en nuage → **c** (logiciels accessibles partout, produits mis à jour à distance).\n   - Objets connectés → **a** (capteurs, maintenance prédictive).\n   - Intelligence artificielle → **d** (apprentissage automatique pour détecter les défauts).\n   - Données ouvertes → **b** (données publiques réutilisées)."}$exo$::jsonb),
  ('4c36fda0-88df-58a9-8572-9470f217411b'::uuid, 2, 'redaction', $exo${"titre":"Traiteur Saveurs d'Oc : dessiner les flux","consigne":"Lis la description du processus, puis réponds aux questions.","enonce":"**Le processus de commande du traiteur Saveurs d'Oc.**\n\n> Le client envoie sa commande par courriel au service commercial. Le commercial recopie la commande dans un tableur, puis imprime un ordre de fabrication qu'il porte à la cuisine. La cuisine prépare les plats et les livre au client avec un bon de livraison. Le soir, le comptable, à partir d'une copie papier de la commande, ressaisit les informations dans le logiciel de comptabilité et envoie la facture au client. Le client règle la facture à la comptabilité. Chaque mois, deux ou trois factures comportent une erreur de montant.\n\n1. Liste les **acteurs** du processus en distinguant acteurs internes et externes.\n2. Présente le **diagramme des flux** sous forme de tableau (numéro, flux, de, vers).\n3. Repère les **ressaisies** et explique le lien avec les erreurs de facturation.\n4. Propose une amélioration fondée sur le numérique et justifie-la.","bareme":[{"critere":"Acteurs identifiés : client (externe), service commercial, cuisine, comptabilité (internes)","points":4},{"critere":"Tableau des cinq flux complet et ordonné (commande, ordre de fabrication, bon de livraison, facture, règlement)","points":7},{"critere":"Deux ressaisies repérées (tableur, logiciel comptable) et lien avec les erreurs expliqué","points":5},{"critere":"Amélioration pertinente (PGI, workflow, dématérialisation) et justifiée","points":4}],"dureeMin":12,"corrige":"1. - Acteur **externe** : le client.\n   - Acteurs **internes** : le service commercial, la cuisine, la comptabilité.\n\n2. | N° | Flux | De | Vers |\n|---|---|---|---|\n| 1 | Commande | Client | Service commercial |\n| 2 | Ordre de fabrication | Service commercial | Cuisine |\n| 3 | Bon de livraison (avec les plats) | Cuisine | Client |\n| 4 | Facture | Comptabilité | Client |\n| 5 | Règlement | Client | Comptabilité |\n\n(La copie papier de la commande transmise à la comptabilité peut être ajoutée comme flux interne.)\n\n3. La commande est saisie **deux fois** : le commercial la recopie dans un tableur, puis le comptable la **ressaisit** dans le logiciel de comptabilité. Chaque ressaisie est une occasion d'erreur de frappe, ce qui explique les factures fausses ; elle fait aussi perdre du temps et retarde la facturation.\n\n4. Adopter un **PGI** (ou relier les outils) : la commande est saisie **une seule fois** et partagée par le commercial, la cuisine et la comptabilité, grâce à une base de données unique. Un **workflow** peut transmettre automatiquement l'ordre de fabrication à la cuisine, et la facture électronique (**dématérialisation**) être générée à partir de la commande. On supprime les ressaisies, donc les erreurs, et on gagne en réactivité."}$exo$::jsonb),
  ('4c36fda0-88df-58a9-8572-9470f217411b'::uuid, 3, 'redaction', $exo${"titre":"Boulangerie Fournil 4.0 : chance ou menace ?","consigne":"Rédige une réponse structurée (introduction, développement argumenté, conclusion) en t'appuyant sur les documents et sur le cours.","enonce":"**Document 1.**\n\n> La boulangerie industrielle Fournil du Nord a équipé ses fours de **capteurs connectés** qui mesurent la température et les vibrations ; les données partent vers une application **en nuage**. Un modèle d'**intelligence artificielle** prévoit chaque jour les quantités à produire pour ses 60 magasins clients. Coût du projet : **85 000 €**, plus trois semaines de formation des équipes.\n\n**Document 2 — Un an après.**\n\n> Pannes de fours : **12** l'année précédente, **4** cette année. Invendus en baisse. Mais une **cyberattaque** a paralysé l'application pendant deux jours : faute d'alertes, un four a surchauffé et une fournée entière a été perdue. Deux boulangers expérimentés regrettent que « la machine décide à leur place » et disent perdre leur savoir-faire de réglage.\n\n**Question.** Les transformations numériques sont-elles une chance pour la production de Fournil du Nord ?\n\nTon développement doit : présenter les **opportunités** en citant les données ; présenter les **risques** ; proposer au moins **deux mesures** pour limiter ces risques.","bareme":[{"critere":"Introduction qui présente l'entreprise, les technologies en jeu et la question","points":3},{"critere":"Opportunités argumentées avec les données (8 pannes de moins, maintenance prédictive, moins d'invendus grâce à l'IA)","points":5},{"critere":"Risques argumentés : coût, dépendance au réseau et cyberattaque, perte de savoir-faire","points":5},{"critere":"Au moins deux mesures pertinentes pour limiter les risques (relevé manuel de secours, sécurité, formation, garder le jugement humain)","points":4},{"critere":"Conclusion nuancée : chance si le numérique sert un processus bien pensé","points":3}],"dureeMin":20,"corrige":"**Introduction.** Fournil du Nord a intégré plusieurs technologies numériques à sa production : objets connectés, informatique en nuage, intelligence artificielle. Ces transformations sont-elles une chance ou une menace pour sa production ?\n\n**Les opportunités.**\n- **Maintenance prédictive** : les capteurs repèrent les signes de panne avant qu'elle survienne ; les pannes sont passées de **12 à 4**, soit **8 pannes de moins** en un an.\n- **Prévision de la demande** par l'IA (apprentissage automatique) : production plus ajustée aux besoins des 60 magasins, **invendus en baisse**, donc moins de pertes.\n- Plus globalement : gains de productivité, réactivité, qualité plus régulière.\n\n**Les risques.**\n- **Coût** de l'investissement (85 000 €) et de la **formation** (trois semaines).\n- **Dépendance** aux prestataires et aux réseaux ; **cyberattaque** : deux jours de paralysie, une fournée perdue faute d'alertes.\n- **Transformation des emplois** et **perte de savoir-faire** : les boulangers expérimentés ne règlent plus eux-mêmes les fours.\n\n**Mesures pour limiter les risques.**\n- Prévoir un **relevé manuel de secours** et des alarmes locales sur les fours en cas de coupure.\n- Renforcer la **sécurité informatique** (sauvegardes, protection contre les attaques).\n- Garder le **jugement humain** : les boulangers valident les prévisions de l'IA et continuent à pratiquer les réglages ; associer les salariés au projet et les former.\n\n**Conclusion.** Le numérique est une **chance** pour Fournil du Nord (moins de pannes, moins de pertes), mais il ne l'est que s'il sert un **processus bien pensé** : il automatise aussi bien les erreurs que les bonnes pratiques, et il crée de nouvelles fragilités qu'il faut anticiper."}$exo$::jsonb),
  ('6de1bc3b-6ffe-523f-b02a-579eb92fb43c'::uuid, 1, 'redaction', $exo${"titre":"Mécanismes de coordination","consigne":"Réponds à chaque question en justifiant brièvement.","enonce":"1. Pour chaque situation, identifie le **mécanisme de coordination** (Mintzberg) :\n   - a) Dans une start-up de cinq personnes, chacun règle les problèmes en discutant autour de la machine à café.\n   - b) Dans une chaîne de sandwicheries, chaque employé suit une fiche technique qui décrit la recette au gramme près.\n   - c) Une commerciale reçoit un objectif de 200 contrats par an, libre de s'organiser comme elle veut.\n   - d) Dans un hôpital, infirmiers et médecins se coordonnent grâce à leur formation commune.\n   - e) Le patron d'une petite boulangerie répartit lui-même le travail chaque matin et contrôle.\n2. Donne deux caractéristiques du **taylorisme** et deux caractéristiques du **toyotisme**.","bareme":[{"critere":"Les cinq mécanismes correctement identifiés et justifiés","points":12},{"critere":"Deux caractéristiques exactes du taylorisme et deux du toyotisme","points":8}],"dureeMin":8,"corrige":"1. a) **Ajustement mutuel** : communication informelle entre les personnes.\n   b) **Standardisation des procédés** : des règles et procédures fixent le travail.\n   c) **Standardisation des résultats** : on fixe l'objectif, pas la méthode.\n   d) **Standardisation des qualifications** : la formation garantit la coordination.\n   e) **Supervision directe** : une personne donne des ordres et contrôle.\n\n2. - **Taylorisme** (OST, Taylor, 1911) : séparation de la conception et de l'exécution ; décomposition du travail en gestes simples ; chronométrage ; salaire au rendement. (Deux éléments attendus.)\n   - **Toyotisme** (Ōno, Toyota) : production en juste-à-temps (flux tendus) ; qualité totale ; ouvriers polyvalents travaillant en équipes ; droit d'arrêter la chaîne en cas de défaut ; amélioration continue. (Deux éléments attendus.)"}$exo$::jsonb),
  ('6de1bc3b-6ffe-523f-b02a-579eb92fb43c'::uuid, 2, 'redaction', $exo${"titre":"Glacier Pôle Sud : de l'atelier au réseau","consigne":"Lis la situation et réponds en utilisant les notions du cours ; appuie chaque réponse sur un indice.","enonce":"**Situation.**\n\n> En 2016, trois amis ouvrent un atelier de glaces artisanales ; ils décident de tout ensemble, au fil de la journée. En 2019, avec quatre boutiques, la fondatrice, Inès, passe chaque jour dans chaque boutique pour donner les consignes et vérifier le travail. En 2025, le réseau compte 30 boutiques : chaque gérant applique un livret de recettes commun et reçoit un objectif de chiffre d'affaires ; il recrute lui-même ses saisonniers et choisit ses animations. Chaque mois, il envoie à la direction un rapport sur ses ventes et ses coûts.\n\n1. Identifie le **mécanisme de coordination** dominant en 2016, puis en 2019. Justifie.\n2. En 2025, quels **mécanismes** sont utilisés ? Justifie avec le texte.\n3. L'organisation de 2025 est-elle plutôt **centralisée** ou **décentralisée** ? Quel outil accompagne la délégation ?\n4. Explique pourquoi la croissance a obligé l'entreprise à changer de mode de coordination.","bareme":[{"critere":"2016 : ajustement mutuel ; 2019 : supervision directe, justifiés","points":5},{"critere":"2025 : standardisation des procédés (livret) et des résultats (objectif), justifiés","points":5},{"critere":"Décentralisation avec délégation, reporting mensuel identifié","points":5},{"critere":"Explication : la croissance différencie les tâches, la supervision directe ne suffit plus","points":5}],"dureeMin":12,"corrige":"1. - **2016** : **ajustement mutuel** — trois associés « décident de tout ensemble, au fil de la journée », par communication informelle.\n   - **2019** : **supervision directe** — Inès « donne les consignes et vérifie le travail » elle-même.\n\n2. En **2025** :\n   - **standardisation des procédés** : un « livret de recettes commun » fixe la façon de produire ;\n   - **standardisation des résultats** : chaque gérant a « un objectif de chiffre d'affaires », sans que la méthode soit imposée.\n\n3. L'organisation est **décentralisée** : une partie du pouvoir de décision est **déléguée** aux gérants (recrutement des saisonniers, choix des animations), qui ont autonomie et responsabilité. La délégation s'accompagne d'un **reporting** : le rapport mensuel sur les ventes et les coûts, par lequel l'échelon délégué rend compte de ses résultats.\n\n4. En grandissant (de 1 atelier à 30 boutiques), l'entreprise a dû **diviser** le travail entre plus de personnes et de lieux (**différenciation** des tâches). La discussion informelle, puis la présence d'Inès dans chaque boutique, ne suffisaient plus : une seule personne ne peut pas superviser 30 boutiques. Il a fallu des **règles communes**, des **objectifs** et une **délégation** pour que l'ensemble reste cohérent."}$exo$::jsonb),
  ('6de1bc3b-6ffe-523f-b02a-579eb92fb43c'::uuid, 3, 'redaction', $exo${"titre":"Logipack adopte le lean management","consigne":"Analyse la situation en mobilisant les notions du cours et des indices précis du document. Rédige des réponses structurées.","enonce":"**Document.**\n\n> Logipack prépare des colis pour des sites de vente en ligne. Jusqu'ici, chaque préparateur faisait toujours la même tâche (scanner, emballer ou étiqueter) en suivant des procédures détaillées, sous le contrôle de trois niveaux de chefs. Face à des commandes de plus en plus imprévisibles (soldes, fêtes, promotions éclair), la direction lance un projet de **lean management** : suppression d'un niveau hiérarchique, équipes autonomes de six préparateurs **polyvalents** qui organisent eux-mêmes leur journée, chasse aux attentes et aux déplacements inutiles, droit pour chaque équipe d'arrêter la ligne en cas d'erreur d'étiquetage.\n>\n> Six mois plus tard, les délais de préparation ont baissé de 20 %. Mais le délégué du personnel signale une hausse des arrêts maladie : « On court toute la journée, on n'a plus un temps mort. »\n\n1. Caractérise l'organisation du travail **avant** le projet (rigide ou souple, modèle historique dont elle se rapproche). Justifie.\n2. Montre que le projet s'inspire du **toyotisme**.\n3. Quels **mécanismes de coordination** le projet privilégie-t-il ? Pourquoi sont-ils adaptés à l'environnement de Logipack ?\n4. Le lean management est-il une réussite chez Logipack ? Discute en distinguant performance économique et **performance sociale**.","bareme":[{"critere":"Organisation rigide, proche du taylorisme, justifiée (tâches parcellisées, procédures, hiérarchie longue)","points":4},{"critere":"Traits du toyotisme repérés : polyvalence, équipes, droit d'arrêter la ligne, amélioration continue, chasse aux gaspillages","points":4},{"critere":"Ajustement mutuel et délégation (ligne hiérarchique raccourcie) reliés à l'environnement incertain","points":5},{"critere":"Bilan nuancé : gain d'efficacité (− 20 % de délais) mais intensification du travail et dégradation de la performance sociale","points":5},{"critere":"Réponses rédigées et appuyées sur des indices","points":2}],"dureeMin":20,"corrige":"1. Avant le projet, l'organisation est **rigide** : tâches **parcellisées et répétitives** (« toujours la même tâche »), salariés **spécialisés**, **procédures détaillées**, **ligne hiérarchique longue** (trois niveaux de chefs). Elle se rapproche du **taylorisme** : séparation de la conception et de l'exécution, travail décomposé en gestes simples. Atout : productivité sur des séries stables ; limite : faible adaptation.\n\n2. Le projet reprend les principes du **toyotisme** : ouvriers **polyvalents** en **équipes**, **droit d'arrêter la ligne** en cas de défaut (comme sur la chaîne Toyota), recherche de la qualité et **amélioration continue** ; le **lean management**, inspiré du toyotisme, chasse ce qui n'apporte pas de valeur au client (attentes, déplacements).\n\n3. Le projet privilégie :\n   - l'**ajustement mutuel** : les équipes « organisent elles-mêmes leur journée » en se parlant ;\n   - la **délégation** et une ligne hiérarchique **plus courte** (un niveau supprimé), donc plus de **décentralisation**.\n   Ils sont adaptés parce que l'environnement est **incertain** (commandes imprévisibles) : plus l'environnement est incertain, plus il faut une coordination **souple** plutôt que des procédures rigides. La polyvalence donne de la **flexibilité**.\n\n4. **Réussite économique** : les délais baissent de 20 %, l'entreprise gagne en efficacité et en réactivité.\n   **Échec social partiel** : la chasse à tous les temps morts **intensifie le travail** (« on court toute la journée ») et les arrêts maladie augmentent : la **performance sociale** se dégrade. Le cours le souligne : bien mené, le lean améliore l'efficacité ; mal mené, il intensifie le travail.\n   **Conclusion** : le succès est incomplet ; Logipack doit réintroduire des pauses, associer les équipes au rythme de travail, sans quoi la hausse de l'absentéisme finira par peser aussi sur la performance économique."}$exo$::jsonb),
  ('68a546b8-1543-5849-875a-2e2933b8756b'::uuid, 1, 'redaction', $exo${"titre":"Styles de direction et attentes des acteurs","consigne":"Réponds à chaque question en justifiant brièvement.","enonce":"1. Identifie le **style de direction** de chaque dirigeant :\n   - a) Paul décide seul, sans explication, et sanctionne ceux qui discutent ses ordres.\n   - b) Aïcha demande l'avis de son équipe par un sondage, puis tranche seule.\n   - c) Marc décide seul, mais offre des repas et s'inquiète de la santé de chacun.\n   - d) Chez Léa, les décisions importantes sont votées en réunion avec les salariés.\n2. Donne la **limite** du style participatif.\n3. Présente une **attente** typique de chacun de ces acteurs : salariés, actionnaires, bénévoles.","bareme":[{"critere":"Les quatre styles correctement identifiés (autoritaire, consultatif, paternaliste, participatif)","points":10},{"critere":"Limite du style participatif : lenteur des décisions","points":3},{"critere":"Attentes des trois acteurs conformes au cours","points":7}],"dureeMin":7,"corrige":"1. a) **Autoritaire** : le dirigeant décide seul et impose.\n   b) **Consultatif** : il consulte avant de décider seul.\n   c) **Paternaliste** : il décide seul mais se soucie du bien-être des salariés.\n   d) **Participatif** : les décisions sont prises avec les salariés.\n\n2. La limite du style participatif est la **lenteur des décisions**.\n\n3. - **Salariés** : rémunération, sécurité de l'emploi, conditions de travail, reconnaissance (une attente suffit).\n   - **Actionnaires** : rentabilité, dividendes, valeur de leurs titres.\n   - **Bénévoles** : le sens de l'action, le lien social."}$exo$::jsonb),
  ('68a546b8-1543-5849-875a-2e2933b8756b'::uuid, 2, 'redaction', $exo${"titre":"Les Restos du Canal : bénévoles et salariés","consigne":"Lis la situation et réponds en mobilisant les notions du cours.","enonce":"**Situation.**\n\n> L'association Les Restos du Canal distribue des repas dans une grande ville. Elle emploie 6 salariés et s'appuie sur 80 bénévoles. Les salariés demandent une hausse de salaire et des horaires moins lourds ; les bénévoles, eux, disent « venir pour se rendre utiles et rencontrer du monde », mais plusieurs ont arrêté : « On ne sait jamais à quoi servent nos idées, personne ne nous demande notre avis. » La directrice veut relancer l'implication de tous avant l'hiver.\n\n1. Présente les **attentes** des salariés et des bénévoles. Sont-elles convergentes ou divergentes ?\n2. Classe les motivations citées en facteurs **internes** ou **externes**.\n3. Propose deux **dispositifs** qui favorisent la coopération et l'implication, et justifie-les.","bareme":[{"critere":"Attentes identifiées (salariés : salaire, conditions de travail ; bénévoles : sens, lien social) et intérêts convergents ou divergents analysés","points":7},{"critere":"Motivations classées : sens et utilité internes, salaire et horaires externes","points":5},{"critere":"Deux dispositifs pertinents du cours, justifiés par la situation","points":8}],"dureeMin":11,"corrige":"1. - **Salariés** : rémunération (hausse de salaire) et **conditions de travail** (horaires moins lourds).\n   - **Bénévoles** : **sens de l'action** (« se rendre utiles ») et **lien social** (« rencontrer du monde »), plus la reconnaissance de leurs idées.\n   Les intérêts sont **divergents** sur les moyens (les salaires pèsent sur le budget de l'association), mais **convergents** sur l'essentiel : que l'association réussisse sa mission. La directrice doit s'appuyer sur ce but commun.\n\n2. - Facteurs **internes** : l'envie de se rendre utile, l'intérêt de l'action (besoin d'accomplissement).\n   - Facteurs **externes** : le salaire, les horaires (conditions de travail), la reconnaissance (être consulté).\n\n3. Dispositifs possibles (deux attendus, justifiés) :\n   - des **réunions** régulières où bénévoles et salariés proposent des idées, et une **communication interne** qui dit ce qu'elles sont devenues : répond à « personne ne nous demande notre avis » ;\n   - des **groupes de projet** (préparer la campagne d'hiver) mêlant salariés et bénévoles : coopération et cohésion ;\n   - une **technique de créativité** (remue-méninges) pour faire émerger les idées ;\n   - des **outils collaboratifs** pour organiser les plannings ;\n   - pour les salariés, une réflexion sur les **conditions de travail** et la **QVT** (horaires).\n   La coopération ne se décrète pas : elle se favorise par ces dispositifs."}$exo$::jsonb),
  ('68a546b8-1543-5849-875a-2e2933b8756b'::uuid, 3, 'redaction', $exo${"titre":"Codelys : retenir les développeurs","consigne":"Analyse la situation en t'appuyant sur les documents et sur le cours. Rédige des réponses structurées.","enonce":"**Document 1 — Le constat.**\n\n> Codelys, éditeur de logiciels de 60 salariés, a perdu 14 développeurs en un an. Son fondateur, Victor, fixe seul les outils, les méthodes et les priorités de chaque équipe ; il ne tolère pas qu'on discute ses choix. Les actionnaires, qui ont investi l'an dernier, réclament une hausse des **dividendes**. Les développeurs, eux, demandent des **primes** et « plus de liberté pour choisir comment coder ». Dans les couloirs, certains disent ne plus savoir « ce que défend Codelys ».\n\n**Document 2 — Extrait d'une enquête interne.**\n\n> 72 % des répondants jugent leur travail « intéressant » ; 65 % se disent « peu écoutés » ; 58 % travaillent seuls sur leurs projets et ne connaissent pas les autres équipes.\n\n1. Caractérise le **style de direction** de Victor et montre sa limite dans ce cas.\n2. Analyse les **intérêts** des actionnaires et des salariés : en quoi divergent-ils, en quoi convergent-ils ?\n3. Explique le rôle de la **culture d'organisation** et ce que révèle la remarque « ce que défend Codelys ».\n4. Propose un plan d'action d'au moins **trois dispositifs** pour fédérer les salariés, en justifiant chacun par les documents.","bareme":[{"critere":"Style autoritaire identifié et limite reliée aux départs (peu d'implication, résistance)","points":4},{"critere":"Intérêts analysés : divergence dividendes / primes, convergence sur la réussite de l'entreprise","points":4},{"critere":"Culture : valeurs partagées, cohésion, implication ; manque de culture commune repéré","points":4},{"critere":"Trois dispositifs pertinents (style plus participatif, groupes de projet, communauté de pratiques, QVT, rémunération) justifiés par les chiffres","points":6},{"critere":"Réponses structurées et appuyées sur les documents","points":2}],"dureeMin":20,"corrige":"1. Victor adopte un style **autoritaire** : il « fixe seul » outils, méthodes et priorités et « ne tolère pas qu'on discute ses choix ». Limite : **peu d'implication** et **résistance** ; ici, les développeurs se sentent « peu écoutés » (65 %) et partent (14 départs en un an). Aucun style n'est idéal en soi, mais celui-ci est mal adapté à des salariés très qualifiés qui demandent de l'autonomie.\n\n2. - **Divergence** : les actionnaires veulent des **dividendes** (rentabilité de leurs titres), les salariés des **primes** (rémunération) : ce que l'un reçoit, l'autre ne le reçoit pas.\n   - **Convergence** : tous ont intérêt à ce que Codelys réussisse ; or les départs de développeurs coûtent (recrutements, retards) et menacent la valeur de l'entreprise, donc aussi les dividendes. Le management doit les **fédérer** autour de cet objectif commun.\n\n3. La **culture** (valeurs, normes, rites, symboles, histoire) assure la **cohésion** et favorise l'**implication** : on se sent membre d'un collectif. La remarque montre que Codelys n'a pas de culture partagée claire, ce qui affaiblit le sentiment d'appartenance ; 58 % travaillent seuls et ne connaissent pas les autres équipes.\n\n4. Plan d'action (trois dispositifs justifiés) :\n   - évoluer vers un style plus **participatif** ou **consultatif** : les équipes choisissent leurs outils (répond à « plus de liberté » et aux 65 % « peu écoutés ») ;\n   - des **groupes de projet** transverses et une **communauté de pratiques** entre développeurs : ils cassent l'isolement (58 %) et font partager le savoir-faire ;\n   - un dispositif de **rémunération** lié aux résultats (intéressement, primes) : il rapproche les intérêts des salariés et des actionnaires ;\n   - une **communication interne** sur les valeurs et le projet de l'entreprise, et des mesures de **QVT** (télétravail partiel).\n   Le travail est jugé intéressant (72 %) : la motivation interne existe, il faut la conforter. Fédérer, c'est donner à chacun une raison personnelle de servir l'objectif commun."}$exo$::jsonb),
  ('a224fba3-c05a-56ad-a429-1a7b9ca4ce75'::uuid, 1, 'redaction', $exo${"titre":"Du besoin à l'avis en ligne","consigne":"Réponds en phrases complètes, avec le vocabulaire du cours.","enonce":"1. Distingue le **consommateur**, le **client** et l'**usager**. Illustre la différence entre client et consommateur par un exemple.\n2. Cite dans l'ordre les **cinq étapes** du processus d'achat.\n3. Définis un **frein** à l'achat et donne un exemple lié à l'achat en ligne.","bareme":[{"critere":"Consommateur, client et usager distingués avec un exemple pertinent","points":7},{"critere":"Les cinq étapes dans l'ordre","points":8},{"critere":"Frein défini avec un exemple lié au commerce en ligne","points":5}],"dureeMin":7,"corrige":"1. - Le **consommateur** utilise le produit.\n   - Le **client** l'achète.\n   - L'**usager** bénéficie d'un service public.\n   Exemple : un parent (client) achète un jouet pour son enfant (consommateur). Un élève qui emprunte un livre à la médiathèque municipale est un usager.\n\n2. 1. **Prise de conscience** du besoin ; 2. **recherche d'informations** (sites, comparateurs, avis, réseaux sociaux) ; 3. **évaluation** des solutions ; 4. **décision** d'achat ; 5. **comportement après l'achat** (satisfaction, avis, réachat ou réclamation).\n\n3. Un **frein** est une force qui retient d'acheter (peur, inhibition, prix). Exemple : la peur d'une arnaque sur un site inconnu, ou la crainte de ne pas pouvoir essayer un vêtement avant de l'acheter."}$exo$::jsonb),
  ('a224fba3-c05a-56ad-a429-1a7b9ca4ce75'::uuid, 2, 'redaction', $exo${"titre":"Le vélo de Chloé","consigne":"Lis la situation, puis réponds en t'appuyant sur des indices précis.","enonce":"**Situation.**\n\n> Chloé, 17 ans, vient d'être admise dans un lycée à 6 km de chez elle. Elle veut un vélo pour y aller. Elle regarde des vidéos d'influenceurs cyclistes, compare trois modèles sur un comparateur et lit les avis clients. Elle hésite à commander en ligne : « Et si la taille ne me va pas ? » Finalement, elle choisit un vélo vert pomme « qui ne ressemble à aucun autre », le commande sur le site de l'enseigne Cyclo+ et le retire en magasin. Une semaine plus tard, elle publie un avis cinq étoiles. Depuis, elle reçoit chaque semaine des publicités de Cyclo+ pour des casques et des antivols.\n\n1. Retrouve dans le texte chacune des **cinq étapes** du processus d'achat.\n2. Identifie une **motivation** (précise son type) et un **frein**.\n3. Quel **facteur social** a influencé Chloé ?\n4. Comment Cyclo+ peut-il envoyer ces publicités ciblées ? Quelles règles doit-il respecter ?","bareme":[{"critere":"Les cinq étapes repérées avec un indice chacune","points":7},{"critere":"Motivation d'auto-expression et frein (peur que la taille ne convienne) identifiés","points":5},{"critere":"Facteur social : les influenceurs","points":2},{"critere":"Traces numériques et connaissance client ; RGPD (consentement, droits d'accès et d'opposition)","points":6}],"dureeMin":12,"corrige":"1. - **Prise de conscience** du besoin : admise dans un lycée à 6 km, elle a besoin de se déplacer.\n   - **Recherche d'informations** : vidéos d'influenceurs, comparateur, avis clients.\n   - **Évaluation** des solutions : elle compare trois modèles.\n   - **Décision** d'achat : elle commande le vélo vert pomme sur le site.\n   - **Comportement après l'achat** : elle publie un avis cinq étoiles (satisfaction).\n\n2. - Motivation **d'auto-expression** : elle veut un vélo « qui ne ressemble à aucun autre », pour affirmer son style.\n   - **Frein** : la peur que « la taille ne [lui] aille pas », liée à l'achat en ligne.\n\n3. Facteur **social** : les **influenceurs** cyclistes dont elle regarde les vidéos.\n\n4. Cyclo+ exploite les **traces numériques** de Chloé (historique d'achat, navigation, cookies) grâce à ses outils de **gestion de la relation client** (CRM) : c'est la **connaissance client**, qui permet des offres personnalisées (accessoires pour un vélo déjà acheté). Il doit respecter le **RGPD** : obtenir son **consentement** (cookies, communications commerciales) et respecter ses droits d'**accès** et d'**opposition**. Il doit aussi veiller à ce qu'elle ne se sente pas **surveillée** par une personnalisation excessive."}$exo$::jsonb),
  ('a224fba3-c05a-56ad-a429-1a7b9ca4ce75'::uuid, 3, 'redaction', $exo${"titre":"Mairie en ligne et enseigne connectée","consigne":"Analyse les deux documents à l'aide des notions du cours, puis rédige une réponse argumentée à la dernière question.","enonce":"**Document 1 — Une enseigne de bricolage.**\n\n> BricoMax a lancé une application : liste de courses, conseils vidéo, agent conversationnel ouvert jour et nuit, carte de fidélité. Grâce à l'historique d'achats, l'application propose « les produits dont vous aurez besoin pour finir votre chantier ». Un client s'agace sur un réseau social : « Ils savent que j'ai acheté de la peinture pour la chambre du bébé avant que j'aie annoncé la naissance ! » Son message est partagé 3 000 fois.\n\n**Document 2 — Une commune de 9 000 habitants.**\n\n> La mairie de Saint-Aubin a mis en ligne l'inscription à la cantine, les demandes d'acte de naissance et la consultation des comptes rendus du conseil municipal. Les files d'attente ont disparu, mais plusieurs habitants âgés ne parviennent plus à inscrire leurs petits-enfants. La mairie envisage de fermer son guichet d'accueil pour faire des économies.\n\n1. Montre que BricoMax a **digitalisé** sa relation client (connaissance client, interactivité, outils).\n2. Analyse le message du client : quelle limite de la digitalisation révèle-t-il ? Quel rôle jouent les **réseaux sociaux** ?\n3. Présente les trois usages du numérique par l'**administration électronique** illustrés par le document 2.\n4. La mairie doit-elle fermer son guichet ? Argumente.","bareme":[{"critere":"Digitalisation montrée : connaissance client, interactivité (agent conversationnel), outils (application, fidélité)","points":5},{"critere":"Limite : sentiment de surveillance, exploitation des traces ; réseaux sociaux comme canal de critique","points":4},{"critere":"Trois usages de l'administration électronique reliés au document","points":4},{"critere":"Argumentation sur le guichet : fracture numérique, maintien d'un accueil humain","points":5},{"critere":"Réponses structurées, appuyées sur les documents","points":2}],"dureeMin":18,"corrige":"1. BricoMax a digitalisé sa relation client :\n   - **connaissance client** : l'historique d'achats sert à proposer des offres **personnalisées** (« les produits dont vous aurez besoin ») ;\n   - **interactivité** : un **agent conversationnel** ouvert jour et nuit permet des échanges en temps réel ;\n   - **outils** : application mobile, programme de **fidélité**, conseils vidéo.\n\n2. Le client se sent **surveillé** : l'exploitation de ses **traces numériques** (achats) révèle une information personnelle qu'il n'avait pas choisi de partager. C'est la limite d'une **personnalisation excessive** : elle détruit la confiance au lieu de rendre service. Les **réseaux sociaux grand public** sont à la fois un canal de communication, de service client… et **de critique** : partagé 3 000 fois, le message nuit à l'image de l'enseigne. L'exploitation des données est encadrée par le **RGPD**.\n\n3. - **Faciliter l'accès aux documents administratifs** : consultation en ligne des comptes rendus du conseil municipal (droit reconnu par la loi de 1978).\n   - **Simplifier les démarches** : inscription à la cantine, demande d'acte de naissance en ligne.\n   - **Améliorer les processus** : moins de files d'attente, traitement plus rapide.\n\n4. Fermer le guichet ferait des économies, mais exclurait une partie des usagers : c'est la **fracture numérique** — certains habitants, notamment âgés, n'ont pas l'équipement ou la maîtrise des outils. Le service public s'adresse à **tous** les usagers ; le cours rappelle qu'il faut **maintenir un accueil humain**. Réponse attendue : garder un guichet (éventuellement à horaires réduits) ou un accompagnement pour faire les démarches en ligne. La relation digitale n'est un progrès que si elle rend service à l'usager ; sinon, elle déplace le travail vers lui."}$exo$::jsonb),
  ('f372e048-2b4a-5b3d-9f53-4177fe14429f'::uuid, 1, 'redaction', $exo${"titre":"Les formes de la communication","consigne":"Réponds à chaque question en justifiant brièvement.","enonce":"1. Quel est le **triptyque** de base d'une stratégie de communication ? Explique chaque terme en une phrase.\n2. Classe chaque exemple : communication **interne** (descendante, ascendante ou horizontale) ou **externe** (commerciale ou institutionnelle).\n   - a) La directrice envoie une note à tous les salariés sur les nouveaux horaires.\n   - b) Une chaîne de magasins diffuse une publicité pour ses promotions de rentrée.\n   - c) Des salariés déposent des propositions dans une boîte à idées.\n   - d) Une entreprise publie un film sur ses actions pour protéger la biodiversité, sans parler de ses produits.\n   - e) Deux chefs d'équipe échangent sur le réseau social d'entreprise.","bareme":[{"critere":"Cible, message et support nommés et expliqués","points":8},{"critere":"Les cinq exemples correctement classés","points":12}],"dureeMin":7,"corrige":"1. Le triptyque est **cible / message / support** :\n   - **cible** : à qui parle-t-on ;\n   - **message** : ce que l'on veut dire (informer, convaincre, faire agir) ;\n   - **support** : par quel média (affiche, site, réseau social, réunion, lettre).\n\n2. a) Interne **descendante** (direction → salariés).\n   b) Externe **commerciale** (vendre un produit).\n   c) Interne **ascendante** (salariés → direction).\n   d) Externe **institutionnelle** (valoriser l'image de l'organisation, sans vendre un produit).\n   e) Interne **horizontale** (entre collègues du même niveau)."}$exo$::jsonb),
  ('f372e048-2b4a-5b3d-9f53-4177fe14429f'::uuid, 2, 'redaction', $exo${"titre":"La piscine de Val-d'Oise : un plan de communication","consigne":"Lis la situation et réponds en utilisant le vocabulaire du cours.","enonce":"**Situation.**\n\n> La société Aquaval gère une piscine pour le compte d'une communauté de communes. Elle va ouvrir un **bassin chauffé à l'énergie solaire** et des cours de natation pour les seniors. Pour financer les panneaux solaires, elle demande un prêt à sa banque. Les maîtres-nageurs devront suivre une formation d'une journée. La communauté de communes, propriétaire des lieux, doit valider les nouveaux horaires.\n\n1. Identifie quatre **cibles** de communication, en distinguant cibles internes et externes.\n2. Construis un **plan de communication** sous forme de tableau (cible, message, support) pour ces quatre cibles.\n3. Quelle forme de communication externe s'adresse à la banque ? Quel document lui présenter ?\n4. Pourquoi Aquaval doit-elle veiller à la **cohérence** de ces messages ?","bareme":[{"critere":"Quatre cibles identifiées et classées interne / externe","points":4},{"critere":"Tableau cible / message / support cohérent pour les quatre cibles","points":8},{"critere":"Communication financière vers la banque (solvabilité) et plan d'affaires","points":4},{"critere":"Cohérence expliquée : communication globale, ce qui est dit dehors doit être vrai dedans","points":4}],"dureeMin":12,"corrige":"1. - Cible **interne** : les maîtres-nageurs (salariés).\n   - Cibles **externes** : les nageurs seniors (clients), la banque, la communauté de communes (collectivité).\n\n2. | Cible | Message | Support |\n|---|---|---|\n| Maîtres-nageurs | « Vous serez formés en une journée aux cours seniors » | Réunion, note interne, intranet |\n| Seniors | « Nagez au chaud, dans un bassin chauffé au soleil » | Affiches, presse locale, flyers en mairie |\n| Banque | « Un projet rentable qui réduit la facture d'énergie » | Plan d'affaires, rendez-vous |\n| Communauté de communes | « Un service nouveau pour les habitants, plus écologique » | Rencontre avec les élus, dossier |\n\n(Toute réponse cohérente est acceptée.)\n\n3. C'est la **communication financière** : la banque attend surtout des informations sur la **solvabilité** d'Aquaval et la rentabilité du projet. Le document adapté est le **plan d'affaires** (*business plan*), qui présente le projet, le marché, la stratégie et les prévisions financières pour convaincre des financeurs.\n\n4. Les messages diffèrent selon les cibles, mais ils doivent rester **cohérents** autour d'une même idée (un bassin écologique, utile aux habitants et rentable). C'est la **communication globale** : les salariés sont aussi des habitants et des clients, et ce qui est dit dehors doit être vrai dedans. Un décalage entre discours et réalité nuirait à l'image."}$exo$::jsonb),
  ('f372e048-2b4a-5b3d-9f53-4177fe14429f'::uuid, 3, 'redaction', $exo${"titre":"Verdiane : une image à reconstruire","consigne":"Analyse la situation en mobilisant les notions du cours ; rédige des réponses structurées appuyées sur les documents.","enonce":"**Document 1 — Une campagne remarquée.**\n\n> Verdiane, fabricant de produits d'entretien, a lancé une campagne télévisée : « Chez Verdiane, nous prenons soin de la planète et de nos équipes. » La même semaine, sur un site d'avis d'employeurs, d'anciens salariés dénoncent des cadences intenables et des heures supplémentaires non payées. Les captures d'écran circulent sur les réseaux sociaux. Le service recrutement constate que les candidatures ont chuté de moitié.\n\n**Document 2 — La situation interne.**\n\n> Les salariés disent apprendre les décisions de la direction « par la presse ». Il n'existe ni journal interne ni réunion régulière. La direction s'apprête à demander un prêt à sa banque pour moderniser une usine.\n\n1. Identifie la forme de la campagne télévisée (commerciale ou institutionnelle). Justifie.\n2. Explique ce qu'est l'**e-réputation** et pourquoi Verdiane ne la contrôle pas entièrement.\n3. Analyse l'effet de la situation sur la **marque employeur**.\n4. Montre que Verdiane manque de **communication globale** et de **communication interne**, puis propose des actions (formes et outils).\n5. Pourquoi la banque risque-t-elle d'être prudente, et quelle information attendra-t-elle ?","bareme":[{"critere":"Campagne institutionnelle justifiée : elle valorise l'image, pas un produit","points":3},{"critere":"E-réputation définie, perte de contrôle expliquée par les avis et les partages","points":4},{"critere":"Marque employeur dégradée : image d'employeur, candidatures divisées par deux","points":4},{"critere":"Décalage discours / réalité ; actions de communication interne (descendante, ascendante, outils) proposées","points":6},{"critere":"Banque : communication financière, solvabilité, transparence","points":3}],"dureeMin":20,"corrige":"1. C'est une communication **institutionnelle** : elle valorise l'**image** de l'organisation (« nous prenons soin de la planète et de nos équipes ») sans vanter un produit particulier.\n\n2. L'**e-réputation** est l'image qui se construit **en ligne** (avis, commentaires, articles). Elle échappe **en partie au contrôle** de l'organisation : ici, d'anciens salariés publient des avis, et les internautes les partagent sur les réseaux sociaux ; Verdiane ne peut ni les effacer ni maîtriser leur diffusion.\n\n3. La **marque employeur** est l'image de l'organisation **en tant qu'employeur**, qui sert à attirer et retenir les talents. Les avis négatifs l'ont dégradée : les candidatures ont **chuté de moitié**. L'entreprise aura plus de mal à recruter.\n\n4. - **Communication globale** : elle doit harmoniser interne et externe ; ce qui est dit dehors doit être **vrai dedans**. Or le discours (« nous prenons soin de nos équipes ») contredit la réalité vécue (cadences, heures non payées) : le décalage se paie cher en ligne.\n   - **Communication interne** défaillante : les salariés apprennent les décisions « par la presse » (pas de communication **descendante**), et rien ne permet de faire remonter leurs difficultés (pas de communication **ascendante**).\n   - **Actions** : d'abord corriger la réalité (paiement des heures, cadences), puis informer par un **journal interne**, un **intranet**, des **réunions** régulières ; ouvrir des canaux ascendants (boîte à idées, enquête) ; utiliser le **réseau social d'entreprise**. La communication contribue au **dialogue social** et à l'adhésion du personnel. Enfin, ne communiquer à l'extérieur que sur des progrès réels.\n\n5. La banque attend de la **communication financière** des informations sur la **solvabilité** de Verdiane : sa capacité à rembourser. La crise d'image (difficultés de recrutement, risque pour les ventes) peut la rendre prudente ; Verdiane devra présenter des comptes fiables et **transparents**, établis selon des **règles comptables normalisées**, et un **plan d'affaires** pour la modernisation de l'usine."}$exo$::jsonb),
  ('d1a45a7f-0049-5e74-90af-091ce2dc2a24'::uuid, 1, 'redaction', $exo${"titre":"Éthique, déontologie et discours trompeurs","consigne":"Réponds à chaque question en une ou deux phrases précises.","enonce":"1. Distingue l'**éthique** de la **déontologie**, avec un exemple pour chacune.\n2. Identifie la pratique décrite (lobbying, greenwashing, social washing) et dis si elle est acceptable :\n   - a) Une marque de lessive affiche une feuille verte et le mot « éco » sur un produit dont la formule n'a pas changé.\n   - b) Une fédération professionnelle rencontre des députés pour défendre ses intérêts, et déclare publiquement ces rencontres.\n   - c) Une entreprise communique sur son « engagement pour l'inclusion » alors qu'elle n'a pris aucune mesure concrète.\n3. Qu'est-ce qu'une **charte éthique** ?","bareme":[{"critere":"Éthique et déontologie définies et illustrées","points":7},{"critere":"Les trois pratiques identifiées et jugées (greenwashing et social washing trompeurs, lobbying légal s'il est transparent)","points":9},{"critere":"Charte éthique : document qui formalise les engagements de conduite","points":4}],"dureeMin":7,"corrige":"1. - L'**éthique** est une réflexion sur ce qui est **bien** ou **mal** dans l'action, **au-delà de la loi**. Exemple : refuser un marché obtenu par un pot-de-vin, même indétectable.\n   - La **déontologie** est l'ensemble des **règles et devoirs propres à une profession**. Exemple : le secret médical, le secret professionnel de l'avocat.\n\n2. a) **Greenwashing** : se présenter comme écologique sans l'être ; c'est trompeur et trahit la confiance.\n   b) **Lobbying** : défendre ses intérêts auprès des décideurs est **légal** ; ici il est **transparent** (rencontres déclarées), donc acceptable.\n   c) **Social washing** : afficher un engagement social de façade ; c'est trompeur.\n\n3. Une **charte éthique** (ou code de conduite) est le document dans lequel l'organisation **formalise ses engagements de conduite** envers ses parties prenantes."}$exo$::jsonb),
  ('d1a45a7f-0049-5e74-90af-091ce2dc2a24'::uuid, 2, 'redaction', $exo${"titre":"Recrutement chez Transnord","consigne":"Lis la situation, puis réponds en mobilisant les notions du cours.","enonce":"**Situation.**\n\n> Transnord, entreprise de transport de 120 salariés, recrute des agents d'exploitation. Une ancienne stagiaire du service RH témoigne : « Le responsable écartait les CV des candidats qui habitaient la cité des Tilleuls, en disant qu'ils seraient souvent en retard. Il demandait aussi aux candidates si elles comptaient avoir des enfants. » Par ailleurs, les femmes de l'entreprise gagnent en moyenne nettement moins que les hommes à poste égal.\n\n1. Définis la **discrimination**. Identifie les deux critères interdits utilisés par le responsable.\n2. Quelle obligation Transnord doit-elle respecter en matière d'**égalité femmes-hommes** ? Justifie par son effectif. Que risque-t-elle si le résultat est trop faible ?\n3. Propose trois **mesures** pour lutter contre les discriminations à l'embauche.\n4. Au-delà de la loi, pourquoi l'éthique est-elle aussi un enjeu de **performance** pour Transnord ?","bareme":[{"critere":"Discrimination définie ; critères identifiés : lieu de résidence et sexe (projet d'enfants lié au sexe)","points":5},{"critere":"Index de l'égalité professionnelle à calculer et publier chaque année (au moins 50 salariés), mesures correctrices sous peine de pénalité","points":5},{"critere":"Trois mesures pertinentes (CV sans nom, formation des recruteurs, objectifs de mixité)","points":5},{"critere":"Enjeu de performance : sanctions, image, confiance, attractivité","points":5}],"dureeMin":12,"corrige":"1. Une **discrimination** est une différence de traitement fondée sur un **critère interdit par la loi**. Le responsable utilise :\n   - le **lieu de résidence** (écarter les habitants de la cité des Tilleuls) ;\n   - le **sexe** (seules les candidates sont interrogées sur un projet d'enfants).\n\n2. Avec **120 salariés**, Transnord compte au moins 50 salariés : elle doit **calculer et publier chaque année l'index de l'égalité professionnelle** femmes-hommes. Les écarts de salaire à poste égal risquent de donner un index faible : elle devra alors prendre des **mesures correctrices**, sous peine de **pénalité**.\n\n3. Mesures (trois attendues) : examiner les **CV sans nom** (ni adresse) ; **former les recruteurs** à la non-discrimination ; fixer des **objectifs de mixité** ; définir des critères de sélection liés aux seules compétences ; faire mener les entretiens par deux personnes.\n\n4. Les **parties prenantes** exigent des comportements responsables. Un manquement se paie : **sanctions**, **perte de confiance**, image dégradée, **départs de salariés** et difficultés de recrutement. De plus, écarter des candidats pour leur adresse prive l'entreprise de compétences. L'éthique est une condition de la confiance, donc de la **performance durable**."}$exo$::jsonb),
  ('d1a45a7f-0049-5e74-90af-091ce2dc2a24'::uuid, 3, 'redaction', $exo${"titre":"Alpina Eaux : trois affaires en un an","consigne":"Analyse la situation à l'aide des notions du cours. Rédige des réponses structurées, appuyées sur le document.","enonce":"**Document.**\n\n> Alpina Eaux, qui embouteille de l'eau de source, a connu une année difficile.\n> - Ses bouteilles portent la mention « 100 % recyclées », alors qu'elles contiennent 25 % de plastique recyclé.\n> - Un journal révèle que l'entreprise a financé en secret un collectif d'« habitants » qui faisait campagne auprès des élus pour obtenir un nouveau forage.\n> - Le commissaire aux comptes a refusé de certifier les comptes : des stocks invendus et abîmés y figuraient à leur pleine valeur.\n>\n> Résultat : une grande enseigne a retiré ses produits, deux cadres ont démissionné, et la banque a suspendu une demande de prêt.\n\n1. Qualifie chacune des trois pratiques à l'aide des notions du cours.\n2. Identifie les **parties prenantes** lésées ou inquiètes, et ce que chacune reproche à l'entreprise.\n3. Explique le rôle de la **normalisation comptable** et du **commissaire aux comptes**. En quoi le troisième fait est-il un problème éthique ?\n4. Propose une **réponse éthique** pour chaque pratique, et montre qu'elle sert aussi la performance de l'entreprise.","bareme":[{"critere":"Pratiques qualifiées : greenwashing, lobbying non transparent, information financière non sincère","points":5},{"critere":"Parties prenantes identifiées (clients, distributeur, salariés, banque, élus, habitants) avec leurs griefs","points":4},{"critere":"Normalisation comptable et commissaire aux comptes expliqués ; comptes non sincères qui trompent actionnaires, salariés et prêteurs","points":4},{"critere":"Réponses éthiques pertinentes (étiquetage exact et labels contrôlés, lobbying transparent, comptes sincères, charte) reliées à la performance","points":5},{"critere":"Analyse structurée et appuyée sur le document","points":2}],"dureeMin":20,"corrige":"1. - « 100 % recyclées » pour 25 % de plastique recyclé : **greenwashing** (se dire écologique sans l'être), tromperie du consommateur.\n   - Financer en secret un faux collectif d'habitants : **lobbying** déguisé. Le lobbying est légal mais doit être **transparent** ; ici il manque de **sincérité** et trompe les élus et les habitants.\n   - Stocks abîmés comptés à pleine valeur : **information financière non sincère**, contraire à la **transparence** (et au principe de prudence). \n\n2. - **Clients** : trompés sur le caractère recyclé.\n   - **Grande enseigne** (distributeur) : risque pour sa propre image, d'où le retrait des produits.\n   - **Salariés** : deux cadres ont démissionné, perte de confiance.\n   - **Banque** : ne peut plus se fier aux comptes, suspend le prêt.\n   - **Élus et habitants** : manipulés par une fausse campagne.\n   - **Concurrents honnêtes** : concurrence déloyale.\n\n3. La **normalisation comptable** impose des règles communes de présentation des comptes ; le **commissaire aux comptes** contrôle et certifie leur sincérité. Ensemble, ils garantissent une **information fiable**. En surévaluant ses stocks, Alpina présente un patrimoine et un résultat meilleurs que la réalité : elle **trompe** actionnaires, salariés et prêteurs. C'est un manquement éthique, pas seulement une erreur technique.\n\n4. - Étiquetage **exact** (« 25 % de plastique recyclé »), **labels contrôlés par un tiers**, communication sur les **progrès réels**.\n   - **Lobbying transparent** : défendre publiquement le projet de forage, en son nom.\n   - **Comptes sincères** : déprécier les stocks abîmés, accepter le contrôle du commissaire aux comptes.\n   - Formaliser ces engagements dans une **charte éthique**.\n   Ces réponses servent la performance : elles rétablissent la **confiance** des distributeurs, de la banque (prêt), des salariés et des clients, et évitent sanctions et boycott. L'éthique est une condition de la **performance durable**."}$exo$::jsonb),
  ('3a60e7b4-021b-5709-96b1-d4f5df521f4c'::uuid, 1, 'redaction', $exo${"titre":"Nouveaux modes de vie, nouvelles réponses","consigne":"Réponds à chaque question en une ou deux phrases.","enonce":"1. Associe chaque réponse d'organisation à l'évolution du rapport au travail qu'elle traite (temps, lieu, mode d'organisation, vie connectée) :\n   - a) un accord de télétravail deux jours par semaine ;\n   - b) l'interdiction d'envoyer des courriels professionnels après 20 h ;\n   - c) des horaires flexibles pour mieux concilier vie privée et vie professionnelle ;\n   - d) un management par objectifs et le recours à des indépendants.\n2. Distingue l'**économie de la fonctionnalité** et l'**économie collaborative**, avec un exemple chacune.\n3. Définis le **mécénat**.","bareme":[{"critere":"Les quatre associations justes (a lieu, b vie connectée, c temps, d mode d'organisation)","points":8},{"critere":"Économie de la fonctionnalité et économie collaborative distinguées avec exemples","points":8},{"critere":"Mécénat défini (soutien financier ou en nature à une œuvre d'intérêt général)","points":4}],"dureeMin":7,"corrige":"1. a) **Lieu** : essor du télétravail.\n   b) **Vie connectée** : sollicitations permanentes ; c'est une application du **droit à la déconnexion** (inscrit dans le Code du travail depuis 2017).\n   c) **Temps** : envie d'équilibre entre vie privée et vie professionnelle.\n   d) **Mode d'organisation** : rapport différent à la hiérarchie, travail indépendant.\n\n2. - L'**économie de la fonctionnalité** consiste à vendre l'**usage** d'un bien plutôt que le bien lui-même (louer des pneus au kilomètre, abonnement vélo).\n   - L'**économie collaborative** repose sur le **partage entre particuliers** (covoiturage).\n\n3. Le **mécénat** est un **soutien financier ou en nature** à une œuvre d'**intérêt général** (culture, recherche, solidarité) ; il ouvre droit à une réduction d'impôt."}$exo$::jsonb),
  ('3a60e7b4-021b-5709-96b1-d4f5df521f4c'::uuid, 2, 'redaction', $exo${"titre":"Lumen : louer la lumière","consigne":"Lis la situation et réponds en justifiant par des indices du texte.","enonce":"**Situation.**\n\n> Lumen fabrique des luminaires pour les bureaux. Au lieu de les vendre, elle propose désormais aux entreprises un **abonnement « lumière »** : elle installe, entretient et remplace les lampes, et facture selon les heures d'éclairage. Ses 40 salariés administratifs ont obtenu un accord de télétravail ; certains reçoivent pourtant des messages de leur chef à 22 h. Lumen finance aussi l'éclairage d'une église classée de sa ville et organise chaque année un vote de ses salariés pour choisir l'association qu'elle soutiendra.\n\n1. Quel **mode de consommation** Lumen met-elle en œuvre ? Justifie.\n2. Quelles évolutions du **rapport au travail** apparaissent ? Quel droit est menacé par les messages de 22 h ?\n3. Identifie deux **préoccupations civiques** de Lumen et nomme-les avec le vocabulaire du cours.","bareme":[{"critere":"Économie de la fonctionnalité justifiée (vente de l'usage, facturation aux heures d'éclairage)","points":6},{"critere":"Télétravail (lieu) et vie connectée ; droit à la déconnexion menacé","points":7},{"critere":"Mécénat (église) et démocratie participative (vote des salariés) identifiés","points":7}],"dureeMin":10,"corrige":"1. Lumen pratique l'**économie de la fonctionnalité** : elle ne vend plus le bien (le luminaire) mais son **usage** (la lumière), facturé selon les heures d'éclairage, tout en restant propriétaire et responsable de l'entretien.\n\n2. - Évolution du **lieu** de travail : l'accord de **télétravail**.\n   - Évolution liée à la **vie connectée** : les messages envoyés à 22 h montrent des sollicitations permanentes.\n   Ces messages menacent le **droit à la déconnexion**, inscrit dans le Code du travail depuis 2017 : l'entreprise doit organiser des temps sans sollicitation professionnelle.\n\n3. - Le **mécénat** : Lumen finance l'éclairage d'une église classée, soutien en nature ou financier à une œuvre d'intérêt général (culture, patrimoine).\n   - La **démocratie participative** en son sein : les salariés votent pour choisir l'association soutenue, ils sont associés aux décisions."}$exo$::jsonb),
  ('3a60e7b4-021b-5709-96b1-d4f5df521f4c'::uuid, 3, 'redaction', $exo${"titre":"La crèche au bout de l'algorithme","consigne":"Analyse les documents en mobilisant les notions du cours. Rédige des réponses argumentées.","enonce":"**Document 1 — Une commune.**\n\n> La ville de Montval attribue désormais les places en crèche grâce à un logiciel : il classe les demandes selon un score calculé à partir de la situation des parents. Une mère refusée demande pourquoi ; la mairie répond que « c'est le logiciel qui a décidé ». Le fichier des familles contient les revenus, l'adresse et, pour certains enfants, des informations sur leur santé.\n\n**Document 2 — Une coopérative laitière.**\n\n> La coopérative Lait des Monts enregistre chaque étape de son lait (ferme, collecte, transformation, magasin) dans une **chaîne de blocs**. En scannant la brique, le client voit le trajet du lait. Le mois dernier, un pirate a tenté de voler le fichier des recettes de ses fromages.\n\n1. Quelle obligation la mairie ne respecte-t-elle pas ? Explique-la.\n2. Quelles règles du **RGPD** s'appliquent au fichier des familles ? Pourquoi certaines données demandent-elles une protection renforcée ?\n3. Quel est l'intérêt de la chaîne de blocs pour Lait des Monts et pour ses clients ?\n4. Le fichier des recettes relève de quel type de données ? Pourquoi doit-il être protégé ?\n5. Montre, à partir des deux documents, que plus une organisation utilise les données, plus elle a de **responsabilités**.","bareme":[{"critere":"Transparence des algorithmes : informer la personne et lui expliquer les règles utilisées","points":4},{"critere":"RGPD : finalité, consentement, minimisation, sécurité, droits ; données de santé sensibles","points":4},{"critere":"Chaîne de blocs : registre partagé et infalsifiable, traçabilité, confiance sans tiers central","points":4},{"critere":"Données stratégiques : patrimoine exposé aux cyberattaques et à l'espionnage","points":4},{"critere":"Synthèse argumentée sur la responsabilité liée aux données et aux décisions automatisées","points":4}],"dureeMin":20,"corrige":"1. La mairie ne respecte pas l'obligation de **transparence des algorithmes** : une administration qui prend une **décision individuelle** fondée sur un traitement algorithmique doit en **informer** la personne et pouvoir lui **expliquer les règles utilisées** (critères du score). « C'est le logiciel qui a décidé » n'est pas une réponse acceptable.\n\n2. Le **RGPD** impose : une **finalité** précise (attribuer les places), le **consentement** ou une base légale, la **minimisation** (ne collecter que les données utiles), la **sécurité** des données et le respect des **droits** des personnes (accès, opposition) ; il prévoit des sanctions lourdes. Les informations de **santé** sont des **données sensibles** : elles exigent une protection renforcée, car leur fuite ou leur mauvais usage porterait gravement atteinte aux familles.\n\n3. La **chaîne de blocs** est un registre numérique **partagé** et **infalsifiable** qui sécurise les échanges sans tiers de confiance central. Pour Lait des Monts, elle assure la **traçabilité** du lait ; pour le client, elle apporte une preuve fiable de l'origine, donc de la **confiance**.\n\n4. Les recettes sont des **données stratégiques** (secrets de fabrication) : c'est un **patrimoine** de la coopérative, exposé aux **cyberattaques** et à l'**espionnage** ; leur vol profiterait aux concurrents.\n\n5. La mairie décide automatiquement et détient des données sensibles : elle doit expliquer ses règles et protéger les familles. La coopérative collecte des données tout au long de sa filière et possède des secrets : elle doit sécuriser son système. Dans les deux cas, les **transformations numériques** donnent de nouveaux pouvoirs, donc de **nouvelles responsabilités** : plus une organisation collecte de données et automatise ses décisions, plus elle doit **rendre des comptes** sur l'usage qu'elle en fait. Sinon, la confiance s'effondre."}$exo$::jsonb),
  ('4bcb3795-1e8c-5d14-8db9-9b9b33565a6e'::uuid, 1, 'redaction', $exo${"titre":"S'implanter : critères et écosystème","consigne":"Réponds à chaque question avec le vocabulaire du cours.","enonce":"1. Classe chaque élément dans un **critère d'implantation** (ressources humaines, financières et fiscales, infrastructures, marché, réseau, qualité de vie) :\n   - a) une école d'ingénieurs à proximité ;\n   - b) une gare TGV et le très haut débit ;\n   - c) une aide de la région à l'installation ;\n   - d) des sous-traitants et un laboratoire de recherche dans la zone ;\n   - e) une ville agréable qui attire les cadres.\n2. Définis une **grappe d'entreprises** (*cluster*) et donne un exemple.\n3. Distingue **délocalisation** et **relocalisation**.","bareme":[{"critere":"Les cinq éléments correctement classés","points":8},{"critere":"Grappe d'entreprises définie avec un exemple","points":6},{"critere":"Délocalisation et relocalisation distinguées","points":6}],"dureeMin":7,"corrige":"1. a) **Ressources humaines** (main-d'œuvre qualifiée, écoles).\n   b) **Infrastructures** (gares, très haut débit).\n   c) **Financières et fiscales** (aides locales).\n   d) **Réseau** (fournisseurs, sous-traitants, centres de recherche).\n   e) **Qualité de vie** (attractivité pour les salariés).\n\n2. Une **grappe d'entreprises** est une **concentration géographique** d'entreprises d'un **même domaine**, avec des centres de formation et de recherche. Exemple : l'aéronautique à Toulouse, ou la « vallée de la cosmétique » en région Centre.\n\n3. - **Délocaliser** : transférer une activité à l'étranger, souvent pour réduire les coûts (pertes d'emplois sur le territoire d'origine).\n   - **Relocaliser** : rapatrier une activité (emplois recréés, sécurité d'approvisionnement)."}$exo$::jsonb),
  ('4bcb3795-1e8c-5d14-8db9-9b9b33565a6e'::uuid, 2, 'redaction', $exo${"titre":"Drone Azur choisit son site","consigne":"Lis les données, puis réponds en justifiant par les critères du cours.","enonce":"**Situation.**\n\n> Drone Azur, jeune fabricant de drones agricoles, cherche un site pour sa première usine (150 emplois prévus). Deux villes sont candidates.\n\n| Critère | Ville A | Ville B |\n|---|---|---|\n| Main-d'œuvre | Peu de techniciens qualifiés | Lycée technique et IUT en électronique |\n| Coût du foncier | Faible, aide régionale de 500 000 € | Élevé, pas d'aide |\n| Infrastructures | Autoroute ; pas de très haut débit | Autoroute et très haut débit |\n| Réseau | Aucune entreprise du secteur | Pôle de compétitivité en robotique, 40 entreprises et deux laboratoires |\n| Marché | Grande région agricole | Région agricole moyenne |\n\n1. Pour chaque ville, présente deux **atouts** en les rattachant aux critères du cours.\n2. Quelle ville recommandes-tu ? Justifie en hiérarchisant les critères pour un fabricant de drones.\n3. Explique ce qu'apporterait à Drone Azur le **pôle de compétitivité** de la ville B.\n4. Donne deux **effets** que l'usine produirait sur le territoire choisi.","bareme":[{"critere":"Deux atouts par ville, rattachés aux bons critères","points":5},{"critere":"Recommandation justifiée par une hiérarchie cohérente des critères","points":6},{"critere":"Pôle de compétitivité : entreprises, laboratoires, formation, innovation par la proximité","points":5},{"critere":"Deux effets sur le territoire (emplois directs et indirects, impôts locaux, formation, nuisances…)","points":4}],"dureeMin":12,"corrige":"1. - **Ville A** : foncier faible et aide régionale de 500 000 € (critère **financier et fiscal**) ; grande région agricole, donc proximité des clients (**marché**) ; autoroute (**infrastructures**).\n   - **Ville B** : lycée technique et IUT en électronique (**ressources humaines**) ; très haut débit (**infrastructures**) ; pôle de compétitivité en robotique (**réseau**).\n\n2. Recommandation attendue : plutôt la **ville B**. Un fabricant de drones est une entreprise **innovante** qui a besoin de **techniciens qualifiés**, de **très haut débit** et d'un **réseau** de recherche : ces ressources sont rares et difficiles à créer, alors que le coût du foncier se compense avec le temps. La ville A est moins chère et proche des clients, mais le manque de main-d'œuvre qualifiée gênerait le recrutement des 150 salariés. (Une recommandation pour A est acceptée si elle est solidement justifiée, par exemple par le marché et l'aide, avec un plan de formation.)\n\n3. Le **pôle de compétitivité**, labellisé par l'État, associe **entreprises, laboratoires et centres de formation** autour de projets d'**innovation**. Drone Azur y trouverait des partenaires, des sous-traitants, des compétences et des projets communs ; la **proximité** favorise les échanges informels et la circulation des compétences. Il entrerait dans un **écosystème** où l'on coopère et rivalise à la fois.\n\n4. Effets possibles : **emplois directs** (150) et **indirects** (sous-traitants, commerces), commandes aux entreprises locales, **impôts locaux**, formations créées avec le lycée et l'IUT, mais aussi besoins en logements ou nuisances à gérer avec les collectivités."}$exo$::jsonb),
  ('4bcb3795-1e8c-5d14-8db9-9b9b33565a6e'::uuid, 3, 'redaction', $exo${"titre":"Pharmaval revient en France","consigne":"Analyse la situation en mobilisant les notions du cours ; construis une réponse argumentée à la dernière question.","enonce":"**Document 1.**\n\n> Pharmaval, laboratoire français, fabriquait depuis 2005 le principe actif de son antidouleur en Asie, « pour réduire les coûts ». En 2020, pendant la crise sanitaire, les livraisons ont été interrompues trois mois : ruptures de stock dans les pharmacies. Pharmaval a décidé de **rapatrier** cette production dans une friche industrielle d'une vallée où une usine chimique avait fermé dix ans plus tôt.\n\n**Document 2 — Le projet.**\n\n> 220 emplois dans l'usine ; une trentaine de PME locales sollicitées pour la maintenance, le transport et la restauration ; un partenariat avec le lycée professionnel pour former des opérateurs ; un coût de production 15 % plus élevé qu'en Asie ; des habitants inquiets pour la ressource en eau de la rivière.\n\n1. Qualifie les deux décisions de Pharmaval (2005 et 2020). Quelles étaient leurs motivations ?\n2. Qu'a montré la crise de 2020 ? Relie ta réponse à la notion de **souveraineté**.\n3. Présente les **effets** du projet sur le territoire en les classant (économiques, sociaux, environnementaux).\n4. Montre que le territoire **fournit** aussi des ressources à Pharmaval.\n5. La relocalisation est-elle une bonne décision ? Argumente en pesant avantages et limites.","bareme":[{"critere":"Délocalisation (2005, coûts) et relocalisation (2020, sécurité d'approvisionnement) qualifiées","points":4},{"critere":"Fragilité des chaînes d'approvisionnement lointaines et souveraineté industrielle","points":3},{"critere":"Effets classés : emplois directs et indirects, formation, réhabilitation de friche, eau","points":5},{"critere":"Ressources fournies par le territoire : friche, main-d'œuvre, lycée, PME","points":3},{"critere":"Argumentation nuancée : sécurité et emplois contre surcoût de 15 % et risque environnemental","points":5}],"dureeMin":20,"corrige":"1. - **2005** : **délocalisation** — transfert de la production à l'étranger, « pour réduire les coûts ».\n   - **2020** : **relocalisation** — rapatriement de l'activité, pour retrouver la **sécurité d'approvisionnement** après les ruptures.\n\n2. La crise sanitaire de 2020 a montré la **fragilité de chaînes d'approvisionnement très lointaines** (médicaments) : trois mois sans livraison ont provoqué des ruptures en pharmacie. Elle a relancé les débats sur la **souveraineté industrielle** : produire sur son territoire des biens essentiels pour ne pas dépendre de l'étranger.\n\n3. - **Économiques** : 220 **emplois directs** ; **emplois indirects** et commandes pour une trentaine de PME locales (maintenance, transport, restauration) ; impôts locaux.\n   - **Sociaux** : formation d'opérateurs avec le lycée professionnel, retour de l'emploi industriel dans une vallée touchée par une fermeture.\n   - **Environnementaux** : positif, la **réhabilitation d'une friche** ; négatif, la pression sur la **ressource en eau** de la rivière.\n\n4. Le territoire fournit : un **foncier** disponible (la friche), une **main-d'œuvre** avec une culture industrielle, un **lycée** pour former, des **PME** pour la sous-traitance : c'est une relation dans les deux sens.\n\n5. **Avantages** : sécurité d'approvisionnement des patients et de l'entreprise, image, emplois et vitalité retrouvés pour la vallée, écosystème local renforcé.\n   **Limites** : un coût de production **15 % plus élevé**, qui pèse sur la rentabilité ; un risque environnemental à maîtriser (eau), qui peut créer des tensions avec les habitants.\n   **Conclusion** : la décision est pertinente pour un produit essentiel, à condition de gérer l'eau avec les collectivités et de compenser le surcoût (productivité, image). Une grande implantation change le destin d'un territoire, dans un sens comme dans l'autre."}$exo$::jsonb),
  ('6bd17d64-ebc5-583d-8d85-7c6c7cfb86ed'::uuid, 1, 'redaction', $exo${"titre":"Partie double, TVA et amortissement","consigne":"Réponds à chaque question ; pose les calculs.","enonce":"1. Explique le principe de la **partie double**.\n2. Au mois de mai, l'entreprise Solaris a collecté **18 000 €** de TVA sur ses ventes et payé **11 500 €** de TVA sur ses achats. Combien doit-elle reverser à l'État ? Explique pourquoi la TVA n'est pas une charge pour elle.\n3. Solaris achète une machine **36 000 €**, qu'elle utilisera **6 ans**. Pourquoi cet achat n'est-il pas une charge de l'exercice ? Calcule la dotation annuelle d'**amortissement linéaire**.","bareme":[{"critere":"Partie double : débit d'un compte et crédit d'un autre pour le même montant","points":5},{"critere":"TVA à reverser = 18 000 − 11 500 = 6 500 € ; taxe collectée pour l'État","points":7},{"critere":"Immobilisation à l'actif ; dotation = 36 000 ÷ 6 = 6 000 € par an","points":8}],"dureeMin":8,"corrige":"1. Selon la **partie double**, chaque opération est inscrite au **débit** d'un compte et au **crédit** d'un autre, pour le **même montant**. Par exemple, un achat payé par la banque est inscrit au débit du compte de l'achat et au crédit du compte banque.\n\n2. TVA à reverser = TVA collectée − TVA déductible = 18 000 − 11 500 = **6 500 €**.\n   La TVA n'est pas une charge : l'entreprise la **collecte** sur ses ventes pour le compte de l'État, **déduit** celle payée sur ses achats, et **reverse la différence**. C'est le client final qui la supporte.\n\n3. La machine sera utilisée plusieurs années : c'est une **immobilisation**, inscrite à l'**actif** du bilan, et non une charge de l'exercice. Elle perd de la valeur par l'**amortissement**.\n   Dotation annuelle (linéaire) = coût d'acquisition ÷ durée d'utilisation = 36 000 ÷ 6 = **6 000 € par an**."}$exo$::jsonb),
  ('6bd17d64-ebc5-583d-8d85-7c6c7cfb86ed'::uuid, 2, 'redaction', $exo${"titre":"Rentabilité et levier chez Vitralys","consigne":"Pose chaque calcul (formule, calcul, résultat), puis interprète.","enonce":"**Données de Vitralys (fabricant de vitrages).**\n\n| Élément | Montant |\n|---|---|\n| Résultat d'exploitation | 90 000 € |\n| Capitaux investis | 600 000 € |\n| Résultat net | 63 000 € |\n| Capitaux propres | 350 000 € |\n| Dettes financières | 250 000 € |\n| Capacité d'autofinancement (CAF) | 80 000 € |\n| Taux d'intérêt de ses emprunts | 4 % |\n\n1. Calcule la **rentabilité économique** et la **rentabilité financière**.\n2. L'**effet de levier** joue-t-il en faveur des associés ? Justifie.\n3. Calcule la **capacité de remboursement** et interprète-la.\n4. Vitralys envisage d'emprunter **100 000 €** de plus (CAF inchangée). Recalcule la capacité de remboursement et conclus.","bareme":[{"critere":"Rentabilité économique 15 % et financière 18 %, formules posées","points":6},{"critere":"Effet de levier favorable : 15 % > 4 %, rentabilité financière supérieure","points":4},{"critere":"Capacité de remboursement = 250 000 ÷ 80 000 ≈ 3,1 et interprétation (zone de 3 à 4)","points":5},{"critere":"Nouvelle capacité ≈ 4,4, au-delà de 4 : endettement risqué, conclusion","points":5}],"dureeMin":12,"corrige":"1. - Rentabilité économique = résultat d'exploitation ÷ capitaux investis = 90 000 ÷ 600 000 = **15 %**.\n   - Rentabilité financière = résultat net ÷ capitaux propres = 63 000 ÷ 350 000 = **18 %**.\n\n2. Oui : l'activité rapporte **15 %** alors que l'entreprise emprunte à **4 %**. Quand la rentabilité économique dépasse le taux d'intérêt, l'endettement **augmente la rentabilité financière** : ici 18 % pour les associés, contre 15 % pour l'ensemble des capitaux. L'effet de levier est **favorable**, mais il accroît aussi le **risque**.\n\n3. Capacité de remboursement = dettes financières ÷ CAF = 250 000 ÷ 80 000 = **3,125** (environ 3,1). Il faudrait un peu plus de 3 ans de CAF pour rembourser les dettes : le ratio est dans la zone de **3 à 4**, jugée encore saine, mais proche de la limite.\n\n4. Nouvelles dettes financières = 250 000 + 100 000 = 350 000 €.\n   Capacité de remboursement = 350 000 ÷ 80 000 = **4,375** (environ 4,4).\n   Le ratio dépasserait **4** : l'endettement deviendrait lourd au regard des ressources générées par l'activité. Les banques pourraient refuser le prêt ; Vitralys devrait envisager d'autres financements (autofinancement, augmentation de capital) ou un emprunt plus faible."}$exo$::jsonb),
  ('6bd17d64-ebc5-583d-8d85-7c6c7cfb86ed'::uuid, 3, 'redaction', $exo${"titre":"Brasserie Hoplà : diagnostic avant d'investir","consigne":"Pose les calculs, interprète chacun, puis rédige une recommandation argumentée.","enonce":"**Document 1 — Extraits des comptes de la Brasserie Hoplà (en euros).**\n\n| Élément | Montant |\n|---|---|\n| Valeur ajoutée | 400 000 |\n| Subventions d'exploitation | 10 000 |\n| Impôts et taxes | 15 000 |\n| Charges de personnel | 260 000 |\n| Capitaux propres | 300 000 |\n| Dettes financières | 200 000 |\n| Emplois stables | 430 000 |\n| Stocks | 60 000 |\n| Créances clients | 80 000 |\n| Dettes fournisseurs | 50 000 |\n| CAF | 90 000 |\n\nLes ressources stables sont constituées des capitaux propres et des dettes financières.\n\n**Document 2.**\n\n> La brasserie veut acheter une ligne d'embouteillage de **150 000 €**. Les deux associés hésitent entre un emprunt bancaire et une augmentation de capital ouverte à un investisseur. Ils tiennent à rester majoritaires.\n\n1. Calcule l'**excédent brut d'exploitation** (EBE).\n2. Calcule le FRNG, le BFR et la trésorerie nette. Interprète.\n3. Calcule le ratio d'**indépendance financière** et la **capacité de remboursement** actuelle.\n4. Recalcule la capacité de remboursement si la ligne est financée entièrement par emprunt.\n5. Propose une solution de financement de la ligne et une solution pour la trésorerie, en justifiant.","bareme":[{"critere":"EBE = 400 000 + 10 000 − 15 000 − 260 000 = 135 000 €","points":3},{"critere":"FRNG 70 000 €, BFR 90 000 €, trésorerie − 20 000 € interprétée","points":5},{"critere":"Indépendance financière 0,6 (60 %) et capacité de remboursement ≈ 2,2 interprétées","points":4},{"critere":"Avec emprunt : 350 000 ÷ 90 000 ≈ 3,9, proche de la limite de 3 à 4","points":3},{"critere":"Recommandation justifiée (endettement, pouvoir des associés) et solution de trésorerie (découvert, escompte, affacturage, délais clients)","points":5}],"dureeMin":20,"corrige":"1. EBE = valeur ajoutée + subventions d'exploitation − impôts et taxes − charges de personnel = 400 000 + 10 000 − 15 000 − 260 000 = **135 000 €**. L'activité courante dégage un excédent.\n\n2. Ressources stables = 300 000 + 200 000 = 500 000 €.\n   - FRNG = 500 000 − 430 000 = **70 000 €**.\n   - BFR = (60 000 + 80 000) − 50 000 = **90 000 €**.\n   - Trésorerie nette = 70 000 − 90 000 = **− 20 000 €**.\n   Le FRNG ne couvre pas le BFR : la trésorerie est **négative**, la brasserie dépend de financements à court terme.\n\n3. - Indépendance financière = capitaux propres ÷ ressources stables = 300 000 ÷ 500 000 = **0,6** (60 %) : les ressources durables viennent majoritairement des associés, l'entreprise est plutôt indépendante de ses prêteurs.\n   - Capacité de remboursement = 200 000 ÷ 90 000 ≈ **2,2** : un peu plus de deux ans de CAF suffiraient à rembourser les dettes, niveau **sain** (inférieur à 3).\n\n4. Avec un emprunt de 150 000 € : dettes financières = 350 000 €. Capacité de remboursement = 350 000 ÷ 90 000 ≈ **3,9** : proche de la limite haute (3 à 4). L'endettement deviendrait lourd.\n\n5. **Financement de la ligne** : l'emprunt total pousse le ratio près de 4 ; l'augmentation de capital n'ajoute pas de dette mais **dilue le pouvoir**, ce que les associés refusent au-delà de la majorité. Solution attendue et justifiée, par exemple : un **financement mixte** (emprunt partiel + **autofinancement** ou **apports en compte courant d'associés**, ou augmentation de capital limitée qui laisse les associés majoritaires). Toute solution cohérente avec les calculs et la contrainte de pouvoir est acceptée.\n   **Trésorerie** : combler le déficit de 20 000 € par un **découvert** autorisé, l'**escompte** ou l'**affacturage** des créances clients ; à plus long terme, réduire le BFR (raccourcir les délais clients). Le **budget de trésorerie** permet d'anticiper ces besoins."}$exo$::jsonb),
  ('53dbb27a-4444-525f-9572-63bf3aec6c25'::uuid, 1, 'redaction', $exo${"titre":"Segmenter, cibler, se positionner","consigne":"Réponds en une ou deux phrases par question.","enonce":"1. Définis la **segmentation**, le **ciblage** et le **positionnement**, dans l'ordre de la démarche.\n2. Identifie la stratégie marketing (masse, différencié, concentré, individualisé) :\n   - a) Une marque de sel vend le même paquet à tous les consommateurs.\n   - b) Une marque de chaussures ne vise que les grimpeurs de haut niveau.\n   - c) Un site de vêtements compose pour chaque client une sélection selon ses achats passés.\n   - d) Un constructeur propose une citadine pour les jeunes, un monospace pour les familles et une berline pour les cadres.\n3. Distingue distribution **intensive**, **sélective** et **exclusive**.","bareme":[{"critere":"Segmentation, ciblage et positionnement définis dans l'ordre","points":6},{"critere":"Les quatre stratégies correctement identifiées","points":8},{"critere":"Les trois types de distribution distingués","points":6}],"dureeMin":8,"corrige":"1. - **Segmenter** : découper le marché en groupes homogènes (âge, revenu, style de vie, usage).\n   - **Cibler** : choisir le ou les segments visés.\n   - **Se positionner** : occuper une place claire dans l'esprit des clients par rapport aux concurrents.\n\n2. a) **Marketing de masse** (indifférencié) : une seule offre pour tous.\n   b) **Marketing concentré** : une offre pour un seul segment (niche).\n   c) **Marketing individualisé** (*one-to-one*) : une offre personnalisée pour chaque client.\n   d) **Marketing différencié** : une offre adaptée à chaque segment.\n\n3. - **Intensive** : le produit est distribué partout.\n   - **Sélective** : dans des points de vente choisis.\n   - **Exclusive** : un seul distributeur par zone."}$exo$::jsonb),
  ('53dbb27a-4444-525f-9572-63bf3aec6c25'::uuid, 2, 'redaction', $exo${"titre":"Vertigo, salle d'escalade","consigne":"Lis la situation et réponds avec le vocabulaire du cours ; pose le calcul.","enonce":"**Situation.**\n\n> La salle d'escalade Vertigo propose une entrée à 16 € le samedi, mais à 9 € en semaine avant 16 h. Son application gratuite donne accès aux plans des voies ; le suivi de progression et les vidéos d'entraînement sont payants. Beaucoup de clients consultent les avis en ligne puis viennent acheter leur carte à l'accueil. On peut aussi réserver un créneau sur l'application et payer sur place. L'abonnement coûte **32 € par mois**, et un abonné reste en moyenne **2 ans**.\n\n1. Identifie deux **politiques tarifaires** pratiquées par Vertigo. Justifie.\n2. Quel comportement du client est décrit par « consultent les avis en ligne puis viennent acheter à l'accueil » ? Et par « réserver sur l'application et payer sur place » ?\n3. Calcule la **valeur vie client** d'un abonné.\n4. Quel montant de dépenses de fidélisation ce calcul peut-il justifier ? Explique le raisonnement.","bareme":[{"critere":"Prix différencié selon le moment et modèle freemium identifiés et justifiés","points":6},{"critere":"ROPO et distribution cross-canal identifiés","points":5},{"critere":"Valeur vie client = 32 × 12 × 2 = 768 €","points":5},{"critere":"Raisonnement : un abonné rapporte 768 €, on peut investir pour le garder tant que la dépense reste inférieure","points":4}],"dureeMin":11,"corrige":"1. - **Prix différencié** selon le moment : 16 € le samedi, 9 € en semaine avant 16 h (on remplit les heures creuses).\n   - Modèle de **gratuité** de type **freemium** : l'application est gratuite pour l'essentiel (plans des voies), les options sont payantes (suivi, vidéos).\n   (L'abonnement mensuel peut aussi être présenté comme un **prix forfaitaire**.)\n\n2. - Se renseigner en ligne puis acheter sur place : le **ROPO** (*Research Online, Purchase Offline*).\n   - Réserver sur l'application et payer en salle : distribution **cross-canal** (le client passe d'un canal à l'autre).\n\n3. Valeur vie client = 32 € × 12 mois × 2 ans = **768 €** par abonné.\n\n4. Un abonné rapporte en moyenne **768 €** sur toute sa relation avec la salle. Vertigo peut donc consacrer à sa conquête et à sa **fidélisation** (séance offerte, programme de fidélité, suivi personnalisé) une somme nettement inférieure à 768 €, et ces dépenses sont rentables si elles allongent la durée d'abonnement. La valeur vie client justifie d'investir dans la relation plutôt que de raisonner vente par vente."}$exo$::jsonb),
  ('53dbb27a-4444-525f-9572-63bf3aec6c25'::uuid, 3, 'redaction', $exo${"titre":"Sève, cosmétiques en direct","consigne":"Analyse la stratégie de l'entreprise à l'aide des notions du cours ; pose le calcul et argumente.","enonce":"**Document 1.**\n\n> Sève, marque de soins solides pour la peau, vendait uniquement en pharmacie. Elle a ouvert son **site de vente en ligne** et vend aussi sur une grande **place de marché**. Elle cible les 25-40 ans soucieux de réduire leurs déchets, avec un positionnement « efficace et sans emballage plastique ». Chaque nouveau client reçoit un échantillon qui coûte **12 €** à la marque. Des influenceuses « zéro déchet » présentent les produits ; une community manager répond aux questions sur les réseaux sociaux.\n\n**Document 2.**\n\n> Un client fidèle dépense en moyenne **45 €** par commande, commande **4 fois par an** et reste fidèle **3 ans**. Le mois dernier, une influenceuse a publié une vidéo montrant un savon Sève qui fondait sous la douche ; la vidéo a été vue 400 000 fois.\n\n1. Présente la **cible** et le **positionnement** de Sève. De quelle stratégie marketing s'agit-il ?\n2. Analyse l'évolution de la **distribution** : désintermédiation ou réintermédiation ? Justifie pour chaque canal.\n3. Calcule la **valeur vie client**. L'échantillon offert est-il justifié ?\n4. Quels **moyens de communication et de fidélisation** numériques Sève utilise-t-elle ?\n5. Analyse le risque révélé par le document 2 et propose une réponse.","bareme":[{"critere":"Cible et positionnement identifiés, marketing concentré (ou différencié) justifié","points":4},{"critere":"Site propre = désintermédiation ; place de marché = réintermédiation, justifiés","points":4},{"critere":"Valeur vie client = 45 × 4 × 3 = 540 € ; échantillon de 12 € justifié","points":4},{"critere":"Marketing d'influence, community management, CRM ou vente directe identifiés","points":4},{"critere":"Limite : bouche-à-oreille qui tourne au bad buzz, perte de contrôle du message ; réponse proposée","points":4}],"dureeMin":20,"corrige":"1. - **Cible** : les 25-40 ans soucieux de réduire leurs déchets.\n   - **Positionnement** : « efficace et sans emballage plastique », une place claire face aux soins classiques.\n   Sève vise un segment précis : c'est un **marketing concentré** (niche). (Différencié accepté si l'élève considère plusieurs segments servis par des canaux différents, avec justification.)\n\n2. - Le **site de vente en ligne** : vente **directe** au client, sans la pharmacie : **désintermédiation** grâce au numérique.\n   - La **place de marché** : un nouvel intermédiaire (une plateforme où des vendeurs tiers proposent leurs produits) apparaît : **réintermédiation**.\n   Sève combine plusieurs canaux (pharmacie, site, place de marché).\n\n3. Valeur vie client = 45 € × 4 commandes × 3 ans = **540 €**.\n   Un client fidèle rapporte 540 € sur toute sa relation avec la marque ; un échantillon à **12 €** est largement justifié s'il transforme une part suffisante des personnes qui l'essaient en clients fidèles.\n\n4. - **Marketing d'influence** (influenceuses « zéro déchet »).\n   - **Gestion de communauté** (*community management*) sur les réseaux sociaux.\n   - La vente directe permet de connaître ses clients et d'utiliser un outil de **gestion de la relation client** (CRM) pour la fidélisation.\n\n5. Le **bouche-à-oreille** numérique peut tourner au ***bad buzz*** : la marque **perd le contrôle du message** (400 000 vues d'une vidéo négative). Réponse : la community manager répond vite et sans nier, explique comment conserver un soin solide (porte-savon qui sèche), propose un geste aux clients concernés, et vérifie la qualité du produit ; la marque peut aussi publier sa propre démonstration. L'influence est puissante dans les deux sens."}$exo$::jsonb),
  ('c3f09051-fbb4-5439-a786-e298f13a7af4'::uuid, 1, 'redaction', $exo${"titre":"Évaluer, former, rémunérer","consigne":"Réponds à chaque question en une ou deux phrases.","enonce":"1. Distingue l'**entretien annuel d'évaluation** et l'**entretien professionnel**.\n2. Qu'est-ce que le **compte personnel de formation** (CPF) ?\n3. Classe chaque élément en rémunération **individualisée** ou **collective** : a) une prime de performance personnelle ; b) l'intéressement ; c) un véhicule de fonction ; d) la participation aux bénéfices.\n4. À partir de quel effectif la **participation** est-elle obligatoire ?","bareme":[{"critere":"Les deux entretiens distingués (performances et objectifs / perspectives d'évolution et de formation, tous les deux ans)","points":6},{"critere":"CPF défini","points":4},{"critere":"Les quatre éléments correctement classés","points":6},{"critere":"Participation obligatoire à partir de 50 salariés","points":4}],"dureeMin":7,"corrige":"1. - L'**entretien annuel d'évaluation** porte sur les **performances** du salarié et ses **objectifs**.\n   - L'**entretien professionnel**, obligatoire **tous les deux ans**, est consacré aux **perspectives d'évolution et de formation**. Les deux aident le salarié à orienter son projet de carrière.\n\n2. Le **CPF** est le **compte personnel de formation** du salarié : il lui permet de financer des formations de son choix pour développer ses compétences.\n\n3. a) **Individualisée** ; b) **collective** ; c) **individualisée** (avantage particulier) ; d) **collective**.\n\n4. La participation est obligatoire à partir de **50 salariés**. L'intéressement, lui, est facultatif."}$exo$::jsonb),
  ('c3f09051-fbb4-5439-a786-e298f13a7af4'::uuid, 2, 'redaction', $exo${"titre":"Absences à la blanchisserie Clairlin","consigne":"Pose le calcul, puis réponds en t'appuyant sur la situation et sur le cours.","enonce":"**Situation.**\n\n> La blanchisserie industrielle Clairlin emploie 30 salariés qui plient et repassent le linge des hôtels. Cette année, on compte **3 150 heures d'absence** pour **45 000 heures théoriques** de travail. Beaucoup d'absences sont liées à des douleurs au dos et aux poignets. Plusieurs salariés se plaignent aussi du stress : les délais imposés par les hôtels sont très courts et le chef d'atelier crie souvent.\n\n1. Calcule le **taux d'absentéisme**.\n2. Identifie les deux catégories de **risques** professionnels présentes, avec un indice pour chacune.\n3. Quelle obligation pèse sur l'employeur ? Quel document l'aide à la respecter ?\n4. Propose trois **mesures** de prévention et justifie-les.","bareme":[{"critere":"Taux d'absentéisme = 3 150 ÷ 45 000 × 100 = 7 %","points":5},{"critere":"TMS (dos, poignets, gestes répétitifs) et risques psychosociaux (stress, cris) identifiés","points":5},{"critere":"Obligation de sécurité ; évaluation des risques dans le document unique","points":4},{"critere":"Trois mesures pertinentes (ergonomie, rotation des tâches, formation gestes et postures, management, négociation des délais)","points":6}],"dureeMin":12,"corrige":"1. Taux d'absentéisme = heures d'absence ÷ heures théoriques × 100 = 3 150 ÷ 45 000 × 100 = **7 %**.\n\n2. - **Troubles musculo-squelettiques** (TMS) : douleurs au dos et aux poignets, liées aux gestes répétitifs (plier, repasser) et aux postures.\n   - **Risques psychosociaux** (RPS) : stress dû aux délais très courts, comportement du chef qui « crie souvent » (pouvant aller jusqu'au harcèlement).\n\n3. L'employeur a une **obligation de sécurité** envers ses salariés : il doit évaluer les risques et les prévenir. L'**évaluation des risques** se fait dans le **document unique**.\n\n4. Mesures (trois attendues, justifiées) :\n   - aménagements **ergonomiques** (tables réglables en hauteur, aides à la manutention) contre les TMS ;\n   - **rotation des tâches** pour varier les gestes ;\n   - formation « **gestes et postures** » ;\n   - formation du chef d'atelier au management, écoute des salariés, contre les RPS ;\n   - renégocier les délais avec les hôtels ou mieux planifier la charge.\n   Ces mesures améliorent la **qualité de vie et des conditions de travail** et, en réduisant l'absentéisme, la performance."}$exo$::jsonb),
  ('c3f09051-fbb4-5439-a786-e298f13a7af4'::uuid, 3, 'redaction', $exo${"titre":"Tensions chez Mécanord","consigne":"Analyse la situation à l'aide des notions du cours ; pose les calculs et rédige des réponses argumentées.","enonce":"**Document 1.**\n\n> Mécanord, équipementier automobile de **320 salariés**, traverse une période tendue. Le taux d'absentéisme était de **5 %** l'an dernier. Cette année : **38 400 heures d'absence** pour **480 000 heures théoriques**. Trois techniciens très qualifiés sont partis chez un concurrent, et les candidatures se font rares. Un débrayage d'une heure a eu lieu après l'annonce d'un gel des salaires, alors que le résultat de l'entreprise est en hausse.\n\n**Document 2 — Propositions de la direction.**\n\n> « Mettre en place un accord d'intéressement lié à la baisse des défauts ; ouvrir une négociation sur les salaires avec les délégués syndicaux ; informer le CSE à partir de la BDESE ; créer des parcours de formation pour les opérateurs. »\n\n1. Calcule le taux d'absentéisme de cette année et compare-le à celui de l'an dernier.\n2. Caractérise le **climat social** et le type de **conflit** observé.\n3. Présente les **acteurs**, les **formes** et les **outils** du dialogue social mobilisés dans le document 2. Pourquoi le **bilan social** concerne-t-il Mécanord ?\n4. Distingue l'**intéressement** de la **participation**. Mécanord est-elle concernée par la participation ?\n5. Montre que l'entreprise a un problème de **compétences** et propose des mesures pour attirer et fidéliser.","bareme":[{"critere":"Taux = 38 400 ÷ 480 000 × 100 = 8 %, hausse de 3 points interprétée","points":4},{"critere":"Climat social dégradé et conflit social (débrayage) caractérisés","points":3},{"critere":"Acteurs (direction, CSE, délégués syndicaux), formes (information, négociation), outils (BDESE, bilan social obligatoire dès 300 salariés)","points":5},{"critere":"Intéressement facultatif lié aux performances, participation obligatoire dès 50 salariés : Mécanord concernée","points":4},{"critere":"Fuite des compétences identifiée, mesures (marque employeur, formation, rémunération, fidélisation) proposées","points":4}],"dureeMin":20,"corrige":"1. Taux d'absentéisme = 38 400 ÷ 480 000 × 100 = **8 %**. Il passe de 5 % à 8 % : **+ 3 points**. C'est un signal d'alerte sur les conditions de travail et la motivation.\n\n2. Le **climat social** est **dégradé** : absentéisme en hausse, départs, débrayage. Il s'agit d'un **conflit social** (collectif) : un arrêt de travail (débrayage, forme de grève) déclenché par le gel des salaires, jugé injuste alors que le résultat augmente.\n\n3. - **Acteurs** : la direction, les représentants élus au **comité social et économique** (CSE), les **délégués syndicaux**.\n   - **Formes** : **information** du CSE, **négociation collective** sur les salaires (qui fait partie des obligations de négocier).\n   - **Outils** : la **BDESE** (base de données économiques, sociales et environnementales mise à disposition des représentants du personnel) et le **bilan social**, obligatoire à partir de **300 salariés** : avec 320 salariés, Mécanord doit l'établir.\n   Le dialogue social peut dépasser le conflit (écoute, négociation) et renforcer la **cohésion**.\n\n4. - L'**intéressement** est **facultatif** et lié aux **performances** (ici, la baisse des défauts).\n   - La **participation** redistribue une **part des bénéfices** ; elle est **obligatoire à partir de 50 salariés** : Mécanord (320 salariés) est **concernée**.\n   Ces rémunérations **collectives** peuvent répondre au sentiment d'injustice (résultat en hausse, salaires gelés).\n\n5. Trois techniciens très qualifiés sont partis chez un concurrent et les candidatures sont rares : c'est une **fuite des compétences** et un problème d'**attractivité**. Mesures : soigner la **marque employeur** pour attirer ; **fidéliser** (rémunération, perspectives de carrière grâce aux **entretiens professionnels**) ; développer les compétences en interne par la **formation** (parcours pour les opérateurs, plan de développement des compétences) ; améliorer la QVCT pour réduire l'absentéisme."}$exo$::jsonb),
  ('2f958091-bc90-559e-919f-03d2bae57b3e'::uuid, 1, 'redaction', $exo${"titre":"Lire une requête SQL","consigne":"Réponds à chaque question en une ou deux phrases.","enonce":"1. Le **système informatique** et le **système d'information** sont-ils la même chose ? Explique.\n2. Dans une base relationnelle, distingue **clé primaire** et **clé étrangère**.\n3. Voici une requête :\n\n| Ligne | Code |\n|---|---|\n| 1 | SELECT libelle, prix |\n| 2 | FROM PRODUIT |\n| 3 | WHERE categorie = 'Jardin' |\n| 4 | ORDER BY prix ; |\n\n   a) Que produit cette requête ? b) Quel est le rôle de la ligne 3 ? c) Quel est le rôle de la ligne 4 ?","bareme":[{"critere":"Système informatique présenté comme une partie du SI (matériel, logiciel, infrastructure)","points":5},{"critere":"Clé primaire et clé étrangère correctement définies","points":6},{"critere":"Requête expliquée : libellé et prix des produits Jardin, filtre WHERE, tri ORDER BY","points":9}],"dureeMin":7,"corrige":"1. Non. Le **système informatique** (matériel, logiciel, infrastructure de communication) n'est **qu'une partie** du **système d'information**, qui comprend aussi des ressources humaines, des données, des procédures et des objectifs.\n\n2. - La **clé primaire** identifie de façon **unique** chaque ligne d'une table.\n   - La **clé étrangère** est un champ qui **fait référence** à la clé primaire d'une autre table : elle relie les tables.\n\n3. a) La requête affiche le **libellé et le prix des produits de la catégorie « Jardin »**, **triés par prix**.\n   b) La ligne 3 (**WHERE**) **filtre** les lignes : seuls les produits dont la catégorie est « Jardin » sont retenus.\n   c) La ligne 4 (**ORDER BY**) **trie** le résultat selon le prix."}$exo$::jsonb),
  ('2f958091-bc90-559e-919f-03d2bae57b3e'::uuid, 2, 'redaction', $exo${"titre":"La base de données de Pages & Plumes","consigne":"Étudie le schéma de la base, puis réponds. Écris les requêtes en SQL.","enonce":"**La base de la librairie en ligne Pages & Plumes.**\n\n- CLIENT (**id**, nom, prenom, ville, courriel)\n- COMMANDE (**num**, date_cde, montant, id_client)\n\nLes champs en gras sont les clés primaires. Le champ id_client de COMMANDE contient l'identifiant du client qui a passé la commande.\n\n1. Quelle est la **clé étrangère** de la base ? Quel lien établit-elle ?\n2. Écris la requête qui affiche le **nom et le prénom des clients qui habitent Nantes**, triés par nom.\n3. Écris la requête qui affiche le **nom du client, la date et le montant de chaque commande**, en reliant les deux tables par une **jointure**.\n4. La librairie veut envoyer une offre par courriel aux clients. Quelle règle doit-elle respecter ?","bareme":[{"critere":"Clé étrangère id_client identifiée, lien commande-client expliqué","points":4},{"critere":"Requête 2 juste : SELECT nom, prenom FROM CLIENT WHERE ville = 'Nantes' ORDER BY nom","points":6},{"critere":"Requête 3 juste avec JOIN … ON CLIENT.id = COMMANDE.id_client","points":6},{"critere":"RGPD : consentement et possibilité de se désinscrire","points":4}],"dureeMin":12,"corrige":"1. La clé étrangère est **id_client** dans la table COMMANDE : elle fait référence à la clé primaire **id** de CLIENT et indique **quel client a passé chaque commande**. Un client peut avoir plusieurs commandes.\n\n2. ```\nSELECT nom, prenom\nFROM CLIENT\nWHERE ville = 'Nantes'\nORDER BY nom ;\n```\n\n3. ```\nSELECT CLIENT.nom, COMMANDE.date_cde, COMMANDE.montant\nFROM CLIENT\nJOIN COMMANDE ON CLIENT.id = COMMANDE.id_client ;\n```\n   La jointure relie chaque commande au client correspondant grâce à la clé commune.\n\n4. Les courriels et les noms sont des données personnelles : la librairie doit respecter le **RGPD**, obtenir le **consentement** des clients pour les offres commerciales et leur laisser la possibilité de **se désinscrire** (droit d'opposition)."}$exo$::jsonb),
  ('2f958091-bc90-559e-919f-03d2bae57b3e'::uuid, 3, 'redaction', $exo${"titre":"Le projet de site de la Fromagerie Morel","consigne":"Analyse le projet à l'aide des notions du cours et rédige des réponses argumentées.","enonce":"**Document 1 — Le projet.**\n\n> La Fromagerie Morel (18 salariés, aucun informaticien) veut vendre en ligne. Le site devra afficher le délai de livraison en interrogeant directement le service du transporteur, et permettre le paiement par carte. Le gérant hésite entre développer le site avec un étudiant en informatique ou confier l'hébergement et la maintenance à un prestataire. Il souhaite voir une première version dans un mois, puis l'améliorer au fil des retours des clients.\n\n**Document 2 — Un incident chez un voisin.**\n\n> La cave à vins voisine a vu son site bloqué trois jours par une cyberattaque ; son unique sauvegarde se trouvait sur le même serveur.\n\n1. Quel outil permet au site d'interroger le service du transporteur ? Explique son principe.\n2. Quel **protocole** doit utiliser la page de paiement, et pourquoi ?\n3. Faut-il recourir à l'**infogérance** ? Pèse les arguments pour la Fromagerie Morel.\n4. Quelle méthode de conduite de projet correspond au souhait du gérant ? Qu'est-ce que la **recette** du projet ?\n5. Quels **risques** le document 2 révèle-t-il ? Propose deux mesures de sécurisation.","bareme":[{"critere":"API : interface qui permet à deux applications d'échanger des données, appliquée au transporteur","points":4},{"critere":"HTTPS : communication chiffrée entre navigateur et site, indispensable au paiement","points":3},{"critere":"Infogérance discutée : pas de compétences internes, coût, dépendance au prestataire","points":4},{"critere":"Méthode agile (livraisons courtes et fréquentes) et recette (vérifier que le système répond au besoin)","points":5},{"critere":"Risques informatiques identifiés et deux mesures (sauvegardes séparées, pare-feu, chiffrement, VPN…)","points":4}],"dureeMin":20,"corrige":"1. Une **interface de programmation** (**API**) permet à deux applications d'**échanger des données** : le site de la fromagerie envoie l'adresse du client au service du transporteur, qui lui renvoie le délai de livraison, sans intervention humaine.\n\n2. La page de paiement doit utiliser **HTTPS** : ce protocole garantit une communication **chiffrée** entre le navigateur du client et le site, ce qui protège les données de la carte bancaire contre l'interception. C'est indispensable à la confiance des clients.\n\n3. L'**infogérance** consiste à **confier tout ou partie de son informatique à un prestataire**.\n   - **Pour** : la fromagerie n'a **aucun informaticien** ; un prestataire apporte compétences, sécurité, disponibilité et maintenance ; un étudiant peut partir et laisser un site que personne ne sait entretenir.\n   - **Contre** : un **coût** régulier et une **dépendance** au prestataire.\n   Conclusion attendue et justifiée : l'infogérance (au moins pour l'hébergement et la maintenance) paraît adaptée à une petite entreprise sans compétences internes.\n\n4. Le gérant veut une première version rapide, améliorée au fil des retours : c'est une méthode **agile** (livraisons **courtes et fréquentes**), plutôt qu'une méthode classique où tout est livré à la fin. La **recette** consiste à **vérifier que le système livré répond au besoin** exprimé (affichage des délais, paiement, commande) avant son déploiement.\n\n5. Le document 2 révèle des **risques informatiques** : **cyberattaque**, paralysie du site, **perte de données** (sauvegarde sur le même serveur, donc détruite ou bloquée avec lui). Mesures (deux attendues) : des **sauvegardes** régulières stockées **ailleurs** (autre support ou en nuage) ; un **pare-feu** ; le **chiffrement** des données ; des mises à jour et une sécurisation des accès (VPN pour l'administration du site)."}$exo$::jsonb),
  ('97aba00c-62d7-5859-af2a-3283c7cb8e4c'::uuid, 1, 'redaction', $exo${"titre":"Notion, application, conclusion","consigne":"Applique la méthode du cours : notion définie, application au cas avec un indice, conclusion.","enonce":"**Document.**\n\n> « Chez Pédalo, nous ne commandons nos cadres de vélo qu'une fois la commande du client reçue ; notre entrepôt ne contient presque plus de produits finis. » — la directrice de Pédalo.\n\n1. **Question** : « Montrez que Pédalo produit en flux tendus. » Rédige la réponse en trois temps : notion, application avec une citation courte du document, conclusion.\n2. Pour chacune des questions suivantes, indique son **type** (caractériser, calculer, analyser, justifier, question de réflexion) et ce qui est attendu :\n   - a) « Les transformations numériques sont-elles une chance pour la production ? »\n   - b) « Calculez la marge sur coût spécifique de la gamme Ville. »\n   - c) « Caractérisez le style de direction de la gérante. »","bareme":[{"critere":"Notion de flux tendus correctement définie (produire à la commande, au plus juste, peu de stocks)","points":4},{"critere":"Application avec au moins un indice cité du document","points":4},{"critere":"Conclusion qui répond à la question, avec une conséquence pour l'organisation","points":3},{"critere":"Les trois types de questions identifiés avec leur attendu","points":9}],"dureeMin":8,"corrige":"1. - **Notion** : produire en **flux tendus**, c'est produire **à la commande**, **au plus juste**, en limitant les stocks.\n   - **Application** : Pédalo ne commande ses cadres « qu'une fois la commande du client reçue » et son entrepôt « ne contient presque plus de produits finis ».\n   - **Conclusion** : Pédalo produit donc en flux tendus, ce qui réduit ses coûts de stockage mais la rend vulnérable à un retard de ses fournisseurs.\n\n2. a) **Question de réflexion** : réponse structurée (introduction, deux ou trois arguments, conclusion) qui mobilise le cours et des exemples.\n   b) **Calculer** : formule, calcul posé, résultat avec unité, puis **interprétation** de ce que le résultat signifie pour l'organisation.\n   c) **Caractériser** : nommer le style avec la notion exacte et l'appuyer sur un **indice** du document."}$exo$::jsonb),
  ('97aba00c-62d7-5859-af2a-3283c7cb8e4c'::uuid, 2, 'redaction', $exo${"titre":"Un calcul qui dit quelque chose","consigne":"Réponds en appliquant la méthode du cours : calcul posé et interprété, puis réponse en trois temps.","enonce":"**Document 1 — Données de l'entreprise Lumibois (lampes en bois).**\n\n| Gamme | Chiffre d'affaires | Charges variables | Charges fixes spécifiques |\n|---|---|---|---|\n| Chevet | 180 000 € | 110 000 € | 40 000 € |\n\n> Rappel donné par le sujet : marge sur coût spécifique = chiffre d'affaires − (charges variables + charges fixes spécifiques). Si elle est positive, la gamme contribue à couvrir les charges communes de l'entreprise.\n\n**Document 2 — Témoignage d'un salarié.**\n\n> « Notre gérante demande toujours notre avis en réunion avant les grandes décisions, mais c'est elle qui tranche, seule, à la fin. »\n\n> Rappel donné par le sujet : un style de direction est **consultatif** quand le dirigeant consulte avant de décider seul.\n\n1. « Calculez la marge sur coût spécifique de la gamme Chevet. » Présente formule, calcul, résultat avec unité **et interprétation**.\n2. « Caractérisez le style de direction de la gérante. » Réponds en trois temps : notion, application avec un indice, conclusion.\n3. Relis tes deux réponses : cite deux points à vérifier à la relecture selon la méthode du cours.","bareme":[{"critere":"Formule et calcul posés : 180 000 − 150 000 = 30 000 €","points":5},{"critere":"Interprétation : la gamme couvre ses charges et contribue à couvrir les charges communes","points":5},{"critere":"Style consultatif caractérisé en trois temps avec un indice cité","points":7},{"critere":"Deux points de relecture (orthographe, unités, cohérence des calculs)","points":3}],"dureeMin":11,"corrige":"1. - **Formule** : marge sur coût spécifique = CA − (charges variables + charges fixes spécifiques).\n   - **Calcul** : 180 000 − (110 000 + 40 000) = 180 000 − 150 000.\n   - **Résultat** : **30 000 €**.\n   - **Interprétation** : la marge est positive ; la gamme Chevet couvre ses propres charges et **contribue à couvrir les charges communes** de Lumibois : elle a intérêt à la conserver. (Un calcul juste sans interprétation ne rapporte qu'une partie des points.)\n\n2. - **Notion** : un style de direction est **consultatif** quand le dirigeant consulte avant de décider seul.\n   - **Application** : la gérante « demande toujours notre avis en réunion », mais « c'est elle qui tranche, seule, à la fin ».\n   - **Conclusion** : son style de direction est donc consultatif.\n\n3. Points de relecture (deux attendus) : l'**orthographe**, la présence des **unités** (€), la **cohérence des calculs** (refaire la soustraction), la réponse effective à la question posée."}$exo$::jsonb),
  ('97aba00c-62d7-5859-af2a-3283c7cb8e4c'::uuid, 3, 'redaction', $exo${"titre":"Question de réflexion : le numérique dans une scierie","consigne":"Rédige une réponse structurée : introduction, deux ou trois arguments appuyés sur les documents, conclusion. Soigne l'expression.","enonce":"**Question de réflexion.** « Les transformations numériques sont-elles une chance pour la production de la scierie Delorme ? »\n\n**Document 1.**\n\n> La scierie Delorme (25 salariés) a installé un scanner qui mesure chaque tronc et un logiciel qui calcule la meilleure découpe. Les chutes de bois ont diminué d'un tiers. Les commandes des clients arrivent directement dans le planning de l'atelier : la ressaisie a disparu.\n\n**Document 2.**\n\n> L'investissement a coûté 140 000 €. En février, une panne du réseau a arrêté la ligne toute une journée. Le plus ancien scieur, qui « lisait » le bois à l'œil, dit : « Aujourd'hui, c'est la machine qui décide, je ne sers plus qu'à appuyer sur le bouton. »\n\n**Aide donnée par le sujet.** Une opportunité est ce que le numérique apporte à la production (gains de productivité, moins d'erreurs, moins de pertes) ; un risque est ce qu'il menace (coût, dépendance au réseau, perte de savoir-faire).\n\nTa réponse doit :\n- présenter la scierie et la question en introduction ;\n- développer au moins un argument sur les opportunités et un sur les risques, chacun appuyé sur un indice ;\n- conclure en répondant clairement à la question.","bareme":[{"critere":"Introduction : présentation de l'organisation, du contexte et de la question","points":3},{"critere":"Argument sur les opportunités appuyé sur des indices (chutes réduites d'un tiers, fin de la ressaisie)","points":5},{"critere":"Argument sur les risques appuyé sur des indices (140 000 €, panne d'une journée, savoir-faire du scieur)","points":5},{"critere":"Conclusion nuancée qui répond à la question","points":4},{"critere":"Organisation du propos, vocabulaire précis et expression soignée","points":3}],"dureeMin":20,"corrige":"**Introduction.** La scierie Delorme, PME de 25 salariés, a numérisé une partie de sa production : un scanner mesure les troncs, un logiciel optimise la découpe, et les commandes alimentent directement le planning. Ces transformations numériques sont-elles une chance pour sa production ?\n\n**Premier argument : des gains réels.**\n- **Moins de pertes** : les chutes de bois ont diminué **d'un tiers** grâce au calcul de la meilleure découpe ; la même quantité de bois donne plus de planches.\n- **Moins d'erreurs** et plus de **réactivité** : les commandes arrivent « directement dans le planning », **la ressaisie a disparu**.\n\n**Deuxième argument : des risques nouveaux.**\n- Un **coût** élevé pour une PME : **140 000 €**.\n- Une **dépendance** au réseau : une panne a arrêté la ligne **toute une journée**.\n- Une **perte de savoir-faire** et un sens du travail menacé : le scieur expérimenté a le sentiment de ne plus « servir qu'à appuyer sur le bouton ».\n\n**(Troisième argument possible : comment limiter les risques)** — prévoir une procédure de secours en cas de panne, associer les salariés expérimentés au réglage et à la vérification du logiciel pour préserver leur savoir-faire.\n\n**Conclusion.** Le numérique est une **chance** pour la production de la scierie Delorme, puisqu'il réduit les pertes et les erreurs ; mais cette chance n'est complète que si l'entreprise **anticipe** ses risques : panne, coût, place des salariés. Toute conclusion nuancée et justifiée est acceptée.\n\nLe correcteur vérifie aussi que chaque argument commence par une idée claire, s'appuie sur un indice précis du document et que la copie est bien rédigée."}$exo$::jsonb)
) AS v (chapter_id, difficulte, style, contenu)
JOIN public.chapters c ON c.id = v.chapter_id
ON CONFLICT (id) DO UPDATE
  SET style      = EXCLUDED.style,
      contenu    = EXCLUDED.contenu,
      difficulte = EXCLUDED.difficulte,
      origine    = 'catalogue';

DO $$
DECLARE
  n INT;
BEGIN
  SELECT count(*) INTO n
    FROM public.chapter_exercices e
   WHERE e.origine = 'catalogue'
     AND e.chapter_id IN ('7cbd8a7e-3772-51db-a89c-0390e1c6eb36', 'c72a0423-5189-5138-8487-3350088f8afe', '70da3aef-6b9c-5d46-a2e1-f4414de341b7', 'cee613e0-8d08-598a-86a2-22bdefbc269d', '7aeefedb-4028-5b71-b194-3542de89aaef', 'a1467307-77b6-5c43-b345-e82504ab15b0', '37aff0ea-aa91-5a64-b706-3590a8a24ccc', '7a11e7fe-a29d-50be-aa9e-ac7d75246068', '9667b134-4db8-5573-88b0-16ab3f9ea2a6', 'a75fbd39-ecee-50e0-8bb6-4171a4931cc6', '0534bd63-d404-5338-870b-1d39fdb6ca01', '245d7288-4db0-5e78-847e-1826becffcfe', '1b407335-9135-5de3-9afd-9e5cd66da90d', '3dfe8b2c-e4d9-5f74-8d21-6dd731772024', '4fce27b4-0ef0-58ec-b4f2-92b9f0286eea', 'b7369998-f445-522b-a4aa-73ca33b02ec4', 'a80fab3b-809c-5553-99d8-aa651fc764ae', '640789de-a2ba-55f1-9cbc-47c8ff599ab1', '0f1bd440-e489-50c6-9d89-b6f338df63e9', '215ac38c-8bc0-521d-90f8-78b2edabf966', '4b21fe51-1861-54d5-a941-0bd78aa07130', '6cb7aadf-41e1-552f-82c2-e653fd402ea7', 'f947ad8e-255e-5af6-a101-00ba1a63ed2a', '1e93d6ee-75bb-5f4f-bf3b-11f57521c6a1', '21fc23b8-7d0a-5cee-8284-3fad6af886e5', 'fd328438-8bb9-54d5-95ca-16027500a4eb', '29435005-8b98-5af4-a25a-226f6b969d8b', '5f404260-52cc-59e5-9e87-b461a7634711', 'fb970bea-7672-5c00-a72a-415c3426f942', '2b0aee15-572b-5419-a50f-08da8108987e', '0ba3cb40-87a4-5764-8631-67cef5de82e4', '33441d30-66aa-5411-92fd-8ea37d0f66de', '2774fa37-70aa-5c10-a20f-72e35dc083a9', '51252a34-afd8-53d2-9c80-a37caf268eb9', '7cb44eba-8094-52a0-80ca-2c337dfe27f0', '82d9a027-dbaa-5e47-97a0-a779dce9af6a', '32a3eb6f-ae4f-54c5-85c0-9590d2c4f453', '52e7d094-4bba-545b-b866-603f9b785bc3', '72027180-b57a-57c1-be3b-a044924efbe9', '9f2f35db-9c91-50a8-87f1-60869cb7594e', '0eb1886a-d515-50b0-bc6a-0a6a3ffc2cfe', 'a4d78489-85e8-5176-9e2a-daf3772f8d8d', '1917545c-4cb7-59e5-a3c2-3ee1cafe0a40', 'f383dc99-8a45-5edf-ab4b-743fa80757bc', 'ccfa9fad-79b2-5e2e-9503-9928547b9265', '8fc83035-70b5-53ee-82ab-bad804fd1919', '56f70b98-1d1e-56bd-aae1-e9a823e43a0e', '7b9550ee-1d89-52be-9a3c-6fa0cd4d45e4', '260e98c0-9992-5d62-9829-ea2e987d430b', '985d9f4c-20ce