  RAISE NOTICE '416 : % sujets au catalogue (attendu : 276)', n;
  IF n < 276 THEN
    RAISE WARNING '416 : il manque des sujets — des fiches ont-elles changé d''identifiant ?';
  END IF;
END $$;
